def _cosine_similarity(left: list[float], right: list[float]) -> float:
    denominator = math.sqrt(sum(x * x for x in left)) * math.sqrt(sum(x * x for x in right))
    return sum(x * y for x, y in zip(left, right)) / denominator if denominator else -1.0


def _world_bank_country_name(item):
    country = item.get("country")
    if isinstance(country, dict):
        country = country.get("value") or country.get("id")
    return country or item.get("countryiso3code") or "Unknown country"


def _format_world_bank_value(value: Any, missing_value: str | None = None) -> str | None:
    if value is None:
        return missing_value
    try:
        number = float(value)
    except (TypeError, ValueError):
        return str(value)
    if number.is_integer():
        return f"{int(number):,}"
    return f"{number:,.2f}".rstrip("0").rstrip(".")


def _startup_laya_provider(config: Settings | None = None) -> tuple[LayaDecisionProvider, dict[str, Any]]:
    provider = LayaDecisionProvider(
        multilingual_model=getattr(config, "laya_multilingual_model", os.environ.get("OLCR_LAYA_MULTILINGUAL_MODEL", "convaiinnovations/laya-multilingual")),
        english_model=getattr(config, "laya_english_model", os.environ.get("OLCR_LAYA_ENGLISH_MODEL", "convaiinnovations/laya")),
        revision=getattr(config, "laya_model_revision", os.environ.get("OLCR_LAYA_MODEL_REVISION", DEFAULT_LAYA_MODEL_REVISION)),
        english_revision=getattr(config, "laya_english_model_revision", os.environ.get("OLCR_LAYA_ENGLISH_REVISION", DEFAULT_LAYA_ENGLISH_MODEL_REVISION)),
        device=getattr(config, "laya_device", os.environ.get("OLCR_LAYA_DEVICE", "auto")),
    )
    preflight_result = laya_preflight(multilingual_model=provider.multilingual_model,
                                      english_model=provider.english_model,
                                      revision=provider.revision, english_revision=provider.english_revision,
                                      device=provider.device)
    if preflight_result["ready"]:
        try:
            provider.load()
        except LayaRuntimeError as exc:
            preflight_result = {**preflight_result, "ready": False, "health": "DEGRADED", "reason": exc.category}
    print("LOCAL_DECISION_PROVIDER=LAYA LAYA_REQUIRED=YES LAYA_READY={} LAYA_STARTUP_LOAD={} LAYA_ENGLISH_CHECKPOINT_READY={}".format(
        "YES" if preflight_result["ready"] else "NO", "YES" if provider.loaded else "NO",
        "YES" if preflight_result.get("english_checkpoint_ready") else "NO"),
        file=__import__('sys').stderr, flush=True)
    return provider, preflight_result


