_laya_setup_lock = threading.Lock()
_laya_setup_worker = None

def _prepare_laya_component():
    global _laya_setup_worker
    with _laya_setup_lock:
        if _laya_setup_worker and _laya_setup_worker.is_alive():
            return optional_components.status('laya')
        def work():
            global _laya_startup_status
            try:
                path = optional_components.ensure('laya')
                os.environ['OLCR_LAYA_CACHE'] = str(path)
                optional_components.update('laya', 'installing', '判断用モデルを読み込み中…')
                local = laya_provider.local if isinstance(laya_provider, PurposeDecisionProvider) else laya_provider
                local.load()
                _laya_startup_status = laya_preflight()
                optional_components.update('laya', 'ready')
            except Exception as exc:
                optional_components.update('laya', 'error', '判断用モデルを準備できませんでした。接続を確認して再試行してください。')
        optional_components.update('laya', 'installing', '判断用モデルを準備中…')
        _laya_setup_worker = threading.Thread(target=work, name='olcr-laya-setup', daemon=True)
        _laya_setup_worker.start()
    return optional_components.status('laya')

def _prepare_required_components():
    # Landing owns first-run download consent. Startup may reload an already
    # installed component, but never begins a new transfer on its own.
    if (purpose_models.choice('typed_local_decisions')['protocol'] == 'preset'
            and not laya_provider.loaded and optional_components.installed('laya')):
        _prepare_laya_component()

app.add_event_handler('startup', _prepare_required_components)

@app.get('/api/components')
def component_status():
    rows = [optional_components.status(name) for name in OPTIONAL_COMPONENT_NAMES]
    local_laya = getattr(laya_provider, 'local', laya_provider)
    if local_laya.loaded and rows[0]['state'] not in {'installing','downloading','removing'}:
        rows[0].update(state='ready', message='')
    conversion = conversion_service.downloads_status()
    conversion['enabled'] = settings.convert_enabled
    return {'components': rows, 'conversion': conversion}

@app.post('/api/components/{name}/prepare')
def prepare_component(name: Literal['laya','agents','node-tools','browser','serena']):
    return _prepare_laya_component() if name == 'laya' else optional_components.prepare(name)

@app.delete('/api/components/{name}')
def remove_component(name: Literal['laya','agents','node-tools','browser','serena']):
    try:
        if name == 'laya':
            with _laya_setup_lock:
                if _laya_setup_worker and _laya_setup_worker.is_alive():
                    raise HTTPException(409, 'LAYA_SETUP_IN_PROGRESS')
                local_laya = getattr(laya_provider, 'local', laya_provider)
                if local_laya.loaded:
                    local_laya.unload()
                return optional_components.remove(name)
        return optional_components.remove(name)
    except ValueError as exc:
        raise HTTPException(409, str(exc)) from None
