_pending_semantic_action_plans: dict[str, dict[str, Any]] = {}


def _validate_computer_action_scope(project_id: str | None, conversation_id: str | None) -> None:
    project = db.project(project_id) if project_id else None
    if project_id and not project:
        raise HTTPException(404, "PROJECT_NOT_FOUND")
    if not conversation_id:
        raise HTTPException(422, "ACTIVE_CONVERSATION_REQUIRED")
    conversation = db.conversation(conversation_id)
    if not conversation:
        raise HTTPException(404, "CONVERSATION_NOT_FOUND")
    if conversation["project_id"] != project_id:
        raise HTTPException(403, "CONVERSATION_PROJECT_MISMATCH")


def _validate_ax_observation_size(observation: Any) -> None:
    try:
        observation_bytes = len(json.dumps(observation, ensure_ascii=False).encode("utf-8"))
    except (TypeError, ValueError):
        raise HTTPException(422, "AX_OBSERVATION_INVALID")
    if observation_bytes > 24_000:
        raise HTTPException(413, "AX_OBSERVATION_TOO_LARGE")


def _prune_pending_semantic_action_plans() -> None:
    while len(_pending_semantic_action_plans) > 64:
        _pending_semantic_action_plans.pop(next(iter(_pending_semantic_action_plans)))


def _require_pending_semantic_action_plan(
        plan_id: str, action_kind: str | None, missing_reason: str,
        expired_reason: str) -> dict[str, Any]:
    plan = _pending_semantic_action_plans.get(plan_id)
    if not plan or (action_kind is not None and plan.get("action_kind") != action_kind):
        raise HTTPException(404, missing_reason)
    if time.monotonic() > plan["expires_at"]:
        _pending_semantic_action_plans.pop(plan_id, None)
        raise HTTPException(410, expired_reason)
    return plan


def _capture_verified_routine_trace(plan: dict[str, Any], after_observation: dict[str, Any],
                                   verification: dict[str, Any]) -> None:
    """Capture only compact confirmed action evidence; never store screenshots or full trees."""
    before = plan.get("before_state")
    action_kind = plan.get("action_kind")
    if (verification.get("result") != "CONFIRMED" or verification.get("verified") is not True
            or action_kind not in {"open_disclosure", "open_find"}
            or not hasattr(before, "elements")):
        return
    after = DOMAXObservationProvider().observe(
        dom=after_observation.get("dom"), ax=after_observation.get("ax"))
    target_id = str(plan.get("element_id") or "")
    before_element = next((item for item in before.elements
                           if str(item.get("id") or item.get("element_id") or "") == target_id), {})
    expected = {"open_disclosure": {"role": "disclosure", "expanded": True},
                "open_find": {"role": "AXSearchField|AXTextField", "focused": True}}[action_kind]
    after_element = next((item for item in after.elements if
        (action_kind == "open_disclosure" and
         str(item.get("id") or item.get("element_id") or "") == target_id and item.get("expanded") is True)
        or (action_kind == "open_find" and item.get("focused") is True and
            (item.get("subrole") == "AXSearchField" or
             str(item.get("label") or "").casefold() in {"find", "search", "検索"}))), {})
    if not before_element or not after_element:
        return
    safe_fields = ("role", "subrole", "label", "enabled", "expanded", "focused")
    compact = lambda element: {key: element[key] for key in safe_fields if key in element}
    shortcut = plan.get("keyboard_shortcut")
    if isinstance(shortcut, dict):
        shortcut = {key: shortcut[key] for key in ("key_code", "modifiers", "key", "provenance")
                    if key in shortcut}
    trace = {
        "trace_version": 1,
        "goal_signature_version": 1,
        "goal_signature": routine_goal_signature(str(plan.get("question") or "")),
        "context": {"source": before.source, "session_id": before.session_id,
                    "application_pid": plan.get("application_pid"),
                    "application_bundle_id": plan.get("application_bundle_id"),
                    "coordinate_space": before.coordinate_space},
        "preconditions": [compact(before_element)],
        "observed_state": {"observation_id": before.observation_id,
                            "observed_at": before.observed_at,
                            "elements": [compact(before_element)]},
        "action": {"kind": action_kind, "mechanism": plan.get("action_route", {}).get("mechanism")},
        "actions": [{"kind": action_kind, "mechanism": plan.get("action_route", {}).get("mechanism"),
                     "target": compact(before_element), "shortcut": shortcut}],
        "expected_effects": [expected],
        "verification": {"result": verification.get("result"), "reason": verification.get("reason"),
                         "before_observation_id": before.observation_id,
                         "after_observation_id": after.observation_id,
                         "after_observed_at": after.observed_at},
        "final_state": {"observation_id": after.observation_id,
                        "observed_at": after.observed_at, "elements": [compact(after_element)]},
        "provenance": {"semantic_source": before.source,
                       "action_source": plan.get("action_route", {}).get("mechanism"),
                       "verification_source": after.source,
                       "route_reliability": plan.get("action_route", {}).get("reliability")},
    }
    captured = ProcedureStore(db).capture_verified_trace(trace)
    print(f"ROUTINE_TRACE_CAPTURE=PASS TRACE_ID={captured.id} ACTION={action_kind}",
          file=__import__("sys").stderr,flush=True)


def _record_approved_routine_success(plan: dict[str, Any], verification: dict[str, Any]) -> None:
    """Finalize only a confirmed staged GUI-routine step through ProcedureRunner."""
    candidate_id = plan.get("routine_candidate_id")
    if (not isinstance(candidate_id, str) or not candidate_id
            or verification.get("result") != "CONFIRMED"
            or verification.get("verified") is not True):
        return
    store = ProcedureStore(db)
    candidate = store.get(candidate_id)
    if (candidate is None or candidate.status != "CANDIDATE" or candidate.validated
            or not isinstance(candidate.review, dict)
            or candidate.review.get("decision") != "APPROVED"):
        return
    if (len(candidate.steps) != 1
            or candidate.steps[0].get("tool") != f"olcr.gui.{plan.get('action_kind')}"):
        return
    if runtime.procedures.record_staged_outcome(
            candidate, verification, execution_attempted=True):
        model_telemetry.record_routine_outcome(success=True)


def _native_action_receipt_matches_plan(plan: dict[str, Any], receipt: Any,
                                        observation: dict[str, Any]) -> bool:
    """Count only a native result returned after input dispatch with an unconfirmed effect."""
    if (not isinstance(receipt, dict) or receipt.get("source") != "native_accessibility"
            or receipt.get("execution_attempted") is not True
            or receipt.get("status") != "FAILED"
            or receipt.get("action_kind") != plan.get("action_kind")):
        return False
    route = plan.get("action_route")
    mechanism = route.get("mechanism") if isinstance(route, dict) else None
    if mechanism not in {"accessibility", "deterministic_input", "vision_pointer",
                         "keyboard_shortcut"}:
        return False
    ax = observation.get("ax") if isinstance(observation, dict) else None
    if (not isinstance(ax, dict) or ax.get("permissionGranted") is not True
            or not isinstance(ax.get("applicationPid"), int)
            or isinstance(ax.get("applicationPid"), bool)
            or ax.get("applicationPid") != plan.get("application_pid")
            or ax.get("applicationBundleId") != plan.get("application_bundle_id")
            or ax.get("sessionId") != route.get("session_id")):
        return False
    if mechanism == "vision_pointer" and plan.get("action_kind") == "press_button":
        evidence = plan.get("vision_pointer")
        provenance = evidence.get("provenance") if isinstance(evidence, dict) else None
        alignment = receipt.get("alignment")
        if (not isinstance(provenance, dict) or not isinstance(alignment, dict)
                or receipt.get("action") != "VISION_GROUNDED_POINTER"
                or alignment.get("captureSessionId") != provenance.get("capture_session_id")
                or not isinstance(alignment.get("targetApplication"), dict)
                or alignment["targetApplication"].get("applicationPid") != plan.get("application_pid")
                or alignment["targetApplication"].get("applicationBundleId") != plan.get("application_bundle_id")
                or alignment.get("seedSequence") != provenance.get("frame_sequence")
                or not isinstance(alignment.get("verifiedSequence"), int)
                or isinstance(alignment.get("verifiedSequence"), bool)
                or alignment["verifiedSequence"] <= alignment.get("seedSequence", 0)
                or alignment.get("targetWindowContainsPoint") is not True
                or alignment.get("trackingSource") not in {"APPLE_VISION_OBJECT_TRACKING", "OPENCV_LUCAS_KANADE"}
                or not isinstance(alignment.get("trackingConfidence"), (int, float))
                or isinstance(alignment.get("trackingConfidence"), bool)
                or not 0.75 <= alignment["trackingConfidence"] <= 1.0):
            return False
    return True


def _native_action_execution_receipt_matches_plan(plan: dict[str, Any], receipt: Any,
                                                   observation: dict[str, Any]) -> bool:
    """Accept only bounded native dispatch receipts tied to this plan and target."""
    if (not isinstance(receipt, dict) or receipt.get("source") != "native_accessibility"
            or receipt.get("execution_attempted") is not True
            or receipt.get("status") not in {"PASS", "FAILED"}
            or receipt.get("action_kind") != plan.get("action_kind")):
        return False
    route = plan.get("action_route")
    mechanism = route.get("mechanism") if isinstance(route, dict) else None
    if mechanism not in {"accessibility", "deterministic_input", "vision_pointer", "keyboard_shortcut"}:
        return False
    ax = observation.get("ax") if isinstance(observation, dict) else None
    matches_target = bool(
        isinstance(ax, dict) and ax.get("permissionGranted") is True
        and isinstance(ax.get("applicationPid"), int) and not isinstance(ax.get("applicationPid"), bool)
        and ax.get("applicationPid") == plan.get("application_pid")
        and ax.get("applicationBundleId") == plan.get("application_bundle_id")
        and ax.get("sessionId") == route.get("session_id")
    )
    if not matches_target:
        return False
    if plan.get("action_kind") == "type_text":
        return bool(receipt.get("status") == "PASS" and receipt.get("verified") is True
                    and receipt.get("element_id") == plan.get("element_id")
                    and receipt.get("value_matched") is True
                    and receipt.get("action") == "AXSetValue")
    if plan.get("action_kind") == "scroll_wheel":
        return bool(receipt.get("status") == "PASS"
            and receipt.get("action") == "CGEventScrollWheel"
            and receipt.get("direction") == plan.get("direction")
            and receipt.get("element_id") == plan.get("element_id")
            and receipt.get("scrollbar_element_id") == plan.get("scrollbar_element_id"))
    if plan.get("action_kind") == "press_key":
        return bool(receipt.get("status") == "PASS"
            and receipt.get("action") == "CGEventKeyboard"
            and receipt.get("key") == plan.get("key")
            and receipt.get("element_id") == plan.get("element_id"))
    if mechanism == "vision_pointer" and plan.get("action_kind") == "press_button":
        evidence = plan.get("vision_pointer")
        provenance = evidence.get("provenance") if isinstance(evidence, dict) else None
        alignment = receipt.get("alignment")
        return bool(
            isinstance(provenance, dict) and isinstance(alignment, dict)
            and receipt.get("action") == "VISION_GROUNDED_POINTER"
            and alignment.get("captureSessionId") == provenance.get("capture_session_id")
            and isinstance(alignment.get("targetApplication"), dict)
            and alignment["targetApplication"].get("applicationPid") == plan.get("application_pid")
            and alignment["targetApplication"].get("applicationBundleId") == plan.get("application_bundle_id")
            and alignment.get("seedSequence") == provenance.get("frame_sequence")
            and isinstance(alignment.get("verifiedSequence"), int)
            and not isinstance(alignment.get("verifiedSequence"), bool)
            and alignment["verifiedSequence"] > alignment.get("seedSequence", 0)
            and alignment.get("targetWindowContainsPoint") is True
            and alignment.get("trackingSource") in {"APPLE_VISION_OBJECT_TRACKING", "OPENCV_LUCAS_KANADE"}
            and isinstance(alignment.get("trackingConfidence"), (int, float))
            and not isinstance(alignment.get("trackingConfidence"), bool)
            and 0.75 <= alignment["trackingConfidence"] <= 1.0
        )
    return True


def _structured_action_execution_receipt_matches_plan(plan: dict[str, Any], receipt: Any,
                                                       observation: dict[str, Any]) -> bool:
    """Accept the bounded WebView disclosure click receipt for its exact DOM transition."""
    if (not isinstance(receipt, dict) or receipt.get("source") != "native_structured"
            or receipt.get("execution_attempted") is not True
            or receipt.get("status") != "PASS"
            or receipt.get("action_kind") != "open_disclosure"):
        return False
    route = plan.get("action_route")
    before = plan.get("before_state")
    if (not isinstance(route, dict) or route.get("mechanism") != "native_structured"
            or not isinstance(before, ScreenState) or before.source != "DOM"):
        return False
    after_payload = observation.get("dom") if isinstance(observation, dict) else None
    if not isinstance(after_payload, dict):
        return False
    after = DOMAXObservationProvider().observe(dom=after_payload)
    values = (
        (receipt.get("before_observation_id"), before.observation_id),
        (receipt.get("before_session_id"), before.session_id),
        (receipt.get("after_observation_id"), after.observation_id),
        (receipt.get("after_session_id"), after.session_id),
        (route.get("observation_id"), before.observation_id),
        (route.get("session_id"), before.session_id),
    )
    if any(not isinstance(given, str) or not given or len(given) > 128 or given != expected
           for given, expected in values):
        return False
    return bool(after.source == "DOM" and before.observation_id != after.observation_id
                and before.session_id == after.session_id)


def _record_approved_routine_attempt_failure(plan: dict[str, Any], receipt: Any,
                                              observation: dict[str, Any]) -> bool:
    if not _native_action_receipt_matches_plan(plan, receipt, observation):
        return False
    candidate_id = plan.get("routine_candidate_id")
    if not isinstance(candidate_id, str) or not candidate_id:
        return False
    store = ProcedureStore(db)
    candidate = store.get(candidate_id)
    if (candidate is None or candidate.status != "CANDIDATE" or candidate.validated
            or not isinstance(candidate.review, dict)
            or candidate.review.get("decision") != "APPROVED"):
        return False
    if (len(candidate.steps) != 1
            or candidate.steps[0].get("tool") != f"olcr.gui.{plan.get('action_kind')}"):
        return False
    recorded = runtime.procedures.record_staged_outcome(
        candidate, {"result": "NOT_CONFIRMED"}, execution_attempted=True)
    if recorded:
        model_telemetry.record_routine_outcome(success=False)
    return recorded


def _approved_routine_action_plan(question: str, observation: dict[str, Any], *,
                                 expected_kind: str) -> dict[str, Any] | None:
    """Use an approved routine only when this request repeats the saved fresh observation exactly."""
    now = time.time()
    world_record = db.load_latest_desktop_world_state(now)
    if not isinstance(world_record, dict) or not isinstance(world_record.get("state"), dict):
        model_telemetry.record_routine_match(0)
        return None
    state = DOMAXObservationProvider().observe(
        dom=observation.get("dom") if isinstance(observation, dict) else None,
        ax=observation.get("ax") if isinstance(observation, dict) else None)
    saved_state = world_record["state"]
    same_ax_target = True
    if state.source == "AX":
        saved_window = saved_state.get("active_window")
        saved_window = saved_window if isinstance(saved_window, dict) else {}
        saved_pid = saved_window.get("application_pid")
        same_ax_target = (
            state.permission_granted is True
            and isinstance(state.application_pid, int)
            and not isinstance(state.application_pid, bool)
            and state.application_pid > 0
            and isinstance(saved_pid, int)
            and not isinstance(saved_pid, bool)
            and saved_pid > 0
            and state.application_pid == saved_pid
            and isinstance(state.application_bundle_id, str)
            and bool(state.application_bundle_id.strip())
            and state.application_bundle_id == saved_window.get("application_bundle_id")
        )
    if (state.source not in {"DOM", "AX"}
            or state.source != saved_state.get("source")
            or state.observation_id != saved_state.get("observation_id")
            or state.session_id != saved_state.get("session_id")
            or state.coordinate_space != saved_state.get("coordinate_space")
            or not same_ax_target
            or list(state.elements) != saved_state.get("ui_elements")):
        model_telemetry.record_routine_match(0)
        return None
    try:
        matches = ProcedureStore(db).match_candidates(question, world_record, now=now)
    except (TypeError, ValueError):
        model_telemetry.record_routine_match(0)
        return None
    if len(matches) != 1:
        model_telemetry.record_routine_match(len(matches))
        return None
    match = matches[0]
    record = db.procedure(str(match.get("procedure_id") or ""))
    captured = record.get("captured_trace") if isinstance(record, dict) else None
    action = captured.get("action") if isinstance(captured, dict) else None
    if not isinstance(action, dict) or action.get("kind") != expected_kind:
        model_telemetry.record_routine_match(0)
        return None
    model_telemetry.record_routine_match(1)
    return plan_approved_routine_action(question, observation, record, match)


request_approvals = RequestApprovals()

@app.middleware("http")
async def gui_session_guard(request: Request, call_next):
    public_player = request.method == 'GET' and re.fullmatch(r'/assistant-player/[A-Za-z0-9_-]{43}', request.url.path)
    if _gui_session_token and request.method != "OPTIONS" and request.url.path != "/api/health" and not public_player:
        if request.headers.get("X-OLCR-Session") != _gui_session_token and not mobile_bridge_access.permits(request):
            return __import__("fastapi").responses.JSONResponse({"detail":"missing or invalid GUI session credential"}, status_code=401)
    approved_request = False
    if settings.permission_level == 'confirm' and requires_request_approval(request.method, request.url.path):
        fingerprint = request_approvals.fingerprint(request.method, str(request.url), await request.body())
        if not request_approvals.consume(request.headers.get('X-OLCR-Approval', ''), fingerprint):
            token = request_approvals.issue(fingerprint)
            return __import__('fastapi').responses.JSONResponse({'detail': {
                'code': 'PERMISSION_CONFIRMATION_REQUIRED', 'approval_id': token,
                'summary': 'OLCRの操作を許可しますか？外部アクセスやファイル変更を含む場合があります。',
            }}, status_code=409)
        approved_request = True
    conversation_id = request.query_params.get("conversation_id")
    project_id = request.query_params.get("project_id")
    if request.method in {"POST", "PUT", "PATCH"} and "application/json" in request.headers.get("content-type", "").lower():
        try:
            request_data = await request.json()
            if isinstance(request_data, dict):
                requested_conversation_id = request_data.get("conversation_id")
                requested_project_id = request_data.get("project_id")
                if isinstance(requested_conversation_id, str) and requested_conversation_id:
                    conversation_id = requested_conversation_id
                if isinstance(requested_project_id, str) and requested_project_id:
                    project_id = requested_project_id
        except (ValueError, AttributeError):
            pass
    project_name = None
    conversation_title = None
    if conversation_id or project_id:
        with db.connect() as connection:
            if conversation_id:
                label = connection.execute("""SELECT c.project_id,c.title,p.name AS project_name
                    FROM conversations c LEFT JOIN projects p ON p.id=c.project_id WHERE c.id=?""",
                    (conversation_id,)).fetchone()
                if label:
                    project_id = label["project_id"]
                    project_name = label["project_name"]
                    conversation_title = label["title"]
            if project_id and not project_name:
                project = connection.execute("SELECT name FROM projects WHERE id=?", (project_id,)).fetchone()
                project_name = project["name"] if project else None
    with traffic_scope(project_id, project_name, conversation_id, conversation_title), response_language_scope(request.headers.get("X-OLCR-Language", "ja")), brain_scope(brain_models.configuration(conversation_id)), observe_model_progress(lambda data:record_model_log(db,conversation_id,data)):
        approval_context = request_approved.set(approved_request)
        try:
            response = await call_next(request)
        except GenerationCancelled:
            raise
        except Exception as exc:
            if request.url.path not in {"/api/chat", "/api/chat/stream", "/api/commands"}:
                raise
            # Keep unexpected failures inside CORS so the desktop receives an
            # HTTP error instead of an opaque fetch TypeError. No prompt/secrets.
            print(f"CHAT_REQUEST_FAILED path={request.url.path} exception={type(exc).__name__}",
                  file=__import__('sys').stderr, flush=True)
            response = __import__('fastapi').responses.JSONResponse({"detail":
                "CHAT_REQUEST_FAILED: " + ("回答処理に失敗しました。もう一度お試しください。"
                if request.headers.get("X-OLCR-Language", "ja") == "ja"
                else "The request could not be completed. Please try again.")}, status_code=500)
        finally:
            request_approved.reset(approval_context)
    if request.headers.get("Access-Control-Request-Private-Network") == "true":
        response.headers["Access-Control-Allow-Private-Network"] = "true"
    return response

# CORS must wrap permission challenges as well as successfully dispatched requests.
