MEMORY_OFF_CONSTRAINT = (
    "[MEMORY_DISABLED]\n"
    "Conversation memory is disabled for this request. Do not claim to remember "
    "or retrieve facts from previous conversations unless they are independently "
    "present in currently available context. If prior-conversation details are "
    "unavailable, say they cannot be verified because conversation memory is "
    "disabled or unavailable. Do not invent replacement facts. Current user "
    "message, core context, and explicitly supplied context remain usable."
)

def conversation_memory_constraint(enabled: bool) -> str:
    return "" if enabled else MEMORY_OFF_CONSTRAINT


def _conversation_memory_context(items: list[dict[str, Any]]) -> str:
    if not items:
        return ""
    # Saved text must not introduce a host context marker such as ACTIVE_SKILL.
    marker_escape = str.maketrans("[]", "［］")
    return "\n\n".join(item["text"][:3000].translate(marker_escape) for item in items)


def _schedule_conversation_memory(conversation_id: str) -> None:
    memory = conversation_memory
    if memory.db.path == db.path:
        memory.schedule_maintenance(conversation_id)


def rebuild(candidate: Settings) -> None:
    global settings,files,vectors,retrieval,runtime,coding_knowledge,laya_provider,_laya_startup_status,_api_embedding_provider
    previous_convert = settings.convert_enabled
    purpose_models.settings = candidate
    purpose_models.downloads.settings = candidate
    if purpose_models.choice('semantic_embedding')['protocol'] != 'preset':
        candidate.embedding_model = purpose_models.namespace()
    elif candidate.embedding_model.startswith('purpose:'):
        candidate.embedding_model = purpose_models.namespace()
    settings=candidate; files=FileRetriever(settings.allowed_roots)
    _api_embedding_provider = purpose_embedding_provider(timeout=5.0)
    vectors=LocalVectorStore(db,purpose_embedding_provider(),settings.embedding_model,settings.allowed_roots) if settings.vector_enabled else DisabledVectorStore()
    retrieval=RetrievalRouter(files,FTSRetriever(db),vectors,settings.vector_enabled,OllamaSemanticRelationEvaluator(settings.ollama_endpoint,settings.semantic_judge_model),OllamaIntentNormalizer(settings.ollama_endpoint,settings.semantic_judge_model),None,settings.reranker_threshold)
    retrieval.graphify = GraphifyRAG(purpose_embedding_provider(timeout=2.0), lambda: laya_provider, settings.embedding_model, settings.graphify_enabled, min_relevance=settings.rag_min_relevance)
    runtime=Runtime(settings,db,retrieval,RoleAwareModelProvider(settings, ModelRegistry(settings.model_manifest_path)),artifacts)
    brain_models.settings = settings
    brain_models.providers.settings = settings
    runtime.model.brain_models = brain_models
    runtime.model.purpose_models = purpose_models
    global conversation_memory
    conversation_memory=ConversationMemory(db, purpose_embedding_provider(), settings.embedding_model, min_relevance=settings.conversation_memory_min_relevance, budget=settings.context_budget // 4, cross_project=settings.conversation_memory_cross_project_enabled)
    coding_knowledge=CodingKnowledge()
    if purpose_models.choice('typed_local_decisions')['protocol'] == 'preset':
        local, _laya_startup_status = _startup_laya_provider(candidate)
    else:
        local = laya_provider.local if isinstance(laya_provider, PurposeDecisionProvider) else laya_provider
    laya_provider = PurposeDecisionProvider(purpose_models, local)
    if previous_convert != candidate.convert_enabled:
        from .conversion_runtime import runtime as conversion_service
        conversion_service.configure(candidate.convert_enabled, prepare=candidate.convert_enabled)


def coding_knowledge_context_for_subtask(request: str, workspace_root: str | None, provider: OllamaEmbeddingProvider | None = None) -> str:
    """Return bounded release knowledge for one phase, or an empty safe fallback.

    This deliberately accepts no project contents or task history.  The
    workspace is consulted only for small dependency manifests when selecting
    stack metadata; no such information is persisted in the knowledge index.
    """
    if provider is None and purpose_models.choice('semantic_embedding')['protocol'] != 'preset':
        result = coding_knowledge.context_for_embedding(request, workspace_root, purpose_embedding_provider(), settings.embedding_model)
        return coding_knowledge.format_context(result)
    provider = provider or OllamaEmbeddingProvider(settings.ollama_endpoint)
    # Do not contact Ollama at all when the immutable release artifact is not
    # installed.  This keeps the existing development fallback fast and
    # ensures Coding Tasks remain usable with KNOWLEDGE_STATUS=NOT_AVAILABLE.
    if not coding_knowledge.index.available:
        print("CODING_KNOWLEDGE_STATUS=NOT_AVAILABLE CODING_KNOWLEDGE_REASON=" + coding_knowledge.index.reason + " CODING_KNOWLEDGE_CORE_RULES=0 CODING_KNOWLEDGE_DETAILED=0 CODING_KNOWLEDGE_RERANKER=NOT_USED", file=__import__("sys").stderr, flush=True)
        return ""
    try:
        identity = provider.model_identity(EXPECTED_EMBEDDING_MODEL)
    except Exception as exc:
        identity = None
        identity_reason = getattr(exc, "category", type(exc).__name__)
    else:
        identity_reason = "AVAILABLE"
    result = coding_knowledge.context_for(request, workspace_root, provider, identity)
    context = coding_knowledge.format_context(result)
    print(
        f"CODING_KNOWLEDGE_STATUS={result.status} CODING_KNOWLEDGE_REASON={result.reason or identity_reason} "
        f"CODING_KNOWLEDGE_CORE_RULES={len(result.core_rules)} CODING_KNOWLEDGE_DETAILED={len(result.records)} "
        "CODING_KNOWLEDGE_RERANKER=NOT_USED",
        file=__import__("sys").stderr, flush=True,
    )
    return context


def purpose_routing_status():
    selected = purpose_models.choice('typed_local_decisions')
    if selected['protocol'] != 'preset':
        return {'status': 'ready' if laya_provider.loaded else 'not_ready',
                'provider': selected['protocol'], 'model': selected['model'],
                'loaded': laya_provider.loaded, 'last_trace': laya_provider.last_trace}
    return laya_preflight(multilingual_model=settings.laya_multilingual_model,
                          english_model=settings.laya_english_model,
                          revision=settings.laya_model_revision,
                          english_revision=settings.laya_english_model_revision,
                          device=settings.laya_device)


