def _interrupted_replan_resume(task: dict[str, Any]) -> bool:
    state = task.get("resume_state") if isinstance(task.get("resume_state"), dict) else {}
    return bool(
        task.get("status") == "RESUMABLE"
        and task.get("recovery_action") == "RECOVERY_REVIEW"
        and task.get("recovery_reason") in {"SCHEDULER", "PAUSED"}
        and str(state.get("continuation_user_revision") or "").strip()
        and state.get("next_task_action") in {"DISPATCH_IMPLEMENTATION", "QWEN_REPLANNING"}
    )


def _supersede_effective_replan_authorization(task: dict[str, Any]) -> bool:
    """Clear only stale ineffective-replan state after current-revision PASS evidence."""
    pending = task.get("pending_authorization")
    if not (isinstance(pending, dict) and pending.get("type") == "REPLAN_INEFFECTIVE"
            and task.get("status") == "RESUMABLE"
            and task.get("recovery_reason") == "COMPLETION_EVIDENCE"):
        return False
    plan = task.get("plan") if isinstance(task.get("plan"), dict) else {}
    phases = [phase for phase in plan.get("phases", []) if isinstance(phase, dict)]
    if not phases or any(phase.get("status") != "pass" for phase in phases):
        return False
    conversation = db.conversation(str(task.get("conversation_id") or "")) or {}
    project = db.project(str(conversation.get("project_id") or "")) or {}
    workspace_root = task_workspaces.service.root_for(task["id"], project.get("workspace_path"))
    revision = int(task.get("plan_revision") or 0)
    if revision <= 0:
        return False
    for phase in phases:
        row = _latest_current_phase_report(str(task.get("id") or ""), str(phase.get("id") or ""), revision)
        if not row or report_has_authoritative_failure(row.get("structured_report") or {}, phase, workspace_root):
            return False
    return True


_coding_resume_lock = threading.RLock()


def _resume_coding_task_control(task: dict, *, source: str) -> dict:
    # UI clicks and chat commands can arrive together. Serialize the small
    # control transition and reload its authoritative state before reserving
    # a retry, so a stale WAITING snapshot cannot reset a dispatched task.
    with _coding_resume_lock:
        current = db.coding_task(task["id"]) or task
        if current.get('console_hidden') and not current.get('archived'):
            current = _persist_coding_console(current,False)
        if (current.get("status") in {"QUEUED", "RUNNING", "PLANNING", "QWEN_REPLANNING", "FINAL_REPORTING"}
                and not current.get("pending_authorization") and not current.get("pending_user_confirmation")):
            return {"conversation_id": current.get("conversation_id"), "coding_task_id": current["id"],
                    "response": "このTaskはすでに実行中または待機中です。", "sources": [],
                    "progress_event": {"type": "coding_task_progress", "origin": "HOST_STATUS",
                                       "task_id": current["id"], "status": current["status"]}}
        return _resume_coding_task_control_locked(current, source=source)


def _resume_coding_task_control_locked(task: dict, *, source: str) -> dict:
    """Queue one persisted task from an explicit, exclusive resume action."""
    pending = task.get("pending_authorization")
    if (task.get("status") == "WAITING_FOR_USER" and not task.get("archived") and isinstance(pending, dict)
            and pending.get("type") == "REPLAN_INEFFECTIVE"):
        if not _record_recovery_model_call(task["id"]):
            db.update_coding_task(task["id"], pending_authorization=None, pending_user_confirmation=0)
            _record_coding_stop(task["id"], "GLOBAL_RECOVERY_LIMIT", False)
            blocked = db.coding_task(task["id"]) or task
            return {"conversation_id": task.get("conversation_id"), "coding_task_id": task["id"],
                    "response": _blocked_task_user_message(blocked), "sources": [],
                    "progress_event": {"type": "coding_task_progress", "origin": "HOST_STATUS",
                                       "task_id": task["id"], "status": "BLOCKED"}}
        # A planner response that left the failing phase unchanged is not a
        # reason to call the planner again with the same requirements. Resume
        # the persisted phase directly; its prior typed report is supplied to
        # the implementer as retry context. This does not mark the phase as
        # complete or grant any additional filesystem scope.
        state = task.get("resume_state") if isinstance(task.get("resume_state"), dict) else {}
        state = {**state, "ineffective_replan_retry_requested": {
            "at": time.time(), "phase_id": task.get("current_phase_id"),
            "plan_revision": int(task.get("plan_revision") or 0),
            "instruction": "Retry the current phase using its saved failure evidence; preserve completed phases and approved scope.",
        }}
        task = db.update_coding_task(task["id"], status="RESUMABLE", activity="NONE",
                                     pending_authorization=None, pending_user_confirmation=0,
                                     recovery_action="RECOVERY_REVIEW", recovery_reason="REPLAN_INEFFECTIVE",
                                     pause_requested=False, resume_state=state) or task
        print(f"TASK_ID={task['id']} INEFFECTIVE_REPLAN_RESUME=PHASE_RETRY "
              f"PHASE_ID={task.get('current_phase_id') or 'UNKNOWN'} "
              "PLANNER_RECALLED=NO PLAN_REVISION_CHANGED=NO SCOPE_EXPANSION=NO",
              file=__import__('sys').stderr, flush=True)
        pending = None
    if _supersede_effective_replan_authorization(task):
        task = db.update_coding_task(task["id"], pending_authorization=None,
                                     pending_user_confirmation=0) or task
        print(f"TASK_ID={task['id']} STALE_REPLAN_AUTHORIZATION_CLEARED=YES "
              "REASON=EFFECTIVE_REPLAN_WITH_CURRENT_PASS_EVIDENCE",
              file=__import__('sys').stderr, flush=True)
        pending = task.get("pending_authorization")
    if isinstance(pending, dict) and pending.get("type") == "USER_REVISION":
        # Older recovery builds stored a task-local revision in the protected-
        # operation authorization slot, which made the scheduler treat the
        # correction itself as an approval gate. Migrate it to resume state;
        # user revisions are not scope or permission grants.
        state = task.get("resume_state") if isinstance(task.get("resume_state"), dict) else {}
        revision = str(pending.get("user_revision") or "")
        if revision:
            state = {**state, "continuation_user_revision": revision}
        task = db.update_coding_task(task["id"], pending_authorization=None,
                                     pending_user_confirmation=0, resume_state=state) or task
        print(f"TASK_ID={task['id']} USER_REVISION_MIGRATED_FROM_AUTHORIZATION=YES "
              "AUTHORIZATION_GATE_CREATED=NO", file=__import__('sys').stderr, flush=True)
    if _interrupted_replan_resume(task):
        task = db.update_coding_task(task["id"], pause_requested=False,
                                     recovery_action="REPLAN_CONTINUATION",
                                     recovery_reason="REPLAN_LIMIT") or task
        print(f"TASK_ID={task['id']} INTERRUPTED_REPLAN_RESUME=AUTHORIZED "
              "SAME_TASK=YES BOUNDED_REPLAN=YES", file=__import__('sys').stderr, flush=True)
    if (task.get("status") == "BLOCKED"
            and task.get("recovery_reason") == "NARRATIVE_ONLY_RETRY_EXHAUSTED"):
        plan = task.get("plan") if isinstance(task.get("plan"), dict) else {}
        artifact = plan.get("implementation_plan_artifact") if isinstance(plan.get("implementation_plan_artifact"), dict) else {}
        raw_manifest = artifact.get("file_manifest") or plan.get("file_manifest") or []
        manifest = [str(item.get("path") or "") if isinstance(item, dict) else str(item)
                    for item in raw_manifest]
        allowed = [str(item) for item in ((plan.get("scope") or {}).get("allowed") or [])]
        requested = []
        for entry in task.get("approved_scopes") or []:
            if isinstance(entry, dict):
                requested.extend(str(item) for item in (entry.get("requested_scope") or entry.get("approved_paths") or []))
        phase_id = str(task.get("current_phase_id") or "")
        phases = [item for item in (plan.get("phases") or []) if isinstance(item, dict)]
        phase = next((item for item in phases if str(item.get("id") or "") == phase_id), None)
        root = str(artifact.get("target_root") or "")
        scope_matches = (
            bool(phase) and bool(root) and Path(root).is_absolute()
            and bool(manifest) and len(manifest) == len(set(manifest))
            and set(manifest) == set(allowed) == set(requested)
            and not task.get("pending_authorization") and not task.get("pending_user_confirmation")
            and not task.get("archived")
        )
        if scope_matches:
            human_epochs = int(task.get("human_recovery_epochs") or 0)
            recovery_calls = int(task.get("task_total_recovery_model_calls") or 0)
            if (human_epochs >= MAX_HUMAN_RECOVERY_REPLAN_EPOCHS
                    or recovery_calls >= TASK_GLOBAL_RECOVERY_MODEL_CALL_LIMIT):
                print(f"TASK_ID={task['id']} EXPLICIT_NARRATIVE_RECOVERY=DENIED "
                      f"HUMAN_RECOVERY_EPOCHS={human_epochs} RECOVERY_MODEL_CALLS={recovery_calls} "
                      "RECOVERY_BUDGET_EXHAUSTED=YES", file=__import__('sys').stderr, flush=True)
                return {"conversation_id": task.get("conversation_id"), "coding_task_id": task["id"],
                        "response": "Coding Task のbounded recovery上限に達しているため再開できません。",
                        "progress_event": {"type": "coding_task_progress", "origin": "HOST_STATUS",
                                           "task_id": task["id"], "status": "BLOCKED"}, "sources": []}
            before_epoch = int(task.get("recovery_epoch") or 0)
            state = task.get("resume_state") if isinstance(task.get("resume_state"), dict) else {}
            state = {**state, "explicit_narrative_recovery_grant": {
                "source": source, "at": time.time(), "reason": "NARRATIVE_ONLY_RETRY_EXHAUSTED",
                "next_recovery_epoch": before_epoch + 1, "manifest_paths": sorted(manifest),
            }}
            phase = {**phase, "status": "pending"}
            updated_phases = [phase if str(item.get("id") or "") == phase_id else item for item in phases]
            progress = task.get("subtask_progress")
            if isinstance(progress, list):
                progress = [{**entry, "status": "WAITING", "verification_status": "UNVERIFIED",
                             "attempt": 0, "started_at": None, "finished_at": None, "failure_summary": None}
                            if isinstance(entry, dict) and str(entry.get("phase_id") or "") == phase_id else entry
                            for entry in progress]
            plan["phases"] = updated_phases
            db.update_coding_task(task["id"], status="RESUMABLE", activity="NONE", queue_order=None,
                                  plan=plan, subtask_progress=progress, retry_count=0,
                                  recovery_action="REPLAN_CONTINUATION",
                                  recovery_reason="NARRATIVE_ONLY_RETRY_EXHAUSTED", resume_state=state)
            task = db.coding_task(task["id"]) or task
            print(f"TASK_ID={task['id']} EXPLICIT_NARRATIVE_RECOVERY=AUTHORIZED "
                  f"RECOVERY_EPOCH_BEFORE={before_epoch} RECOVERY_EPOCH_PENDING={before_epoch + 1} "
                  f"SAME_TASK_ID=YES NEW_TASK_CREATED=NO MANIFEST_PATH_COUNT={len(manifest)}",
                  file=__import__('sys').stderr, flush=True)
        else:
            return _revalidate_blocked_task(task, source=source)
    if (task.get("status") == "RESUMABLE"
            and task.get("recovery_action") == "RECOVERY_REVIEW"
            and task.get("recovery_reason") == "MODEL_CALL"
            and int(task.get("replan_count") or 0) >= TASK_GLOBAL_REPLAN_LIMIT):
        human_epochs = int(task.get("human_recovery_epochs") or 0)
        recovery_calls = int(task.get("task_total_recovery_model_calls") or 0)
        if (human_epochs >= MAX_HUMAN_RECOVERY_REPLAN_EPOCHS
                or recovery_calls >= TASK_GLOBAL_RECOVERY_MODEL_CALL_LIMIT):
            db.update_coding_task(task["id"], status="BLOCKED", activity="NONE", queue_order=None,
                                  recovery_action="NONE", recovery_reason="GLOBAL_RECOVERY_LIMIT")
            blocked = db.coding_task(task["id"]) or task
            print(f"TASK_ID={task['id']} EXPLICIT_MODEL_FAILURE_RESUME=DENIED "
                  f"HUMAN_RECOVERY_EPOCHS={human_epochs} RECOVERY_MODEL_CALLS={recovery_calls} "
                  "AUTO_REQUEUE_AFTER_GLOBAL_LIMIT=NO", file=__import__('sys').stderr, flush=True)
            return {"conversation_id": task.get("conversation_id"), "coding_task_id": task["id"],
                    "response": "Coding Task is blocked: the final bounded recovery budget is exhausted.",
                    "progress_event": {"type": "coding_task_progress", "origin": "HOST_STATUS",
                                       "task_id": task["id"], "status": "BLOCKED"}, "sources": []}
        # An explicit user resume can grant one last bounded planner retry
        # after a recoverable planner/model-call failure. Do not reset task-
        # global counts; only the per-epoch counter is reset below.
        db.update_coding_task(task["id"], recovery_action="REPLAN_CONTINUATION",
                              recovery_reason="REPLAN_LIMIT")
        task = db.coding_task(task["id"]) or task
        print(f"TASK_ID={task['id']} EXPLICIT_MODEL_FAILURE_RESUME=AUTHORIZED "
              f"HUMAN_RECOVERY_EPOCHS={human_epochs} RECOVERY_MODEL_CALLS={recovery_calls} "
              "AUTOMATIC_BUDGET_RESET=NO", file=__import__('sys').stderr, flush=True)
    if str(task.get("status") or "") == "BLOCKED":
        recovery_calls = int(task.get("task_total_recovery_model_calls") or 0)
        same_epoch_continuation = (
            task.get("recovery_reason") == "GLOBAL_RECOVERY_LIMIT"
            and int(task.get("human_recovery_epochs") or 0) >= MAX_HUMAN_RECOVERY_REPLAN_EPOCHS
            and int(task.get("recovery_epoch") or 0) > 0
            and int(task.get("replan_count_in_epoch") or 0) > 0
            and int(task.get("replan_count") or 0) < _task_global_replan_limit(task)
            and recovery_calls < TASK_GLOBAL_RECOVERY_MODEL_CALL_LIMIT
            and int(task.get("task_total_plan_repair_count") or 0) < TASK_GLOBAL_PLAN_REPAIR_LIMIT
        )
        if same_epoch_continuation:
            db.update_coding_task(task["id"], status="RESUMABLE", activity="NONE", queue_order=None,
                                  recovery_action="REPLAN_CONTINUATION", recovery_reason="REPLAN_LIMIT")
            task = db.coding_task(task["id"]) or task
            print(f"TASK_ID={task['id']} EXPLICIT_SAME_EPOCH_REPLAN_CONTINUATION=AUTHORIZED "
                  f"RECOVERY_EPOCH={task.get('recovery_epoch', 0)} "
                  f"REPLAN_COUNT_IN_EPOCH={task.get('replan_count_in_epoch', 0)} "
                  f"RECOVERY_MODEL_CALLS={recovery_calls} SAME_TASK_ID=YES",
                  file=__import__('sys').stderr, flush=True)
        else:
        # An explicit human resume can authorize one more finite epoch after
        # either the global replan budget or the no-progress guard blocked the
        # task. The per-task human-epoch cap still applies, and this branch is
        # reachable only from an explicit resume command.
            if (task.get("recovery_reason") in {"GLOBAL_RECOVERY_LIMIT", "NO_PROGRESS"}
                    and int(task.get("replan_count") or 0) >= TASK_GLOBAL_REPLAN_LIMIT
                    and int(task.get("human_recovery_epochs") or 0) < MAX_HUMAN_RECOVERY_REPLAN_EPOCHS):
                db.update_coding_task(task["id"], status="RESUMABLE", activity="NONE", queue_order=None,
                                      recovery_action="REPLAN_CONTINUATION", recovery_reason="REPLAN_LIMIT")
                task = db.coding_task(task["id"]) or task
                print(f"TASK_ID={task['id']} EXPLICIT_HUMAN_GLOBAL_REPLAN_RECOVERY=AUTHORIZED "
                      f"HUMAN_RECOVERY_EPOCHS={task.get('human_recovery_epochs', 0)} "
                      "AUTOMATIC_BUDGET_RESET=NO", file=__import__('sys').stderr, flush=True)
            else:
                return _revalidate_blocked_task(task, source=source)
    if not resumable_continuation_eligible(task):
        raise HTTPException(409, "task is not safely resumable or requires authorization")
    task_id = task["id"]
    if (task.get("status") == "RESUMABLE"
            and task.get("recovery_action") == "REPLAN_CONTINUATION"
            and task.get("recovery_reason") == "REPLAN_VALIDATION"
            and int(task.get("task_total_recovery_model_calls") or 0) >= TASK_GLOBAL_RECOVERY_MODEL_CALL_LIMIT):
        resume_state = task.get("resume_state") if isinstance(task.get("resume_state"), dict) else {}
        revision = str(resume_state.get("continuation_user_revision") or "")
        if _deterministic_verifier_recovery_plan(task, revision) is not None:
            task = db.update_coding_task(task_id, recovery_reason="REPLAN_LIMIT") or task
            print(f"TASK_ID={task_id} EXHAUSTED_MODEL_BUDGET_DETERMINISTIC_REPLAN=ELIGIBLE "
                  "SOURCE=EXPLICIT_USER_REVISION MODEL_CALLS_ADDED=0",
                  file=__import__('sys').stderr, flush=True)
    if task.get("recovery_reason") == "PLAN_MANIFEST_REPAIR_NO_PROGRESS":
        # An unchanged failed repair has no new information to consume.  An
        # explicit Resume must not replay the same model repair or emit the
        # same pause message a second time.
        print(f"TASK_ID={task_id} RESUME_REQUEST_SOURCE={source} RESUME_SAME_TASK=NO "
              "RESUME_REQUESTED=true RESUME_ACCEPTED=false "
              "RECOVERY_REASON=PLAN_MANIFEST_REPAIR_NO_PROGRESS "
              "NEXT_TASK_ACTION=NONE NORMAL_BRAIN_INVOKED=NO "
              "DUPLICATE_PAUSE_MESSAGE_SUPPRESSED=YES",
              file=__import__('sys').stderr, flush=True)
        return {"conversation_id": task.get("conversation_id"), "coding_task_id": task_id,
                "response": "", "progress_event": {"type": "coding_task_progress", "origin": "HOST_STATUS",
                                                      "task_id": task_id, "status": "RESUMABLE"},
                "sources": []}
    if task.get('status')=='RESUMABLE' and task.get('recovery_reason')=='VERIFICATION_CONTRACT_INVALID':
        state=dict(task.get('resume_state') or {})
        state['verification_retry_epoch']=min(
            int(state.get('verification_retry_epoch') or 0)+1,
            VERIFICATION_MAX_SAME_SOURCE_MANUAL_RETRIES)
        task=db.update_coding_task(task_id,resume_state=state) or task
    replan_epoch_resume = _begin_human_recovery_epoch(task)
    current = db.coding_task(task_id)
    queued = current
    if current and current.get("status") != "BLOCKED":
        queued = db.enqueue_coding_task(task_id)
        _coding_scheduler_wake.set()
    accepted = bool(queued and queued.get("status") == "QUEUED")
    after_status = queued.get("status", "UNKNOWN") if queued else "UNKNOWN"
    phase_before = task.get("current_phase_id") or ((task.get("batch_handoff") or {}).get("next_phase_id") if isinstance(task.get("batch_handoff"), dict) else None)
    phase_after = queued.get("current_phase_id") if queued else phase_before
    print(
        f"TASK_ID={task_id} RESUME_REQUEST_SOURCE={source} "
        f"RESUME_SAME_TASK=YES RESUME_REQUESTED=true "
        f"RESUME_ACCEPTED={'true' if accepted else 'false'} "
        f"STATUS_BEFORE_RESUME={task.get('status','UNKNOWN')} STATUS_AFTER_RESUME={after_status} "
        f"ORIGINAL_CANONICAL_REQUIREMENTS_PRESERVED=YES "
        f"CONTINUATION_INPUT_SEPARATED=YES CODING_CONTEXT_SIGNAL=RESUMED_CODING_TASK "
        f"NORMAL_BRAIN_INVOKED=NO USER_VISIBLE_MESSAGE_EMITTED_AFTER_RESUME=NO "
        f"RECOVERY_ACTION={task.get('recovery_action','NONE')} "
        f"RECOVERY_REASON={task.get('recovery_reason','NONE')} "
        f"RECOVERY_EPOCH={queued.get('recovery_epoch',0) if queued else task.get('recovery_epoch',0)} "
        f"REPLAN_COUNT_FOR_NEW_EPOCH={queued.get('replan_count_in_epoch','unchanged') if queued else 'unchanged'} "
        f"PHASE_CURSOR_BEFORE_RESUME={phase_before or 'NONE'} PHASE_CURSOR_AFTER_RESUME={phase_after or 'NONE'} "
        f"GREENFIELD_INIT_REENTERED_AFTER_COMPLETION=NO "
        f"NEXT_TASK_ACTION={'QUEUE_FIFO' if replan_epoch_resume else 'NONE'}",
        file=__import__('sys').stderr, flush=True)
    return {"conversation_id": task.get("conversation_id"), "coding_task_id": task_id,
            "response": "" if accepted else _blocked_task_user_message(queued or task),
            "progress_event": {"type": "coding_task_progress", "origin": "HOST_STATUS",
                                "task_id": task_id, "status": after_status},
            "sources": []}


def _completed_task_false_pass_evidence(task: dict) -> dict[str, Any] | None:
    """Identify the narrow false-pass where empty manifested files run zero tests."""
    if str(task.get("status") or "") != "COMPLETED":
        return None
    plan = task.get("active_plan") if isinstance(task.get("active_plan"), dict) else task.get("plan")
    manifest = plan.get("file_manifest") if isinstance(plan, dict) else None
    manifest_paths = {str(item.get("path") or "").replace("\\", "/").lstrip("./")
                      for item in (manifest or []) if isinstance(item, dict) and item.get("path")}
    if not manifest_paths:
        return None
    reports = db.coding_phase_reports(str(task.get("id") or ""))
    for row in reversed(reports):
        report = row.get("structured_report") if isinstance(row.get("structured_report"), dict) else {}
        typed = report.get("typed_execution_summary") if isinstance(report.get("typed_execution_summary"), dict) else {}
        operations = [item for item in (typed.get("operations") or []) if isinstance(item, dict)]
        zero_write_targets = [
            str(item.get("input", {}).get("path") or "").replace("\\", "/").lstrip("./")
            for item in operations
            if item.get("tool") == "workspace_write"
            and isinstance(item.get("output"), dict)
            and int(item["output"].get("bytes", -1)) == 0
        ]
        zero_written_paths = {
            manifest_path for manifest_path in manifest_paths
            if any(target == manifest_path or target.endswith("/" + manifest_path)
                   for target in zero_write_targets)
        }
        zero_test_verifications = [
            item for item in operations
            if item.get("tool") == "verification_command"
            and isinstance(item.get("output"), dict)
            and int(item["output"].get("returncode", -1)) == 0
            and re.search(r"\bRan\s+0\s+tests?\b", str(item["output"].get("output") or ""), re.IGNORECASE)
        ]
        if (str(report.get("status") or "").upper() == "PASS"
                and zero_test_verifications
                and manifest_paths.issubset(zero_written_paths)):
            return {"phase_id": str(row.get("phase_id") or ""),
                    "attempt": int(row.get("attempt") or 0),
                    "manifest_paths": sorted(manifest_paths),
                    "zero_written_paths": sorted(zero_written_paths),
                    "zero_test_verification_count": len(zero_test_verifications)}
    return None


def _reopen_completed_task_for_verified_false_pass(task: dict, *, source: str) -> dict:
    """Queue the same task for one user-authorized repair of a proven false pass."""
    evidence = _completed_task_false_pass_evidence(task)
    if evidence is None:
        return {"conversation_id": task.get("conversation_id"), "coding_task_id": task.get("id"),
                "response": "完了済みCoding Taskに再実装可能なゼロ件テスト誤判定の証拠がありません。",
                "sources": []}
    task_id = str(task["id"])
    human_epochs = int(task.get("human_recovery_epochs") or 0)
    recovery_calls = int(task.get("task_total_recovery_model_calls") or 0)
    if human_epochs >= MAX_HUMAN_RECOVERY_REPLAN_EPOCHS or recovery_calls >= TASK_GLOBAL_RECOVERY_MODEL_CALL_LIMIT:
        return {"conversation_id": task.get("conversation_id"), "coding_task_id": task_id,
                "response": "Coding Task の bounded recovery 上限に達しているため再実装できません。",
                "sources": []}
    before_epoch = int(task.get("recovery_epoch") or 0)
    state = task.get("resume_state") if isinstance(task.get("resume_state"), dict) else {}
    state = {**state, "last_verified_false_pass_reopen": {
        "source": source, "at": time.time(), "phase_id": evidence["phase_id"],
        "attempt": evidence["attempt"], "manifest_paths": evidence["manifest_paths"],
        "zero_written_paths": evidence["zero_written_paths"],
        "zero_test_verification_count": evidence["zero_test_verification_count"],
        "next_recovery_epoch": before_epoch + 1,
    }}
    db.update_coding_task(task_id, status="RESUMABLE", activity="NONE", queue_order=None,
                          current_phase_id=evidence["phase_id"], retry_count=0,
                          recovery_epoch=before_epoch + 1,
                          human_recovery_epochs=human_epochs + 1,
                          replan_count_in_epoch=0,
                          recovery_action="VERIFIED_FALSE_PASS_REPAIR",
                          recovery_reason="ZERO_TEST_VERIFICATION",
                          resume_state=state)
    queued = db.enqueue_coding_task(task_id)
    _coding_scheduler_wake.set()
    accepted = bool(queued and queued.get("status") == "QUEUED")
    print(f"TASK_ID={task_id} VERIFIED_FALSE_PASS_REOPEN=YES SOURCE={source} "
          f"RECOVERY_EPOCH_BEFORE={before_epoch} RECOVERY_EPOCH_AFTER={before_epoch + 1} "
          f"HUMAN_RECOVERY_EPOCHS={human_epochs + 1} MANIFEST_PATH_COUNT={len(evidence['manifest_paths'])} "
          f"SAME_TASK_ID=YES NEW_TASK_CREATED=NO QUEUED={'YES' if accepted else 'NO'} "
          "NORMAL_RUNTIME_FALLBACK=false RESPONSE_OWNER=CODING_ORCHESTRATOR",
          file=__import__('sys').stderr, flush=True)
    return {"conversation_id": task.get("conversation_id"), "coding_task_id": task_id,
            "response": "" if accepted else "同じCoding Taskをキューへ戻せませんでした。",
            "progress_event": {"type": "coding_task_progress", "origin": "HOST_STATUS",
                               "task_id": task_id, "status": queued.get("status") if queued else "UNKNOWN"},
            "sources": []}


def _requeue_authorized_false_pass_epoch(task: dict, *, source: str) -> dict:
    """Continue the already-authorized epoch if stale PASS evidence short-circuited it."""
    task_id = str(task.get("id") or "")
    state = task.get("resume_state") if isinstance(task.get("resume_state"), dict) else {}
    marker = state.get("last_verified_false_pass_reopen") if isinstance(state, dict) else None
    epoch = int(task.get("recovery_epoch") or 0)
    if (task.get("status") not in {"COMPLETED", "RESUMABLE"} or not isinstance(marker, dict)
            or int(marker.get("next_recovery_epoch", -1)) != epoch):
        return {"conversation_id": task.get("conversation_id"), "coding_task_id": task_id,
                "response": "このCoding Taskに継続可能な承認済みrecovery epochがありません。", "sources": []}
    phase_id = str(marker.get("phase_id") or "")
    current_reports = _phase_reports_for_epoch(task_id, phase_id, int(task.get("plan_revision") or 0), epoch)
    if (current_reports and (task.get("status") != "RESUMABLE"
            or (current_reports[-1].get("structured_report") or {}).get("manager_decision", {}).get("decision") != "RETRY"
            or len(current_reports) > int((task.get("plan") or {}).get("max_retries_per_phase", 2)))):
        return {"conversation_id": task.get("conversation_id"), "coding_task_id": task_id,
                "response": "承認済みrecovery epochの実行記録から安全なbounded retryを確認できません。", "sources": []}
    plan = json.loads(json.dumps(task.get("plan") or {}))
    if not any(item.get("id") == phase_id for item in plan.get("phases", []) if isinstance(item, dict)):
        return {"conversation_id": task.get("conversation_id"), "coding_task_id": task_id,
                "response": "承認済みrecovery epochのphaseを特定できません。", "sources": []}
    if task.get("status") == "COMPLETED":
        plan = _phase_status(plan, phase_id, "pending")
    progress = task.get("subtask_progress")
    if isinstance(progress, list) and task.get("status") == "COMPLETED":
        progress = [{**entry, "status": "WAITING", "verification_status": "UNVERIFIED",
                     "attempt": 0, "started_at": None, "finished_at": None, "failure_summary": None}
                    if isinstance(entry, dict) and entry.get("phase_id") == phase_id else entry
                    for entry in progress]
    db.update_coding_task(task_id, status="RESUMABLE", activity="NONE", queue_order=None,
                          plan=plan, subtask_progress=progress, current_phase_id=phase_id,
                          retry_count=int(task.get("retry_count") or 0), recovery_action="VERIFIED_FALSE_PASS_REPAIR",
                          recovery_reason="ZERO_TEST_VERIFICATION")
    queued = db.enqueue_coding_task(task_id)
    _coding_scheduler_wake.set()
    accepted = bool(queued and queued.get("status") == "QUEUED")
    print(f"TASK_ID={task_id} VERIFIED_FALSE_PASS_EPOCH_CONTINUED=YES SOURCE={source} "
          f"RECOVERY_EPOCH={epoch} NEW_EPOCH_CREATED=NO SAME_TASK_ID=YES "
          f"CURRENT_EPOCH_REPORTS={len(current_reports)} SAME_EPOCH_RETRY={'YES' if bool(current_reports) else 'NO'} "
          f"PHASE_RESET={'YES' if task.get('status') == 'COMPLETED' else 'NO'} QUEUED={'YES' if accepted else 'NO'}",
          file=__import__('sys').stderr, flush=True)
    return {"conversation_id": task.get("conversation_id"), "coding_task_id": task_id,
            "response": "既に承認された同じrecovery epochを継続し、同じ4ファイル範囲で再実装をキューへ追加しました。" if accepted else "同じCoding Taskをキューへ戻せませんでした。",
            "progress_event": {"type": "coding_task_progress", "origin": "HOST_STATUS",
                               "task_id": task_id, "status": queued.get("status") if queued else "UNKNOWN"},
            "sources": []}


@app.patch("/api/coding-tasks/{task_id}")
def update_coding_task(task_id: str, value: CodingTaskUpdate):
    task=db.coding_task(task_id)
    if not task: raise HTTPException(404,"coding task not found")
    updates={}
    if value.pause_requested is not None: updates["pause_requested"]=value.pause_requested
    if value.archived is not None:
        updates["archived"]=value.archived
        if value.archived and task["status"] in {"QUEUED", "PLANNING", "RUNNING", "FINAL_REPORTING"}:
            updates["pause_requested"] = True
    if value.resume:
        if updates: db.update_coding_task(task_id,**updates)
        result = _resume_coding_task_control(task, source="EXPLICIT_GUI_RESUME_ACTION")
        return {**(db.coding_task(task_id) or result),
                "control_response": str(result.get("response") or "")}
    if value.pause_requested is True:
        if task['status'] not in {'RUNNING','PLANNING','FINAL_REPORTING','QWEN_REPLANNING'}:
            db.dequeue_coding_task(task_id)
        result=db.update_coding_task(task_id,pause_requested=True,archived=updates.get("archived",task.get("archived")),recovery_action="RECOVERY_REVIEW",recovery_reason="PAUSED")
        cancel_coding_generation(task_id)
        if result and result['status'] == 'RESUMABLE':
            _record_coding_stop(task_id, 'PAUSED', True)
        return result
    if value.archived is True and task["status"] == "QUEUED":
        db.dequeue_coding_task(task_id)
    result=db.update_coding_task(task_id,**updates)
    if value.pause_requested is False: _coding_scheduler_wake.set()
    return result

@app.get("/api/coding-tasks/{task_id}/phase-reports")
def coding_task_phase_reports(task_id: str):
    if not db.coding_task(task_id): raise HTTPException(404,"coding task not found")
    return {"reports":db.coding_phase_reports(task_id)}

@app.get("/api/coding-tasks/{task_id}/telemetry")
def coding_task_telemetry(task_id: str):
    if not db.coding_task(task_id): raise HTTPException(404, "coding task not found")
    return db.coding_telemetry(task_id) or {"task_id": task_id, "status": "NOT_AVAILABLE"}

@app.get("/api/coding-tasks/{task_id}")
def get_coding_task(task_id: str):
    task=db.coding_task(task_id)
    if not task: raise HTTPException(404,"coding task not found")
    task["queue_position"]=db.coding_task_queue_position(task_id)
    return task

def _record_coding_stop(task_id: str, reason: str, intended: bool) -> str:
    task = db.coding_task(task_id)
    if not task: return ''
    reports=db.coding_phase_reports(task_id)
    snapshot = stop_progress(task, reports, reason, intended)
    return db.persist_coding_stop(task_id,snapshot,len(reports))


def _pause_at_checkpoint(task_id: str) -> bool:
    task=db.coding_task(task_id)
    if not task or task.get("pause_requested") or task.get("archived"):
        if task:
            db.update_coding_task(task_id,status="RESUMABLE",activity="NONE",queue_order=None,recovery_action="RECOVERY_REVIEW",recovery_reason="PAUSED")
            _record_coding_stop(task_id, 'PAUSED', True)
        print(f"TASK_ID={task_id} PAUSE_REQUESTED=true TASK_STATUS=RESUMABLE",file=__import__('sys').stderr,flush=True)
        return True
    return False

def _transition_resumable(task_id: str, failure_stage: str, failure_class: str, recovery_action: str = "RECOVERY_REVIEW", exc: Exception | None = None, recovery_reason: str | None = None) -> None:
    before=db.coding_task(task_id) or {}
    if not before or before.get('status') == 'COMPLETED' or before.get('archived'):
        print(f'TASK_ID={task_id} RECOVERY_TRANSITION=SKIPPED STATUS={before.get("status","MISSING")} '
              f'ARCHIVED={bool(before.get("archived"))}',file=__import__('sys').stderr,flush=True)
        return
    if before.get('pause_requested'):
        db.update_coding_task(task_id,status='RESUMABLE',activity='NONE',queue_order=None,recovery_reason='PAUSED')
        _record_coding_stop(task_id, 'PAUSED', True)
        return
    reason=recovery_reason or failure_stage
    telemetry_snapshot = "NOT_PRESENT"
    if task_id in _coding_telemetry:
        try:
            _persist_coding_telemetry_snapshot(task_id)
            telemetry_snapshot = "PERSISTED"
        except Exception as telemetry_exc:
            telemetry_snapshot = "FAILED"
            print(f"TASK_ID={task_id} RECOVERY_TELEMETRY_SNAPSHOT={telemetry_snapshot} "
                  f"ERROR_TYPE={type(telemetry_exc).__name__}",
                  file=__import__('sys').stderr, flush=True)
    db.update_coding_task(task_id,status="RESUMABLE",activity="NONE",queue_order=None,recovery_action=recovery_action,recovery_reason=reason)
    _record_coding_stop(task_id, 'MODEL_TIMEOUT' if getattr(exc, 'category', None) == 'timeout' else reason, False)
    print(f"TASK_ID={task_id} STATUS_BEFORE={before.get('status','UNKNOWN')} ACTIVITY_BEFORE={before.get('activity','UNKNOWN')} FAILURE_STAGE={failure_stage} FAILURE_CLASS={failure_class} EXCEPTION_TYPE={type(exc).__name__ if exc else 'NONE'} RECOVERY_ACTION={recovery_action} RECOVERY_REASON={reason} RECOVERY_TELEMETRY_SNAPSHOT={telemetry_snapshot} STATUS_AFTER=RESUMABLE",file=__import__('sys').stderr,flush=True)

def _begin_human_recovery_epoch(task: dict) -> bool:
    """Grant one fresh automatic-replan budget only for an explicit Resume.

    The task remains the source of truth; callers must enqueue it after this
    transition.  Other resumable reasons retain their existing epoch/budget.
    """
    if task.get("recovery_action") != "REPLAN_CONTINUATION":
        return False
    human_epochs = int(task.get("human_recovery_epochs") or 0)
    state = task.get("resume_state") if isinstance(task.get("resume_state"), dict) else {}
    narrative_grant = state.get("explicit_narrative_recovery_grant") if isinstance(state, dict) else None
    is_narrative_grant = (
        task.get("recovery_reason") == "NARRATIVE_ONLY_RETRY_EXHAUSTED"
        and isinstance(narrative_grant, dict)
        and int(narrative_grant.get("next_recovery_epoch", -1)) == int(task.get("recovery_epoch") or 0) + 1
    )
    if task.get("recovery_reason") != "REPLAN_LIMIT" and not is_narrative_grant:
        return False
    resume_state = task.get("resume_state") if isinstance(task.get("resume_state"), dict) else {}
    revision = str(resume_state.get("continuation_user_revision") or "")
    deterministic_fallback_available = (
        int(task.get("task_total_recovery_model_calls") or 0) >= TASK_GLOBAL_RECOVERY_MODEL_CALL_LIMIT
        and _deterministic_verifier_recovery_plan(task, revision) is not None
    )
    same_epoch_continuation = (
        task.get("recovery_reason") == "REPLAN_LIMIT"
        and int(task.get("human_recovery_epochs") or 0) >= MAX_HUMAN_RECOVERY_REPLAN_EPOCHS
        and int(task.get("recovery_epoch") or 0) > 0
        and int(task.get("replan_count_in_epoch") or 0) > 0
        and int(task.get("replan_count") or 0) < _task_global_replan_limit(task)
        and ((int(task.get("task_total_recovery_model_calls") or 0) < TASK_GLOBAL_RECOVERY_MODEL_CALL_LIMIT
              and int(task.get("task_total_plan_repair_count") or 0) < TASK_GLOBAL_PLAN_REPAIR_LIMIT)
             or deterministic_fallback_available)
    )
    if same_epoch_continuation:
        print(f"TASK_ID={task['id']} SAME_HUMAN_EPOCH_CONTINUATION=YES "
              f"RECOVERY_EPOCH={task.get('recovery_epoch', 0)} "
              f"REPLAN_COUNT_IN_EPOCH={task.get('replan_count_in_epoch', 0)} "
              "BOUNDED_COUNTERS_RESET=NO", file=__import__('sys').stderr, flush=True)
        return True
    if ((is_narrative_grant or int(task.get("replan_count") or 0) >= TASK_GLOBAL_REPLAN_LIMIT)
            and human_epochs >= MAX_HUMAN_RECOVERY_REPLAN_EPOCHS) or \
            int(task.get("task_total_recovery_model_calls") or 0) >= TASK_GLOBAL_RECOVERY_MODEL_CALL_LIMIT:
        db.update_coding_task(task["id"], status="BLOCKED", activity="NONE", queue_order=None,
                              recovery_action="NONE", recovery_reason="GLOBAL_RECOVERY_LIMIT")
        print(f"TASK_ID={task['id']} TASK_GLOBAL_BOUND_ENFORCED=YES AUTO_REQUEUE_AFTER_GLOBAL_LIMIT=NO "
              "GLOBAL_LIMIT_KIND=REPLAN STATUS_AFTER=BLOCKED", file=__import__('sys').stderr, flush=True)
        return False
    grant_human_epoch = is_narrative_grant or int(task.get("replan_count") or 0) >= TASK_GLOBAL_REPLAN_LIMIT
    db.update_coding_task(task["id"], recovery_epoch=int(task.get("recovery_epoch") or 0) + 1,
                          replan_count_in_epoch=0,
                          human_recovery_epochs=human_epochs + (1 if grant_human_epoch else 0))
    return True


def _task_global_replan_limit(task: dict) -> int:
    """Base task budget plus the one explicitly granted human recovery epoch."""
    extra_epochs = min(int(task.get("human_recovery_epochs") or 0), MAX_HUMAN_RECOVERY_REPLAN_EPOCHS)
    return TASK_GLOBAL_REPLAN_LIMIT + extra_epochs * MAX_SUBSTANTIAL_REPLANS_PER_TASK


def _record_recovery_model_call(task_id: str, *, repair: bool = False) -> bool:
    """Reserve one recovery model call before making it."""
    task = db.coding_task(task_id) or {}
    calls = int(task.get("task_total_recovery_model_calls") or 0)
    repairs = int(task.get("task_total_plan_repair_count") or 0)
    if calls >= TASK_GLOBAL_RECOVERY_MODEL_CALL_LIMIT or (repair and repairs >= TASK_GLOBAL_PLAN_REPAIR_LIMIT):
        db.update_coding_task(task_id, status="BLOCKED", activity="NONE", queue_order=None,
                              recovery_action="NONE", recovery_reason="GLOBAL_RECOVERY_LIMIT")
        print(f"TASK_ID={task_id} TASK_GLOBAL_BOUND_ENFORCED=YES AUTO_REQUEUE_AFTER_GLOBAL_LIMIT=NO "
              f"GLOBAL_LIMIT_KIND={'PLAN_REPAIR' if repair else 'RECOVERY_MODEL_CALL'} STATUS_AFTER=BLOCKED",
              file=__import__('sys').stderr, flush=True)
        return False
    updates = {"task_total_recovery_model_calls": calls + 1}
    if repair:
        updates["task_total_plan_repair_count"] = repairs + 1
    db.update_coding_task(task_id, **updates)
    return True

def _telemetry_role(activity: str) -> str:
    """Map a task activity to its model-call role for telemetry only."""
    if activity == "QWEN_PLANNING":
        return "PLANNER"
    if activity == "QWEN_REPLANNING":
        return "REPLANNER"
    if "PLAN_SCHEMA_REPAIR" in activity:
        return "PLAN_REPAIR"
    if "REPORT_SCHEMA_REPAIR" in activity:
        return "REPORT_SCHEMA_REPAIR"
    if "REVIEW" in activity:
        return "SEMANTIC_VERIFICATION"
    return "OTHER_CODING"

def _telemetry_provenance(model: str, role: str) -> dict[str, Any]:
    return _coding_model_provenance(model, role)


def _coding_phase_model(phase: dict[str, Any], phase_request: str = "", task_goal: str = "",
                        task_size: str = "", *, repairing_verification: bool = False) -> str:
    """Select the implementation role before the model invocation boundary."""
    explicit = str(phase.get("model_role") or "").strip()
    if explicit in {"role:planner_replanner", "role:short_coding_fix_debug", "role:long_implementation"}:
        return explicit
    # Planning may paraphrase a short repair as neutral implementation work
    # (for example, "Add the missing import"). Keep the original user intent
    # in the deterministic role selector without resending it to the model.
    # The prompt contains policy and retry text that can mention multiple
    # model roles.  It is not user intent.  Only the persisted phase goal and
    # original task goal are authoritative for role directives.
    role_text = " ".join((str(phase.get("goal") or ""), task_goal)).lower()
    if re.search(r"\blong_implementation\b|\blong[- ]implementation(?: role)?\b", role_text):
        return settings.long_implementation_model
    if re.search(r"\bshort_coding_fix_debug\b|\bshort[- ]coding[- ]fix(?:[- ]debug)?\b", role_text):
        return settings.short_coding_model
    # A failed executable check is typed evidence of a repair stage. The
    # original task being a new app must not keep its debugging calls on the
    # long implementation role. Explicit human role choices above still win.
    if repairing_verification:
        return settings.short_coding_model
    # Runtime instructions and retry diagnoses often contain generic words
    # such as "fix" or "repair" even when the task is a long implementation.
    # Only use task-authored text for this heuristic; otherwise the selected
    # role can change between the preflight log and the actual model call.
    # Test-remediation clauses in a new-app request ("fix failing tests")
    # do not turn the entire initial implementation into a small repair.
    new_project = bool(re.search(r'空のプロジェクト|新規.{0,30}(?:アプリ|プロジェクト|web)|'
        r'\b(?:create|build|develop)\b.{0,60}\b(?:app|application|project|website)\b',task_goal,re.I))
    task_text = " ".join((str(phase.get("goal") or ""), '' if new_project else task_goal)).lower()
    if re.search(r"\b(fix|debug|repair|bug|regression|failing|broken|hotfix|correct)\b|修正|不具合|デバッグ|修復", task_text):
        return settings.short_coding_model
    # The deterministic continuation policy is authoritative for small tasks;
    # planner paraphrases must not silently send bounded work to the long model.
    if str(task_size).upper() == "SMALL":
        return settings.short_coding_model
    return settings.long_implementation_model


def _alternate_coding_model(previous_model: str, conversation_id: str | None = None) -> str | None:
    """Return a distinct configured coding model for one bounded repair handoff."""
    def identity(model: str) -> str | None:
        value=str(model or "").strip()
        if not value.startswith("role:"):
            return value or None
        try:
            configuration=brain_models.configuration(conversation_id)
            return brain_models.selected_model_for_role(value.removeprefix("role:"),configuration)
        except Exception:
            return None

    previous_identity=identity(previous_model)
    if not previous_identity:
        return None
    for candidate in (settings.short_coding_model,settings.long_implementation_model):
        candidate_identity=identity(candidate)
        if candidate_identity and candidate_identity!=previous_identity:
            return candidate
    return None


def coding_debug_reference_context(task: dict, phase: dict | None = None, diagnostics=None) -> str:
    """Optional evidence only; no repair budgets, approval, or scopes change."""
    enabled = capability_enabled(settings, "external_access_enabled") and settings.coding_stackoverflow_enabled
    forbidden = set((task.get('requirements') or {}).get('forbidden_capabilities') or [])
    no_network = re.search(r'\b(?:no\s+(?:network|internet|web)|offline[- ]only|do not (?:search|access the internet))\b|オフライン|(?:外部通信|ネットワーク|インターネット)(?:アクセス|接続|通信)?(?:を|は)?(?:禁止|使わない|使用しない|利用しない)',
                           str(task.get('original_goal') or ''), re.I)
    enabled = enabled and not no_network and not bool(forbidden & {'network','web','external_access','external_tools','web_search'})
    if not enabled:
        return ''
    try:
        if diagnostics is None:
            reports = db.coding_phase_reports(task['id']) if task.get('id') else []
            diagnostics = [row.get('structured_report', {}) for row in reports[-2:]]
        result = stackoverflow_debug.lookup(task.get('original_goal',''), (phase or {}).get('goal',''), diagnostics, enabled=enabled)
        print(f"TASK_ID={task.get('id','UNKNOWN')} CODING_STACKOVERFLOW_STATUS={result['status']} "
              f"CODING_STACKOVERFLOW_REFERENCES={len(result.get('references',[]))} "
              f"CODING_STACKOVERFLOW_CACHED={'YES' if result.get('cached') else 'NO'}", file=__import__('sys').stderr, flush=True)
        return stackoverflow_debug.context(result)
    except Exception:
        print('CODING_STACKOVERFLOW_STATUS=UNAVAILABLE', file=__import__('sys').stderr, flush=True)
        return ''


@unbounded_inference()
@inference_timeout(MODEL_REQUEST_TIMEOUT_SECONDS)
def _model_text(task_id: str, status: str, activity: str, model: str, messages: list[dict], structured_schema: dict | None = None) -> str | None:
    if _pause_at_checkpoint(task_id): return None
    if activity in {'QWEN_PLANNING', 'QWEN_REPLANNING'}:
        instructions = task_workspaces.service.instruction_context(task_id)
        if instructions and messages:
            messages = [*messages[:-1], {**messages[-1], 'content': messages[-1]['content'] + "\n[USER_TASK_INSTRUCTIONS]\n" + instructions}]
        reference = coding_debug_reference_context(db.coding_task(task_id) or {})
        if reference:
            messages = [*messages[:-1], {**messages[-1], 'content': messages[-1]['content'] + reference}]
    if structured_schema and 'phases' in structured_schema.get('properties',{}):
        from .concept_diagrams import ConceptDiagram, diagram_output_instruction
        design_goal=str((db.coding_task(task_id) or {}).get('original_goal') or '')
        if re.search(r'概念図|構成図|図解|concept\s+diagram|architecture\s+diagram|diagram.*(?:plan|system)', design_goal, re.I):
            diagram_schema=ConceptDiagram.model_json_schema()
            definitions=diagram_schema.pop('$defs',{})
            diagram_schema['properties']['schema_version']={'type':'integer','const':2}
            structured_schema={**structured_schema,'properties':{**structured_schema['properties'],'concept_diagram':diagram_schema},'$defs':{**structured_schema.get('$defs',{}),**definitions}}
            messages=[*messages,{'role':'system','content':'For this system-design request, include a concept_diagram object in the plan. It depicts the proposed system components and relationships, not the execution phases. Use the concept_diagram schema: version 2, at most 12 readable nodes with finite absolute positions and sizes, optional parent_id only for fully contained subordinate concepts below the parent title area. Mark directed edges with arrow_end/arrow_start. Keep this object inside the plan JSON; no Markdown fences. The diagram grants no mutation scope or approval.'}]
    db.update_coding_task(task_id,status=status,activity=activity)
    print(f"TASK_ID={task_id} TASK_STATUS={status} TASK_ACTIVITY={activity} MODEL_SLOT_OWNER={task_id} MODEL_NAME={model}",file=__import__('sys').stderr,flush=True)
    role = _telemetry_role(activity)
    provenance = _telemetry_provenance(model, role)
    boundary = InvocationBoundary(task_id, str((db.coding_task(task_id) or {}).get("current_phase_id") or ""))
    boundary.stop(); boundary.commit_evidence(); boundary.checkpoint()
    print(f"TASK_ID={task_id} MODEL_INVOCATION_BOUNDARY=STOP_EVIDENCE_CHECKPOINT MODEL_HANDOFF_ALLOWED=YES SAME_TASK_ID={task_id}", file=__import__('sys').stderr, flush=True)
    _record_coding_model_progress(task_id,{"state":"slot_waiting"})
    with _coding_task_traffic_scope(task_id), brain_scope(brain_models.configuration((db.coding_task(task_id) or {}).get("conversation_id"))), model_slot():
        _record_coding_model_progress(task_id,{"state":"slot_acquired"})
        started = time.perf_counter()
        model_provider = getattr(runtime, "model", None)
        generate = getattr(model_provider, "generate", None)
        from .thinking import decide_thinking, configured_thinking_mode
        from .brain_models import active_configuration
        policy_text=str((db.coding_task(task_id) or {}).get('original_goal') or '')
        policy_role=model.removeprefix('role:') if model.startswith('role:') else 'normal_chat'
        decision=decide_thinking(configured_thinking_mode(active_configuration(),policy_role),
                                 policy_text,structured=structured_schema is not None,role=policy_role)
        internal_contract=activity=='VERIFICATION_CONTRACT' and structured_schema is not None
        if internal_contract:
            decision={**decision,'enabled':False,'reason':'internal_verification_contract'}
            options={'think':False,'thinking_text':policy_text,'force_no_thinking':True}
        else:
            options=({'think':None,'thinking_text':policy_text}
                     if getattr(model_provider,'handles_thinking_policy',False) is True
                     else {'think':decision['enabled']})
        if structured_schema is not None:
            options['format']=structured_schema
            # Structured coding responses are executable source operations and
            # often contain several complete file edits. The old 8K ceiling
            # truncated otherwise successful implementation calls, after
            # which provider failover could not repair the partial JSON.
            # Keep plans and verification contracts bounded separately.
            options['max_tokens']=8192
            schema_properties=structured_schema.get('properties',{})
            if {'operations','edits'} & set(schema_properties):
                options['max_tokens']=16384
            elif 'phases' in schema_properties:
                # A multi-file plan repeats requirements, scope and phase
                # contracts; keep its cap finite and independent of chat.
                options['max_tokens']=8192
        try:
            if callable(generate):
                parameters=inspect.signature(generate).parameters
                if not any(p.kind == inspect.Parameter.VAR_KEYWORD for p in parameters.values()):
                    options={key:value for key,value in options.items() if key in parameters}
        except (TypeError,ValueError):
            pass
        model_progress_snapshot={}
        def record_model_progress(data):
            model_progress_snapshot.update(data)
            _record_coding_model_progress(task_id,data)
        try:
            from .model_progress import observe_model_progress
            with observe_model_progress(record_model_progress):
                if not callable(generate):
                    raise ModelFailure('unavailable','Selected coding model provider is unavailable')
                raw=generate(messages,model,**options)
        except Exception as exc:
            telemetry = _coding_telemetry.setdefault(task_id, CodingTelemetry(task_id, model_name=model))
            telemetry.add_call(phase_id=(db.coding_task(task_id) or {}).get("current_phase_id"), role=role, model=model, messages=messages, result=None,
                               started=time.time() - (time.perf_counter() - started), finished=time.time(), structured=structured_schema is not None, thinking=decision['enabled'], success=False, failure_class=type(exc).__name__, model_provenance=provenance)
            current=db.coding_task(task_id) or {}
            cancelled=isinstance(exc,GenerationCancelled) or bool(current.get('pause_requested') or current.get('archived'))
            failure=('cancelled' if cancelled else getattr(exc,'category',None) or
                     ('timeout' if isinstance(exc,(TimeoutError,)) else 'provider_unavailable'))
            terminal={'state':'request_cancelled' if cancelled else 'request_failed',
                      'model':model_progress_snapshot.get('model') or model,
                      'runtime':model_progress_snapshot.get('runtime'),
                      'failure':failure}
            if model_progress_snapshot.get('invocation_id'):
                terminal['invocation_id']=model_progress_snapshot['invocation_id']
            _record_coding_model_progress(task_id,terminal)
            raise
    telemetry = _coding_telemetry.setdefault(task_id, CodingTelemetry(task_id, model_name=model))
    telemetry.add_call(phase_id=(db.coding_task(task_id) or {}).get("current_phase_id"), role=role, model=model, messages=messages,
                       result=raw if isinstance(raw, dict) else None, started=time.time() - (time.perf_counter() - started), finished=time.time(),
                       structured=structured_schema is not None, thinking=(raw.get('thinking_decision') or decision).get('enabled') if isinstance(raw,dict) else decision['enabled'], success=isinstance(raw, dict), failure_class="NONE" if isinstance(raw, dict) else "INVALID_RESPONSE", model_provenance=provenance)
    boundary.finalize_telemetry()
    print(f"TASK_ID={task_id} MODEL_INVOCATION_BOUNDARY_TELEMETRY_FINALIZED=YES MODEL_HANDOFF_NEXT_REQUIRES_NEW_INVOCATION=YES", file=__import__('sys').stderr, flush=True)
    print(f"TASK_ID={task_id} CODING_TELEMETRY_CALL=RECORDED CODING_TELEMETRY_ROLE={role} MODEL_CALL_COUNT={telemetry.record['model_call_count']}", file=__import__('sys').stderr, flush=True)
    if structured_schema is not None and isinstance(raw,dict):
        directory=Path(db.path).resolve().parent/'coding-model-responses'
        directory.mkdir(parents=True,exist_ok=True)
        (directory/(uuid.uuid4().hex+'.json')).write_text(json.dumps({
            'task_id':task_id,'stage':activity,'requested_model':model,
            'response':raw.get('text',''),'finish_reason':raw.get('finish_reason'),
            'completion_tokens':raw.get('completion_tokens'),'prompt_tokens':raw.get('prompt_tokens')},ensure_ascii=False),encoding='utf8')
    return raw.get("text","") if isinstance(raw,dict) else ""

def _record_coding_model_progress(task_id,data):
    verification_progress=_CODING_VERIFICATION_PROGRESS.get()
    if verification_progress:
        data={**verification_progress,**data}
    if data.get('state')!='reasoning':
        kind='MODEL_INVOCATION' if data.get('state') in {'request_started','request_failed','request_completed','request_cancelled'} else 'MODEL_PROGRESS'
        db.record_coding_event(task_id,kind,data)
    record_model_log(db,(db.coding_task(task_id) or {}).get('conversation_id'),data)


def _coding_task_traffic_scope(task_id: str):
    task = db.coding_task(task_id) or {}
    conversation_id = task.get('conversation_id')
    project_id = None
    project_name = None
    conversation_title = None
    if conversation_id:
        with db.connect() as connection:
            row = connection.execute("""SELECT c.project_id,c.title,p.name AS project_name
                FROM conversations c LEFT JOIN projects p ON p.id=c.project_id WHERE c.id=?""",
                (conversation_id,)).fetchone()
        if row:
            project_id, conversation_title, project_name = row['project_id'], row['title'], row['project_name']
    return traffic_scope(project_id, project_name, conversation_id, conversation_title)


def _finish_coding_telemetry(task_id: str, verify_status: str = "UNKNOWN") -> None:
    telemetry=_coding_telemetry.get(task_id)
    if telemetry is None:
        return
    record=telemetry.finish(verify_status)
    db.save_coding_telemetry(task_id, record)
    _coding_telemetry.pop(task_id, None)
    print(f"TASK_ID={task_id} CODING_TELEMETRY_FINISHED=YES MODEL_CALL_COUNT={record['model_call_count']} TOTAL_TASK_MS={record['total_task_ms']:.2f} INPUT_TOKENS_TOTAL={record['input_tokens_total']} OUTPUT_TOKENS_TOTAL={record['output_tokens_total']}", file=__import__('sys').stderr, flush=True)

def _persist_coding_telemetry_snapshot(task_id: str) -> None:
    telemetry=_coding_telemetry.get(task_id)
    if telemetry is not None and db.coding_task(task_id):
        db.save_coding_telemetry(task_id, telemetry.record)

def _phase_status(plan: dict, phase_id: str, status: str) -> dict:
    revised=json.loads(json.dumps(plan))
    for item in revised.get("phases",[]):
        if item.get("id")==phase_id: item["status"]=status
    return revised

_SUBTASK_STATES={"WAITING","RUNNING","DONE","FAILED","PARTIAL"}
_SUBTASK_VERIFICATION={"PASS","FAILED","NOT_RUN","UNVERIFIED"}

def _subtask_entries(plan: dict, prior: list[dict] | None = None, completed_phase_ids: set[str] | None = None) -> list[dict] | None:
    """Create only plan-explicit graph records; legacy plans remain absent."""
    tasks=plan.get("tasks") if isinstance(plan,dict) else None
    phases={phase.get("id") for phase in plan.get("phases",[]) if isinstance(phase,dict)} if isinstance(plan,dict) else set()
    if not isinstance(tasks,list) or not tasks or any(not isinstance(item,dict) or item.get("phase_id") not in phases for item in tasks):
        return None
    prior_by_id={str(item.get("task_id")):item for item in (prior or []) if isinstance(item,dict)}
    completed_phase_ids=completed_phase_ids or set()
    entries=[]
    for graph_task in tasks:
        task_id=str(graph_task["task_id"]); phase_id=str(graph_task["phase_id"]); old=prior_by_id.get(task_id)
        if old and old.get("phase_id")==phase_id and phase_id in completed_phase_ids and old.get("status")=="DONE":
            entries.append(old)
        else:
            entries.append({"task_id":task_id,"phase_id":phase_id,"status":"WAITING","verification_status":"UNVERIFIED","attempt":0,"started_at":None,"finished_at":None,"failure_summary":None})
    return entries

def _initialize_subtask_progress(task_id: str, plan: dict, *, preserve: bool = False, completed_phase_ids: set[str] | None = None) -> None:
    current=db.coding_task(task_id) or {}
    same_schedule=preserve and completed_phase_ids is None
    if same_schedule:
        completed_phase_ids={phase['id'] for phase in plan.get('phases',[]) if phase.get('status')=='pass'}
    entries=_subtask_entries(plan,current.get("subtask_progress") if preserve else None,completed_phase_ids)
    if entries is not None and preserve:
        prior={entry['task_id']:entry for entry in current.get('subtask_progress') or []}
        reports=None
        for index,entry in enumerate(entries):
            old=prior.get(entry['task_id'])
            if (same_schedule and old and old.get('phase_id')==entry['phase_id']
                    and (old.get('status')!='DONE' or entry['phase_id'] in (completed_phase_ids or set()))):
                entries[index]=entry=copy.deepcopy(old)
            if entry['phase_id'] in (completed_phase_ids or set()) and entry['status']!='DONE':
                # Restore controller-verified phases even if an older retry
                # incorrectly cleared their graph rows. A model plan's pass
                # label alone cannot manufacture completion evidence.
                if reports is None:
                    reports=db.coding_phase_reports(task_id)
                saved=next((row for row in reversed(reports)
                    if row.get('phase_id')==entry['phase_id'] and row.get('validation_status')=='PASS'
                    and (row.get('structured_report') or {}).get('manager_decision',{}).get('decision')=='PASS'),None)
                if saved:
                    entries[index]={**entry,'status':'DONE','verification_status':_subtask_verification(saved['structured_report'],'PASS'),
                        'attempt':saved['attempt'],'finished_at':saved.get('created_at'),'failure_summary':None}
    db.update_coding_task(task_id,subtask_progress=entries)

def _subtask_verification(report: dict | None, decision: str | None = None) -> str:
    if not isinstance(report,dict): return "UNVERIFIED"
    if report.get("status") in {"FAIL","BLOCKED"} or report.get("errors") or report.get("blockers") or report.get("test_fail") or report.get("build_pass")=="FAIL": return "FAILED"
    if decision=="PASS": return "PASS"
    if report.get("status")=="NOT_RUN" or report.get("build_executed")=="NOT_RUN" or report.get("build_pass")=="NOT_RUN": return "NOT_RUN"
    return "PASS" if decision=="PASS" else "UNVERIFIED"

def _set_subtask_state(task_id: str, phase_id: str, status: str, *, attempt: int | None = None, report: dict | None = None, decision: str | None = None) -> None:
    """Persist a phase-bound graph state at the existing scheduler boundary."""
    if status not in _SUBTASK_STATES: raise ValueError("invalid subtask status")
    task=db.coding_task(task_id) or {}; entries=task.get("subtask_progress")
    if not isinstance(entries,list): return
    matches=[entry for entry in entries if isinstance(entry,dict) and entry.get("phase_id")==phase_id]
    if len(matches)!=1: return
    if status=="RUNNING" and any(entry.get("status")=="RUNNING" and entry.get("phase_id")!=phase_id for entry in entries if isinstance(entry,dict)):
        raise RuntimeError("multiple running subtasks are not permitted")
    now=time.time(); entry=matches[0]; updated={**entry,"status":status}
    if attempt is not None: updated["attempt"]=attempt
    if status=="RUNNING": updated["started_at"]=entry.get("started_at") or now; updated["finished_at"]=None
    if status in {"DONE","FAILED","PARTIAL"}: updated["finished_at"]=now
    if status=="DONE": updated["verification_status"]=_subtask_verification(report,decision); updated["failure_summary"]=None
    elif status in {"FAILED","PARTIAL"}:
        updated["verification_status"]=_subtask_verification(report,decision)
        details=report or {}
        failed_tests=[failure.get('name') for operation in (details.get('typed_execution_summary') or {}).get('operations') or []
            for run in (operation.get('output') or {}).get('test_runs') or [] for failure in run.get('failures') or [] if failure.get('name')]
        summary=(', '.join(failed_tests) if failed_tests else
            next((str(values[0]) for key in ("errors","blockers","test_fail") if isinstance((values:=details.get(key)),list) and values),""))
        updated["failure_summary"]=summary[:500] or None
    progress=[updated if item is entry else item for item in entries]
    db.update_coding_task(task_id,subtask_progress=progress)

def _typed_summary(execution: Task) -> dict:
    operations=[]
    failure_class = "UNKNOWN"
    worktree_state = "UNKNOWN"
    attempted_mutations = 0
    accepted_mutations = 0
    rejected_mutations = 0
    rolled_back_mutations = 0
    written_paths: list[str] = []
    rejected_signals: list[dict[str, str]] = []
    preimage_diagnostics: list[dict[str, Any]] = []
    package_install_evidence: list[dict[str, Any]] = []
    package_install_requested = False
    package_install_authorized = False
    package_install_process_started = False
    package_install_exit_code: int | None = None
    package_install_status = "NOT_RUN"
    successful_operation_count = 0
    unchanged_operation_count = 0
    net_changed_paths: set[str] = set()
    operation_diagnostics: list[dict[str, Any]] = []
    net_observation_seen = False
    for item in execution.tool_executions:
        operations.append({"tool":item.get("tool"),"status":item.get("status"),"input":item.get("input"),"output":item.get("output"),"error":item.get("error")})
        tool = str(item.get("tool") or "")
        status = str(item.get("status") or "").lower()
        if status in {"success", "completed", "ok"} and tool not in {"operation_preflight", "workspace_write_normalized"}:
            successful_operation_count += 1
        if tool in {"operation_preflight", "workspace_write", "workspace_write_normalized", "workspace_patch", "workspace_delete", "workspace_remove", "write_text", "package_install", "operation_rejection"}:
            attempted_mutations += 1 if tool != "operation_preflight" or status != "pass" else 0
        # ``workspace_write_normalized`` is a contract-normalization event,
        # not an additional filesystem mutation.  Count only the tool event
        # that actually changed the worktree so scaffold/accepted/rollback
        # evidence remains one operation per write.
        if tool in {"workspace_write", "workspace_patch", "workspace_delete", "workspace_remove", "write_text"} and status in {"success", "completed", "ok"}:
            accepted_mutations += 1
            output = item.get("output") if isinstance(item.get("output"), dict) else {}
            path = output.get("path") or (item.get("input") or {}).get("path")
            if isinstance(path, str) and path.strip():
                written_paths.append(path.strip())
            if output.get("net_changed") is False:
                net_observation_seen = True
                unchanged_operation_count += 1
            elif output.get("net_changed") is True:
                net_observation_seen = True
                net_changed_paths.add(str(path).strip())
        if tool in {"package_install", "package_install_evidence"}:
            package_install_requested = True
            output = item.get("output") if isinstance(item.get("output"), dict) else {}
            if tool == "package_install_evidence":
                for evidence in output.get("evidence") or []:
                    if isinstance(evidence, dict):
                        package_install_evidence.append(dict(evidence))
                if str(output.get("status") or "").upper() == "PASS":
                    package_install_status = "PASS"
                package_install_authorized = True
                package_install_process_started = package_install_process_started or any(
                    evidence.get("process_started") is True for evidence in (output.get("evidence") or []) if isinstance(evidence, dict))
                continue
            package_install_authorized = status in {"success", "completed", "ok"} or str(output.get("failure_class") or "") not in {
                "PACKAGE_NOT_AUTHORIZED", "PACKAGE_SPEC_INVALID", "PACKAGE_LIST_INVALID"}
            package_install_process_started = package_install_process_started or output.get("process_started") is True
            if output.get("exit_code") is not None:
                package_install_exit_code = output.get("exit_code")
            package_install_status = "PASS" if status in {"success", "completed", "ok"} and output.get("exit_code") == 0 else "FAIL"
            if status not in {"success", "completed", "ok"}:
                failure_class = str(output.get("failure_class") or failure_class)
            if status in {"success", "completed", "ok"}:
                accepted_mutations += 1
                written_paths.extend([str(path) for path in ("package.json",) if output.get("package_json_after", {}).get("exists")])
            if output:
                package_install_evidence.append(dict(output))
        if tool == "operation_rejection" or status in {"rejected", "denied", "forbidden_by_user", "permission_denied"}:
            rejected_mutations += 1
            input_value = item.get("input") if isinstance(item.get("input"), dict) else {}
            output = item.get("output") if isinstance(item.get("output"), dict) else {}
            rejected_signals.append({
                "category": str(input_value.get("failure_class") or "REJECTED_OPERATION"),
                "path": str(input_value.get("path") or "UNKNOWN"),
                "reason": str(output.get("failure") or item.get("error") or "rejected")[:300],
                "semantic_field": str(output.get("semantic_field") or input_value.get("semantic_field") or ""),
                "owner": str(output.get("owner") or input_value.get("owner") or ""),
                "package_install_status": str(output.get("package_install_status") or ""),
                "dependencies_already_satisfied": output.get("dependencies_already_satisfied"),
                "failure_fingerprint": str(output.get("failure_fingerprint") or input_value.get("failure_fingerprint") or ""),
            })
        if tool == "operation_application_failure":
            output = item.get("output") or {}
            if isinstance(output.get("operation_diagnostic"), dict):
                operation_diagnostics.append(dict(output["operation_diagnostic"]))
            failure_class = str((item.get("input") or {}).get("failure_class") or failure_class)
            worktree_state = str(output.get("worktree_state") or worktree_state)
            if worktree_state == "ROLLED_BACK":
                rolled_back_mutations = max(rolled_back_mutations, accepted_mutations)
                accepted_mutations = 0
                written_paths = []
                net_changed_paths.clear()
        if tool == "preimage_diagnostic" and isinstance(item.get("output"), dict):
            preimage_diagnostics.append(dict(item["output"]))
    if rejected_signals and failure_class == "UNKNOWN":
        failure_class = rejected_signals[-1]["category"]
    mutation_classification = ("ROLLED_BACK" if worktree_state == "ROLLED_BACK" else
                                "NET_CHANGED" if net_changed_paths else
                                "IDEMPOTENT_NOOP" if net_observation_seen and unchanged_operation_count else
                                "NO_OPERATION_EVIDENCE" if not operations else "ACCEPTED_NO_NET_OBSERVATION")
    return {"state":execution.state.value,"error":execution.error,"operations":operations,
            "failure_class":failure_class,"worktree_state":worktree_state,
            "attempted_mutations":attempted_mutations,
            "accepted_mutations":accepted_mutations,
            "rejected_mutations":rejected_mutations,
            "files_written":len(set(written_paths)),
            "written_paths":sorted(set(written_paths)),
            "rejected_operations":rejected_signals,
            "preimage_diagnostics":preimage_diagnostics,
            "package_install_evidence": package_install_evidence,
            "package_install_requested": package_install_requested,
            "package_install_authorized": package_install_authorized,
            "package_install_process_started": package_install_process_started,
            "package_install_exit_code": package_install_exit_code,
            "package_install_status": package_install_status,
            "rolled_back_mutations":rolled_back_mutations,
            "successful_operation_count": successful_operation_count,
            "unchanged_operation_count": unchanged_operation_count,
            "net_changed_paths": sorted(net_changed_paths) if net_observation_seen else sorted(set(written_paths)),
            "net_changed_mutation_count": len(net_changed_paths) if net_observation_seen else len(set(written_paths)),
            "operation_diagnostics": operation_diagnostics[:8],
            "mutation_classification": mutation_classification,
            "final_worktree_mutations": len(net_changed_paths) if net_observation_seen else len(set(written_paths)),
            "phase_progress":bool(net_changed_paths or (accepted_mutations and not net_observation_seen)
                                   or package_install_status == "PASS")}


def _phase_execution_expectations(phase: dict) -> dict:
    """Return the scheduler contract, preferring explicit phase metadata.

    New plans carry ``execution_mode``.  Legacy persisted plans do not, so
    they retain the previous conservative behavior and can never gain the
    verification-only elision accidentally.
    """
    explicit_mode = phase.get("execution_mode") if isinstance(phase, dict) else None
    verification_required=bool(phase.get('verify') or phase.get('verification_command')
        or phase.get('host_verification') or explicit_mode in {'IMPLEMENTATION_AND_VERIFICATION','VERIFICATION_ONLY'})
    if explicit_mode is not None:
        errors = phase_execution_contract_errors(phase)
        if explicit_mode not in PHASE_EXECUTION_MODES or errors:
            return {
                "execution_mode": explicit_mode,
                "execution_mode_source": "EXPLICIT_PHASE_FIELD",
                "execution_mode_valid": False,
                "execution_mode_errors": errors or ["invalid phase execution_mode"],
                "requires_repo_mutation": True,
                "requires_tool_execution": True,
                "requires_verification": verification_required,
                "read_only_allowed": False,
            }
        mutation = explicit_mode in {"IMPLEMENTATION", "IMPLEMENTATION_AND_VERIFICATION"}
        return {
            "execution_mode": explicit_mode,
            "execution_mode_source": "EXPLICIT_PHASE_FIELD",
            "execution_mode_valid": True,
            "execution_mode_errors": [],
            "requires_repo_mutation": mutation,
            "requires_tool_execution": mutation,
            "requires_verification": verification_required,
            "read_only_allowed": explicit_mode == "VERIFICATION_ONLY",
        }
    phase_text = " ".join([str(phase.get("goal") or ""),
                            *map(str, phase.get("done") or []),
                            *map(str, phase.get("verify") or [])])
    verification = bool(re.search(
        r"(?:browser|visual|manual|verification|verify|test|pytest|check)"
        r"|(?:ブラウザ|視覚|手動|検証|確認|テスト)", phase_text, re.I))
    mutation = bool(re.search(
        r"\b(?:implement|create|build|write|edit|modify|modified|update|updated|fix|fixed|correct|corrected|patch|delete|remove|add|change|changed)\b"
        r"|(?:実装|作成|構築|書込|編集|変更|修正|更新|削除|追加)", phase_text, re.I))
    # A phase whose observable work is only test/verification work is a
    # read-only phase.  This generic distinction is independent of fixture
    # filenames and prevents a verification target from becoming a write
    # target merely because a planner used it in a phase description.
    read_only = phase.get("kind") == "ORCHESTRATOR_BLUEPRINT" or (verification and not mutation)
    return {
        "execution_mode": None,
        "execution_mode_source": "LEGACY_TEXT_HEURISTIC",
        "execution_mode_valid": False,
        "execution_mode_errors": [],
        "requires_repo_mutation": not read_only,
        "requires_tool_execution": not read_only,
        "requires_verification": verification_required,
        "read_only_allowed": read_only,
    }


def _approved_scope_paths(scopes: list[Any] | None) -> list[str]:
    """Flatten persisted scope entries without changing their authority."""
    paths: list[str] = []
    for scope in scopes or []:
        values = scope.get("requested_scope", []) if isinstance(scope, dict) else scope
        if isinstance(values, str):
            values = [values]
        if isinstance(values, (list, tuple, set)):
            for value in values:
                normalized = _normalize_scope_path(value)
                if normalized and normalized not in paths:
                    paths.append(normalized)
    return paths


def _read_only_context(workspace_root: str | None, approved_scopes: list[Any] | None) -> dict[str, Any]:
    """Describe readable files separately from the writable implementation scope."""
    if not workspace_root:
        return {"access": "READ_ONLY", "paths": []}
    root = Path(workspace_root).expanduser().resolve()
    allowed = _approved_scope_paths(approved_scopes)
    paths: list[str] = []
    try:
        candidates = sorted(path for path in root.rglob("*") if path.is_file())
    except OSError:
        candidates = []
    for path in candidates:
        relative = path.relative_to(root).as_posix()
        if relative == ".benchmark_metadata.json":
            continue
        if any(relative == item.rstrip("/") or relative.startswith(item.rstrip("/") + "/") for item in allowed):
            continue
        paths.append(relative)
    return {"access": "READ_ONLY", "paths": paths[:200]}


def _verification_spec(phase: dict, workspace_root: str | None) -> dict[str, Any] | None:
    """Return a trusted read-only verification command, when one is available.

    Production tasks may provide ``verification_command`` directly.  The
    benchmark harness persists the same generic contract in
    ``.benchmark_metadata.json``.  Planner prose is never treated as an
    executable command.
    """
    if not workspace_root:
        return None
    command = phase.get("verification_command")
    targets = phase.get("verification_targets")
    metadata: dict[str, Any] = {}
    if workspace_root:
        metadata_path = Path(workspace_root).expanduser().resolve() / ".benchmark_metadata.json"
        try:
            loaded = json.loads(metadata_path.read_text(encoding="utf-8"))
            if isinstance(loaded, dict):
                metadata = loaded
        except (OSError, ValueError, TypeError):
            pass
    if command is None:
        command = metadata.get("verify_command")
    if targets is None:
        targets = metadata.get("verification_targets")
    command = normalized_verification_argv(command)
    if command is None:
        return None
    if not isinstance(targets, (list, tuple)) or not targets:
        return None
    executable = Path(command[0]).name.lower()
    if executable in {"sh", "bash", "zsh", "fish", "cmd", "powershell", "pwsh"} and any(
            argument.lower() in {"-c", "/c", "-command", "-encodedcommand"} for argument in command[1:]):
        return None
    root = Path(workspace_root).expanduser().resolve()
    normalized_targets: list[str] = []
    for item in targets:
        raw = str(item).replace("\\", "/").strip()
        if not raw:
            return None
        supplied = Path(raw).expanduser()
        if supplied.is_absolute():
            target = supplied.resolve()
            try:
                relative = PurePosixPath(target.relative_to(root).as_posix())
            except ValueError:
                return None
        else:
            while raw.startswith("./"):
                raw = raw[2:]
            relative = PurePosixPath(raw)
            if relative.is_absolute() or ".." in relative.parts:
                return None
            target = (root / Path(*relative.parts)).resolve()
        try:
            target.relative_to(root)
        except ValueError:
            return None
        if not target.is_file():
            return None
        normalized_targets.append(relative.as_posix())
    normalized_command = [item.strip() for item in command]
    if normalized_command[0]=='node':
        # GUI backends need not inherit a shell's Node PATH. Prefer the same
        # packaged executable used by OLCR's acceptance runner.
        from .node_mcp_runtime import runtime_root
        if node_resources:=runtime_root():
            normalized_command[0]=str(node_resources/'node/bin/node')
    # macOS installations commonly provide ``python3`` without a ``python``
    # alias. Resolve only a bare missing ``python`` executable; explicit paths
    # and all other argv remain untouched, and no shell is introduced.
    if (Path(normalized_command[0]).name.lower() == "python"
            and normalized_command[0] == Path(normalized_command[0]).name
            and shutil.which(normalized_command[0]) is None):
        python3 = shutil.which("python3")
        if python3:
            normalized_command[0] = python3
    verification_cwd = root
    # A bounded unittest invocation such as ``python -m unittest test_foo``
    # imports ``test_foo`` as a top-level module. If its explicitly listed
    # verification target is nested one directory below the project root,
    # execute from that target directory (but only when every bounded target
    # is a sibling there). Dotted package selectors retain the project root.
    try:
        module_flag = normalized_command.index("-m")
        if normalized_command[module_flag + 1] == "unittest":
            selectors = [item for item in normalized_command[module_flag + 2:]
                         if not item.startswith("-")]
            if len(selectors) == 1 and "." not in selectors[0] and ":" not in selectors[0]:
                selector = selectors[0]
                matching = [PurePosixPath(item) for item in normalized_targets
                            if PurePosixPath(item).stem == selector]
                if len(matching) == 1:
                    candidate_parent = matching[0].parent
                    if all(PurePosixPath(item).parent == candidate_parent for item in normalized_targets):
                        candidate = (root / Path(*candidate_parent.parts)).resolve()
                        candidate.relative_to(root)
                        if candidate.is_dir():
                            verification_cwd = candidate
    except (ValueError, IndexError, OSError):
        verification_cwd = root
    return {"command": normalized_command,
            "targets": list(dict.fromkeys(normalized_targets)),
            "cwd": str(verification_cwd),
            "source": "PHASE_CONTRACT" if phase.get("verification_command") is not None else "WORKSPACE_VERIFICATION_CONTRACT"}


def _workspace_scope_contract(workspace_root: str | None) -> dict[str, list[str]]:
    """Load a trusted generic writable/read-only file-role contract."""
    if not workspace_root:
        return {"write_allowed": [], "read_only": []}
    metadata_path = Path(workspace_root).expanduser().resolve() / ".benchmark_metadata.json"
    try:
        metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
    except (OSError, ValueError, TypeError):
        return {"write_allowed": [], "read_only": []}
    if not isinstance(metadata, dict):
        return {"write_allowed": [], "read_only": []}
    allowed = metadata.get("allowed_mutation") or metadata.get("target_files") or []
    read_only = metadata.get("verification_targets") or []
    def normalize(values: Any) -> list[str]:
        if isinstance(values, str): values = [values]
        normalized = []
        for value in (values or []):
            raw = str(value).replace("\\", "/").strip()
            if not raw:
                continue
            value = raw.lstrip("./") or "."
            normalized.append(value)
        return list(dict.fromkeys(normalized))
    return {"write_allowed": normalize(allowed), "read_only": normalize(read_only)}


def _bind_scope_contract(plan: dict, contract: dict[str, list[str]]) -> dict:
    """Bind planner output to a pre-existing task file-role contract."""
    allowed = list(contract.get("write_allowed") or [])
    if not allowed:
        return plan
    scope = dict(plan.get("scope") or {})
    forbidden = list(scope.get("forbidden") or [])
    for path in contract.get("read_only") or []:
        if path not in forbidden:
            forbidden.append(path)
    def writable(path: Any) -> bool:
        candidate = str(path or "").replace("\\", "/").lstrip("./")
        return any(item in {"", "."} or candidate == item.rstrip("/") or candidate.startswith(item.rstrip("/") + "/") for item in allowed)
    # Keep the planner's typed manifest/task graph consistent with the trusted
    # contract.  Verification files remain phase evidence and are never
    # represented as mutation entries.
    manifest = [entry for entry in (plan.get("file_manifest") or [])
                if isinstance(entry, dict) and writable(entry.get("path"))]
    tasks = []
    for item in (plan.get("tasks") or []):
        if not isinstance(item, dict):
            continue
        tasks.append({**item, "change_scope": [path for path in (item.get("change_scope") or []) if writable(path)]})
    bound = {**plan, "scope": {**scope, "allowed": allowed, "forbidden": forbidden},
             "file_manifest": manifest, "tasks": tasks}
    print(f"PLANNER_SCOPE_CONTRACT_BOUND=YES WRITABLE_TARGET_COUNT={len(allowed)} READ_ONLY_TARGET_COUNT={len(contract.get('read_only') or [])}", file=__import__('sys').stderr, flush=True)
    return bound


def _selection_exclusion_spec(original: str, criteria: dict, sources: dict) -> dict | None:
    """Enable observed selection diagnostics for simple synchronous line lists."""
    scripts=[source for name,source in sources.items() if name.endswith(('.js','.mjs','.cjs'))
             and not re.search(r'(?:^|[/.])(?:test|spec)(?:[/.])|\.(?:test|spec)\.',name)]
    if (not re.search(r'1行に1つ|一行に一つ|one .{0,24}per line|one per line',original,re.I)
            or any(re.search(r'\b(?:async|setTimeout|setInterval|requestAnimationFrame)\b',source) for source in scripts)
            or not any('.filter(Boolean)' in source and re.search(r"\.split\s*\(\s*(['\"])\\n\1\s*\)",source) for source in scripts)):
        return None
    identifiers=[]
    prefix='In the browser, verify the original requirement:'
    for identifier,text in criteria.items():
        body=text.removeprefix(prefix).strip()
        if not text.startswith(prefix) or body not in original:
            continue
        if (re.search(r'consecutive|連続',body,re.I) and re.search(r'same|repeat|同じ|直前|前回',body,re.I)
                and re.search(r'avoid|without|\bno\b|\bnot\b|ない|避ける|避けたい|防ぐ',body,re.I)
                and re.search(r'\b(?:two|2)\b|2[つ件個]|二[つ件個]',body,re.I)
                and not re.search(r'no need|避けなく|連続.{0,12}(?:構わ|かまわ|許容|てもよい|てもいい)',body,re.I)):
            identifiers.append(identifier)
    labels=list(dict.fromkeys(re.findall(r'[「“"]([^」”"\n]{1,80})[」”"]',original)))
    return {'ids':identifiers,'button_labels':labels} if identifiers and labels else None


def _observed_text_control_contract_defect(criteria: dict, sources: dict, candidate: dict, failures: list,
                                          original: str = '') -> dict | None:
    """Classify a directly observed text-control capability mismatch as a source defect."""
    for failure in failures:
        if failure.get('kind')!='BROWSER' or failure.get('contract_error') or failure.get('browser_errors'):
            continue
        requirements=[str(criteria[key]) for key in failure.get('ids') or [] if key in criteria]
        requirement=next((text for text in requirements if re.search(r'input|textbox|text.?area|入力',text,re.I)
            and re.search(r'multi.?line|multiple lines|per line|1行に1つ|一行に一つ|複数行|改行',text,re.I)),None)
        if requirement is None:
            requirement=next((line.strip() for line in original.splitlines()
                if re.search(r'one per line|one .* per line|each line|1行に1つ|一行に一つ|複数行|改行',line,re.I)),None)
        checks=[check for check in candidate.get('checks') or [] if set(check.get('ids') or [])&set(failure.get('ids') or [])]
        if not requirement or not any(re.search(r'\.fill\s*\(',check.get('code','')) for check in checks):
            continue
        has_multiline_semantics=bool(re.search(r'multi.?line|multiple lines|per line|each line|one .+ per line|1行に1つ|一行に一つ|複数行|改行',requirement,re.I))
        if not has_multiline_semantics:
            continue
        fields=(failure.get('observed_page') or {}).get('fields') or []
        text_targets=[field for field in fields if field.get('tag') in {'input','textarea'}
            and field.get('type') not in {'button','submit','reset','checkbox','radio','hidden','password'}]
        for field in (failure.get('observed_page') or {}).get('fields') or []:
            if (field.get('tag')!='input' or field.get('type') not in {'text','search','email','url','tel'}
                    or not field.get('id') or '\n' in str(field.get('value') or '')
                    or '\r' in str(field.get('value') or '')):
                continue
            attempted_values=[]
            for action in failure.get('input_actions') or []:
                selector=str(action.get('selector') or '')
                explicit_target=bool(re.search(r'#'+re.escape(field['id'])+r'(?![\w-])',selector)
                    or (field.get('name') and re.search(r'\[name\s*=\s*(["\'])'+re.escape(field['name'])+r'\1',selector)))
                unique_textbox=selector.startswith('internal:role=textbox') and len(text_targets)==1
                if (isinstance(action.get('value'),str) and ('\n' in action['value'] or '\r' in action['value'])
                        and (explicit_target or unique_textbox)):
                    attempted_values.append(action['value'])
            observed_value=str(field.get('value') or '')
            normalized_attempts={normalized for value in attempted_values for normalized in (
                re.sub(r'[\r\n]+',' ',value).strip(),
                re.sub(r'\s*[\r\n]+\s*','',value),
                re.sub(r'[\r\n]+','',value))}
            truncated_expected=str((failure.get('assertion') or {}).get('raw_expected') or '')
            truncated_actual=str((failure.get('assertion') or {}).get('raw_actual') or observed_value)
            observed_matches_assertion=(not isinstance((failure.get('assertion') or {}).get('raw_actual'),str)
                or observed_value==str((failure.get('assertion') or {}).get('raw_actual')))
            maxlength_fragment=None
            if (not attempted_values and observed_matches_assertion and truncated_expected and truncated_actual
                    and len(truncated_actual)<len(truncated_expected)):
                for source in sources.values():
                    for match in re.finditer(r'<input\b[^>]*>',source,re.I):
                        fragment=match.group()
                        source_id=re.search(r"\bid\s*=\s*(['\"])([^'\"]+)\1",fragment)
                        unquoted_id=re.search(r"\bid\s*=\s*([^\s>]+)",fragment)
                        input_id=source_id.group(2) if source_id else unquoted_id.group(1) if unquoted_id else ''
                        limit=re.search(r"\bmaxlength\s*=\s*(['\"]?)(\d+)\1",fragment,re.I)
                        if (input_id==field['id'] and limit and len(truncated_expected)>int(limit.group(2))
                                and truncated_actual==truncated_expected[:int(limit.group(2))]):
                            maxlength_fragment=fragment
                            break
            if attempted_values and observed_value not in normalized_attempts:
                continue
            for source in sources.values():
                for match in re.finditer(r'<input\b[^>]*>',source,re.I):
                    fragment=match.group()
                    if re.search(r"\bid\s*=\s*([\"'])"+re.escape(field['id'])+r'\1',fragment):
                        if attempted_values:
                            return {'verdict':'SOURCE_DEFECT','reason':'The checked text field is an HTML single-line input. A successful fill containing line breaks was observed, but the actual field value normalized those breaks, contradicting the explicit multiline text-entry requirement.',
                                'requirement':requirement,'source_fragment':fragment,'evidence_origin':'OBSERVED_INPUT_CAPABILITY',
                                'observed_value':observed_value}
                        if maxlength_fragment and maxlength_fragment==fragment:
                            return {'verdict':'SOURCE_DEFECT','reason':'The checked text field truncates the required text at its declared maxlength; the observed value matches that truncation exactly.',
                                'requirement':requirement,'source_fragment':fragment,'evidence_origin':'OBSERVED_MAXLENGTH_TRUNCATION',
                                'observed_value':truncated_actual,'attempted_value':truncated_expected}
    return None


def _observed_fill_value_reset_defect(criteria: dict, sources: dict, candidate: dict,
                                     failures: list, original: str = '') -> dict | None:
    """Promote a valid, completed browser fill that an input handler immediately undoes."""
    numeric_value=re.compile(r'^[+-]?(?:(?:\d+(?:\.\d*)?)|(?:\.\d+))(?:[eE][+-]?\d+)?$')

    def matching_source_fragment(field_id: str):
        quoted=re.escape(field_id)
        references=(
            re.compile(r"\$\(\s*(['\"])#"+quoted+r"\1\s*\)"),
            re.compile(r"(?:document\s*\.\s*)?querySelector\(\s*(['\"])#"+quoted+r"\1\s*\)"),
            re.compile(r"(?:document\s*\.\s*)?getElementById\(\s*(['\"])"+quoted+r"\1\s*\)"),
        )
        for path,source in sources.items():
            if is_project_test_path(path):
                continue
            for reference in references:
                for match in reference.finditer(source):
                    prefix=source[max(0,match.start()-120):match.start()]
                    declaration=re.search(r"(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*$",prefix)
                    target=declaration.group(1) if declaration else ''
                    suffix=source[match.end():match.end()+320]
                    listener=re.match(r"\s*\.\s*addEventListener\(\s*(['\"])input\1\s*,",suffix,re.I)
                    if not listener and target:
                        listener=re.search(r"\b"+re.escape(target)+
                            r"\s*\.\s*addEventListener\(\s*(['\"])input\1\s*,",suffix,re.I)
                    if not listener:
                        continue
                    body_start=match.end()+listener.start()+listener.end()
                    close=re.search(r"\}\s*\)\s*;",source[body_start:body_start+5000])
                    if not close:
                        continue
                    end=body_start+close.end()
                    fragment=source[match.start():end]
                    assignment=(re.search(r"\b"+re.escape(target)+r"\s*\.\s*value\s*=(?!=)",fragment)
                                if target else re.search(r"(?:\bthis|\$\(\s*(['\"])#"+quoted+
                                    r"\1\s*\)|querySelector\(\s*(['\"])#"+quoted+
                                    r"\1\s*\)|getElementById\(\s*(['\"])"+quoted+
                                    r"\1\s*\))\s*\.\s*value\s*=(?!=)",fragment))
                    if assignment:
                        return path,fragment[:1200]
        return None

    for failure in failures:
        if failure.get('kind')!='BROWSER' or failure.get('contract_error') or failure.get('browser_errors'):
            continue
        failed_ids=set(failure.get('ids') or [])
        checks=[check for check in candidate.get('checks') or []
            if set(check.get('ids') or [])&failed_ids]
        if not any(re.search(r"\.fill\s*\(",str(check.get('code') or '')) for check in checks):
            continue
        requirement=next((text.split(':',1)[1].strip() for identifier,text in criteria.items()
            if identifier in failed_ids and text.startswith('In the browser, verify the original requirement:')
            and text.split(':',1)[1].strip() in original),None)
        if not requirement:
            requirement=next((line.strip() for line in original.splitlines() if line.strip()
                and re.search(r'\bbudget\b|予算|spending limit|budget cap',line,re.I)),None)
        if not requirement:
            continue
        for action in failure.get('browser_actions') or []:
            if action.get('action')!='fill' or action.get('outcome')!='completed':
                continue
            selector=str(action.get('selector') or '')
            field_id=str(action.get('field_id') or '')
            selector_id=re.search(r'#([A-Za-z_][\w:-]*)',selector)
            if selector_id:
                if field_id and field_id!=selector_id.group(1):
                    continue
                field_id=selector_id.group(1)
            if not field_id or re.search(r'password|secret|token|api[-_ ]?key|credential|authorization|auth',
                    ' '.join((selector,field_id,str(action.get('field_name') or ''),
                              str(action.get('field_type') or '')),),re.I):
                continue
            if not any(re.search(r"\.fill\s*\(",str(check.get('code') or ''))
                    and re.search(r"#"+re.escape(field_id)+r"\b|['\"]"+re.escape(field_id)+r"['\"]",
                                  str(check.get('code') or ''))
                    for check in checks):
                continue
            value=action.get('requested_value')
            observed=action.get('observed_value')
            previous=action.get('previous_value')
            field_type=str(action.get('field_type') or '').lower()
            if not isinstance(value,str) or not value.strip() or not isinstance(observed,str) or observed==value:
                continue
            if field_type=='number' and not numeric_value.fullmatch(value.strip()):
                continue
            if field_type not in {'number','text','search','email','url','tel','textarea'}:
                continue
            if observed!='' and (not isinstance(previous,str) or not previous or observed!=previous):
                continue
            evidence=matching_source_fragment(field_id)
            if not evidence:
                continue
            source_path,source_fragment=evidence
            return {'verdict':'SOURCE_DEFECT',
                'reason':f"The browser completed a valid fill of #{field_id}, but the rendered input immediately returned to its previous value instead of retaining the entered value.",
                'requirement':requirement,'source_fragment':source_fragment,'source_path':source_path,
                'evidence_origin':'OBSERVED_FILL_VALUE_RESET','field_id':field_id,'field_type':field_type,
                'requested_value':value,'previous_value':previous,'observed_value':observed}
    return None


# Kept as a private alias for existing task journals and regression fixtures.
_observed_multiline_input_defect=_observed_text_control_contract_defect


def _focused_verification_checks(checks: list[dict], criteria: dict) -> list[dict]:
    """Keep rejected execution evidence aligned with the criterion being repaired."""
    return [check for check in checks if set(check.get('ids') or []) & set(criteria)][:1]


def _bounded_verification_repair_finding(raw: str, limit: int=6000) -> str:
    """Keep the diagnosis and measured UI facts inside the same prompt budget."""
    try:
        finding=json.loads(raw)
    except (ValueError,TypeError):
        return str(raw)[:limit]
    if not isinstance(finding,dict):return str(raw)[:limit]
    review=finding.get('review') or {}
    if not isinstance(review,dict):review={}
    source_fragment=str(review.get('source_fragment') or '')
    # CHECK_DEFECT quotes are advisory source context, not source-repair
    # authorization; the current source is already present in the authoring
    # prompt. Drop oversized quotations so repetitive reviewer output cannot
    # crowd measured visible guidance out of the bounded repair evidence.
    if review.get('verdict')!='SOURCE_DEFECT' and len(source_fragment)>240:
        source_fragment=''
    bounded={'review':{key:str(review[key])[:cap]for key,cap in
        [('verdict',32),('verification_form',32),('reason',1000),('requirement',240),('source_fragment',1000)]
        if key in review and review.get(key) is not None}}
    if 'source_fragment' in bounded['review']:
        bounded['review']['source_fragment']=source_fragment[:1000]
    encode=lambda value:json.dumps(value,ensure_ascii=False)
    if len(encode(bounded))>limit:
        bounded['review']['reason']=str(review.get('reason') or '')[:160]
        bounded['review'].pop('requirement',None)
    key='successful_checks'if 'successful_checks'in finding else 'failures'
    bounded[key]=[]
    for item in (finding.get(key) or [])[:2]:
        if not isinstance(item,dict):continue
        entry={'ids':[str(identifier)[:40]for identifier in (item.get('ids') or [])[:4]],'observed_page':{}}
        bounded[key].append(entry)
        if len(encode(bounded))>limit:
            bounded[key].pop();break
        def add(target,name,value):
            target[name]=value
            if len(encode(bounded))>limit:target.pop(name,None)
        page=item.get('observed_page') or {}
        # Visible guidance and control states must survive alongside advice.
        for field,fields in [('messages',{'selector':100,'text':140,'visible':None}),
                             ('buttons',{'id':80,'text':80,'disabled':None}),
                             ('fields',{'id':80,'tag':24,'type':24,'value':100})]:
            values=[]
            for value in (page.get(field) or [])[:12]:
                if isinstance(value,dict):
                    values.append({name:value[name]if cap is None else str(value[name])[:cap]
                        for name,cap in fields.items()if name in value})
            if values:add(entry['observed_page'],field,values)
        if item.get('error'):add(entry,'error',str(item['error']).split('\n',1)[0][:160])
        reads=[{name:str(value.get(name) or '')[:cap]for name,cap in [('selector',100),('text',120)]}
            for value in (item.get('reads') or [])[-2:]if isinstance(value,dict)]
        if reads:add(entry,'reads',reads)
        actions=[{name:value[name]for name in ('action','selector','outcome','observed_state_changed','field_id',
                            'field_name','field_type','requested_value','previous_value','observed_value')if name in value}
            for value in (item.get('browser_actions') or [])[-2:]if isinstance(value,dict)]
        if actions:add(entry,'browser_actions',actions)
    return encode(bounded)


def _review_verification_failure(task_id: str, original: str, criteria: dict, sources: dict,
                                 candidate: dict, failures: list, previous_checks: list | None = None,
                                 observations: list | None = None, _reserve_model_call=None) -> dict:
    """Check a failing assertion's meaning before allowing source repairs.

    Valid JavaScript can still test invented requirements or misuse the UI.
    A source-defect verdict needs a quotation from both the request and source;
    it is diagnostic evidence, never success evidence for the application.
    """
    failed_ids={identifier for failure in failures if isinstance(failure,dict)
        for identifier in (failure.get('ids') or []) if identifier in criteria}
    review_criteria={identifier:text for identifier,text in criteria.items()
        if not failed_ids or identifier in failed_ids}
    review_candidate={**candidate,'checks':[check for check in candidate.get('checks') or []
        if not failed_ids or set(check.get('ids') or [])&failed_ids]}
    review_failures=[{**failure,'ids':[identifier for identifier in (failure.get('ids') or [])
        if not failed_ids or identifier in failed_ids]} for failure in failures if isinstance(failure,dict)
        and (not failed_ids or set(failure.get('ids') or [])&failed_ids)]
    entrypoint=candidate.get('entrypoint') or ''
    if (review_criteria and Path(entrypoint).suffix.lower() in {'.html','.htm'} and entrypoint in sources
            and any(failure.get('kind')=='BROWSER' and not failure.get('contract_error') for failure in review_failures)):
        from .source_repair import html_boundary_errors
        boundary_errors=html_boundary_errors(sources[entrypoint])
        if boundary_errors:
            error=boundary_errors[0]
            # A definite current-source syntax defect is not a request to
            # invent another selector or weaken the browser check. Also
            # recover projects produced by versions lacking write preflight.
            return {'verdict':'SOURCE_DEFECT','reason':
                f"The current HTML entrypoint contains <{error['tag']}/> without its required explicit closing tag; following markup is consumed as text or inactive content.",
                'requirement':next(iter(review_criteria.values())),
                'source_fragment':error['source_fragment'],'source_path':entrypoint,'line':error['line'],
                'evidence_origin':'CURRENT_HTML_BOUNDARY_PARSE'}
    observed_fill=_observed_fill_value_reset_defect(review_criteria,sources,review_candidate,review_failures,original)
    if observed_fill:
        return observed_fill
    observed=_observed_multiline_input_defect(review_criteria,sources,review_candidate,review_failures,original)
    if observed:
        return observed
    for failure in review_failures:
        witness=failure.get('observed_no_repeat') or {}
        if witness and not failure.get('contract_error'):
            requirement=next((criteria[key] for key in witness.get('ids') or [] if key in criteria),None)
            output_id=witness.get('output_id')
            if requirement and output_id:
                for source in sources.values():
                    fragment=next((match.group() for match in re.finditer(r'<[a-z][^>]*>',source,re.I)
                        if re.search(r"\bid\s*=\s*([\"'])"+re.escape(output_id)+r'\1',match.group())),None)
                    if fragment:
                        return {'verdict':'SOURCE_DEFECT','reason':'Separate completed selection clicks produced the same result while other observed valid choices remained in the same input.',
                            'requirement':requirement,'source_fragment':fragment,'evidence_origin':'OBSERVED_SELECTION_COUNTEREXAMPLE',
                            'observed_no_repeat':witness}
    schema={'type':'object','properties':{
        'verification_form':{'type':'string','enum':['STATEFUL_CODE','LITERAL_OBSERVATIONS']},
        'verdict':{'type':'string','enum':['SOURCE_DEFECT','CHECK_DEFECT','CHECK_VALID','INCONCLUSIVE']},
        'reason':{'type':'string','maxLength':1200},
        'requirement':{'type':'string','maxLength':600},
        'source_fragment':{'type':'string','maxLength':1200}},
        'required':['verification_form','verdict','reason','requirement','source_fragment'],'additionalProperties':False}
    prompt=('Review the acceptance CHECK independently against the original requirement and actual source. '
        'Return JSON with verdict SOURCE_DEFECT, CHECK_DEFECT, CHECK_VALID or INCONCLUSIVE, reason, requirement (exact quotation), '
        'source_fragment (exact quotation), and verification_form. Choose STATEFUL_CODE when proving the requirement needs '
        'intermediate observations or deriving later expectations from earlier real outputs. Choose LITERAL_OBSERVATIONS '
        'when fixed final-state reads suffice. The replacement author will be constrained to that capability. '
        'SOURCE_DEFECT requires an actual source fragment that contradicts the requirement. '
        'A failing assertion alone is not proof of a source defect. CHECK_DEFECT includes overwriting input with successive fill calls, '
        'escaped literal backslash-n instead of line breaks, querying a current-result element as a history list, '
        'invented selectors/accessible names, asserting unrelated lengths or expecting first-N instead of latest-N. '
        'A repaired check that passes is CHECK_VALID only if it still proves the requested behavior. Merely weakening equality to bounds, '
        'checking a value against itself, or deriving expected history from the history being tested is CHECK_DEFECT. '
        'For latest-N history, observe each new result independently of the history, then compare the history with the last N observed results. '
        'Playwright fill retains newlines in a textarea; a single-line HTML input cannot retain them. Use observed field tag/type/value rather than inventing a general limitation of fill. '
        'For empty/invalid input, inspect visible guidance as well as the disabled control state. A disabled button cannot be clicked; this actionability timeout alone does not prove a source defect. '
        'Do not recommend filling valid input to verify an empty-input requirement, force-enabling a control, or requiring the message in a particular element unless the human specified it. '
        'observed_page.messages records actual visible message text and its source selector; observed_page.buttons records actual disabled states. '
        'If a check asserts nonempty text in an initial result area, inspect these other visible messages before diagnosing missing guidance. Do not assume renderResult or another event handler ran at startup. '
        'observed_successful_checks contains measured page state and actual reads after the repaired check passed. Do not contradict those readings by guessing that an uncalled handler ran. '
        'assertResponsiveLayout(viewport,stylesheet) is a host-owned executed browser check: it applies the viewport, measures document overflow and rendered content, '
        'confirms a named stylesheet is loaded and parsed, and checks enabled visible control bounds and non-clicking trial actionability. '
        'Its actual measurements are in layout_observations. Assess those facts; this proves generic responsive usability, not a named menu arrangement or application behavior. '
        'A passing check still needs meaningful coverage of the original requirement; assess coverage using both its assertions and the measured facts. '
        'The original human request outranks generated plan wording. Do not require an internal function name or return shape chosen only by the plan '
        'when the human did not constrain that interface and the actual equivalent API can prove the same required behavior. '
        'Review only the CURRENT source and CURRENT failed IDs. A previously fixed defect cannot justify another source rewrite. '
        'If valid input and completed user actions produce no state change, trace the entrypoint, loaded modules, initialization and event wiring in the current source. '
        'An absent event binding or a disconnected UI is an application defect even when pure module tests pass and the browser reports no exception. '
        'An actionability timeout alone remains inconclusive: distinguish a missing prerequisite in the check from a broken state transition in the app. '
        'Do not recommend changing the app to satisfy an invalid check. Do not fix source or rewrite the check here.\n'
        +json.dumps({'original_request':original,'criteria':review_criteria,'actual_source':verification_source_excerpts(sources),
                    'previous_checks':[check for check in (previous_checks or []) if not failed_ids or
                        set(check.get('ids') or [])&failed_ids],
                    'check':review_candidate,'observed_failures':review_failures,
                    'observed_successful_checks':observations or []},ensure_ascii=False))
    if re.search(r'empty input|input.{0,12}empty|空入力|入力.{0,8}空|有効.{0,8}候補.{0,12}ない','\n'.join(review_criteria.values()),re.I):
        prompt+=('\nEMPTY_GUIDANCE_RULE: Unless the HUMAN explicitly requires feedback only after submission, '
            'clear guidance already visible while input is empty satisfies the message requirement. '
            'A static hint is valid feedback; do not demand that an unreachable empty-submit handler run or that the result container hold the message. '
            'Use the actual measured visible messages. The check must still assert the real guidance text with empty/invalid input; '
            'control visibility or disabled state alone is insufficient. The planner word "error" cannot add a submission-path requirement absent from the human request.')
    if _reserve_model_call is not None and not _reserve_model_call('review',review_criteria):
        return {'verdict':'INCONCLUSIVE',
                'reason':'The bounded independent-review model-call budget was exhausted; no source change is authorized.'}
    raw=_model_text(task_id,'RUNNING','VERIFICATION_CONTRACT',settings.planner_model,
        [{'role':'system','content':'You review the meaning of a failed acceptance check. Return JSON only.'},
         {'role':'user','content':prompt}],structured_schema=schema)
    value,error=extract_plan_json(raw or '')
    if error or not isinstance(value,dict):
        return {'verdict':'INCONCLUSIVE','reason':'Verification failure review returned invalid JSON.'}
    if value.get('verdict')=='SOURCE_DEFECT':
        requirement=value.get('requirement')
        fragment=value.get('source_fragment')
        if (not isinstance(requirement,str) or not requirement.strip()
                or not any(requirement in text for text in [original,*criteria.values()])
                or not isinstance(fragment,str) or not fragment.strip()
                or not any(fragment in source for source in sources.values())):
            # Local reviewers sometimes identify the right mismatch but return
            # a paraphrase instead of the exact quotes required to authorize a
            # write. Give that formatting error one bounded correction attempt;
            # never broaden the scope or accept the original unsupported claim.
            correction_prompt=(prompt+'\nEVIDENCE_QUOTE_CORRECTION: Your previous SOURCE_DEFECT response was rejected because its '
                'requirement or source_fragment was not an exact substring of the supplied original_request, criteria, or actual_source. '
                'Re-read only those fields and return exact, short quotations copied verbatim. If no contradictory source fragment can be '
                'quoted exactly, return INCONCLUSIVE. Do not paraphrase, infer missing code, or add a requirement.\n'
                +'Rejected response: '+json.dumps(value,ensure_ascii=False))
            if _reserve_model_call is not None and not _reserve_model_call('review',review_criteria):
                return {'verdict':'INCONCLUSIVE',
                        'reason':'The bounded independent-review model-call budget was exhausted; no source change is authorized.'}
            retry_raw=_model_text(task_id,'RUNNING','VERIFICATION_CONTRACT',settings.planner_model,
                [{'role':'system','content':'Correct unsupported evidence quotations in a failed-check review. Return JSON only.'},
                 {'role':'user','content':correction_prompt}],structured_schema=schema)
            value,error=extract_plan_json(retry_raw or '')
            if error or not isinstance(value,dict):
                return {'verdict':'INCONCLUSIVE','reason':'Verification failure review could not provide exact evidence quotations.'}
            if value.get('verdict')=='SOURCE_DEFECT':
                requirement=value.get('requirement')
                fragment=value.get('source_fragment')
                if (not isinstance(requirement,str) or not requirement.strip()
                        or not any(requirement in text for text in [original,*criteria.values()])
                        or not isinstance(fragment,str) or not fragment.strip()
                        or not any(fragment in source for source in sources.values())):
                    return {**value,'verdict':'INCONCLUSIVE',
                        'reason':'Source-defect review still lacks matching requirement/source quotations.'}
    return value


def _project_test_case_paths(failure: dict, sources: dict, *, test_only: bool) -> set[str]:
    available={path for path in sources if is_project_test_path(path)==test_only}
    located=set()
    for item in failure.get('source_locations') or []:
        if not isinstance(item,dict):
            continue
        raw=str(item.get('path') or '').replace('\\','/')
        if raw.startswith('file://'):
            raw=unquote(urlsplit(raw).path)
        for path in available:
            if raw==path or raw.endswith('/'+path):
                located.add(path)
    return located


def _project_test_quote_paths(fragment: str, sources: dict, *, test_only: bool,
                               failure: dict) -> list[str]:
    if not isinstance(fragment,str) or len(fragment.strip())<5:
        return []
    candidates={path for path,source in sources.items()
        if is_project_test_path(path)==test_only and fragment in source}
    located=_project_test_case_paths(failure,sources,test_only=test_only)
    if located:
        candidates &= located
    if test_only and located:
        # A different assertion in the same test file is not evidence for
        # this failure. Require the quoted fragment to span a recorded line.
        def matches_frame(path):
            lines={item['line'] for item in failure.get('source_locations') or []
                   if isinstance(item,dict) and isinstance(item.get('line'),int)
                   and path in _project_test_case_paths({'source_locations':[item]},sources,test_only=True)}
            if not lines:
                return True
            source=sources[path]
            return any(any(start<=line<=start+fragment.count('\n') for line in lines)
                       for start in (source.count('\n',0,m.start())+1 for m in re.finditer(re.escape(fragment),source)))
        candidates={path for path in candidates if matches_frame(path)}
    return sorted(candidates) if len(candidates)==1 else []


def _review_project_test_failure(task_id: str, original: str, criteria: dict, sources: dict,
                                 failure: dict, _reserve_model_call=None) -> dict:
    """Assign one executed test failure to its exact test or source file, or fail closed."""
    schema={'type':'object','properties':{
        'verdict':{'type':'string','enum':['SOURCE_DEFECT','CHECK_DEFECT','INCONCLUSIVE']},
        'reason':{'type':'string','maxLength':1200},
        'requirement':{'type':'string','maxLength':600},
        'source_fragment':{'type':'string','maxLength':1200},
        'test_fragment':{'type':'string','maxLength':1200}},
        'required':['verdict','reason','requirement','source_fragment','test_fragment'],
        'additionalProperties':False}
    test_paths=_project_test_case_paths(failure,sources,test_only=True)
    test_sources={path:sources[path] for path in sorted(test_paths)}
    if not test_sources:
        test_sources={path:source for path,source in sources.items() if is_project_test_path(path)}
    application_sources={path:source for path,source in sources.items() if not is_project_test_path(path)}
    case={'name':str(failure.get('name') or 'Unidentified test case')[:300],
        'failure_type':str(failure.get('failure_type') or '')[:100],
        'detail':str(failure.get('detail') or failure.get('error') or '')[:2400],
        'source_locations':[item for item in (failure.get('source_locations') or [])
            if isinstance(item,dict)][:8]}
    prompt=('Review exactly this one failure from an already executed project test command. '
        'Do not combine it with any other test result. Compare the failing assertion or setup with the original human request '
        'and the current source. The original request outranks generated plan wording. '
        'Before assigning ownership, audit the concrete test fixture: for expected success, verify its values can satisfy '
        'every relevant constraint; for expected errors, verify the fixture triggers that specific condition rather than a '
        'different error. A thrown application error alone does not prove a source defect, and a test name alone does not '
        'prove a fixture defect. '
        'Return SOURCE_DEFECT only when an exact current application-source quotation contradicts an exact requirement quotation. '
        'Return CHECK_DEFECT only when an exact quotation from the failing project test shows that its assertion or setup '
        'is wrong for the stated requirement. Do not infer ownership from the exit code, stack location, or a test name alone. '
        'For SOURCE_DEFECT, put the exact requirement in requirement and exact application code in source_fragment; leave test_fragment empty. '
        'For CHECK_DEFECT, put the exact requirement in requirement and the exact failing test code in test_fragment; leave source_fragment empty. '
        'If the evidence does not decide ownership, return INCONCLUSIVE with empty quotations. Do not propose edits or paths.\n'
        +json.dumps({'original_request':original,'acceptance_criteria':criteria,'failing_case':case,
            'current_failing_test_sources':verification_source_excerpts(test_sources),
            'current_application_sources':verification_source_excerpts(application_sources)},
            ensure_ascii=False))
    if _reserve_model_call is not None and not _reserve_model_call('review',criteria):
        return {'verdict':'INCONCLUSIVE','budget_exhausted':True,
            'reason':'The bounded independent-review model-call budget was exhausted; no file change is authorized.'}
    raw=_model_text(task_id,'RUNNING','VERIFICATION_CONTRACT',settings.planner_model,
        [{'role':'system','content':'You assign ownership for exactly one failed project test. Return JSON only.'},
         {'role':'user','content':prompt}],structured_schema=schema)
    value,error=extract_plan_json(raw or '')
    if error or not isinstance(value,dict):
        return {'verdict':'INCONCLUSIVE','reason':'The project-test ownership review returned invalid JSON.'}
    verdict=value.get('verdict')
    if verdict not in {'SOURCE_DEFECT','CHECK_DEFECT','INCONCLUSIVE'}:
        return {'verdict':'INCONCLUSIVE','reason':'The project-test ownership review returned an unsupported verdict.'}
    if verdict=='INCONCLUSIVE':
        return value
    requirement=value.get('requirement')
    if (not isinstance(requirement,str) or not requirement.strip()
            or not any(requirement in text for text in [original,*criteria.values()]
                if isinstance(text,str))):
        return {**value,'verdict':'INCONCLUSIVE',
            'reason':'The ownership review did not quote an exact requirement from the request or acceptance criteria.'}
    if verdict=='SOURCE_DEFECT':
        fragment=value.get('source_fragment')
        paths=_project_test_quote_paths(fragment,sources,test_only=False,failure=failure)
        if not paths:
            return {**value,'verdict':'INCONCLUSIVE',
                'reason':'The source-defect review did not identify one exact, current application file and code quotation.'}
        return {**value,'repair_paths':paths,'evidence_origin':'CURRENT_PROJECT_TEST_REVIEW'}
    fragment=value.get('test_fragment')
    paths=_project_test_quote_paths(fragment,sources,test_only=True,failure=failure)
    if not paths:
        return {**value,'verdict':'INCONCLUSIVE',
            'reason':'The check-defect review did not identify one exact quotation in the failing project test file.'}
    return {**value,'repair_paths':paths,'evidence_origin':'CURRENT_PROJECT_TEST_REVIEW'}


def _review_project_test_failures(task_id: str, original: str, criteria: dict, sources: dict,
                                  observed: dict, _reserve_model_call=None,
                                  file_manifest: list[dict] | None=None) -> dict:
    """Review bounded individual failures and authorize only the first evidenced repair."""
    deterministic=project_test_failure_diagnosis(observed,sources,
        requirements=[original,*criteria.values()],file_manifest=file_manifest)
    if deterministic.get('verdict')=='CHECK_DEFECT' and reviewed_project_test_paths(deterministic,sources):
        return deterministic
    if file_manifest:
        runtime_finding=project_test_runtime_source_diagnosis(observed,sources,file_manifest)
        if runtime_finding.get('verdict')=='SOURCE_DEFECT':
            return runtime_finding
    cases=project_test_review_cases(observed)
    if not cases:
        return {'verdict':'INCONCLUSIVE','reason':'The failed project-test command supplied no attributable failing case.'}
    reviewed=[]
    check_defects=[]
    cases_to_review=cases[:VERIFICATION_PROJECT_TEST_CASE_LIMIT]
    for failure in cases_to_review:
        finding=_review_project_test_failure(task_id,original,criteria,sources,failure,
            _reserve_model_call=_reserve_model_call)
        summary={'name':str(failure.get('name') or 'Unidentified test case')[:300],
            'verdict':finding.get('verdict'),'reason':str(finding.get('reason') or '')[:1200],
            'repair_paths':finding.get('repair_paths') or []}
        reviewed.append(summary)
        if finding.get('verdict')=='SOURCE_DEFECT' and finding.get('repair_paths'):
            # Source failures take priority over any test-owned issue in the
            # same run. Repairing the application first and rerunning the
            # complete suite prevents one bad fixture from masking real bugs.
            return {**finding,'failure_case':failure,'reviewed_cases':reviewed}
        if finding.get('verdict')=='CHECK_DEFECT' and finding.get('repair_paths'):
            check_defects.append((finding,failure))
        if finding.get('budget_exhausted'):
            break
    # A test-only repair is authorized only when every observed failure was
    # reviewed and independently attributed to the project test. If the
    # review budget truncates the cases, or any case is inconclusive, fail
    # closed instead of narrowing the implementation scope to a test file.
    if (check_defects and len(reviewed)==len(cases)
            and len(check_defects)==len(cases)):
        paths=sorted({path for finding,_ in check_defects for path in finding.get('repair_paths') or []
                      if isinstance(path,str) and path in sources and is_project_test_path(path)})
        if paths:
            first,failure=check_defects[0]
            return {**first,'repair_paths':paths,'failure_case':failure,
                'reviewed_cases':reviewed,'failure_cases':[case for _,case in check_defects]}
    return {'verdict':'INCONCLUSIVE','reason':
        f'No complete failure review established a safe single repair owner ({len(reviewed)} of {len(cases)} case(s) reviewed).',
        'reviewed_cases':reviewed}


def _record_verification_preparation_failure(task_id: str, phase_id: str, error: Exception) -> None:
    current=db.coding_task(task_id) or {}
    state=current.get('resume_state') or {}
    previous=state.get('verification_preparation_failure') or {}
    signature=getattr(error,'verification_signature',None)
    repeated=(int(previous.get('repeat_count') or 0)+1
        if signature and previous.get('signature')==signature else 1)
    db.update_coding_task(task_id,resume_state={**state,'verification_preparation_failure':{
        'phase_id':phase_id,'error':str(error)[:4000],
        'signature':signature,'repeat_count':repeated,
        'verification_retry_epoch':int(state.get('verification_retry_epoch') or 0),
        'model_calls':int(getattr(error,'verification_model_calls',0) or 0),
        'author_calls':int(getattr(error,'verification_author_calls',0) or 0),
        'author_call_limit':int(getattr(error,'verification_author_call_limit',0) or 0),
        'review_calls':int(getattr(error,'verification_review_calls',0) or 0),
        'model_call_limit':int(getattr(error,'verification_model_call_limit',0) or 0),
        'budget_exhaustion':str(getattr(error,'verification_budget_exhaustion','') or ''),
        'budget_version':int(getattr(error,'verification_budget_version',0) or 0),
        'covered_ids':sorted({str(identifier) for identifier in
            getattr(error,'verification_covered_ids',[]) if isinstance(identifier,str)}),
        'missing_ids':sorted({str(identifier) for identifier in
            getattr(error,'verification_missing_ids',[]) if isinstance(identifier,str)}),
        'recorded_at':time.time()}})


def _clear_verification_preparation_failure(task_id: str, _signature: str) -> None:
    """Clear a previous verifier stop after the current contract succeeds."""
    current=db.coding_task(task_id) or {}
    state=current.get('resume_state') or {}
    previous=state.get('verification_preparation_failure') or {}
    if not previous:
        return
    if previous.get('signature') and previous.get('signature')!=_signature:
        return
    updated=dict(state)
    updated.pop('verification_preparation_failure',None)
    db.update_coding_task(task_id,resume_state=updated)


def _verification_coverage_pending(phase: dict, report: dict) -> bool:
    """Recognize successful partial checks, never an observed application failure."""
    if not phase.get('host_verification') or report.get('blockers'):
        return False
    if any(error!='verification command failed' for error in report.get('errors') or []):
        return False
    operations=(report.get('typed_execution_summary') or {}).get('operations') or []
    commands=[op for op in operations if op.get('tool')=='verification_command']
    if not commands:
        return False
    output=commands[-1].get('output') or {}
    passed=output.get('passed_criteria_ids')
    required=set(acceptance_criteria(phase))
    return bool(isinstance(passed,list) and passed and set(passed)<required
                and output.get('returncode')==0 and not output.get('failures')
                and not output.get('changed_targets') and output.get('zero_tests') is False)


def _restore_legacy_executor_error(report: dict) -> dict:
    """Attribute old host/OS launch failures without inventing test results."""
    operations=(report.get('typed_execution_summary') or {}).get('operations') or []
    runner=Path(__file__).with_name('coding_verification_runner.cjs').resolve()
    def host_failed_without_result(operation):
        command=(operation.get('input') or {}).get('command') or []
        output=operation.get('output') or {}
        return (len(command)>1 and Path(str(command[1])).resolve()==runner
                and output.get('returncode') not in (None,0)
                and 'OLCR_VERIFICATION_RESULT=' not in str(output.get('output') or '')
                and not output.get('passed_criteria_ids') and not output.get('failures'))
    indexes=[index for index,operation in enumerate(operations)
        if operation.get('tool')=='verification_command' and operation.get('status')=='failed'
        and not (operation.get('output') or {}).get('executor_error')
        and not (operation.get('output') or {}).get('changed_targets')
        and (host_failed_without_result(operation) or (
            (operation.get('output') or {}).get('returncode') is None
            and re.match(r'^verification command failed: \[Errno \d+\]',str((operation.get('output') or {}).get('error') or ''))))]
    if not indexes:
        return report
    restored=copy.deepcopy(report)
    for index in indexes:
        output=restored['typed_execution_summary']['operations'][index]['output']
        output.update(executor_error=True,failures=[{'ids':[],'error':output.get('error') or output.get('output') or 'Host verification produced no result',
            'contract_error':True,'executor_error':True}])
    restored.update(verification_pending=True,manager_decision={'decision':'RETRY',
        'reason':'Restored verification executor error from recorded OS failure',
        'retry_channel':'VERIFICATION_EXECUTOR'})
    return restored


def _partition_verification_checks(candidate: dict, result: dict) -> tuple[list[dict], list[dict]]:
    """Keep only checks with explicit passing IDs; isolate failed/uncertain checks."""
    checks=[item for item in (candidate or {}).get('checks') or [] if isinstance(item,dict)]
    failures=[item for item in (result or {}).get('failures') or [] if isinstance(item,dict)]
    failed_ids={identifier for failure in failures for identifier in failure.get('ids') or []}
    passed_ids=set((result or {}).get('passed_criteria_ids') or (result or {}).get('passed_ids') or [])
    candidate_ids={identifier for check in checks for identifier in check.get('ids') or []}
    if not failed_ids:
        failed_ids=candidate_ids-passed_ids
    passed=[]
    failed=[]
    for check in checks:
        ids=set(check.get('ids') or [])
        if ids and not ids&failed_ids and ids<=passed_ids:
            passed.append(check)
        else:
            failed.append(check)
    if not failed and (failures or result and result.get('passed') is False):
        # A malformed runner summary cannot promote uncertain checks as proof.
        return [],checks
    return passed,failed


def _verification_repair_authorized(phase: dict, previous_report: dict) -> bool:
    """A historical failed check cannot grant writes against today's source."""
    if not phase.get('host_verification'):
        return bool(phase.get('verification_repair_allowed') and previous_report.get('test_fail'))
    if phase.get('host_verification_current_source_reviewed'):
        return bool(phase.get('verification_repair_allowed') and
                    (phase.get('host_source_defect') or phase.get('host_runtime_diagnostic')
                     or phase.get('host_current_command_failure')))
    # Project tests are the one separate executor: the preflight has just
    # observed their actual failure, not an old model-authored UI assertion.
    return bool(phase.get('host_test_preflight') and phase.get('verification_repair_allowed')
                and previous_report.get('test_fail'))


def _reported_project_test_failure(report: dict, command: list[str] | None) -> bool:
    """Recover project-test failures even when an older report omitted test_fail."""
    if not is_project_test_command(command):
        return False
    operations=(((report.get('typed_execution_summary') or {}).get('operations'))
        if isinstance(report.get('typed_execution_summary'),dict) else [])
    verification_operations=[operation for operation in operations
        if isinstance(operation,dict) and operation.get('tool')=='verification_command']
    # Older coding runs stored verifier-authoring/runtime errors in the same
    # `test_fail` field as user-project failures. When structured execution
    # evidence is present, it is authoritative: only a non-contract failure
    # from the registered project test command should enter test ownership
    # review. In particular, a failed generated acceptance check must stay in
    # the bounded verification-contract repair path.
    if verification_operations:
        failures=[]
        for operation in verification_operations:
            output=operation.get('output') or {}
            if isinstance(output,dict):
                reported=output.get('failures') or []
                if isinstance(reported,list):
                    failures.extend(item for item in reported if isinstance(item,dict))
        if failures:
            return any(not failure.get('contract_error') for failure in failures)
        if str(report.get('status') or '').upper() not in {'FAIL','FAILED'}:
            return False
        return any(operation.get('status') in {'failed','error'}
                or (operation.get('output') or {}).get('returncode') not in (None,0)
                for operation in verification_operations)
    return bool(report.get('test_fail') and
        str(report.get('status') or '').upper() in {'FAIL','FAILED'})


def _verification_failure_identity(candidate: dict, failures: list, source_identity: str) -> str:
    failed_ids={key for failure in failures for key in failure.get('ids') or []}
    return _context_fingerprint({'source_identity':source_identity,
        'checks':[check for check in candidate.get('checks') or [] if set(check.get('ids') or [])&failed_ids],
        'failures':[{**{key:failure.get(key) for key in ('ids','kind','assertion','observed_page',
                                                       'project_source_error','contract_error')},
                     'error':str(failure.get('error') or '').split('\n',1)[0]} for failure in failures]})


def _verification_failure_context(failures):
    context=[]
    for failure in failures[:2]:
        if not isinstance(failure,dict):continue
        page=failure.get('observed_page') or {}
        observed={
            'messages':[{**message,'text':str(message.get('text') or '')[:240]}
                        for message in (page.get('messages') or [])[:2]],
            'buttons':[{**button,'text':str(button.get('text') or '')[:240]} if isinstance(button,dict) else str(button)[:240] for button in (page.get('buttons') or [])[:32]],
            'fields':[{**field,'value':str(field.get('value') or '')[:160]}
                      for field in (page.get('fields') or [])[:16]],
            'text':str(page.get('text') or '')[:1200]}
        context.append({'ids':failure.get('ids'),
            'error':str(failure.get('error') or '')[:1200],
            'observed_page':observed,'passed':failure.get('passed'),
            'reads':[{**reading,'text':str(reading.get('text') or '')[:160]}
                     for reading in (failure.get('reads') or [])[-4:]],
            'browser_actions':[{key:item.get(key) for key in ('action','selector','outcome','input_summary',
                                    'observed_state_changed','state_before','state_after','field_id','field_name',
                                    'field_type','requested_value','previous_value','observed_value')}
                                for item in (failure.get('browser_actions') or [])[-8:]],
            'unawaited_api_calls':failure.get('unawaited_api_calls'),
            'input_actions':failure.get('input_actions'),
            'check_source':failure.get('check_source') or
                (failure.get('assertion_source') or {}).get('snippet'),
            'assertion':failure.get('assertion'),'assertion_source':failure.get('assertion_source')})
    return context

def _host_verification_phase(task_id: str, phase: dict, plan: dict, workspace_root: str | None, *,
                             _semantic_pass: int=0, _budget: dict | None=None) -> dict:
    """Materialize missing checks independently of source implementation/replanning."""
    if not phase.get('host_verification') or not workspace_root:
        return phase
    def host_probe(candidate):
        result=_run_read_only_verification(candidate,workspace_root)
        if result and result[1].get('executor_error'):
            # A broken host cannot supply counterexamples for either source
            # repair or check reauthoring. Preserve the saved contract.
            raise VerificationExecutorError(str(result[1].get('output') or 'Verification executor failed')[-4000:])
        return result
    phase={key:value for key,value in phase.items() if key not in {
        'host_source_defect','host_source_defect_evidence','host_source_defect_repair_paths','host_runtime_diagnostic',
        'host_project_test_defect','host_project_test_repair_paths','host_project_test_setup_repair',
        'host_current_command_failure','host_current_command_evidence','host_verification_current_source_reviewed'}}
    declared_command=normalized_verification_argv(phase.get('verification_command'))
    node_only_browser_gate=bool(declared_command and Path(declared_command[0]).name.lower() in {'node','node.exe'}
        and len(declared_command)>1 and declared_command[1]=='--test'
        and browser_criteria(acceptance_criteria(phase))
        and any(str(entry.get('path') or '').endswith('.html') for entry in plan.get('file_manifest') or [] if isinstance(entry,dict)))
    owned_runner=Path(__file__).with_name('coding_verification_runner.cjs').resolve()
    owned_command=bool(declared_command and any(Path(arg).name==owned_runner.name
        and Path(arg).resolve()==owned_runner for arg in declared_command[1:]))
    preserve_declared_executor=bool(phase.get('verification_command') and not owned_command
        and not node_only_browser_gate and not phase.get('host_test_preflight')
        and not phase.get('host_partial_verification') and not phase.get('host_contract_failure'))
    if node_only_browser_gate:
        # A Node-only command cannot establish browser interaction criteria.
        # The owned runner still executes real node:test before its browser
        # checks; preserve the declaration in the audit trail.
        phase={**phase,'host_declared_test_command':declared_command}
    root = Path(workspace_root).resolve()
    sources = {}
    source_digests = {}
    for entry in plan.get('file_manifest') or []:
        if not isinstance(entry, dict) or not isinstance(entry.get('path'), str):
            continue
        path = (root / entry['path']).resolve()
        if path.is_relative_to(root) and path.is_file():
            try:
                raw_source=path.read_bytes()
            except OSError:
                continue
            relative=path.relative_to(root).as_posix()
            source_digests[relative]=hashlib.sha256(raw_source).hexdigest()
            sources[relative]=raw_source.decode('utf8',errors='replace')
    html_entrypoints=[path for path in sources if Path(path).suffix.lower()=='.html']

    def bind_entrypoint(value, preferred=None):
        """Bind verifier metadata to an existing HTML file in the task manifest."""
        if not isinstance(value,dict) or not html_entrypoints:
            return value
        requested=preferred or value.get('entrypoint')
        entrypoint=requested if requested in html_entrypoints else html_entrypoints[0]
        if value.get('entrypoint')==entrypoint:
            return value
        print(f'TASK_ID={task_id} PHASE_ID={phase.get("id")} '
              f'VERIFICATION_ENTRYPOINT_CANONICALIZED=YES SELECTED={entrypoint} '
              'SOURCE=EXISTING_MANIFEST_HTML',flush=True)
        return {**value,'entrypoint':entrypoint}

    criteria = acceptance_criteria(phase)
    original_criteria_ids={key for key,text in criteria.items()
        if text.startswith('In the browser, verify the original requirement:')}
    original = str((db.coding_task(task_id) or {}).get('original_goal') or '')
    instructions = task_workspaces.service.instruction_context(task_id)
    if instructions:
        original += '\n[USER_TASK_INSTRUCTIONS]\n' + instructions
    verification_budget = _budget if isinstance(_budget, dict) else {}
    remaining_criteria = len(criteria)
    verification_budget.setdefault('model_calls', 0)
    verification_budget.setdefault('author_calls', 0)
    verification_budget.setdefault('review_calls', 0)
    # Keep ordinary structured responses small enough for local models. When
    # a task has many criteria, enlarge the batch only as much as needed to
    # leave room for bounded repairs inside the phase budget.
    authoring_batch_size = max(VERIFICATION_AUTHORING_BATCH_SIZE,
        (remaining_criteria + max(1, VERIFICATION_MAX_AUTHOR_CALLS - 3) - 1)
        // max(1, VERIFICATION_MAX_AUTHOR_CALLS - 3))
    authoring_batch_count = max(1, (remaining_criteria + authoring_batch_size - 1)
                               // authoring_batch_size)
    verification_budget.setdefault('author_call_limit', min(
        VERIFICATION_MAX_AUTHOR_CALLS,
        max(5, 2 * authoring_batch_count + 2),
    ))
    verification_budget.setdefault('exhaustion', '')
    verification_author_call_limit = int(verification_budget['author_call_limit'])

    def reserve_verification_model_call(kind: str, requested: dict[str, str]) -> bool:
        stop_reason=verification_budget_stop_reason(verification_budget,kind,
            verification_author_call_limit,VERIFICATION_MAX_MODEL_CALLS,VERIFICATION_MAX_REVIEW_CALLS)
        if stop_reason:
            verification_budget['exhaustion']=stop_reason
            return False
        verification_budget['model_calls'] += 1
        if kind == 'author':
            verification_budget['author_calls'] += 1
        else:
            verification_budget['review_calls'] += 1
        verification_budget['progress'] = {
            'verification_kind': kind,
            'attempt': verification_budget['author_calls'] if kind == 'author' else verification_budget['review_calls'],
            'max_attempts': verification_author_call_limit if kind == 'author' else VERIFICATION_MAX_REVIEW_CALLS,
            'model_calls': verification_budget['model_calls'],
            'max_model_calls': VERIFICATION_MAX_MODEL_CALLS,
            'criteria_count': len(requested),
        }
        _record_coding_model_progress(task_id, {
            'state': 'worker_progress',
            'event': f'verification_{kind}_progress',
            **verification_budget['progress'],
        })
        _CODING_VERIFICATION_PROGRESS.set(verification_budget['progress'])
        return True

    def review_verification_failure(*args, **kwargs):
        token = _CODING_VERIFICATION_PROGRESS.set(None)
        try:
            return _review_verification_failure(*args, **kwargs,
                                                _reserve_model_call=reserve_verification_model_call)
        finally:
            _CODING_VERIFICATION_PROGRESS.reset(token)

    def review_project_test_failures(observed):
        token = _CODING_VERIFICATION_PROGRESS.set(None)
        try:
            return _review_project_test_failures(task_id,original,criteria,sources,observed,
                _reserve_model_call=reserve_verification_model_call,
                file_manifest=plan.get('file_manifest') or [])
        finally:
            _CODING_VERIFICATION_PROGRESS.reset(token)

    # Repairs reuse their checks; a new user requirement must invalidate them.
    def contract_identity(version):
        return hashlib.sha256(json.dumps({'criteria':criteria, 'request':original, 'executor_version':version}, sort_keys=True).encode()).hexdigest()[:16]
    # Check-shape and retry-state changes invalidate failed authoring attempts
    # while retaining and rechecking previously earned checks.
    identity = contract_identity(35)
    source_identity=hashlib.sha256(json.dumps(source_digests,sort_keys=True).encode()).hexdigest()
    recovery_signature=hashlib.sha256(json.dumps({'contract':identity,'sources':source_identity},sort_keys=True).encode()).hexdigest()
    previous_failure=((db.coding_task(task_id) or {}).get('resume_state') or {}).get('verification_preparation_failure') or {}
    def annotate_verification_failure(error: Exception, current_value: dict | None=None) -> Exception:
        saved=(previous_failure if previous_failure.get('signature')==recovery_signature
               and not verification_budget.get('_resume_budget_reset') else {})
        calls={name:max(int(verification_budget.get(name) or 0),int(saved.get(name) or 0))
               for name in ('model_calls','author_calls','review_calls')}
        covered={identifier for check in (current_value or {}).get('checks') or []
                 if isinstance(check,dict) for identifier in check.get('ids') or []
                 if identifier in criteria}
        error.verification_signature=recovery_signature
        error.verification_model_calls=calls['model_calls']
        error.verification_author_calls=calls['author_calls']
        error.verification_review_calls=calls['review_calls']
        error.verification_model_call_limit=VERIFICATION_MAX_MODEL_CALLS
        error.verification_author_call_limit=int(verification_budget.get('author_call_limit')
            or saved.get('author_call_limit') or 0)
        error.verification_budget_exhaustion=(verification_budget.get('exhaustion')
            or saved.get('budget_exhaustion',''))
        error.verification_budget_version=VERIFICATION_BUDGET_VERSION
        error.verification_covered_ids=sorted(covered)
        error.verification_missing_ids=sorted(set(criteria)-covered)
        return error
    if _semantic_pass>=VERIFICATION_MAX_SEMANTIC_PASSES:
        blocked=RuntimeError('VERIFICATION_CONTRACT_INVALID: semantic coverage did not converge within its bounded review passes. '
            f'自動検証を安全上限で停止しました（作成 {verification_budget["author_calls"]}/{verification_author_call_limit}、'
            f'独立評価 {verification_budget["review_calls"]}/{VERIFICATION_MAX_REVIEW_CALLS}、総呼出し '
            f'{verification_budget["model_calls"]}/{VERIFICATION_MAX_MODEL_CALLS}）。既存のチェックとソースは保持しました。')
        verification_budget['exhaustion']='semantic-pass limit'
        raise annotate_verification_failure(blocked)
    directory = Path(db.path).resolve().parent / 'coding-verification' / task_id
    directory.mkdir(parents=True, exist_ok=True)
    contract_path = directory / (hashlib.sha256(phase['id'].encode()).hexdigest()[:16] + '-' + identity + '.json')
    diagnostic_path=directory/(contract_path.stem+'-runtime-diagnostic.json')
    requirements = (db.coding_task(task_id) or {}).get('requirements') or {}
    requires_tests = (node_only_browser_gate or bool(phase.get('host_declared_test_command'))
        or any(is_project_test_path(path) for path in sources)
        or 'tests' in (requirements.get('required_verification') or [])
        or bool(re.search(r'node:test|node\s+--test|テスト.{0,8}実行', original, re.I)))
    selection_spec=_selection_exclusion_spec(original,criteria,sources)
    forbid_external_requests=any(network_browser_criteria({key:text}) for key,text in criteria.items())
    def executable(value, partial=False, diagnostic=False, source_defect=False, source_evidence=None):
        value['_olcr_source_identity']=source_identity
        value['requires_tests']=requires_tests
        value['selection_exclusion']=selection_spec
        value['forbid_external_requests']=forbid_external_requests
        value['mobile_criteria']=[identifier for identifier,text in criteria.items()
            if re.search(r'\bsmartphones?\b|\bmobile\b|スマートフォン|モバイル',text,re.I)]
        target=diagnostic_path if diagnostic else contract_path
        target.write_text(json.dumps(value,ensure_ascii=False),encoding='utf8')
        evidence=source_evidence if source_defect and isinstance(source_evidence,dict) else {}
        review=evidence.get('review') if isinstance(evidence.get('review'),dict) else {}
        repair_paths=set(evidence.get('repair_paths') or [])
        for path in (review.get('source_path'),review.get('path')):
            if isinstance(path,str) and path in sources and not is_project_test_path(path):
                repair_paths.add(path)
        fragment=review.get('source_fragment')
        if isinstance(fragment,str) and fragment:
            repair_paths.update(path for path,source in sources.items()
                if not is_project_test_path(path) and fragment in source)
        repair_paths=sorted(path for path in repair_paths
            if isinstance(path,str) and path in sources and not is_project_test_path(path))
        return {**phase,'verification_command':acceptance_command(target,root),
                'verification_targets':list(sources),'host_criteria':criteria,
                'host_partial_verification':partial or diagnostic,'host_runtime_diagnostic':diagnostic,
                'host_test_preflight':False,'host_contract_failure':'',
                'host_source_defect':source_defect,
                'host_source_defect_repair_paths':repair_paths,
                'host_project_test_setup_repair':False,
                'host_verification_current_source_reviewed':True,
                'host_source_defect_evidence':source_evidence if source_defect else None}
    def retain_checks(previous, checks):
        # Review evidence belongs to an exact check body, not just an ID.
        # Rebuilding a partial batch must retain earned reviews for unchanged
        # checks while invalidating reviews for removed/replaced checks.
        previous=previous or {}
        return {**previous,'checks':checks,'_olcr_semantically_reviewed_ids':
            retained_semantic_review_ids(previous,checks)}
    def project_test_failure_phase(observed, target_phase):
        finding=project_test_failure_diagnosis(observed,sources,
            requirements=[original,*criteria.values()],file_manifest=plan.get('file_manifest'))
        if finding['verdict']=='INCONCLUSIVE':
            finding=review_project_test_failures(observed)
        if finding.get('verdict')=='SOURCE_DEFECT':
            fragment=finding.get('source_fragment') or ''
            reviewed_paths=set(finding.get('repair_paths') or [])
            source_paths=sorted(path for path,source in sources.items()
                if not is_project_test_path(path) and fragment and fragment in source
                and (not reviewed_paths or path in reviewed_paths))
            if source_paths:
                return {**target_phase,'host_verification_current_source_reviewed':True,
                    'host_source_defect':True,'host_source_defect_repair_paths':source_paths,
                    'host_source_defect_evidence':{'review':finding,'repair_paths':source_paths,
                        'failures':observed.get('failures') or []},
                    'host_current_command_evidence':observed}
        repair_paths=reviewed_project_test_paths(finding,sources)
        if finding.get('verdict')!='CHECK_DEFECT' or not repair_paths:
            raise annotate_verification_failure(RuntimeError('VERIFICATION_CONTRACT_INVALID: project tests failed, but current evidence does not establish whether the test or application is defective. '+str(finding.get('reason') or '')))
        return {**target_phase,'host_verification_current_source_reviewed':True,'host_current_command_failure':True,
                'host_project_test_defect':True,'host_project_test_repair_paths':repair_paths,
                'host_project_test_setup_repair':finding.get('project_test_setup_repair') is True,
                'verification_repair_allowed':True,
                'host_current_command_evidence':{**observed,'test_diagnosis':finding}}
    if preserve_declared_executor:
        # Preserve approved argv/targets exactly, while reviewing failure
        # ownership before any writable dispatch (including Node-only goals).
        probe=host_probe(phase)
        if probe:
            observed=probe[1]
            if not observed.get('passed') and is_project_test_command(declared_command):
                return project_test_failure_phase(observed,phase)
            return {**phase,'host_verification_current_source_reviewed':True,
                'host_current_command_evidence':observed if not observed.get('passed') else None,
                'host_current_command_failure':bool(not observed.get('passed') and not observed.get('changed_targets'))}
        return phase
    value = None
    # Preserve old checks across executor upgrades, but exercise/review them
    # against current bytes before granting any implementation authority.
    cached_path=contract_path
    if not cached_path.is_file():
        cached_path=next((directory/contract_path.name.replace(identity,contract_identity(version))
                          for version in (34,33,32,31,30,29,28,27,26,25,24,23,22,21,20,19,18,17,16,15,14,13) if
                          (directory/contract_path.name.replace(identity,contract_identity(version))).is_file()),cached_path)
    if cached_path.is_file():
        try:
            value = json.loads(cached_path.read_text())
        except (OSError, ValueError):
            pass
    value=bind_entrypoint(value)
    owned_layout=standard_verification_checks({key:text for key,text in criteria.items()
        if layout_browser_criteria({key:text})})
    owned_layout_ids={key for check in owned_layout for key in check['ids']}
    if value and owned_layout_ids:
        retained=[]
        for check in value.get('checks') or []:
            identifiers=[key for key in check.get('ids') or [] if key not in owned_layout_ids]
            if identifiers:retained.append({**check,'ids':identifiers})
        value=retain_checks(value,[*retained,*owned_layout])
    scenario_setup_diagnostics=verify_required_scenario_capabilities(criteria,sources)
    if value and isinstance(value,dict) and value.get('_olcr_semantic_review_version')!=2:
        value['_olcr_semantically_reviewed_ids']=[]
    if value and isinstance(value,dict) and value.get('_olcr_typed_transport') and value.get('_olcr_observation_compiler_version')!=5:
        reviewed=set(value.get('_olcr_semantically_reviewed_ids') or [])
        value['checks']=[check for check in value.get('checks') or []
            if not ((set(check.get('ids') or []) & original_criteria_ids)-reviewed)]
    complete_cached = not validate_verification(value,criteria,root)
    if complete_cached:
        complete_cached = not verification_syntax_errors(value)
    same_failure_signature=(str(previous_failure.get('error') or '').startswith('VERIFICATION_CONTRACT_INVALID:')
        and previous_failure.get('signature')==recovery_signature)
    current_retry_epoch=int(((db.coding_task(task_id) or {}).get('resume_state') or {}).get('verification_retry_epoch') or 0)
    repeat_failure=bool(same_failure_signature and (
        int(previous_failure.get('verification_retry_epoch') or 0)==current_retry_epoch
        or int(previous_failure.get('repeat_count') or 0)>=VERIFICATION_MAX_SAME_SOURCE_MANUAL_RETRIES+1))
    if not complete_cached and repeat_failure and not (value and not verification_syntax_errors(value)
            and all(error.startswith(('checks must cover every acceptance criterion','BROWSER checks must cover'))
                    for error in validate_verification(value,criteria,root))):
        # A user Resume is not new evidence. If the exact acceptance contract
        # and every manifested source byte are unchanged, do not repeat an
        # identical model-authoring loop. A complete cached contract is still
        # allowed through so existing deterministic evidence can be evaluated.
        blocked=RuntimeError('VERIFICATION_CONTRACT_INVALID: the same verification contract already failed for unchanged task and source. The previous work is retained; change the task/source or select a different verification method before retrying.')
        raise annotate_verification_failure(blocked,value)
    if requires_tests and criteria:
        # Surface an actual failing test before spending model calls authoring
        # browser checks for a module which cannot even be loaded yet.
        if html_entrypoints:
            preflight_path = directory / 'node-test-preflight.json'
            preflight_path.write_text(json.dumps({'entrypoint':html_entrypoints[0],
                'requires_tests':True,'checks':[]}),encoding='utf8')
            command = acceptance_command(preflight_path,root)
            preflight = run_acceptance(command,str(root),80)
            if preflight.returncode != 0:
                try:
                    observed=json.loads((preflight.stdout or '').rsplit('OLCR_VERIFICATION_RESULT=',1)[1].splitlines()[0])
                except (IndexError,ValueError):
                    raise VerificationExecutorError('Project-test preflight returned no structured result.')
                if observed.get('executor_error'):
                    raise VerificationExecutorError(str(observed.get('failures') or 'Project-test executor failed'))
                observed={**observed,'command':command,'returncode':preflight.returncode,
                          'output':(preflight.stdout or '')+(preflight.stderr or '')}
                return project_test_failure_phase(observed,{**phase,'verification_command':command,
                    'verification_targets':list(sources),'host_criteria':criteria,'host_test_preflight':True})
    startup_ids=browser_criteria(criteria)
    if html_entrypoints and startup_ids:
        # Project tests can mock or duplicate the app without ever loading its
        # real browser entrypoint. A failed actual startup is source evidence,
        # never an invitation to rewrite responsive or behavior assertions.
        startup_entrypoint=(value or {}).get('entrypoint') if isinstance(value,dict) else None
        if startup_entrypoint not in html_entrypoints:startup_entrypoint=html_entrypoints[0]
        startup={'entrypoint':startup_entrypoint,'checks':[{'ids':sorted(startup_ids),'kind':'BROWSER',
            'code':'assert.equal(await page.locator("html").count(),1);'}],
            'collect_observations':True,'forbid_external_requests':forbid_external_requests}
        startup_path=directory/(contract_path.stem+'-startup.json')
        startup_path.write_text(json.dumps(startup),encoding='utf8')
        startup_probe=host_probe({**phase,'verification_command':acceptance_command(startup_path,root),
            'verification_targets':list(sources),'host_criteria':{key:criteria[key] for key in startup_ids}})
        startup_failures=(startup_probe[1].get('failures') or []) if startup_probe else []
        locations=[location for failure in startup_failures if failure.get('project_source_error')
            for error in failure.get('browser_errors') or [] for location in error.get('source_locations') or []]
        if locations:
            location=locations[0]
            return {**executable(startup,diagnostic=True,source_defect=True,source_evidence={
                'review':{'verdict':'SOURCE_DEFECT','evidence_origin':'BROWSER_STARTUP_EXCEPTION',
                    'reason':'The actual browser entrypoint failed before any acceptance check ran.',
                    'requirement':criteria[sorted(startup_ids)[0]],'source_path':location['path'],
                    'line':location['line'],'source_fragment':location['source_line']},
                'failures':startup_failures}), 'host_current_command_evidence':startup_probe[1]}
    if diagnostic_path.is_file():
        try:
            diagnostic=bind_entrypoint(json.loads(diagnostic_path.read_text()),
                preferred=(value or {}).get('entrypoint') if isinstance(value,dict) else None)
            covered={key for check in diagnostic['checks'] for key in check['ids']}
            if covered and covered<=set(criteria) and not validate_verification(diagnostic,{key:criteria[key] for key in covered},root):
                diagnostic_phase=executable(diagnostic,diagnostic=True)
                probe=host_probe({**diagnostic_phase,'host_criteria':{key:criteria[key] for key in covered}})
                if probe and any(f.get('project_source_error') for f in probe[1].get('failures') or []):
                    return diagnostic_phase
        except (OSError,ValueError,KeyError,TypeError):
            pass  # Diagnostic probes never establish final acceptance.
    errors = validate_verification(value, criteria, root)
    if not errors:
        errors = verification_syntax_errors(value)
    if value is None:
        standard = standard_verification_checks(criteria)
        if standard and html_entrypoints:
            value = {'entrypoint':html_entrypoints[0], 'checks':standard}
            errors = validate_verification(value, criteria, root)
    coverage_prefixes = ('checks must cover every acceptance criterion', 'BROWSER checks must cover')
    if not verification_budget.get('_resume_budget_initialized'):
        current_covered={identifier for check in (value or {}).get('checks') or []
                         if isinstance(check,dict) for identifier in check.get('ids') or []
                         if identifier in criteria}
        current_missing=set(criteria)-current_covered
        same_contract=previous_failure.get('signature')==recovery_signature
        previous_covered=set(previous_failure.get('covered_ids') or [])
        previous_missing=set(previous_failure.get('missing_ids') or [])
        coverage_advanced=bool(previous_covered and current_covered>previous_covered
            or previous_missing and current_missing<previous_missing)
        current_budget_version=int(previous_failure.get('budget_version') or 0)
        retry_state=((db.coding_task(task_id) or {}).get('resume_state') or {})
        retry_epoch_advanced=(same_contract
            and int(retry_state.get('verification_retry_epoch') or 0)
                > int(previous_failure.get('verification_retry_epoch') or 0)
            and int(retry_state.get('verification_retry_epoch') or 0)
                <= VERIFICATION_MAX_SAME_SOURCE_MANUAL_RETRIES)
        if (same_contract and current_budget_version==VERIFICATION_BUDGET_VERSION
                and not coverage_advanced and not retry_epoch_advanced):
            for field in ('model_calls','author_calls','review_calls'):
                verification_budget[field]=max(int(verification_budget.get(field) or 0),
                                               int(previous_failure.get(field) or 0))
            verification_budget['author_call_limit']=min(VERIFICATION_MAX_AUTHOR_CALLS,max(
                int(verification_budget.get('author_call_limit') or 0),
                int(previous_failure.get('author_call_limit') or previous_failure.get('author_calls') or 0)))
            verification_budget['exhaustion']=str(previous_failure.get('budget_exhaustion') or '')
            verification_budget['_resume_budget_reset']=False
        else:
            verification_budget.update(model_calls=0,author_calls=0,review_calls=0,exhaustion='')
            verification_budget['_resume_budget_reset']=True
        verification_budget['_resume_budget_initialized']=True
        verification_budget['_covered_ids']=sorted(current_covered)
        verification_budget['_missing_ids']=sorted(current_missing)
    failed_checks = []
    semantic_repair_required=False
    draft_typed_transport=False
    authoring_path=directory/(contract_path.stem+'-authoring.json')
    failed_check_errors = str(phase.get('host_contract_failure') or '')
    if (value and all(error.startswith(coverage_prefixes) for error in errors)
            and not verification_syntax_errors(value)):
        # Exercise preserved checks before authoring missing ones. A check can
        # itself be defective, so only a reviewed source contradiction may
        # authorize implementation; other failures are scoped for repair.
        partial_phase=executable(value,partial=bool(errors))
        covered={key for check in value['checks'] for key in check['ids']}
        probe=host_probe({**partial_phase,'host_criteria':{
            key:criteria[key] for key in covered}})
        failures=(probe[1].get('failures') or []) if probe else []
        if any(failure.get('ids')==['REQUIRED_TESTS'] and not failure.get('contract_error')
               and not failure.get('executor_error') for failure in failures):
            # The owned runner executes the real registered project tests
            # before its UI checks. A test regression belongs to the project,
            # not to model-authored acceptance-check repair.
            return {**executable(value,partial=bool(errors)),'host_current_command_failure':True,
                    'host_current_command_evidence':{key:probe[1].get(key) for key in
                        ('command','returncode','output','test_runs','failures','zero_tests')}}
        if failures and any(f.get('project_source_error') for f in failures):
            return executable(value,diagnostic=True)
        behavior_failures=[failure for failure in failures if not failure.get('contract_error')]
        if behavior_failures:
            scoped={key:criteria[key] for key in covered}
            failed_ids={key for failure in behavior_failures for key in failure.get('ids') or [] if key in scoped}
            failing_checks=[check for check in value['checks'] if set(check['ids'])&failed_ids]
            failed_candidate={'entrypoint':value.get('entrypoint'),'checks':failing_checks}
            failure_identity=_verification_failure_identity(failed_candidate,behavior_failures,source_identity)
            saved_review=value.get('_olcr_failure_review') or {}
            owned=standard_verification_checks({key:criteria[key] for key in failed_ids})
            if owned and failing_checks==owned:
                review={'verdict':'SOURCE_DEFECT','reason':'The owned test/resource/browser executor observed an actual project failure.',
                        'evidence_origin':'OWNED_EXECUTOR_FAILURE'}
            elif saved_review.get('identity')==failure_identity and (saved_review.get('review') or {}).get('verdict')=='SOURCE_DEFECT':
                review=saved_review['review']
            else:
                review=review_verification_failure(task_id,original,scoped,sources,failed_candidate,behavior_failures)
            if review.get('verdict')=='SOURCE_DEFECT':
                value['_olcr_failure_review']={'identity':failure_identity,'review':review}
                return executable(value,partial=True,source_defect=True,source_evidence={
                    'review':review,'failures':[{'ids':failure.get('ids'),'error':failure.get('error'),
                        'check_source':failure.get('check_source') or
                            (failure.get('assertion_source') or {}).get('snippet'),
                        'observed_page':failure.get('observed_page'),
                        'browser_actions':failure.get('browser_actions')} for failure in behavior_failures]})
            if repeat_failure:
                blocked=RuntimeError('VERIFICATION_CONTRACT_INVALID: saved checks failed review and the same check-generation attempt already stopped for unchanged source. Existing files and passing checks are retained; revise the task or source before retrying.')
                raise annotate_verification_failure(blocked,value)
            failed_checks=failing_checks
            semantic_repair_required=True
            failed_check_errors=json.dumps({'failures':failures,'review':{
                'verdict':review.get('verdict'),'reason':str(review.get('reason') or '')[:600],
                'verification_form':review.get('verification_form')}},ensure_ascii=False)
            value=retain_checks(value,[check for check in value['checks'] if check not in failing_checks])
            errors=validate_verification(value,criteria,root)
        elif repeat_failure and errors:
            blocked=RuntimeError('VERIFICATION_CONTRACT_INVALID: acceptance criteria remain uncovered and the same check-generation attempt already stopped for unchanged source. Existing work is retained; revise the task or source before retrying.')
            raise annotate_verification_failure(blocked,value)
        if any(f.get('contract_error') for f in failures):
            phase={**phase,'host_contract_failure':json.dumps(failures,ensure_ascii=False)}
        if probe and not probe[1].get('passed') and not failures:
            # A missing executor/result is never evidence that checks or
            # source need rewriting. Leave the actual runner to report it.
            return executable(value,partial=bool(errors))
        if probe and probe[1].get('passed'):
            reviewed=set(value.get('_olcr_semantically_reviewed_ids') or [])
            unchecked=[check for check in value['checks'] if
                (set(check.get('ids') or []) & original_criteria_ids)-reviewed]
            if unchecked:
                review=review_verification_failure(task_id,original,
                    {key:criteria[key] for check in unchecked for key in check['ids']},sources,
                    {'entrypoint':value['entrypoint'],'checks':unchecked},[],
                    observations=probe[1].get('browser_observations'))
                if review.get('verdict')=='CHECK_VALID':
                    reviewed.update(key for check in unchecked for key in check['ids'])
                    value['_olcr_semantically_reviewed_ids']=sorted(reviewed)
                    value['_olcr_semantic_review_version']=2
                    executable(value,partial=bool(errors))
                else:
                    failed_checks=unchecked
                    semantic_repair_required=True
                    failed_check_errors=json.dumps({'review':review,'finding':'Passing checks did not prove the original requirement'},ensure_ascii=False)
                    value=retain_checks(value,[check for check in value['checks'] if check not in unchecked])
                    errors=validate_verification(value,criteria,root)
                if _pause_at_checkpoint(task_id):
                    executable(value,partial=bool(errors))
                    return phase
        if probe and probe[1].get('passed') and not errors:
            _clear_verification_preparation_failure(task_id,recovery_signature)
            return executable(value)
    failure_context = _verification_failure_context
    def repair_finding(failures,review,*,passed=False):
        # Put measured facts before advisory prose, so the bounded prompt
        # cannot discard visible guidance behind a long model quotation. Do
        # retain the source quotation that justifies a setup correction.
        # The rejected program is supplied separately as execution evidence.
        measured=failure_context(failures)
        for item in measured:
            item.pop('check_source',None)
            item.pop('assertion_source',None)
        return json.dumps({('successful_checks' if passed else 'failures'):measured,'review':{
            'verdict':review.get('verdict'),'reason':str(review.get('reason') or '')[:800],
            'verification_form':review.get('verification_form'),
            'requirement':str(review.get('requirement') or '')[:300],
            'source_fragment':str(review.get('source_fragment') or '')[:1000]}},ensure_ascii=False)
    if phase.get('host_contract_failure'):
        try:
            failures = json.loads(phase['host_contract_failure'])
        except (ValueError, TypeError):
            failures = []
        if isinstance(failures,list):
            failed_check_errors=json.dumps({'failures':failure_context(failures)},ensure_ascii=False)
            semantic_repair_required=any(not failure.get('contract_error') for failure in failures if isinstance(failure,dict))
        failed_ids = {key for item in failures if isinstance(item, dict) for key in item.get('ids') or []}
        if value and failed_ids:
            failed_checks = [check for check in value['checks'] if set(check['ids']) & failed_ids]
            value = retain_checks(value,[check for check in value['checks'] if not set(check['ids']) & failed_ids])
            errors = validate_verification(value, criteria, root)
        else:
            errors.append('A verification check could not execute independently of application assertions.')
    elif authoring_path.is_file():
        try:
            draft=json.loads(authoring_path.read_text())
            draft_typed_transport=bool(draft.get('source_identity')==source_identity and draft.get('typed_transport'))
            pending=verification_coverage_gaps(value,criteria) if value else criteria
            first=next(iter(sorted(pending,key=lambda key:
                not pending[key].startswith('In the browser, verify the original requirement:'))),None)
            checks=draft.get('checks') or []
            identifiers={key for check in checks for key in check.get('ids') or []}
            if (draft.get('source_identity')==source_identity and identifiers=={first}
                    and all(isinstance(check.get('code'),str) for check in checks)):
                failed_checks=checks
                failed_check_errors=str(draft.get('finding') or '')[:10000]
                semantic_repair_required=draft.get('semantic_repair_required',True) is not False
        except (OSError,ValueError,TypeError,KeyError,AttributeError):
            pass  # A draft is advisory; it never supplies accepted evidence.
    malformed_attempts = 0
    encoding_failure = False
    adaptive_batch_limit = authoring_batch_size
    output_limit_retry_ids = set()
    literal_output_limit_retries = set()
    typed_transport=bool(draft_typed_transport or (value or {}).get('_olcr_typed_transport') or previous_failure)
    author_attempts,observed_signatures={},{}
    semantic_handoffs=set()
    last_attempt_key=None
    for repair in range(verification_author_call_limit + 1 if errors else 0):
        base_errors = validate_verification(value, criteria, root)
        partial = (value if value is not None and base_errors and all(
            error.startswith(coverage_prefixes) for error in base_errors)
            and not verification_syntax_errors(value) else None)
        gaps = verification_coverage_gaps(partial, criteria) if partial else None
        requested = gaps if gaps is not None else criteria
        # Author a small missing-contract batch per call. The host runner still
        # validates every ID and executes every assertion independently.
        requested = dict(sorted(requested.items(),key=lambda item:
            not item[1].startswith('In the browser, verify the original requirement:')))
        if not partial and not failed_checks:
            human_requirements={key:text for key,text in requested.items()
                if text.startswith('In the browser, verify the original requirement:')}
            if human_requirements and len(human_requirements)<len(requested):
                # Keep the user's explicit behavior ahead of generic planner
                # summaries. Once these checks are preserved, the next call
                # batches the remaining planner-owned criteria.
                requested=human_requirements
        if failed_checks:
            failed_ids={identifier for check in failed_checks for identifier in check.get('ids') or []}
            if failed_ids:
                requested={key:text for key,text in requested.items() if key in failed_ids}
        layout_requested={key:text for key,text in requested.items()
                          if layout_browser_criteria({key:text})}
        scenario_requested={key:text for key,text in requested.items()
                            if multi_scenario_browser_criteria({key:text})}
        special_observation=bool(layout_requested or scenario_requested)
        # These contracts need a different number of literal checks per ID.
        # Keep each schema homogeneous so scenario metadata cannot be applied
        # to unrelated IDs and viewport actions cannot be collapsed together.
        if layout_requested:
            requested=layout_requested
        elif scenario_requested:
            requested=scenario_requested
        elif typed_transport and browser_criteria(requested):
            requested={key:text for key,text in requested.items()
                       if key in browser_criteria(requested)}
        if output_limit_retry_ids:
            retry_subset={key:text for key,text in requested.items() if key in output_limit_retry_ids}
            if retry_subset:
                requested=retry_subset
            else:
                output_limit_retry_ids.clear()
                adaptive_batch_limit=authoring_batch_size
        # Keep repair batches bounded as well. The author budget above is
        # derived from this size, leaving room for a failed generation and a
        # format recovery without discarding already accepted checks.
        batch_limit=adaptive_batch_limit
        requested=dict(list(requested.items())[:batch_limit])
        # Execute mechanically defined criteria with owned checks even in a
        # mixed batch. Otherwise the model can repeatedly replace a test-exit
        # requirement with unrelated DOM assertions.
        mechanical={identifier for check in standard_verification_checks(requested)
                    for identifier in check['ids']}
        if mechanical:
            requested={key:text for key,text in requested.items() if key in mechanical}
        attempt_key=tuple(requested)
        if attempt_key!=last_attempt_key:
            # Narrowing a rejected batch is a new bounded authoring problem,
            # not another malformed response to its old multi-ID request.
            malformed_attempts=0
            last_attempt_key=attempt_key
        author_attempts[attempt_key]=author_attempts.get(attempt_key,0)+1
        observation_signature=None
        typed_transport=typed_transport or bool(malformed_attempts and encoding_failure)
        required_form=None
        if semantic_repair_required and failed_check_errors:
            try:
                required_form=(json.loads(failed_check_errors).get('review') or {}).get('verification_form')
            except (ValueError,TypeError,AttributeError):
                pass
        prompt = verification_prompt(phase, original, sources, requested,
                                    force_code=required_form=='STATEFUL_CODE')
        if scenario_setup_diagnostics:
            prompt+='\nADVISORY_UI_DISCOVERY: '+json.dumps(scenario_setup_diagnostics,ensure_ascii=False)+'. These are discovery limitations, not established application defects. Use actual source-backed user interactions, including allergy controls when applicable.'
        if html_entrypoints:
            prompt += '\nVERIFICATION_ENTRYPOINT: Use exactly '
            prompt += json.dumps(partial.get('entrypoint') if partial else html_entrypoints[0],ensure_ascii=False)
            prompt += '. This is an existing HTML file in the authorized task manifest.'
        prompt += ('\nUse only the host-defined check count and shape for each criterion; every check contains only its own ID. '
            'Keep distinct behaviors independently asserted; use the appropriate executor and actual source API. '
            'This is read-only verification of the already implemented project. Do not create or edit project files, tests or source. '
            'Do not return reasoning, prose, placeholders or unfinished code.')
        if partial:
            prompt += '\nExisting valid checks are preserved by OLCR. Return only additional checks for the supplied missing IDs. Do not regenerate already covered checks. Use the same entrypoint: ' + partial['entrypoint']
            brief_errors=[error.split(': ',1)[0][:240] for error in errors] if failed_checks else errors
            prompt += '\nValidation errors: ' + json.dumps(brief_errors)
        elif not failed_checks and (repair or (value is not None and errors)):
            prompt += '\nRepair the previous verification JSON, preserving requested assertions:\n' + json.dumps(value) + '\nErrors: ' + json.dumps(errors)
        if failed_checks:
            # Do not feed the rejected executable back to its author. Local
            # models often copy malformed selectors, helper calls or quoting
            # verbatim, which turns a bounded repair into the same failure
            # repeated under a fresh invocation. The review finding, measured
            # browser state and current source below are the repair evidence.
            failed_check_outline=[{'ids':check.get('ids') or [],'kind':check.get('kind'),
                'format':'code' if isinstance(check.get('code'),str) else 'literal_observations'}
                for check in _focused_verification_checks(failed_checks,requested)]
            prompt += ('\nRepair these failed checks using the review. Preserve the original required behavior and meaningful assertions. '
                'Correct assertions identified by the review as invalid or unrelated; do not preserve a known incorrect expectation. '
                'Write a fresh concise check from the requirement and current source. '
                + '\nFAILED_CHECK_TO_REPAIR (IDs and format only; rejected executable omitted): '+json.dumps(failed_check_outline,ensure_ascii=False)
                + '\nFix missing setup actions and invalid selectors using the actual source and observations. Preserve the behavioral assertions and reload/state comparisons. Do not restart from a generic check.'
                + '\nFailed check IDs: '+json.dumps([check['ids'] for check in failed_checks]))
        prompt += ('\nFINAL_FOCUS: ' + json.dumps(requested, ensure_ascii=False)
            + '\nReturn the exact host-defined number of separate checks for every listed ID. Use the appropriate executor, source selectors and API. Do not assert unrelated behavior. The original user requirement overrides conflicting planner wording.')
        if failed_checks:
            prompt += '\nFINAL_REPAIR_FINDING (check against the original requirement): '+_bounded_verification_repair_finding(failed_check_errors)
            if browser_criteria(requested):
                prompt += '\nUse the concrete observed_page facts in that finding. messages contains visible text with real selectors and buttons contains actual disabled states.'
                if re.search(r'empty input|input.{0,12}empty|空入力|入力.{0,8}空|有効.{0,8}候補.{0,12}ない','\n'.join(requested.values()),re.I):
                    prompt += (' For this empty-input check, read the existing visible guidance from those messages, keep the input empty/whitespace, '
                        'and do not assume the result area is the guidance element or that an uncalled handler ran at startup.')
            else:
                prompt += ('\nNODE_REPAIR_RULE: Imported bindings/local helpers are not exports of the importing test module. '
                    'Remove invalid testModule namespace assertions; do not re-create them. Read actual test import/call source, inspect only the actual API module exports, and execute runTests as required. '
                    'A review that identifies an invalid expectation authorizes removing that expectation while retaining the actual human requirement.')
        if failed_checks or failed_check_errors:
            prompt += ('\nSELECTOR_REPAIR: A visual tab or CSS class tab is not an ARIA tab. '
                'Derive accessible roles from actual HTML tags and explicit role attributes. '
                'A button without role=tab must be targeted as button or by its actual selector, not getByRole(tab). '
                'Keep the original behavioral assertion; fix the interaction selector and execute through the final observation. '
                'Use the saved failure review and source to replace a rejected selector; do not repeat it unchanged.')
        if declarative_browser_criteria(requested) and required_form!='STATEFUL_CODE':
            prompt += ('\nTRANSPORT_FOCUS: Return literal actions and observations only, without JavaScript or a code field. '
                'Previous JavaScript syntax/escaping problems are avoided by this format. Describe real selectors and required observations; OLCR compiles the program.')
        literal_only = (required_form=='LITERAL_OBSERVATIONS'
                        or required_form!='STATEFUL_CODE' and (special_observation
                            or typed_transport and browser_criteria(requested)==set(requested)))
        if literal_only:
            prompt += ('\nREAD_ONLY_LITERAL_CONTRACT: Return only checks with ids, kind, actions and observations as allowed by the schema. '
                'Do not include a code field or JavaScript snippets. The checker observes the existing app and the host compiles these facts; '
                'never author project tests or change the workspace. Return JSON only, with no reasoning, placeholders, ellipses or comments.')
        elif typed_transport:
            prompt += ('\nFINAL_TRANSPORT: For fixed final-state checks, prefer actions and observations using the JSON schema, without a code field or JavaScript snippets. '
                'OLCR compiles JSON literals into awaited checks. Use DOM measures for real page observations, '
                'file_text/file_nonempty for file facts, module_has_export with selector=module path and export_name, '
                'module_call with selector=module path, export_name and arguments for executing the actual API, '
                'json_field with selector=JSON file path and property_path for configuration, and test_count for actual registered project tests. '
                'For storage failure, use action storage_failure with selector localStorage and boolean value true before a normal UI save, then assert visible error guidance. false restores writes. Code checks may await setStorageFailure(true/false). Never omit failure-path coverage. '
                'Each observation contains selector, measure, operator and expected. Add export_name/arguments only for module_call, '
                'export_name only for module_has_export, and property_path only for json_field. '
                'To verify a particular screen size, use action viewport with selector page and value {width:320,height:640} (numeric pixel dimensions). '
                'Use actions=[] for file, configuration, export and project-test checks. Use fills/clicks only when needed to exercise the required page behavior; click value is null. '
                'text reads all matched real nodes and joins their text with a newline; a missing target fails. '
                'Do not require a single-line input tag while asserting that filled newlines are preserved. '
                'For checks that must observe intermediate outputs and compare them with later state, '
                'use the alternative {ids,kind,code} form, where code is an array of JavaScript source lines. '
                'Capture actual outputs after each action and derive expected values from those independent captures. '
                'Do not mix code with actions/observations in the same check. Syntax, read-only scope and independent semantic review still apply. '
                'Do not redeclare supplied assert, page, expect, readFile, loadModule or runTests bindings. '
                'Assert the required behavior; a file substring alone cannot prove function behavior. Preserve already passing checks.')
        if required_form=='STATEFUL_CODE':
            prompt+=('\nREQUIRED_VERIFIER_CAPABILITY=STATEFUL_CODE: Return only {ids,kind,code} checks. '
                'code is an array of JavaScript source lines. The reviewer established that intermediate real observations '
                'or derived comparisons are necessary. Do not replace this with fixed final-state literals. '
                'Capture actual values after each required action; preserve the reviewed requirement.')
        # The acceptance designer owns the first semantic correction. Two
        # rejected attempts on the same focused criterion earn one alternate
        # writer, still reviewed independently and within the same loop bound.
        semantic_alternate_model=_alternate_coding_model(settings.planner_model,
            (db.coding_task(task_id) or {}).get('conversation_id'))
        semantic_handoff=bool(semantic_repair_required and not encoding_failure
            and author_attempts[attempt_key]>=3 and attempt_key not in semantic_handoffs
            and semantic_alternate_model)
        author_model=(semantic_alternate_model if semantic_alternate_model and
            (malformed_attempts and encoding_failure or semantic_handoff or attempt_key in semantic_handoffs)
            else settings.planner_model)
        standard=standard_verification_checks(requested)
        owned_standard={key for check in standard for key in check['ids']}==set(requested)
        if owned_standard:
            author_model='OLCR_OWNED_CHECK'
            raw=json.dumps({'entrypoint':partial['entrypoint'] if partial else next(
                (path for path in sources if path.endswith('.html')),'index.html'),'checks':standard},ensure_ascii=False)
        else:
            progress_token=_CODING_VERIFICATION_PROGRESS.set(None)
            try:
                if not reserve_verification_model_call('author', requested):
                    break
                if semantic_handoff:
                    semantic_handoffs.add(attempt_key)
                    print(f'TASK_ID={task_id} VERIFICATION_AUTHOR_HANDOFF=STALLED_SEMANTIC_CHECK CRITERIA={json.dumps(list(attempt_key))} MODEL_NAME={author_model}',flush=True)
                try:
                    raw = _model_text(task_id, 'RUNNING', 'VERIFICATION_CONTRACT', author_model,
                        [{'role':'system', 'content':(
                            'You author an internal, read-only verification contract for files that are already implemented. '
                            'Do not create, edit, or suggest project files, tests, or source changes. '
                            'Return only the JSON object required by the supplied schema. Do not include explanations, reasoning, '
                            'markdown, placeholders, ellipses, or unfinished code. Any code field is executable JavaScript and must be complete.' )},
                         {'role':'user', 'content':prompt}], structured_schema=(
                            verification_schema(requested,force_code=True) if required_form=='STATEFUL_CODE' else
                            verification_observation_schema(requested,allow_code=False) if literal_only
                            else verification_observation_schema(requested) if typed_transport else verification_schema(requested)))
                except ModelFailure as exc:
                    if exc.category == 'output_limit' and len(requested) > 1 and adaptive_batch_limit > 1:
                        adaptive_batch_limit=max(1,min(adaptive_batch_limit-1,len(requested)//2))
                        output_limit_retry_ids.update(requested)
                        _record_coding_model_progress(task_id,{
                            'state':'worker_progress','event':'verification_authoring_batch_reduced',
                            'reason':'structured_output_limit','next_batch_size':adaptive_batch_limit,
                            'criteria_count':len(requested),'model_calls':verification_budget['model_calls'],
                            'max_model_calls':VERIFICATION_MAX_MODEL_CALLS,
                        })
                        print(f'TASK_ID={task_id} VERIFICATION_AUTHORING_BATCH_REDUCED=YES '
                              f'CRITERIA={len(requested)} NEXT_BATCH_SIZE={adaptive_batch_limit} REASON=OUTPUT_LIMIT',flush=True)
                        continue
                    if (exc.category == 'output_limit' and len(requested) == 1
                            and browser_criteria(requested) == set(requested)
                            and attempt_key not in literal_output_limit_retries
                            and required_form != 'STATEFUL_CODE'):
                        # Declarative DOM observations are much smaller than
                        # generated JavaScript. Keep this recovery read-only;
                        # stateful workflows retain their required code form.
                        literal_output_limit_retries.add(attempt_key)
                        typed_transport=True
                        _record_coding_model_progress(task_id,{
                            'state':'worker_progress','event':'verification_authoring_transport_reduced',
                            'reason':'structured_output_limit','next_transport':'literal_observations',
                            'criteria_count':len(requested),'model_calls':verification_budget['model_calls'],
                            'max_model_calls':VERIFICATION_MAX_MODEL_CALLS,
                        })
                        print(f'TASK_ID={task_id} VERIFICATION_AUTHORING_TRANSPORT_REDUCED=YES '
                              'NEXT_TRANSPORT=LITERAL_OBSERVATIONS REASON=OUTPUT_LIMIT',flush=True)
                        continue
                    raise
            finally:
                _CODING_VERIFICATION_PROGRESS.reset(progress_token)
        if raw is None:
            blocked=RuntimeError('VERIFICATION_CONTRACT_INVALID: the verification model returned no executable checks. Existing source changes are retained; retry after the model is available or choose another verification method.')
            raise annotate_verification_failure(blocked,value)
        candidate, parse_error = extract_plan_json(raw)
        if parse_error:
            recovered = complete_verification_prefix(raw)
            if recovered:
                candidate, parse_error = recovered, None
        candidate, discarded_criteria=scope_verification_candidate(candidate,requested)
        if discarded_criteria:
            print(f'TASK_ID={task_id} PHASE_ID={phase.get("id")} '
                  f'VERIFICATION_UNREQUESTED_CHECKS_DISCARDED={json.dumps(discarded_criteria)}',flush=True)
        if (literal_only and isinstance(candidate,dict)
                and any(isinstance(check,dict) and ('code' in check or check.get('kind')!='BROWSER')
                        for check in candidate.get('checks') or [])):
            parse_error='Literal-observation checks cannot contain executable code or a non-browser check.'
        try:
            candidate=compile_browser_observations(candidate,requested,sources)
        except VerificationScenarioCapabilityGap as exc:
            # Failure to discover a scenario is a check-authoring problem;
            # this exception contains no observed application contradiction.
            parse_error='Invalid browser observations: '+str(exc)
        except (ValueError,TypeError) as exc:
            parse_error='Invalid browser observations: '+str(exc)
        candidate = normalize_verification_source(candidate)
        candidate=bind_entrypoint(candidate,partial.get('entrypoint') if partial else None)
        if partial and isinstance(candidate,dict) and isinstance(candidate.get('checks'),list):
            # A model can repeat an already accepted contract alongside the
            # requested missing checks. Ignore only exact preserved copies;
            # new bodies outside this batch still require their own review.
            candidate['checks']=[check for check in candidate['checks'] if not (
                isinstance(check,dict) and set(check.get('ids') or []).isdisjoint(requested)
                and check in partial.get('checks',[]))]
        candidate_ids={identifier for check in (candidate or {}).get('checks',[]) if isinstance(check,dict)
            for identifier in check.get('ids') or [] if identifier in criteria}
        candidate_criteria={identifier:criteria[identifier] for identifier in candidate_ids}
        candidate_errors = ([parse_error] if parse_error else
                            validate_verification(candidate, candidate_criteria, root))
        candidate_errors = [error for error in candidate_errors if not error.startswith(coverage_prefixes)]
        if partial and not candidate_ids-{identifier for check in partial.get('checks') or []
                                          for identifier in check.get('ids') or []}:
            candidate_errors.append('The response added no missing acceptance criterion; previously covered checks are already preserved.')
        failure_review = None
        source_defect_observed=False
        source_defect_evidence=None
        pause_after_candidate=False
        if not candidate_errors:
            candidate_errors = verification_syntax_errors(candidate)
        if partial and candidate and candidate.get('entrypoint') != partial['entrypoint']:
            candidate_errors.append('Preserve the existing entrypoint.')
        encoding_failure=bool(candidate_errors)
        if not candidate_errors:
            # Type/reference errors in the check's own APIs belong to authoring,
            # before any source-repair budget or application modification.
            candidate['mobile_criteria'] = [identifier for identifier,text in criteria.items()
                if re.search(r'\bsmartphones?\b|\bmobile\b|スマートフォン|モバイル',text,re.I)]
            candidate['selection_exclusion']=selection_spec
            candidate['forbid_external_requests']=forbid_external_requests
            probe_path=directory/(contract_path.stem+'-probe.json')
            probe_path.write_text(json.dumps({**candidate,'collect_observations':True},ensure_ascii=False),encoding='utf8')
            candidate_ids={key for check in candidate['checks'] for key in check['ids']}
            probe=host_probe({**phase,'verification_command':acceptance_command(probe_path,root),
                'verification_targets':list(sources),'host_criteria':{key:criteria[key] for key in candidate_ids}})
            # Criterion wording cannot enumerate every UI instruction. If the
            # actual check uses the supplied page but selected NODE, retry that
            # exact program once with a real browser. Assertions, IDs and source
            # remain identical; an unrelated/source exception is never promoted.
            browser_recovery=[]
            for check in candidate['checks']:
                if check['kind']!='NODE' or not re.search(r'\bpage\s*\.\s*[A-Za-z_$][\w$]*\s*\(',check['code']):continue
                if any(failure.get('contract_error') and not failure.get('project_source_error')
                       and set(failure.get('ids') or [])&set(check['ids'])
                       and re.search(r'TypeError: Cannot read properties of undefined|ReferenceError: page is not defined',str(failure.get('error') or ''))
                       for failure in ((probe[1].get('failures') or []) if probe else [])):
                    browser_recovery.append(check)
            if browser_recovery and (root/candidate['entrypoint']).is_file():
                for check in browser_recovery:check['kind']='BROWSER'
                probe_path.write_text(json.dumps({**candidate,'collect_observations':True},ensure_ascii=False),encoding='utf8')
                probe=host_probe({**phase,'verification_command':acceptance_command(probe_path,root),
                    'verification_targets':list(sources),'host_criteria':{key:criteria[key] for key in candidate_ids}})
                print(f'TASK_ID={task_id} VERIFICATION_BROWSER_EXECUTOR_RETRY=YES CHECK_SOURCE_CHANGED=NO',flush=True)
            if probe:
                observation_signature=json.dumps({'passed':probe[1].get('passed'),'failures':[
                    {'ids':failure.get('ids'),'error':str(failure.get('error') or '').split('\n',1)[0][:240],
                     'assertion':failure.get('assertion'),'assertion_source':{
                         'snippet':re.sub(r'\s+',' ',str((failure.get('assertion_source') or {}).get('snippet') or '')).strip()}}
                    for failure in probe[1].get('failures') or []]},sort_keys=True)
            contract_errors=[failure for failure in (probe[1].get('failures') or [])
                             if failure.get('contract_error')] if probe else []
            if probe and any(f.get('project_source_error') for f in probe[1].get('failures') or []):
                # The browser recorded an unhandled exception from an actual
                # served application file, independent of assertion wording.
                # Use this only as a repair diagnostic, never final coverage.
                return executable(candidate,diagnostic=True)
            if contract_errors and len(contract_errors)==len(probe[1].get('failures') or []):
                passed_checks,failed_checks=_partition_verification_checks(candidate,probe[1])
                value=retain_checks(partial or value or {'entrypoint':candidate.get('entrypoint')},[
                    *(partial.get('checks') if partial else []),*passed_checks])
                errors=validate_verification(value,criteria,root)
                failed_check_errors=json.dumps({'failures':failure_context(contract_errors)},ensure_ascii=False)
                failed_ids=sorted({identifier for item in contract_errors for identifier in item.get('ids') or []})
                candidate_errors.append('Verification check API failed for '+(', '.join(failed_ids) or 'an unidentified check')+'.')
            elif probe and probe[1].get('failures'):
                semantic_repair_required=True
                passed_checks,failed_checks=_partition_verification_checks(candidate,probe[1])
                failed_candidate={'entrypoint':candidate.get('entrypoint'),'checks':failed_checks}
                failure_ids=sorted({identifier for item in probe[1]['failures'] for identifier in item.get('ids') or []})
                behavior_failures=[failure for failure in probe[1]['failures'] if not failure.get('contract_error')]
                failure_review=review_verification_failure(task_id,original,requested,sources,
                    failed_candidate,behavior_failures)
                pause_after_candidate=_pause_at_checkpoint(task_id)
                if failure_review.get('verdict')!='SOURCE_DEFECT':
                    value=retain_checks(partial or value or {'entrypoint':candidate.get('entrypoint')},[
                        *(partial.get('checks') if partial else []),*passed_checks])
                    errors=validate_verification(value,criteria,root)
                    # A reviewer can correctly reject a browser check while
                    # still over-prescribing STATEFUL_CODE. Runtime parser or
                    # helper errors in the check source are transport defects;
                    # repeating generated JavaScript has already failed to
                    # produce usable evidence. Retry those checks through the
                    # host-compiled observation schema. A fresh independent
                    # review still decides whether the observations prove the
                    # original requirement, and can request code again if the
                    # behavior truly needs intermediate state.
                    failed_check_errors_text='\n'.join(
                        str(failure.get('error') or '')+'\n'+str(failure.get('check_source') or '')
                        for failure in behavior_failures if isinstance(failure,dict))
                    check_source_runtime_error=bool(
                        failure_review.get('verdict')=='CHECK_DEFECT'
                        and failed_checks
                        and all(check.get('kind')=='BROWSER' for check in failed_checks)
                        and not any(failure.get('project_source_error') for failure in behavior_failures)
                        and re.search(r'invalid or unexpected token|unexpected token|syntaxerror|referenceerror|'
                            r'undefined helper|(?:readfile|loadmodule|runtests|page|expect|assert)\s+is\s+not\s+defined',
                            failed_check_errors_text+'\n'+str(failure_review.get('reason') or ''),re.I))
                    repair_review=failure_review
                    if check_source_runtime_error:
                        repair_review={**failure_review,'verification_form':'LITERAL_OBSERVATIONS'}
                        print(f'TASK_ID={task_id} VERIFICATION_CHECK_SOURCE_FALLBACK=YES '
                              'RETRY_TRANSPORT=LITERAL_OBSERVATIONS',flush=True)
                    failed_check_errors=repair_finding(probe[1]['failures'],repair_review)
                    reason=str(failure_review.get('reason') or 'review was inconclusive').strip()[:240]
                    candidate_errors.append('Failed acceptance check(s) '+(', '.join(failure_ids) or 'UNKNOWN')+
                        ' need correction ('+str(failure_review.get('verdict') or 'INCONCLUSIVE')+'): '+reason)
                else:
                    source_defect_observed=True
                    source_defect_evidence={'review':failure_review,
                        'failures':failure_context(probe[1]['failures'])}
            elif probe and probe[1].get('passed') and (typed_transport or failed_checks and semantic_repair_required
                    or any(set(check.get('ids') or []) & original_criteria_ids for check in candidate['checks'])) and not owned_standard:
                failure_review=review_verification_failure(task_id,original,requested,sources,candidate,[],failed_checks,
                    observations=probe[1].get('browser_observations'))
                pause_after_candidate=_pause_at_checkpoint(task_id)
                if failure_review.get('verdict')!='CHECK_VALID':
                    # A passing retry is not accepted until the independent
                    # semantic review confirms it still proves the request.
                    semantic_repair_required=True
                    failed_checks=candidate['checks']
                    failed_check_errors=repair_finding(probe[1].get('browser_observations') or [],failure_review,passed=True)
                    candidate_errors.append('The repaired check did not preserve the original required behavior ('+
                        str(failure_review.get('verdict') or 'INCONCLUSIVE')+'): '+
                        str(failure_review.get('reason') or 'review was inconclusive').strip()[:240])
        transport_recovery_pending=bool(candidate_errors and encoding_failure and not typed_transport)
        if transport_recovery_pending:
            # Persist the format change immediately, including when the first
            # syntax error occurs at the last authoring attempt or a pause
            # checkpoint. Otherwise Resume repeats the same broken code.
            typed_transport=True
        if candidate_errors:
            # A bad response cannot erase checks completed in earlier calls.
            errors = candidate_errors
            seen=observed_signatures.setdefault(attempt_key,set())
            if observation_signature is not None and observation_signature not in seen:
                # A changed measured failure, or the first passing probe,
                # advances repair. Advisory review wording alone cannot do so.
                seen.add(observation_signature)
                malformed_attempts=1
            else:
                malformed_attempts += 1
            if candidate and isinstance(candidate.get('checks'),list):
                pending_authoring=authoring_path.with_suffix('.pending')
                pending_authoring.write_text(json.dumps({'source_identity':source_identity,
                    'typed_transport':typed_transport,
                    'semantic_repair_required':semantic_repair_required,
                    'checks':candidate['checks'],'finding':('; '.join(candidate_errors) if encoding_failure
                        else failed_check_errors or '; '.join(candidate_errors))},
                    ensure_ascii=False),encoding='utf8')
                pending_authoring.replace(authoring_path)
        else:
            value = {**candidate, 'checks': [*(partial['checks'] if partial else []), *candidate['checks']]}
            if output_limit_retry_ids and not (set(output_limit_retry_ids)
                    & set(verification_coverage_gaps(value,criteria) or {})):
                output_limit_retry_ids.clear()
                adaptive_batch_limit=authoring_batch_size
            reviewed=set(retained_semantic_review_ids(partial,value['checks']))
            if failure_review and failure_review.get('verdict')=='CHECK_VALID':
                previous_reviewed=set((partial or {}).get('_olcr_semantically_reviewed_ids') or [])
                reviewed.update(identifier for check in candidate['checks'] for identifier in check.get('ids') or []
                    if identifier in previous_reviewed or all(item in candidate['checks']
                        for item in value['checks'] if identifier in (item.get('ids') or [])))
            value['_olcr_semantically_reviewed_ids']=sorted(reviewed)
            value['_olcr_semantic_review_version']=2
            value['_olcr_typed_transport']=typed_transport
            value['_olcr_observation_compiler_version']=5
            errors = validate_verification(value, criteria, root)
            malformed_attempts = 0
            failed_checks = []
            semantic_repair_required=False
            failed_check_errors = ''
            authoring_path.unlink(missing_ok=True)
            contract_path.write_text(json.dumps(value, ensure_ascii=False), encoding='utf8')
        (directory / (contract_path.stem + f'-response-{time.time_ns()}.json')).write_text(
            json.dumps({'response': raw, 'model':author_model,'validation_errors': errors,'failure_review':failure_review}, ensure_ascii=False), encoding='utf8')
        # A stop must retain observations/review already completed. Persist
        # the accepted check or unaccepted draft before returning, then never
        # start another model call or application repair after the checkpoint.
        if pause_after_candidate or _pause_at_checkpoint(task_id):
            return phase
        if not candidate_errors and source_defect_observed:
            value['_olcr_failure_review']={'identity':_verification_failure_identity(
                candidate,probe[1]['failures'],source_identity),'review':failure_review}
            return executable(value,partial=bool(errors),source_defect=True,source_evidence=source_defect_evidence)
        semantic_handoff_pending=bool(candidate_errors and not encoding_failure
            and failure_review and failure_review.get('verdict') in {'CHECK_DEFECT','INCONCLUSIVE'}
            and author_attempts[attempt_key]>=2 and attempt_key not in semantic_handoffs
            and semantic_alternate_model)
        if verification_budget['exhaustion']:
            break
        # Repeated measured failures do not count as progress. A genuinely
        # different observed failure can advance repair, within the existing
        # per-criterion author cap. An alternate is only a handoff when Brain
        # resolves it to a genuinely different model.
        if not errors or (not transport_recovery_pending and not semantic_handoff_pending and (malformed_attempts >= 2
                or (candidate_errors and author_attempts[attempt_key]>=4))):
            break
    if errors:
        budget_note=(f' 自動検証を安全上限で停止しました（作成 {verification_budget["author_calls"]}/{verification_author_call_limit}、'
                     f'独立評価 {verification_budget["review_calls"]}/{VERIFICATION_MAX_REVIEW_CALLS}、総呼出し '
                     f'{verification_budget["model_calls"]}/{VERIFICATION_MAX_MODEL_CALLS}）。' if verification_budget['exhaustion'] else '')
        blocked=RuntimeError('VERIFICATION_CONTRACT_INVALID: ' + '; '.join(str(error)[:300] for error in errors[:4]) + budget_note)
        raise annotate_verification_failure(blocked,value)
    _clear_verification_preparation_failure(task_id,recovery_signature)
    if original_criteria_ids-set(value.get('_olcr_semantically_reviewed_ids') or []):
        # A mixed batch can preserve passing checks while only its failed
        # checks receive semantic review. Filling the remaining coverage must
        # not promote those unreviewed original-user checks to final PASS.
        # Re-enter the cached-contract gate: it exercises/reviews precisely
        # these remaining checks, preserving all accepted authoring progress.
        return _host_verification_phase(task_id,executable(value),plan,workspace_root,
                                        _semantic_pass=_semantic_pass+1,_budget=verification_budget)
    return executable(value)


def _run_read_only_verification(phase: dict, workspace_root: str | None) -> tuple[Task, dict[str, Any]] | None:
    """Run a typed verification command while forbidding verification writes."""
    spec = _verification_spec(phase, workspace_root)
    if spec is None or not workspace_root:
        return None
    root = Path(workspace_root).expanduser().resolve()
    verification_cwd = Path(spec.get("cwd") or root).expanduser().resolve()
    try:
        verification_cwd.relative_to(root)
    except ValueError:
        verification_cwd = root
    task = Task("read-only verification")
    task.route = Route.DIRECT
    task.transition(TaskState.ROUTING)
    task.transition(TaskState.EXECUTING)
    snapshots: dict[Path, bytes] = {}
    for relative in spec["targets"]:
        target = (root / relative).resolve()
        if root not in target.parents or not target.is_file():
            return None
        try:
            snapshots[target] = target.read_bytes()
        except OSError:
            return None
    if len(snapshots) != len(spec["targets"]):
        return None
    command = spec["command"]
    from .node_project_verification import is_vite_project
    source_isolated = bool(phase.get('host_criteria') and len(command)>2
        and Path(command[1]).resolve()==Path(__file__).with_name('coding_verification_runner.cjs').resolve()
        and is_vite_project(verification_cwd))
    started = time.perf_counter()
    def restore_targets(*, restore: bool = True) -> list[str]:
        changed = []
        for target, original in snapshots.items():
            # The verifier may replace a file or parent with a symlink. Never
            # follow that new link when comparing or restoring source bytes.
            if target.parent.resolve(strict=True) != target.parent:
                raise OSError("verification target parent changed during execution")
            if target.is_symlink():
                if not restore:
                    changed.append(target.relative_to(root).as_posix())
                    continue
                target.unlink()
                changed.append(target.relative_to(root).as_posix())
                target.write_bytes(original)
                continue
            try:
                unchanged = target.read_bytes() == original
            except OSError:
                unchanged = False
            if not unchanged:
                changed.append(target.relative_to(root).as_posix())
                if restore:
                    target.write_bytes(original)
        return changed
    try:
        # Saved tasks may still contain the old Node-only command. Resolve
        # current host resources when retrying without rewriting their checks.
        if (phase.get('host_criteria') and len(command)>2
                and Path(command[1]).resolve()==Path(__file__).with_name('coding_verification_runner.cjs').resolve()):
            command = acceptance_command(Path(command[2]), root)
        host_timeout = 120
        if phase.get('host_criteria'):
            # Each browser check has its own bounded wait. A larger contract
            # must not inherit the deadline for a single small command.
            host_timeout = max(host_timeout, 60 + 8 * len(phase['host_criteria']))
        completed = run_acceptance(command, str(verification_cwd),
                                   host_timeout if phase.get('host_criteria') else 20)
        project_build = getattr(completed, 'project_build', {})
        if not isinstance(project_build, dict):
            project_build = {}
        output = (completed.stdout or "") + (completed.stderr or "")
        passed_ids = None
        host_tests, browser_checks = [], 0
        browser_observations = []
        host_failures = []
        executor_error = False
        if phase.get('host_criteria'):
            try:
                payload = json.loads(output.rsplit('OLCR_VERIFICATION_RESULT=', 1)[1].splitlines()[0])
                observed = payload['passed_ids']
                if (not isinstance(observed, list) or not all(isinstance(item,str) for item in observed)
                        or not set(observed) <= set(phase['host_criteria'])):
                    raise ValueError('unknown criteria')
                for field in ('test_runs','browser_observations','failures'):
                    values = payload.get(field) or []
                    if not isinstance(values,list) or not all(isinstance(item,dict) for item in values):
                        raise ValueError('invalid host result field: '+field)
                for run in payload.get('test_runs') or []:
                    failures = run.get('failures') or []
                    if not isinstance(failures,list) or not all(isinstance(item,dict) for item in failures):
                        raise ValueError('invalid host test failures')
                passed_ids = [identifier for identifier in phase['host_criteria'] if identifier in set(observed)]
                host_tests = payload.get('test_runs') or []
                browser_checks = int(payload.get('browser_checks') or 0)
                browser_observations = payload.get('browser_observations') or []
                host_failures = payload.get('failures') or []
                executor_error = payload.get('executor_error') is True
            except (IndexError, KeyError, ValueError, TypeError):
                passed_ids = []
                host_tests, browser_checks, browser_observations = [], 0, []
                executor_error = True
                host_failures = [{'ids':list(phase['host_criteria']),
                    'error':'Host verification produced no valid result: '+output[-3000:],
                    'executor_error':True,'contract_error':True}]
        unittest_module = any(
            command[index:index + 2] == ["-m", "unittest"]
            for index in range(max(0, len(command) - 1))
        )
        node_test = Path(command[0]).name.lower() in {"node", "node.exe"} and "--test" in command
        if node_test and not host_tests:
            host_tests=[node_test_run(command,output,completed.returncode,root)]
        elif is_project_test_command(command) and not host_tests:
            host_tests=[{'command':command,'returncode':completed.returncode,
                'passed':completed.returncode==0,'failures':[],'output':output[-4000:]}]
        test_diagnosis=project_test_failure_diagnosis({'output':output,'test_runs':host_tests},
            {target.relative_to(root).as_posix():source.decode('utf8',errors='replace')
             for target,source in snapshots.items()}) if completed.returncode!=0 and host_tests else {}
        zero_tests = bool(
            (unittest_module and re.search(r"\bRan\s+0\s+tests?\b", output, re.IGNORECASE))
            or (node_test and re.search(r"^\s*#\s*tests\s+0\s*$", output, re.MULTILINE))
        )
        if unittest_module:
            total_match=re.search(r'\bRan\s+(\d+)\s+tests?\b',output,re.I)
            skipped_match=re.search(r'\bskipped=(\d+)\b',output)
            if total_match and skipped_match and int(skipped_match.group(1))>=int(total_match.group(1)):
                zero_tests=True
        if node_test:
            if host_tests and not any(int(run.get('executed_tests',run.get('passed',0)) or 0)>0
                    for run in host_tests):
                zero_tests=True
            names = re.findall(r'^\s*# Subtest: (.+)$', output, re.MULTILINE)
            def file_container(name):
                candidate = (root / name).resolve()
                return candidate.is_relative_to(root) and candidate.is_file() and candidate.suffix in {'.js','.mjs','.cjs'}
            if names and all(file_container(name) for name in names):
                zero_tests = True
        # The Vite executor works entirely in its disposable source copy.
        # A concurrent edit of the user's real file invalidates this result;
        # restoring the old snapshot would overwrite that unrelated edit.
        changed_targets = restore_targets(restore=not source_isolated)
        target_sha256 = {target.relative_to(root).as_posix(): hashlib.sha256(original).hexdigest()
                         for target, original in snapshots.items()}
        passed = (completed.returncode == 0 and not changed_targets and not zero_tests and not executor_error
                  and (passed_ids is None or set(passed_ids) == set(phase['host_criteria'])))
        status = "success" if passed else "failed"
        task.tool_executions.append({"tool": "verification_command", "version": "1.0", "risk": "SAFE",
                                     "input": {"command": command, "cwd": str(verification_cwd), "write_scope": "NONE"},
                                     "output": {"returncode": completed.returncode, "output": output[-4000:],
                                                "read_only_targets": spec["targets"], "changed_targets": changed_targets,
                                                "target_sha256": target_sha256,
                                                "passed_criteria_ids": passed_ids,
                                                "test_runs": host_tests, "browser_checks": browser_checks,
                                                "test_diagnosis": test_diagnosis,
                                                "browser_observations": browser_observations,
                                                "project_build": project_build,
                                                "executor_error": executor_error,
                                                "failures": host_failures,
                                                "zero_tests": zero_tests},
                                     "status": status, "latency_ms": 0})
        if passed:
            task.transition(TaskState.COMPLETED)
        else:
            if changed_targets:
                task.error = "verification attempted to modify read-only targets"
            elif zero_tests:
                task.error = "verification discovered zero tests"
            else:
                task.error = "verification command failed"
            task.transition(TaskState.FAILED)
        return task, {"command": command, "output": output[-4000:], "returncode": completed.returncode,
                      "passed": passed, "changed_targets": changed_targets, "targets": spec["targets"],
                      "zero_tests": zero_tests,
                      "passed_criteria_ids": passed_ids,
                      "test_runs": host_tests, "browser_checks": browser_checks,
                      "test_diagnosis": test_diagnosis,
                      "browser_observations": browser_observations,
                      "project_build": project_build,
                      "executor_error": executor_error,
                      "failures": host_failures,
                      "elapsed_ms": (time.perf_counter() - started) * 1000}
    except GenerationCancelled:
        restore_targets(restore=not source_isolated)
        raise
    except (OSError, subprocess.TimeoutExpired, VerificationExecutorError) as exc:
        task.error = f"verification command failed: {exc}"
        executor_error=isinstance(exc,(OSError,VerificationExecutorError))
        failures=([{"ids":list(acceptance_criteria(phase)),"error":task.error,
                    "contract_error":True,"executor_error":True}] if executor_error else [])
        try:
            changed_targets = restore_targets(restore=not source_isolated)
        except OSError as restore_error:
            changed_targets = list(spec["targets"])
            task.error += f"; target restoration failed: {restore_error}"
        task.tool_executions.append({"tool": "verification_command", "version": "1.0", "risk": "SAFE",
                                     "input": {"command": command, "cwd": str(verification_cwd), "write_scope": "NONE"},
                                     "output": {"error": task.error, "executor_error":executor_error,
                                                "read_only_targets": spec["targets"],
                                                "changed_targets": changed_targets,
                                                "failures":failures},
                                     "status": "failed", "latency_ms": 0})
        task.transition(TaskState.FAILED)
        return task, {"command": command, "output": str(exc), "returncode": None,
                      "passed": False, "changed_targets": changed_targets, "targets": spec["targets"],
                      "executor_error":executor_error,"failures":failures,
                      "elapsed_ms": (time.perf_counter() - started) * 1000}


def _implementation_result_kind(phase: dict, execution: Task, response: str) -> str:
    """Classify a typed implementation outcome without treating prose as work."""
    expectations = phase.get("execution_expectations") or _phase_execution_expectations(phase)
    successful = [item for item in execution.tool_executions if item.get("status") == "success"]
    mutations = [item for item in successful if item.get("tool") in {
        "workspace_write", "workspace_write_normalized", "workspace_patch", "workspace_delete", "workspace_remove", "package_install"}]
    if any(item.get("tool") == "operation_application_failure" and
           (item.get("output") or {}).get("worktree_state") == "ROLLED_BACK"
           for item in execution.tool_executions):
        return "FAILED"
    error = str(execution.error or "").lower()
    prose = str(response or "").strip().lower()
    narrative_markers = ("i will", "here's what", "here is what", "next step", "次に", "これから", "実装します", "変更します")
    invalid_plan = "did not return a valid file-operation plan" in error or "invalid empty implementation result" in error
    if expectations["requires_repo_mutation"] and not mutations and (invalid_plan or any(marker in prose for marker in narrative_markers)):
        return "NARRATIVE_ONLY"
    if execution.state == TaskState.DENIED:
        return "BLOCKED"
    if execution.state == TaskState.FAILED or execution.error:
        return "FAILED"
    if mutations:
        return "EXECUTED"
    if expectations["read_only_allowed"] and successful:
        return "READ_ONLY_COMPLETED"
    return "NARRATIVE_ONLY" if expectations["requires_repo_mutation"] else "READ_ONLY_COMPLETED"


def _apply_project_build_evidence(report: dict, execution: Task) -> None:
    """Carry host-measured compiler/build results through phase finalization."""
    for operation in execution.tool_executions:
        if operation.get('tool') != 'verification_command':
            continue
        observed = (operation.get('output') or {}).get('project_build') or {}
        if observed.get('build_executed') is True:
            report['build_executed'] = 'VITE_BUILD'
            report['build_pass'] = 'PASS' if observed.get('build_passed') is True else 'FAIL'
        if observed.get('typecheck_executed') is True:
            report['typecheck_pass'] = 'PASS' if observed.get('typecheck_passed') is True else 'FAIL'


def _report_from_execution(phase: dict, attempt: int, execution: Task, response: str) -> dict:
    typed=_typed_summary(execution)
    write_tools={"workspace_write","workspace_write_normalized","workspace_patch","package_install"}
    wrote=any(item.get("tool") in write_tools and item.get("status")=="success" for item in execution.tool_executions)
    expectations=phase.get("execution_expectations") or _phase_execution_expectations(phase)
    executed_verification = bool(expectations.get('read_only_allowed') and any(
        item.get('tool') == 'verification_command' and item.get('status') == 'success'
        for item in execution.tool_executions))
    web_only_zero_write=(not executed_verification and execution.state == TaskState.COMPLETED
                         and execution.route != Route.IMPLEMENTATION and not wrote)
    if web_only_zero_write:
        # A managed implementation phase can never treat a normal-chat/web
        # response as successful implementation evidence.
        print("CODING_IMPLEMENTATION_ZERO_WRITE_WEB_ROUTE=true",file=__import__('sys').stderr,flush=True)
    result_kind=_implementation_result_kind({**phase, "execution_expectations": expectations}, execution, response)
    failed=(execution.state in {TaskState.FAILED,TaskState.DENIED} or bool(execution.error)
            or web_only_zero_write or result_kind == "NARRATIVE_ONLY")
    # The Implementer's text is model evidence only.  A user-visible phase
    # report may carry a response after an authoritative executor result, but
    # never after a failed/invalid operation parse and never as a prose
    # substitute for a typed mutation.
    safe_execution_response = (str(response or "")[:400]
                               if not failed and result_kind in {"EXECUTED", "READ_ONLY_COMPLETED"}
                               else "")
    changed=[]
    for item in execution.tool_executions:
        output=item.get("output") or {}
        if item.get("tool") in {"workspace_write","workspace_write_normalized","package_install"} and output.get("path"):
            changed.append(output["path"])
        if item.get("tool") == "package_install" and isinstance(output.get("package_json_after"), dict) and output["package_json_after"].get("exists"):
            changed.append("package.json")
    if typed.get("worktree_state") == "ROLLED_BACK":
        changed = []
    # Do not surface a model's future-tense narrative as an implementation
    # result.  The structured report records the detection for audit/retry.
    progress = typed.get("phase_progress") is True
    rejected = typed.get("rejected_operations") if isinstance(typed.get("rejected_operations"), list) else []
    ownership = next((item for item in rejected if isinstance(item, dict) and
                      item.get("category") == "PACKAGE_JSON_OWNERSHIP_VIOLATION"), {})
    refresh = next((item for item in (typed.get("operations") or []) if isinstance(item, dict) and
                    item.get("tool") == "workspace_refresh" and item.get("status") == "success"), {})
    rejection_signature = _context_fingerprint({
        "rejections": [{"category": item.get("category"), "path": item.get("path"), "reason": item.get("reason"),
                        "semantic_field": item.get("semantic_field"), "owner": item.get("owner"),
                        "failure_fingerprint": item.get("failure_fingerprint")} for item in rejected if isinstance(item, dict)],
        "accepted_mutations": typed.get("accepted_mutations", 0),
        "files_written": typed.get("files_written", 0),
    }) if rejected else ""
    report = {"phase_id":phase["id"],"attempt":attempt,"status":"FAIL" if failed else "PASS",
            "implemented":([safe_execution_response] if safe_execution_response else []),"changed_files":changed,
            "test_executed":[],"test_pass":[],"test_fail":[],"build_executed":"NOT_RUN",
            "build_pass":"NOT_RUN","errors":([execution.error] if execution.error else []) + (["CODING_IMPLEMENTATION_ZERO_WRITE_WEB_ROUTE"] if web_only_zero_write else []),"blockers":[],"risks":[],
            "typed_execution_summary":typed, "execution_expectations":expectations,
            "implementation_result_kind":result_kind,
            "attempted_mutations":int(typed.get("attempted_mutations") or 0),
            "accepted_mutations":int(typed.get("accepted_mutations") or 0),
            "rejected_mutations":int(typed.get("rejected_mutations") or 0),
            "files_written":int(typed.get("files_written") or len(changed)),
            "rolled_back_mutations":int(typed.get("rolled_back_mutations") or 0),
            "final_worktree_mutations":int(typed.get("final_worktree_mutations") or 0),
            "mutation_classification": str(typed.get("mutation_classification") or "UNKNOWN"),
            "phase_progress":progress,
            "no_progress":not progress,
            "rejection_signature":rejection_signature,
            "ownership_failure_class": str(ownership.get("category") or "NONE"),
            "ownership_failure_fingerprint": str(ownership.get("failure_fingerprint") or ""),
            "ownership_retry_context_required": bool(ownership),
            "post_install_worktree_refresh": bool(refresh),
            "package_install_evidence_preserved": bool(typed.get("package_install_evidence"))}
    _apply_project_build_evidence(report, execution)
    return report


def _repair_phase_report_shape(report: dict, phase_id: str, attempt: int) -> dict:
    """Repair host report containers without generating new execution facts."""
    repaired = dict(report)
    repaired.update(phase_id=phase_id, attempt=attempt)
    for key in ("implemented", "changed_files", "test_executed", "test_pass", "test_fail",
                "errors", "blockers", "risks"):
        value = report.get(key)
        if not isinstance(value, list):
            repaired[key] = [value] if isinstance(value, str) and value else []
    if report.get("status") not in {"PASS", "FAIL", "BLOCKED", "NOT_RUN"}:
        repaired["status"] = "FAIL"
    for key in ("build_executed", "build_pass"):
        if not isinstance(report.get(key), str):
            repaired[key] = "NOT_RUN"
    return repaired


def _merge_verification_execution(report: dict[str, Any], execution: Task) -> None:
    """Persist the verifier's typed command result alongside implementation evidence."""
    typed = report.get("typed_execution_summary")
    if not isinstance(typed, dict):
        typed = {"operations": []}
        report["typed_execution_summary"] = typed
    operations = typed.setdefault("operations", [])
    if not isinstance(operations, list):
        operations = []
        typed["operations"] = operations
    for operation in execution.tool_executions:
        if isinstance(operation, dict) and operation.get("tool") == "verification_command" and operation not in operations:
            operations.append(operation)
    typed["successful_operation_count"] = sum(
        1 for item in operations if isinstance(item, dict)
        and str(item.get("status") or "").lower() in {"success", "completed", "ok"}
    )
    _apply_project_build_evidence(report, execution)

def _save_report(task_id: str, phase_id: str, attempt: int, report: dict, validation_status: str) -> dict:
    task = db.coding_task(task_id) or {}
    recovery_epoch = int(task.get("recovery_epoch") or 0)
    # Every completed Implementer report is tied to the epoch that dispatched
    # it.  This provenance is the boundary between lifetime history and active
    # epoch control state.
    report = dict(report)
    report.setdefault("recovery_epoch", recovery_epoch)
    report.setdefault("attempt_id", f"{task_id}:{recovery_epoch}:{phase_id}:{attempt}")
    report.setdefault("execution_generation", f"recovery-epoch-{recovery_epoch}")
    report.setdefault("execution_attempt_started", True)
    report.setdefault("execution_attempt_completed", True)
    db.add_coding_phase_report(task_id,phase_id,attempt,report,validation_status,time.time())
    # Keep successful package-manager facts on the task itself.  Phase reports
    # remain the detailed audit trail, while this compact state is the restart
    # boundary used before the next Implementer dispatch.
    revision = _report_plan_revision(report)
    evidence = _package_install_state_from_reports(task_id, phase_id, revision)
    if evidence is not None:
        _persist_resume_package_state(task_id, phase_id, revision, evidence,
                                      phase_cursor=task.get("current_phase_id") or phase_id)
    # Persist compact epoch-local counters while retaining the lifetime count.
    # The detailed report rows remain the authoritative history.
    task = db.coding_task(task_id) or task
    state = task.get("resume_state") if isinstance(task.get("resume_state"), dict) else {}
    _epoch_failure, epoch_signature, epoch_count = _repeated_zero_progress_failure(task_id, recovery_epoch)
    if epoch_signature:
        state["epoch_no_progress_count"] = epoch_count
        state["epoch_last_failure_signature"] = epoch_signature
    elif report.get("phase_progress") is True or int(report.get("accepted_mutations") or 0) > 0 or int(report.get("files_written") or 0) > 0:
        state["epoch_no_progress_count"] = 0
        state["epoch_last_failure_signature"] = ""
    lifetime_report_count = sum(
        1 for row in db.coding_phase_reports(task_id)
        if _zero_progress_signature(row.get("structured_report") or {})
    )
    state["lifetime_no_progress_count"] = max(
        int(state.get("lifetime_no_progress_count") or 0),
        int(state.get("no_progress_count") or 0),
        lifetime_report_count,
    )
    state["epoch_execution_attempts"] = int(state.get("epoch_execution_attempts") or 0) + 1
    state["last_execution_attempt_id"] = report["attempt_id"]
    db.update_coding_task(task_id, resume_state=state)
    return db.coding_phase_reports(task_id)[-1]


def _bounded_review_context(report: dict) -> dict:
    """Return only the small, typed portion needed for a retry prompt."""
    decision = report.get("manager_decision") or {}
    diagnosis = decision.get("diagnosis") if isinstance(decision, dict) else {}
    if not isinstance(diagnosis, dict):
        diagnosis = {}
    typed_summary = report.get("typed_execution_summary") if isinstance(report.get("typed_execution_summary"), dict) else {}
    rejected_fields = ("category", "path", "reason", "semantic_field", "owner",
                       "package_install_status", "dependencies_already_satisfied", "failure_fingerprint")
    rejected_operations = [
        {key: (str(item[key])[:240] if isinstance(item.get(key), str) else item.get(key))
         for key in rejected_fields if key in item}
        for item in (typed_summary.get("rejected_operations") or [])[:4]
        if isinstance(item, dict)
    ]
    ownership_rejections = [item for item in rejected_operations
                            if str(item.get("category") or "") == "PACKAGE_JSON_OWNERSHIP_VIOLATION"]
    invalid_source_paths=list(dict.fromkeys(str(((op.get('output') or {}).get('operation_diagnostic') or {}).get('relative_target_path') or '')
        for op in typed_summary.get('operations') or [] if op.get('tool')=='operation_application_failure'
        and ((op.get('output') or {}).get('operation_diagnostic') or {}).get('reason_subtype')=='STRUCTURAL_VALIDATION_FAILED'
        and ((op.get('output') or {}).get('operation_diagnostic') or {}).get('relative_target_path')))[:8]
    reported_failure_class=str(typed_summary.get("failure_class") or "").upper()
    if ownership_rejections:
        typed_failure_class="PACKAGE_JSON_OWNERSHIP_VIOLATION"
    elif invalid_source_paths and reported_failure_class in {"", "UNKNOWN", "RECOVERABLE_INTERNAL"}:
        # A rejected source write is itself typed evidence. Preserve it even
        # when an older report omitted failure_class from its summary.
        typed_failure_class="WRITE_CONTENT_INVALID"
    else:
        typed_failure_class=reported_failure_class or "UNKNOWN"
    test_failures=[failure for op in typed_summary.get('operations') or []
        for run in (op.get('output') or {}).get('test_runs') or []
        for failure in run.get('failures') or []][:8]
    # A broken beforeEach can report the same exception for every test.
    # Keep its actual hook frames once; registration locations and latency
    # differ per test and must not inflate the repair prompt eightfold.
    grouped_hooks={}
    focused_failures=[]
    for failure in test_failures:
        detail=str(failure.get('detail') or '')
        frames=failure.get('source_locations') or []
        if "'hookFailed'" in detail and len(frames)>1:
            identity=(detail.split('error:',1)[-1].split('\n  code:',1)[0],
                      tuple((frame.get('path'),frame.get('line')) for frame in frames[1:]))
            if identity in grouped_hooks:
                grouped_hooks[identity]['affected_tests'].append(failure.get('name'))
                continue
            failure={**failure,'affected_tests':[failure.get('name')]}
            grouped_hooks[identity]=failure
        focused_failures.append(failure)
    test_failures=focused_failures
    return {
        "decision": str(decision.get("decision") or "")[:80],
        "reason": str(decision.get("reason") or "")[:500],
        "diagnosis": {
            "phase_id": str(diagnosis.get("phase_id") or report.get("phase_id") or "")[:120],
            "plan_revision": int(diagnosis.get("plan_revision") or report.get("plan_revision") or 0),
            "attempt": int(diagnosis.get("attempt") or report.get("attempt") or 0),
            "unmet_done": [str(x)[:240] for x in (diagnosis.get("unmet_done") or [])[:8]],
            "unmet_verify": [str(x)[:240] for x in (diagnosis.get("unmet_verify") or [])[:8]],
            "evidence": [str(x)[:240] for x in (diagnosis.get("evidence_used") or diagnosis.get("evidence") or [])[:8]],
            "evidence_used": [str(x)[:240] for x in (diagnosis.get("evidence_used") or diagnosis.get("evidence") or [])[:8]],
            "failure_class": ("PACKAGE_JSON_OWNERSHIP_VIOLATION" if ownership_rejections else
                              str(diagnosis.get("failure_class") or "RECOVERABLE_INTERNAL"))[:80],
            "retry_instruction": str(diagnosis.get("retry_instruction") or "")[:500],
            "specific_fix": str(diagnosis.get("specific_fix") or diagnosis.get("retry_instruction") or "")[:500],
            "verification_instruction": str(diagnosis.get("verification_instruction") or "")[:500],
            "replan_instruction": str(diagnosis.get("replan_instruction") or "")[:500],
            "replan_reason": str(diagnosis.get("replan_reason") or diagnosis.get("replan_instruction") or "")[:500],
            "replan_instruction_source": str(diagnosis.get("replan_instruction_source") or "derived")[:16],
            "replan_reason_source": str(diagnosis.get("replan_reason_source") or "derived")[:16],
        },
        "typed_state": str(typed_summary.get("state") or "")[:80],
        "typed_error": str(typed_summary.get("error") or "")[:500],
        "errors": [str(item)[:500] for item in (report.get("errors") or [])[:4]],
        "test_fail": ([str(failure.get('name') or '')+'\n'+str(failure.get('detail') or '')[:1200]
                       for failure in test_failures[:3]] if test_failures else
                      [str(item)[:1000] for item in (report.get("test_fail") or [])[:3]]),
        "verification_failures": test_failures,
        "browser_checks_executed":sum(int((op.get('output') or {}).get('browser_checks') or 0)
            for op in typed_summary.get('operations') or [] if op.get('tool')=='verification_command'),
        "acceptance_failures": [{
            'ids':list(failure.get('ids') or [])[:8],
            'error':str(failure.get('error') or '').split('\n    at ',1)[0][:1000],
            'check_source':str(failure.get('check_source') or '')[:1600],
            'input_actions':list(failure.get('input_actions') or [])[:3],
            'observed_no_repeat':failure.get('observed_no_repeat'),
            'browser_errors':[{'message':str(item.get('message') or '')[:1000],
                               'source_paths':list(item.get('source_paths') or [])[:5],
                               'source_locations':list(item.get('source_locations') or [])[:3]}
                              for item in failure.get('browser_errors') or []][:3],
            'assertion':{key:str(value)[:600] for key,value in (failure.get('assertion') or {}).items()},
            'assertion_source':failure.get('assertion_source') or {},
            'observed_page':{'text':str((failure.get('observed_page') or {}).get('text') or '')[:1800],
                'fields':[{key:str(value)[:300] for key,value in field.items()}
                          for field in (failure.get('observed_page') or {}).get('fields') or []][:5]}}
            for op in typed_summary.get('operations') or []
            for failure in (op.get('output') or {}).get('failures') or []
            if isinstance(failure,dict) and not failure.get('contract_error')
            and failure.get('ids') != ['REQUIRED_TESTS']
            and not (test_failures and not failure.get('browser_errors') and
                     str(failure.get('error') or '').startswith('Error: node:test failed'))][:4],
        "unchanged_paths": list(dict.fromkeys(str((op.get('output') or {}).get('path') or (op.get('input') or {}).get('path') or '')
            for op in typed_summary.get('operations') or []
            if op.get('tool') in {'workspace_patch','workspace_write'}
            and (op.get('output') or {}).get('net_changed') is False))[:8],
        "invalid_source_paths":invalid_source_paths,
        "blockers": [str(item)[:500] for item in (report.get("blockers") or [])[:4]],
        "typed_failure_class": typed_failure_class[:80],
        "source_bound_repair": any(op.get('tool')=='source_repair_transport'
            for op in typed_summary.get('operations') or [] if isinstance(op,dict)),
        "typed_worktree_state": str(typed_summary.get("worktree_state") or "UNKNOWN")[:40],
        "mutation_accounting": {
            "attempted_operations": int(typed_summary.get("attempted_mutations") or 0),
            "successful_operations": int(typed_summary.get("successful_operation_count") or 0),
            "accepted_mutations": int(typed_summary.get("accepted_mutations") or 0),
            "net_changed_paths": [str(path) for path in (typed_summary.get("net_changed_paths") or [])[:16]],
            "net_changed_mutation_count": int(typed_summary.get("net_changed_mutation_count") or 0),
            "unchanged_operation_count": int(typed_summary.get("unchanged_operation_count") or 0),
            "rolled_back_mutation_count": int(typed_summary.get("rolled_back_mutations") or 0),
            "classification": str(typed_summary.get("mutation_classification") or "UNKNOWN")[:40],
        },
        "rejected_operations": rejected_operations,
        "package_ownership": {
            "failure_class": "PACKAGE_JSON_OWNERSHIP_VIOLATION" if ownership_rejections else "NONE",
            "path": str(ownership_rejections[-1].get("path") or "package.json") if ownership_rejections else "",
            "semantic_field": str(ownership_rejections[-1].get("semantic_field") or "") if ownership_rejections else "",
            "owner": str(ownership_rejections[-1].get("owner") or "PACKAGE_INSTALL") if ownership_rejections else "",
            "package_install_status": str(ownership_rejections[-1].get("package_install_status") or "") if ownership_rejections else "",
            "dependencies_already_satisfied": ownership_rejections[-1].get("dependencies_already_satisfied") if ownership_rejections else None,
            "failure_fingerprint": str(ownership_rejections[-1].get("failure_fingerprint") or "") if ownership_rejections else "",
        },
        "preimage_diagnostics": [
            {key: str(item[key] if item[key] is not None else "")[:240] for key in (
                "path", "failure_class", "expected_hash", "actual_hash", "executor_pre_apply_hash",
                "transaction_base_hash", "match_count", "state", "patch_old_match_count",
                "patch_old_text_hash", "patch_new_text_hash", "implementer_source_hash",
                "preimage_failure_reason", "fragment_source_relation") if key in item}
            for item in (typed_summary.get("preimage_diagnostics") or [])[:2]
            if isinstance(item, dict)
        ],
        "attempted_mutations": int(report.get("attempted_mutations") or typed_summary.get("attempted_mutations") or 0),
        "accepted_mutations": int(report.get("accepted_mutations") or typed_summary.get("accepted_mutations") or 0),
        "rejected_mutations": int(report.get("rejected_mutations") or typed_summary.get("rejected_mutations") or 0),
        "files_written": int(report.get("files_written") or typed_summary.get("files_written") or 0),
        "rolled_back_mutations": int(report.get("rolled_back_mutations") or typed_summary.get("rolled_back_mutations") or 0),
        "final_worktree_mutations": int(report.get("final_worktree_mutations") or typed_summary.get("final_worktree_mutations") or 0),
        "phase_progress": bool(report.get("phase_progress") or typed_summary.get("phase_progress")),
        "rejection_signature": str(report.get("rejection_signature") or "")[:32],
    }


def _context_fingerprint(value: dict) -> str:
    return hashlib.sha256(json.dumps(value, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()[:16]


def _bounded_replan_plan_context(current: dict, completed_ids: set[str],
                                 failing_phase_id: str | None) -> dict[str, Any]:
    """Keep the replacement planner's view to authoritative contracts only.

    Persisted plans also contain blueprint evidence, provenance snapshots,
    preimages, generated task graphs, and duplicated artifacts. Those records
    remain in the database for execution and audit, but repeating them in a
    recovery prompt makes a bounded replan needlessly large and slower to
    resume. This view retains scope, exact approved paths, phase contracts,
    and the small manifest status needed to repair only unfinished work.
    """
    if not isinstance(current, dict):
        return {"schema_version": 1, "scope": {"allowed": [], "forbidden": []},
                "file_manifest": [], "phases": []}
    artifact = current.get("implementation_plan_artifact")
    artifact = artifact if isinstance(artifact, dict) else {}
    manifest = current.get("file_manifest")
    if not isinstance(manifest, list):
        manifest = artifact.get("file_manifest")
    manifest = copy.deepcopy(manifest) if isinstance(manifest, list) else []
    read_only_manifest = current.get("read_only_manifest")
    read_only_manifest = copy.deepcopy(read_only_manifest) if isinstance(read_only_manifest, list) else []
    phase_fields = (
        "id", "kind", "goal", "status", "done", "verify", "dependencies",
        "execution_mode", "required_mcp", "selected_mcp", "acceptance_contract",
        "dependency_requirements", "requires_dependency_installation",
        "package_json_config_mutation", "package_manager_executor",
        "authorized_package_requirements", "verification_command",
        "verification_targets", "verification_executor", "criterion_executors",
        "file_manifest",
    )
    phases = []
    for phase in current.get("phases") or []:
        if not isinstance(phase, dict):
            continue
        compact = {key: copy.deepcopy(phase[key]) for key in phase_fields if key in phase}
        if compact.get("id") in completed_ids:
            compact["status"] = phase.get("status", "pass")
        phases.append(compact)
    coverage = artifact.get("manifest_coverage")
    compact_coverage = {}
    if isinstance(coverage, dict):
        for key in ("valid", "missing_paths", "unexpected_paths", "coverage_ratio"):
            if key in coverage:
                compact_coverage[key] = copy.deepcopy(coverage[key])
    result = {
        "schema_version": current.get("schema_version", 1),
        "scope": copy.deepcopy(current.get("scope") if isinstance(current.get("scope"), dict)
                                else {"allowed": [], "forbidden": []}),
        "file_manifest": manifest,
        "read_only_manifest": read_only_manifest,
        "implementation_plan_artifact": {
            "target_root": artifact.get("target_root"),
            "file_manifest_count": artifact.get("file_manifest_count", len(manifest)),
            "manifest_coverage": compact_coverage,
        },
        "phases": phases,
        "completed_phase_ids": sorted(str(item) for item in completed_ids),
        "failing_phase_id": failing_phase_id,
    }
    return result


def _zero_progress_signature(report: dict) -> str:
    """Return a stable, plan-independent signature for no meaningful progress."""
    if not isinstance(report, dict):
        return ""
    typed = report.get("typed_execution_summary") if isinstance(report.get("typed_execution_summary"), dict) else {}
    evaluation = report.get("phase_evaluation") if isinstance(report.get("phase_evaluation"), dict) else {}
    decision = report.get("manager_decision") if isinstance(report.get("manager_decision"), dict) else {}
    if (report.get('execution_expectations') or {}).get('requires_repo_mutation') is False and any(
            op.get('tool') == 'verification_command' for op in typed.get('operations') or [] if isinstance(op, dict)):
        # A verifier is intentionally read-only. Finding app/check failures
        # must not spend the separate unauthorized-mutation failure budget.
        return ''
    idempotent = (report.get('mutation_classification') or typed.get('mutation_classification')) == 'IDEMPOTENT_NOOP'
    meaningful = ((not idempotent and (bool(report.get("phase_progress")) or
                  int(report.get("accepted_mutations") or typed.get("accepted_mutations") or 0) > 0 or
                  int(report.get("files_written") or typed.get("files_written") or 0) > 0 or
                  int(report.get("final_worktree_mutations") or typed.get("final_worktree_mutations") or 0) > 0)) or
                  evaluation.get("phase_complete") is True or
                  str(decision.get("decision") or "").upper() == "PASS")
    if meaningful:
        return ""
    rejected = typed.get("rejected_operations", [])
    categories = [str(item.get("category") or "UNKNOWN") for item in rejected if isinstance(item, dict)]
    rejection_context = [{"category": item.get("category"), "path": item.get("path"),
                          "semantic_field": item.get("semantic_field"), "owner": item.get("owner"),
                          "package_install_status": item.get("package_install_status"),
                          "dependencies_already_satisfied": item.get("dependencies_already_satisfied"),
                          "failure_fingerprint": item.get("failure_fingerprint")}
                         for item in rejected if isinstance(item, dict)]
    package_failures = [item for item in (typed.get("package_install_evidence") or [])
                        if isinstance(item, dict) and item.get("failure_fingerprint")]
    return _context_fingerprint({
        "failure_class": typed.get("failure_class") or report.get("failure_class") or "UNKNOWN",
        "worktree_state": typed.get("worktree_state") or "UNKNOWN",
        "categories": sorted(categories),
        "rejection_context": rejection_context,
        "package_failure_fingerprint": str(package_failures[-1].get("failure_fingerprint")) if package_failures else "",
    })


def _repeated_zero_progress_failure(task_id: str, recovery_epoch: int | None = None) -> tuple[bool, str, int]:
    """Detect consecutive recovery attempts without worktree or criteria progress."""
    rows = db.coding_phase_reports(task_id)
    if recovery_epoch is not None:
        # Historical reports remain available to diagnostics, but cannot
        # terminate a newly reopened epoch before it has executed anything.
        rows = [row for row in rows
                if _report_recovery_epoch(row.get("structured_report") or {}) == int(recovery_epoch)
                and _report_has_execution_attempt(row.get("structured_report") or {})]
    states = [(_zero_progress_signature(row.get("structured_report") or {}), row.get("structured_report") or {})
              for row in rows]
    if not states or not states[-1][0]:
        return False, "", 0
    latest_signature = states[-1][0]
    consecutive = 0
    # Different plans, failure classes, and fingerprints still count as one
    # recovery attempt when none produced filesystem or acceptance progress.
    for signature, report in reversed(states):
        if not signature:
            break
        consecutive += 1
    latest=states[-1][1]
    pending_handoff = (latest.get('implementation_model') == settings.short_coding_model and latest.get('test_fail')
        and (latest.get('mutation_classification') or (latest.get('typed_execution_summary') or {}).get('mutation_classification')) == 'IDEMPOTENT_NOOP'
        and not any(report.get('phase_id') == latest.get('phase_id')
                    and report.get('implementation_model') == settings.long_implementation_model
                    for _,report in states))
    if pending_handoff:
        # A restart may restore several old no-op reports. Give the bounded,
        # untried model handoff its invocation before applying the stop rule.
        return False, latest_signature, consecutive
    return consecutive >= 2, latest_signature, consecutive


def _evidence_counts(report: dict, typed_summary: dict) -> tuple[int, int]:
    operations=[item for item in (typed_summary.get("operations") or []) if isinstance(item,dict)]
    successful=[item for item in operations if str(item.get("status") or "").lower() in {"success", "completed", "ok"}]
    if typed_summary.get("worktree_state") == "ROLLED_BACK":
        done = 0
    else:
        changed = {str(path) for path in (report.get("changed_files") or [])}
        actual_writes = [item for item in successful
                         if item.get("tool") in {"workspace_write", "workspace_patch"}]
        written_paths = {str((item.get("output") or {}).get("path") or (item.get("input") or {}).get("path") or "")
                         for item in actual_writes}
        done = len(changed | {path for path in written_paths if path})
    verify=sum(1 for item in successful if item.get("tool") in {"workspace_read", "workspace_read_normalized"})
    verify += len(report.get("test_pass") or []) + (1 if report.get("build_pass") == "PASS" else 0)
    return done, verify


def _phase_signature(phase: dict) -> str:
    payload = {key: phase.get(key) for key in ("goal", "done", "verify", "dependencies", "risks", "execution_mode",
                                                "requires_dependency_installation", "dependency_requirements",
                                                "verification_command", "verification_targets", "verification_executor",
                                                "criterion_executors", "host_verification")}
    return hashlib.sha256(json.dumps(payload, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()[:16]

def _retain_completed_replan_phases(plan: dict, current: dict, completed_ids: set[str]) -> dict:
    """Keep persisted completed work when a model emits only its repair stages.

    Completion comes from the saved controller state and verified IDs, never
    from a proposed model status. Changed acceptance contracts still go through
    the existing invalidation path below.
    """
    result=copy.deepcopy(plan)
    proposed={p['id']:p for p in result.get('phases',[])}
    retained=[]
    for previous in current.get('phases',[]):
        phase_id=previous.get('id')
        if phase_id not in completed_ids or previous.get('status')!='pass':
            continue
        replacement=proposed.get(phase_id)
        if replacement is None:
            retained.append(copy.deepcopy(previous))
        # When a model includes a verified phase in a replacement plan, its
        # explicit status must still agree with the authoritative checkpoint.
        # Omitted completed phases are restored above, but an included phase
        # marked pending is rejected by the caller instead of silently fixed.
    if retained:
        result['phases']=retained+result.get('phases',[])
        retained_ids={p['id'] for p in retained}
        result['tasks']=[copy.deepcopy(t) for t in current.get('tasks',[])
                         if t.get('phase_id') in retained_ids]+result.get('tasks',[])
        result,_=normalize_replan_graph(result)
    return result

def _failed_repair_history(reports: list[dict]) -> list[dict]:
    """Keep measured failures from recent edits, not their unverified advice."""
    history=[]
    for report in reports:
        failures=[]
        for operation in (report.get('typed_execution_summary') or {}).get('operations') or []:
            if operation.get('tool')!='verification_command':
                continue
            output=operation.get('output') or {}
            tests=[failure for run in output.get('test_runs') or [] for failure in run.get('failures') or []]
            for failure in tests[:2]:
                detail=str(failure.get('detail') or '')
                failures.append({'test':str(failure.get('name') or '')[:160],
                    'error':detail.split('error:',1)[-1].split('\n  code:',1)[0][:400],
                    'assertions':[{'path':str(frame.get('path') or '')[:300],'line':frame.get('line'),
                                   'source_line':str(frame.get('source_line') or '')[:300]}
                        for frame in failure.get('source_locations') or []][-2:]})
            if not tests:
                failures.extend({'ids':failure.get('ids',[])[:4],'error':str(failure.get('error') or '')[:400]}
                    for failure in output.get('failures') or [] if not failure.get('contract_error'))
        if failures:
            history.append({'attempt':report.get('attempt'),'plan_revision':report.get('plan_revision',0),
                'model':report.get('implementation_model'),'changed_files':(report.get('changed_files') or [])[:4],
                'failures':failures[:2]})
    return history[-3:]


def _verification_repair_stalled(reports: list[dict]) -> bool:
    """Detect edits that leave the same observed failures without improvement."""
    observations=[]
    for report in reports:
        for op in (report.get('typed_execution_summary') or {}).get('operations') or []:
            if op.get('tool')!='verification_command':
                continue
            output=op.get('output') or {}
            failures=[f for f in output.get('failures') or [] if not f.get('contract_error')]
            failed={key for f in failures for key in f.get('ids') or []}
            passed=set(output.get('passed_criteria_ids') or [])-failed
            tests={int(r.get('registered_tests') or 0):int(r.get('passed') or 0)
                   for r in output.get('test_runs') or []
                   if 0<=int(r.get('passed') or 0)<=int(r.get('registered_tests') or 0)}
            identity=(report.get('plan_revision',0),report.get('recovery_epoch',0),
                      json.dumps((op.get('input') or {}).get('command'),sort_keys=True))
            observations.append((identity,failed,passed,tests,report,
                                 bool(failures) and all(f.get('kind')=='BROWSER' for f in failures)))
    if len(observations)<2:
        return False
    before,current=observations[-2:]
    typed=current[4].get('typed_execution_summary') or {}
    edited=int(current[4].get('accepted_mutations') or typed.get('accepted_mutations') or 0)>0
    test_improved=any(total in before[3] and passed>before[3][total] for total,passed in current[3].items())
    def source_errors(report):
        return {json.dumps([item.get('message'),sorted(item.get('source_paths') or [])],ensure_ascii=False)
            for op in (report.get('typed_execution_summary') or {}).get('operations') or []
            for failure in (op.get('output') or {}).get('failures') or [] if failure.get('project_source_error')
            for item in failure.get('browser_errors') or [] if item.get('source_paths')}
    source_error_improved=bool(source_errors(before[4])-source_errors(current[4]))
    def failed_test_names(report):
        return {(str(failure.get('name')),str(failure.get('detail') or '').split('\n',1)[0]
                 if failure.get('name')=='Node.js module loading' else '')
            for op in (report.get('typed_execution_summary') or {}).get('operations') or []
            for run in (op.get('output') or {}).get('test_runs') or []
            for failure in run.get('failures') or [] if failure.get('name')}
    before_tests,current_tests=failed_test_names(before[4]),failed_test_names(current[4])
    # Equal pass counts can hide a different failing assertion after a real
    # correction. Do not hand the fix role away merely because both failures
    # were wrapped as REQUIRED_TESTS. This grants no extra retry budget.
    test_failure_changed=bool(before_tests and current_tests and before_tests!=current_tests)
    return bool(edited and current[0]==before[0] and current[1] and current[1]==before[1]
                and not (current[2]-before[2]) and not source_error_improved and not test_failure_changed
                and (current[5] or not test_improved))


def _phase_retry_limit(phase: dict, current: dict, prior: list[dict]) -> int:
    # Fixing OLCR's generated verifier must not consume an implementation
    # correction. One verifier repair credit is bounded to this plan/epoch.
    credit = phase.get('host_verification') and any(
        report.get('plan_revision', 0) == current.get('plan_revision', 0)
        and report.get('recovery_epoch', 0) == current.get('recovery_epoch', 0)
        and (report.get('verification_pending') or any(failure.get('contract_error') for operation in (report.get('typed_execution_summary') or {}).get('operations') or []
                for failure in (operation.get('output') or {}).get('failures') or [] if isinstance(failure, dict)))
        for report in [*prior,current])
    progress_credit, best_test_counts = 0, {}
    observed = False
    passed_by_contract = {}
    source_errors_by_contract = {}
    resolved_source_errors = set()
    if phase.get('host_verification') or phase.get('verification_command'):
        for report in [*prior, current]:
            if (report.get('plan_revision', 0) != current.get('plan_revision', 0)
                    or report.get('recovery_epoch', 0) != current.get('recovery_epoch', 0)):
                continue
            operations = [op for op in (report.get('typed_execution_summary') or {}).get('operations') or []
                          if op.get('tool') == 'verification_command']
            outputs = [(op.get('output') or {}) for op in operations]
            new_criteria = False
            source_error_improved=False
            for operation in operations:
                output=operation.get('output') or {}
                identity=json.dumps((operation.get('input') or {}).get('command'),sort_keys=True)
                prior_ids=passed_by_contract.setdefault(identity,set())
                failed={key for failure in output.get('failures') or [] for key in failure.get('ids') or []}
                passed=set(output.get('passed_criteria_ids') or [])-failed
                new_criteria = new_criteria or bool(passed-prior_ids)
                prior_ids.update(passed)
                source_errors={json.dumps([item.get('message'),sorted(item.get('source_paths') or [])],ensure_ascii=False)
                    for failure in output.get('failures') or [] if failure.get('project_source_error')
                    for item in failure.get('browser_errors') or [] if item.get('source_paths')}
                previous_errors=source_errors_by_contract.get(identity,set())
                removed=previous_errors-source_errors
                source_error_improved=source_error_improved or bool(removed-resolved_source_errors
                    and not source_errors.intersection(resolved_source_errors))
                resolved_source_errors.update(removed)
                source_errors_by_contract[identity]=source_errors
            tests = [run for output in outputs for run in output.get('test_runs') or [] if int(run.get('registered_tests') or 0)>0]
            test_improved=False
            for run in tests:
                total=int(run['registered_tests'])
                passed=int(run.get('passed') or 0)
                if not 0<=passed<=total:
                    continue
                test_improved = test_improved or (total in best_test_counts and passed>best_test_counts[total])
                best_test_counts[total]=max(best_test_counts.get(total,-1),passed)
            changed = report.get('final_worktree_mutations',report.get('accepted_mutations',0))
            if int(changed or 0)>0 and observed and (new_criteria or test_improved or source_error_improved):
                progress_credit += 1
            if outputs:
                observed=True
        # Progress can justify focused repairs, never unlimited extensions by
        # continuously adding tests. Regaining a previously passed criterion
        # for the same contract earns no additional credit.
        progress_credit=min(progress_credit,max(2,len(phase.get('done') or [])+len(phase.get('verify') or [])))
    same_epoch = [report for report in [*prior,current]
                  if report.get('plan_revision',0)==current.get('plan_revision',0)
                  and report.get('recovery_epoch',0)==current.get('recovery_epoch',0)]
    syntax_handoff = any(
        ((op.get('output') or {}).get('operation_diagnostic') or {}).get('reason_subtype') == 'STRUCTURAL_VALIDATION_FAILED'
        for report in same_epoch for op in (report.get('typed_execution_summary') or {}).get('operations') or [] if isinstance(op, dict))
    stalled_handoff = any(report.get('implementation_model') == settings.short_coding_model and report.get('test_fail')
        and (report.get('mutation_classification') or (report.get('typed_execution_summary') or {}).get('mutation_classification')) == 'IDEMPOTENT_NOOP'
        for report in same_epoch)
    stalled_handoff = stalled_handoff or any(
        report.get('implementation_model')==settings.short_coding_model
        and _verification_repair_stalled(same_epoch[:index+1])
        for index,report in enumerate(same_epoch))
    legacy_repair_handoff = bool(phase.get('host_verification') and phase.get('verification_repair_allowed')
        and settings.short_coding_model != settings.long_implementation_model
        and _coding_phase_model(phase, repairing_verification=True) == settings.short_coding_model
        and any(report.get('implementation_model') == settings.long_implementation_model
                and report.get('test_fail') for report in same_epoch))
    read_only_credit=bool(phase.get('host_verification') and phase.get('verification_repair_allowed') and any(
        (report.get('execution_expectations') or {}).get('requires_repo_mutation') is False
        and any(op.get('tool')=='verification_command' and op.get('status')=='failed'
                for op in (report.get('typed_execution_summary') or {}).get('operations') or [])
        for report in same_epoch))
    limit=(MAX_RETRIES_PER_PHASE + int(bool(credit)) + progress_credit
            + int(bool(syntax_handoff)) + int(bool(stalled_handoff or legacy_repair_handoff)) + int(read_only_credit))
    # The first transition from a file-load failure to actually passing
    # registered tests earns one review of the newly exposed failures. This
    # also works on a resumed old task whose attempt already exceeds limit.
    recovered=next((r for r in same_epoch if r.get('project_test_registration_recovered')),None)
    if recovered:
        recovery_floor=int(recovered.get('attempt') or 0)+1
        # Repairing a now-observable test API mismatch can expose ordinary
        # assertions on the next attempt. Carry forward bounded measured
        # improvements even if an old task exhausted its absolute attempt cap.
        return max(limit,recovery_floor+progress_credit)
    return limit


def _review_phase(task_id: str, managed: dict, phase: dict, report_row: dict, completed: list[dict], workspace_root: str | None = None) -> str | None:
    report=report_row["structured_report"]
    typed=report.get("typed_execution_summary") if isinstance(report.get("typed_execution_summary"),dict) else {}
    prior_reports=[row["structured_report"] for row in db.coding_phase_reports(task_id)
                   if row.get("id") != report_row.get("id") and row.get("phase_id") == phase.get("id")]
    evaluation=evaluate_phase(phase,report,prior_reports,workspace_root)
    report["phase_evaluation"]={key:value for key,value in evaluation.items() if key != "file_state"}
    done_evidence_count, verify_evidence_count = _evidence_counts(report, typed)
    print(f"TASK_ID={task_id} TASK_ACTIVITY=PHASE_EVALUATION PHASE_REPORT_VALID=true "
          f"DONE_EVIDENCE_COUNT={done_evidence_count} VERIFY_EVIDENCE_COUNT={verify_evidence_count} "
          f"GEMMA_EVIDENCE_COUNT={len((typed.get('operations') or []))}",
          file=__import__('sys').stderr,flush=True)
    print(f"TASK_ID={task_id} PHASE_EVALUATION_COMPLETE={'true' if evaluation['phase_complete'] else 'false'} DONE_TOTAL={evaluation['done_total']} DONE_SATISFIED={evaluation['done_satisfied']} VERIFY_TOTAL={evaluation['verify_total']} VERIFY_SATISFIED={evaluation['verify_satisfied']} AUTHORITATIVE_FAILURE={'true' if evaluation['authoritative_failure_present'] else 'false'} REQUIRED_NOT_RUN={'true' if evaluation['required_not_run_present'] else 'false'} ALLOWED_DECISIONS={json.dumps(evaluation['allowed_decisions'])}",file=__import__('sys').stderr,flush=True)
    print(f"TASK_ID={task_id} UNSATISFIED_DONE_IDS={json.dumps(evaluation.get('unsatisfied_done_ids') or [], ensure_ascii=False)} "
          f"UNSATISFIED_VERIFY_IDS={json.dumps(evaluation.get('unsatisfied_verify_ids') or [], ensure_ascii=False)} "
          f"REMAINING_CRITERIA_OWNER_COUNTS={json.dumps(evaluation.get('remaining_criteria_owner_counts') or {}, ensure_ascii=False, sort_keys=True)} "
          f"NEXT_REQUIRED_EXECUTOR={evaluation.get('next_required_executor') or 'NONE'} "
          f"PHASE_ADVANCE_ELIGIBLE={'YES' if evaluation.get('phase_advance_eligible') else 'NO'} "
          f"IMPLEMENTER_RETRY_REQUIRED={'YES' if evaluation.get('implementer_retry_required') else 'NO'} "
          f"IMPLEMENTER_RETRY_REASON={evaluation.get('implementer_retry_reason') or 'none'}",
          file=__import__('sys').stderr, flush=True)
    if evaluation.get("required_not_run_present"):
        print(f"TASK_ID={task_id} REQUIRED_NOT_RUN_IDS={json.dumps(evaluation.get('required_not_run_ids') or [], ensure_ascii=False)} "
              f"REQUIRED_NOT_RUN_KINDS={json.dumps(evaluation.get('required_not_run_kinds') or [], ensure_ascii=False)} "
              f"REQUIRED_NOT_RUN_EXECUTOR_CAPABILITY={json.dumps(evaluation.get('required_not_run_executor_capability') or [], ensure_ascii=False)}",
              file=__import__('sys').stderr, flush=True)
    # Coding Orchestrator decisions are derived from typed evidence.  The
    # lightweight router model remains available to unrelated external-tool
    # routing, but is never a Coding phase manager.
    output_truncated = any(
        (operation.get('output') or {}).get('output_truncated') is True
        for operation in typed.get('operations') or [] if isinstance(operation, dict)) or any(
        'IMPLEMENTER_OUTPUT_LIMIT_EXCEEDED' in str(error) for error in report.get('errors') or [])
    package_manager_unavailable = any(
        isinstance(operation, dict)
        and operation.get("tool") == "package_install"
        and str(operation.get("status") or "").lower() not in {"success", "completed", "ok"}
        and isinstance(operation.get("output"), dict)
        and operation["output"].get("failure_class") == "PACKAGE_MANAGER_UNAVAILABLE"
        and operation["output"].get("process_started") is False
        for operation in typed.get("operations") or [])
    narrative_only = report.get("implementation_result_kind") == "NARRATIVE_ONLY"
    if output_truncated:
        decision = {'decision': 'REPLAN_REQUIRED',
                    'reason': 'implementation exceeded its output budget; split remaining work into smaller file or source-edit batches instead of repeating the same call'}
    elif package_manager_unavailable:
        decision = {"decision": "BLOCKED",
                    "reason": "The authorized package manager is unavailable in the OLCR runtime; install or configure a package manager before resuming.",
                    "failure_class": "PACKAGE_MANAGER_UNAVAILABLE"}
    elif narrative_only:
        attempt=int(report.get("attempt", 0))
        decision = {"decision": "RETRY" if attempt < MAX_RETRIES_PER_PHASE else "BLOCKED",
                    "reason": "implementation returned narrative only; no authoritative workspace operation was executed"}
        print(f"TASK_ID={task_id} IMPLEMENTATION_RESULT_KIND=NARRATIVE_ONLY NARRATIVE_ONLY_DETECTED=YES "
              f"NARRATIVE_RETRY_CAUSE=NO_EXECUTED_OPERATION ATTEMPT={attempt}", file=__import__('sys').stderr, flush=True)
    elif evaluation["phase_complete"]:
        decision = {"decision": "PASS", "reason": "typed phase evidence is complete"}
    elif evaluation.get("phase_advance_eligible"):
        # The implementation owner has completed all mutation work.  Keep the
        # phase unresolved until the declared verification executor runs, but
        # bind the retry channel so the scheduler cannot call Implementer.
        decision = {"decision": "RETRY", "reason": "verification-owned criteria remain",
                    "retry_channel": str(evaluation.get("next_required_executor") or "VERIFICATION")}
    elif evaluation["authorization_blocker_present"]:
        decision = {"decision": "NEED_USER", "reason": "authorization is required"}
    elif evaluation["external_blocker_present"]:
        decision = {"decision": "BLOCKED", "reason": "external condition prevents progress"}
    elif any((operation.get('output') or {}).get('executor_error')
             for operation in typed.get('operations') or []):
        decision = {"decision":"RETRY","reason":"verification executor failed before producing an application test result",
                    "retry_channel":"VERIFICATION_EXECUTOR"}
    elif int(report.get("attempt", 0)) < _phase_retry_limit(phase, report, prior_reports):
        package_channel = "PACKAGE_MANAGER_COMMAND" in (evaluation.get("required_not_run_executor_capability") or [])
        decision = {"decision": "RETRY",
                    "reason": "recoverable package-install evidence is incomplete" if package_channel else "recoverable phase evidence is incomplete",
                    "retry_channel": "PACKAGE_INSTALL" if package_channel else "IMPLEMENTATION"}
    else:
        decision = {"decision": "REPLAN_REQUIRED", "reason": "phase retry budget exhausted"}
    report["manager_decision"] = decision
    decision["diagnosis"] = {
        "unmet_done": [phase["done"][index] for index in range(len(phase.get("done") or []))
                       if f"DONE:{index+1}" in (evaluation.get("unsatisfied_done_ids") or [])],
        "unmet_verify": [phase["verify"][index] for index in range(len(phase.get("verify") or []))
                         if f"VERIFY:{index+1}" in (evaluation.get("unsatisfied_verify_ids") or [])],
        "evidence_used": [str(item)[:500] for item in [*(report.get("errors") or []), *(report.get("test_fail") or [])]][:4],
    }
    report["manager_diagnostics"] = {"raw_decision": None, "decision_valid": True,
                                      "effective_decision": decision["decision"], "phase_complete": evaluation["phase_complete"],
                                      "retry_channel": decision.get("retry_channel", "IMPLEMENTATION"),
                                      "unsatisfied_done_ids": evaluation.get("unsatisfied_done_ids") or [],
                                      "unsatisfied_verify_ids": evaluation.get("unsatisfied_verify_ids") or [],
                                      "remaining_criteria_owner_counts": evaluation.get("remaining_criteria_owner_counts") or {},
                                      "next_required_executor": evaluation.get("next_required_executor"),
                                      "phase_advance_eligible": bool(evaluation.get("phase_advance_eligible")),
                                      "implementer_retry_required": bool(evaluation.get("implementer_retry_required")),
                                      "implementer_retry_reason": evaluation.get("implementer_retry_reason") or "none",
                                      "execution_binding_diagnosis": ("MODEL_RETURNED_NARRATIVE_INSTEAD_OF_FILE_OPERATION_PLAN" if narrative_only else None)}
    # Persist the deterministic decision before callers advance the plan.  The
    # completion path reloads reports from storage and treats this decision as
    # the authority for a completed phase.
    db.update_coding_phase_report(report_row["id"], report, "PASS")
    print(f"TASK_ID={task_id} CODING_GEMMA_PHASE_REVIEW=REMOVED MANAGER_DECISION={decision['decision']}", file=__import__('sys').stderr, flush=True)
    return decision["decision"]

def _generate_plan(task_id: str, goal: str, prompt: str, activity: str, requirements: dict | None = None,
                   *, recovery: bool = False, repair: bool = False) -> tuple[dict | None, str | None]:
    if recovery and not (requirements or {}).get('_explicit_instruction_revision') and not _record_recovery_model_call(task_id, repair=repair):
        return None, None
    schema = plan_schema()
    verification_requested = verification_requested_by_user(goal, requirements)
    raw_preserve_ids = (requirements or {}).get("_preserve_completed_phase_ids") or []
    if isinstance(raw_preserve_ids, (list, tuple, set)):
        preserve_completed_phase_ids = {str(item) for item in raw_preserve_ids if item is not None}
    else:
        preserve_completed_phase_ids = set()
    if not verification_requested:
        schema['properties']['phases']['items']['properties']['verify'].pop('minItems', None)
        prompt += ('\n[VERIFICATION_POLICY: EXPLICIT_OPT_IN_ONLY]\n'
                   'No verification was requested. Keep every implementation phase in IMPLEMENTATION mode with verify:[]; '
                   'do not create tests, build/typecheck/browser checks, acceptance criteria, or verification-only phases unless they are explicitly requested deliverables. '
                   'Feature behavior is implemented as requested and is not an instruction to run a separate check.\n')
    automatic_replan_phase_limit = None
    if recovery and not (requirements or {}).get('_explicit_instruction_revision'):
        requested_limit = (requirements or {}).get('_replan_phase_limit')
        if isinstance(requested_limit, int) and not isinstance(requested_limit, bool):
            automatic_replan_phase_limit = max(1, min(requested_limit, 8))
            schema['properties']['phases']['maxItems'] = automatic_replan_phase_limit
            prompt += (f'\nAUTOMATIC_RECOVERY_PHASE_LIMIT={automatic_replan_phase_limit}. Return only replacement phases '
                       'for unfinished work. The host reattaches completed verified phases. Do not split or add phases.')
    # The task identity is host state, not a field the model may paraphrase
    # or repeat until it exhausts the generation budget.
    schema['properties']['original_goal']={'type':'string','const':goal}
    if not recovery and re.search(r'node:test',goal,re.I) and re.search(r'\bHTML\b',goal,re.I):
        prompt += ('\nFor browser code shared with Node.js tests, record the shared module API and browser/Node loading strategy in assumptions. '
            'When logic and UI are separate files, define the logic API before its consumers and make tests call that actual API. '
            'Run integration checks after their required files exist; do not require a later phase\'s API to run while creating an earlier file.')
    if ((requirements or {}).get('planning_policy') or {}).get('mode') == 'LEAN':
        schema['properties'].pop('tasks', None)
        schema['required']=[*schema['required'],'file_manifest']
        manifest=schema['properties']['file_manifest']['items']
        manifest['required']=[*manifest['required'],'owner_phase']
        manifest['properties']['owner_phase']['maxLength']=80
        manifest['properties']['owner_phase']['minLength']=1
        for field in ('path','role'):
            manifest['properties'][field]['maxLength']=500
        for field,limit in (('allowed',80),('forbidden',12)):
            scope=schema['properties']['scope']['properties'][field]
            scope['maxItems']=limit
            scope['items']['maxLength']=500
        schema['properties']['assumptions'].update(maxItems=8,items={'type':'string','maxLength':500})
        phases=schema['properties']['phases']
        coherent=(requirements or {}).get('planning_policy',{}).get('coherent_static_application')
        phases['maxItems']=(automatic_replan_phase_limit if automatic_replan_phase_limit is not None
                            else 2 if coherent and not recovery else 4)
        properties=phases['items']['properties']
        properties['id']['maxLength']=80
        properties['goal']['maxLength']=500
        for key in ('done','verify','risks'):
            properties[key].update(maxItems=8,items={'type':'string','maxLength':500})
        properties['dependencies'].update(maxItems=4,items={'type':'string','maxLength':80})
        properties.pop('file_manifest',None)
        prompt+='\nKeep plan summaries concise. Use only the top-level file_manifest, with owner_phase assigning each file to its producing phase. Original requirements remain authoritative and are passed separately to implementation.'
    prompt+='\nEvery done/verify array item must be a complete observable condition. JSON delimiters and schema field labels belong outside condition strings; never emit items such as "],", "verify:[" or "verify" as conditions.'
    raw=_model_text(task_id,"PLANNING" if activity=="QWEN_PLANNING" else "RUNNING",activity,settings.planner_model,[
        {"role":"system","content":"You are OLCR Bonsai Planning Mode. Return JSON only; this is read-only planning."},
        {"role":"user","content":prompt},
    ], structured_schema=schema)
    if raw is None: return None,None
    plan,parse_error=extract_plan_json(raw)
    if isinstance(plan, dict):
        plan, checkpoint_changes = enforce_explicit_phase_failure_checkpoint(plan, goal)
        if checkpoint_changes:
            print(f"PLAN_CHECKPOINT_POLICY_NORMALIZED=YES CHANGES={json.dumps(checkpoint_changes, ensure_ascii=False)}",
                  file=__import__('sys').stderr, flush=True)
        plan, mode_changes = ensure_explicit_phase_execution_modes(plan)
        if mode_changes:
            print(f"PLAN_PHASE_EXECUTION_MODE_NORMALIZED=YES CHANGES={json.dumps(mode_changes, ensure_ascii=False)}", file=__import__('sys').stderr, flush=True)
        plan, complexity_changes = repair_phase_complexity(plan)
        if complexity_changes:
            print(f"PLAN_PHASE_COMPLEXITY_AUTO_REPAIRED=YES CHANGES={json.dumps(complexity_changes, ensure_ascii=False)}", file=__import__('sys').stderr, flush=True)
        plan, graph_changes, graph_diagnostics = reconcile_graph_references(plan, plan.get("graph_replacement_map"))
        if graph_changes:
            print(f"GRAPH_REFERENCE_RECONCILIATION=PASS CHANGES={json.dumps(graph_changes, ensure_ascii=False)}",
                  file=__import__('sys').stderr, flush=True)
        if graph_diagnostics.get("errors"):
            first = graph_diagnostics["first_error"] or {}
            print(f"GRAPH_VALIDATION=FAIL OFFENDING_PHASE_ID={first.get('offending_phase_id') or 'NONE'} "
                  f"OFFENDING_TASK_ID={first.get('offending_task_id') or 'NONE'} "
                  f"OFFENDING_DEPENDENCY_REF={first.get('offending_dependency_ref') or 'NONE'} "
                  f"EXPECTED_REFERENCE_TYPE={first.get('expected_reference_type') or 'UNKNOWN'} "
                  f"KNOWN_PHASE_IDS={json.dumps(graph_diagnostics.get('known_phase_ids') or [], ensure_ascii=False)} "
                  f"KNOWN_TASK_IDS={json.dumps(graph_diagnostics.get('known_task_ids') or [], ensure_ascii=False)} "
                  f"DEPENDENCY_VALIDATION_REASON={first.get('reason') or 'UNKNOWN'} "
                  f"GRAPH_ERROR_FINGERPRINT={first.get('fingerprint') or 'NONE'}",
                  file=__import__('sys').stderr, flush=True)
    if recovery and isinstance(plan, dict):
        plan, graph_changes = normalize_replan_graph(plan, (requirements or {}).get("required_mcps"))
        if graph_changes:
            print(f"PLAN_GRAPH_NORMALIZED=YES CHANGES={json.dumps(graph_changes, ensure_ascii=False)}", file=__import__('sys').stderr, flush=True)
    if isinstance(plan, dict) and not verification_requested:
        plan, verification_changes = suppress_unrequested_verification(
            plan, preserve_phase_ids=preserve_completed_phase_ids)
        if verification_changes:
            print(f"PLAN_UNREQUESTED_VERIFICATION_REMOVED=YES CHANGES={json.dumps(verification_changes, ensure_ascii=False)}",
                  file=__import__('sys').stderr, flush=True)
    graph_diagnostics = graph_validation_diagnostics(plan)
    def graph_error_messages(diagnostics):
        return [
            (f"phase {item.get('offending_phase_id') or 'UNKNOWN'} has invalid dependency "
             f"{item.get('offending_dependency_ref') or 'UNKNOWN'}: {item.get('reason') or 'invalid phase reference'}")
            for item in diagnostics.get("errors", []) if isinstance(item, dict)
        ]
    errors=([parse_error] if parse_error else []) + validate_plan(plan,goal) + validate_fix_plan_quality(plan, requirements) + graph_error_messages(graph_diagnostics) + ([] if recovery else validate_definition_steps(plan, goal))
    # The task goal is persisted host state; a model paraphrase must never
    # consume the single schema-repair attempt or alter that identity.
    if plan is not None and errors == ["original goal mismatch"]:
        print("PLAN_ORIGINAL_GOAL_SOURCE=task PLAN_MODEL_ORIGINAL_GOAL_PRESENT=yes PLAN_MODEL_ORIGINAL_GOAL_MATCH=no",file=__import__('sys').stderr,flush=True)
        plan={**plan,"original_goal":goal}
        errors=validate_plan(plan,goal) + validate_fix_plan_quality(plan, requirements) + ([] if recovery else validate_definition_steps(plan, goal))
        print("CANONICAL_PLAN_ORIGINAL_GOAL_SOURCE=task",file=__import__('sys').stderr,flush=True)
    # The planner may provide an advisory task graph, but OLCR derives the
    # authoritative graph after profile normalization.  Preserve a valid phase
    # plan when only those advisory task references are malformed; otherwise a
    # preflight-only row can make Qwen spend its single repair on an artifact
    # the orchestrator replaces anyway.
    if errors and isinstance(plan, dict) and "tasks" in plan:
        phase_plan={key:value for key,value in plan.items() if key != "tasks"}
        phase_graph_diagnostics=graph_validation_diagnostics(phase_plan)
        phase_plan_errors=(validate_plan(phase_plan,goal) + validate_fix_plan_quality(phase_plan, requirements)
                           + graph_error_messages(phase_graph_diagnostics)
                           + ([] if recovery else validate_definition_steps(phase_plan, goal)))
        if not phase_plan_errors:
            print("PLAN_ADVISORY_TASK_GRAPH=DISCARDED_INVALID AUTHORITATIVE_TASK_GRAPH=PENDING_NORMALIZATION",file=__import__('sys').stderr,flush=True)
            plan,errors=phase_plan,[]
    print(f"PLAN_INITIAL_PARSE={'PASS' if not parse_error else 'FAIL'} PLAN_INITIAL_SCHEMA={'PASS' if not validate_plan(plan,goal) else 'FAIL'} PLAN_INITIAL_ERRORS={json.dumps(errors,ensure_ascii=False)}",file=__import__('sys').stderr,flush=True)
    if not errors: return plan,raw
    deterministic_repair = deterministic_plan_schema_repair(plan, goal, errors, verification_requested)
    if deterministic_repair is not None:
        print("PLAN_SCHEMA_REPAIR_DETERMINISTIC=PASS MODEL_REPAIR_CALL=SKIPPED", file=__import__('sys').stderr, flush=True)
        return deterministic_repair, raw
    if recovery and not (requirements or {}).get('_explicit_instruction_revision') and not _record_recovery_model_call(task_id, repair=True):
        return None, raw
    repaired=_model_text(task_id,"PLANNING","QWEN_PLAN_SCHEMA_REPAIR",settings.short_coding_model,[
        {"role":"system","content":"Repair the existing JSON plan and its deliverable boundaries using the supplied validation errors. Split already-requested work when needed; do not add scope or execute tools."},
        {"role":"user","content":plan_repair_prompt(goal,raw,errors,graph_diagnostics)},
    ], structured_schema=schema)
    if repaired is None: return None,None
    plan,repair_parse_error=extract_plan_json(repaired)
    if plan is not None and isinstance(plan,dict):
        plan={**plan,"original_goal":goal}
        plan, checkpoint_changes = enforce_explicit_phase_failure_checkpoint(plan, goal)
        if checkpoint_changes:
            print(f"PLAN_CHECKPOINT_POLICY_NORMALIZED=YES REPAIR_CHANGES={json.dumps(checkpoint_changes, ensure_ascii=False)}",
                  file=__import__('sys').stderr, flush=True)
        plan, mode_changes = ensure_explicit_phase_execution_modes(plan)
        if mode_changes:
            print(f"PLAN_PHASE_EXECUTION_MODE_NORMALIZED=YES REPAIR_CHANGES={json.dumps(mode_changes, ensure_ascii=False)}", file=__import__('sys').stderr, flush=True)
        plan, graph_changes, repair_graph_diagnostics = reconcile_graph_references(plan, plan.get("graph_replacement_map") if isinstance(plan, dict) else None)
        if graph_changes:
            print(f"GRAPH_REFERENCE_RECONCILIATION=PASS REPAIR_CHANGES={json.dumps(graph_changes, ensure_ascii=False)}",
                  file=__import__('sys').stderr, flush=True)
        if recovery:
            plan, graph_changes = normalize_replan_graph(plan, (requirements or {}).get("required_mcps"))
            if graph_changes:
                print(f"PLAN_GRAPH_NORMALIZED=YES REPAIR_CHANGES={json.dumps(graph_changes, ensure_ascii=False)}", file=__import__('sys').stderr, flush=True)
        if not verification_requested:
            plan, verification_changes = suppress_unrequested_verification(
                plan, preserve_phase_ids=preserve_completed_phase_ids)
            if verification_changes:
                print(f"PLAN_UNREQUESTED_VERIFICATION_REMOVED=YES REPAIR_CHANGES={json.dumps(verification_changes, ensure_ascii=False)}",
                      file=__import__('sys').stderr, flush=True)
    repair_graph_diagnostics = graph_validation_diagnostics(plan)
    repair_errors=([repair_parse_error] if repair_parse_error else []) + validate_plan(plan,goal) + validate_fix_plan_quality(plan, requirements) + graph_error_messages(repair_graph_diagnostics) + ([] if recovery else validate_definition_steps(plan, goal))
    deterministic_repair = deterministic_plan_schema_repair(plan, goal, repair_errors, verification_requested)
    if deterministic_repair is not None:
        print("PLAN_REPAIR_SCHEMA_DETERMINISTIC=PASS MODEL_REPAIR_RETRY=SKIPPED", file=__import__('sys').stderr, flush=True)
        return deterministic_repair, repaired
    initial_graph_error = graph_diagnostics.get("first_error") if isinstance(graph_diagnostics, dict) else None
    repaired_graph_error = repair_graph_diagnostics.get("first_error") if isinstance(repair_graph_diagnostics, dict) else None
    if initial_graph_error and repaired_graph_error and initial_graph_error.get("fingerprint") == repaired_graph_error.get("fingerprint"):
        print(f"PLAN_SCHEMA_REPAIR_NO_PROGRESS=YES GRAPH_ERROR_FINGERPRINT={repaired_graph_error.get('fingerprint')}",
              file=__import__('sys').stderr, flush=True)
    if repair_graph_diagnostics.get("errors"):
        first = repair_graph_diagnostics["first_error"] or {}
        print(f"GRAPH_VALIDATION=FAIL REPAIR_OFFENDING_PHASE_ID={first.get('offending_phase_id') or 'NONE'} "
              f"REPAIR_OFFENDING_TASK_ID={first.get('offending_task_id') or 'NONE'} "
              f"REPAIR_OFFENDING_DEPENDENCY_REF={first.get('offending_dependency_ref') or 'NONE'} "
              f"REPAIR_EXPECTED_REFERENCE_TYPE={first.get('expected_reference_type') or 'UNKNOWN'} "
              f"REPAIR_GRAPH_ERROR_FINGERPRINT={first.get('fingerprint') or 'NONE'}",
              file=__import__('sys').stderr, flush=True)
    print(f"PLAN_REPAIR_PARSE={'PASS' if not repair_parse_error else 'FAIL'} PLAN_REPAIR_SCHEMA={'PASS' if not validate_plan(plan,goal) else 'FAIL'} PLAN_REPAIR_ERRORS={json.dumps(repair_errors,ensure_ascii=False)}",file=__import__('sys').stderr,flush=True)
    return (plan,repaired) if not repair_errors else (None,repaired)

def _scope_expansion(current: dict, proposed: dict) -> list[str]:
    previous=set((current.get("scope") or {}).get("allowed") or [])
    return [item for item in ((proposed.get("scope") or {}).get("allowed") or []) if item not in previous]


def _manifest_path_identity(entry: Any) -> str:
    value = entry.get("path") if isinstance(entry, dict) else entry
    if not isinstance(value, str) or not value.strip():
        return ""
    path = PurePosixPath(value.replace("\\", "/")).as_posix()
    return path[2:] if path.startswith("./") else path

_PLAN_AUTHORIZATION_BOUNDARY = re.compile(
    r"(?:\bgit\s+(?:commit|push)\b|\b(?:publish|deploy|purchase)\b|"
    r"\bdelete\s+(?:the\s+)?(?:existing\s+)?(?:file|files|directory|directories|artifact|artifacts|workspace|project)\b|"
    r"(?:秘密|シークレット|認証情報|外部アップロード|公開|デプロイ|購入|"
    r"コミット|プッシュ|破壊的|削除)|"
    r"(?:commit|push|secret|credential|upload).*(?:execute|operation|change))",
    re.IGNORECASE,
)

def _plan_authorization_boundary(plan: dict) -> list[str]:
    """Return only operations that need authorization beyond a coding request."""
    # Inspect both typed scope entries and executable goals, but match
    # destructive deletion only when an existing filesystem artifact is the
    # object; a feature named "delete" is not itself a destructive side effect.
    candidates = list((plan.get("scope") or {}).get("allowed") or [])
    candidates.extend(str(phase.get("goal") or "") for phase in plan.get("phases") or [])
    candidates.extend(str(task.get("goal") or "") for task in plan.get("tasks") or [])
    return [item for item in candidates if _PLAN_AUTHORIZATION_BOUNDARY.search(item)]


def _deterministic_verifier_recovery_plan(task: dict, revision: str) -> dict | None:
    """Apply only the user's exact verifier correction to a matching saved plan."""
    command = ["python3", "-B", "-m", "unittest", "discover", "-s", ".", "-v"]
    rendered_command = "python3 -B -m unittest discover -s . -v"
    old_text = "python3 -B -m unittest discover -s OLCR_E2E_LONG_R17_20260924 -v"
    old_command = ["python3", "-B", "-m", "unittest", "discover", "-s",
                   "OLCR_E2E_LONG_R17_20260924", "-v"]
    allowed = {"__init__.py", "domain.py", "scheduler.py", "test_scheduler.py"}
    if rendered_command not in revision:
        return None
    plan = task.get("plan") if isinstance(task.get("plan"), dict) else None
    if not plan or len(plan.get("phases") or []) != 1:
        return None
    artifact = plan.get("implementation_plan_artifact")
    target_root = artifact.get("target_root") if isinstance(artifact, dict) else None
    manifest = artifact.get("file_manifest") if isinstance(artifact, dict) else None
    plan_manifest = plan.get("file_manifest")
    scopes = [entry.get("requested_scope") or entry.get("approved_paths") or []
              for entry in (task.get("approved_scopes") or []) if isinstance(entry, dict)]
    allowed_plan = set((plan.get("scope") or {}).get("allowed") or [])
    if (not target_root or not Path(target_root).is_absolute()
            or allowed_plan != allowed
            or not isinstance(plan_manifest, list)
            or {str(item.get("path") or "") for item in plan_manifest if isinstance(item, dict)} != allowed
            or not isinstance(manifest, list)
            or {str(item.get("path") or "") for item in manifest if isinstance(item, dict)} != allowed
            or not any(set(map(str, scope)) == allowed for scope in scopes)):
        return None
    phase = plan["phases"][0]
    if (set(map(str, phase.get("verification_targets") or [])) != allowed
            or phase.get("verification_command") != old_command):
        return None
    verify = phase.get("verify")
    if not isinstance(verify, list) or not any(old_text in str(item) for item in verify):
        return None
    corrected = json.loads(json.dumps(plan))
    corrected_phase = corrected["phases"][0]
    corrected_phase["verification_command"] = command
    corrected_phase["verify"] = [str(item).replace(old_text, rendered_command)
                                  for item in corrected_phase["verify"]]
    if validate_plan(corrected, str(task.get("original_goal") or "")):
        return None
    return corrected

def _replan_task(task_id: str, managed: dict, completed_ids: set[str], reason: str, diagnosis: dict | None = None) -> str:
    # Earlier phases may have passed or received steering since this runner
    # snapshot was loaded. Recovery must use the persisted plan and counters.
    managed = db.coding_task(task_id) or managed
    user_revision = reason.startswith('Explicit user instructions at a phase boundary:\n')
    requirements = managed.get('requirements') if isinstance(managed.get('requirements'), dict) else {}
    verification_requested = verification_requested_by_user(str(managed.get('original_goal') or ''), requirements)
    if user_revision:
        revision_text = reason.split('Explicit user instructions at a phase boundary:\n', 1)[-1]
        if verification_requested_by_user(revision_text):
            verification_requested = True
            requirements = {**requirements, 'verification_requested': True,
                            '_explicit_verification_request_revision': True}
            db.update_coding_task(task_id, requirements=requirements)
            managed = db.coding_task(task_id) or {**managed, 'requirements': requirements}
    if not verification_requested:
        saved_plan = managed.get('plan') if isinstance(managed.get('plan'), dict) else {}
        if completed_ids:
            # The report-derived completed set is authoritative even when an
            # older task row persisted stale phase.status values. Mark only
            # those phases as historical before filtering unfinished,
            # unrequested checks, so recovery cannot rewrite a passed
            # contract and invalidate its completion evidence.
            saved_plan = {**saved_plan, "phases": [
                ({**phase, "status": "pass"} if isinstance(phase, dict)
                 and str(phase.get("id") or "") in completed_ids else phase)
                for phase in saved_plan.get("phases") or []
            ]}
        saved_plan, verification_changes = suppress_unrequested_verification(saved_plan)
        if verification_changes:
            db.update_coding_task(task_id, plan=saved_plan)
            managed = db.coding_task(task_id) or {**managed, 'plan': saved_plan}
            print(f"TASK_ID={task_id} SAVED_PLAN_UNREQUESTED_VERIFICATION_REMOVED=YES CHANGES={json.dumps(verification_changes, ensure_ascii=False)}",
                  file=__import__('sys').stderr, flush=True)
    replan_count_in_epoch=int(managed.get("replan_count_in_epoch") or 0)
    global_limit = _task_global_replan_limit(managed)
    recovery_calls = int(managed.get("task_total_recovery_model_calls") or 0)
    deterministic_fallback = (
        _deterministic_verifier_recovery_plan(managed, reason)
        if not user_revision and recovery_calls >= TASK_GLOBAL_RECOVERY_MODEL_CALL_LIMIT else None
    )
    if not user_revision and int(managed.get("replan_count") or 0) >= global_limit and deterministic_fallback is None:
        db.update_coding_task(task_id, status="BLOCKED", activity="NONE", queue_order=None,
                              recovery_action="NONE", recovery_reason="GLOBAL_RECOVERY_LIMIT")
        print(f"TASK_ID={task_id} TASK_GLOBAL_BOUND_ENFORCED=YES AUTO_REQUEUE_AFTER_GLOBAL_LIMIT=NO "
              f"GLOBAL_LIMIT_KIND=REPLAN EFFECTIVE_LIMIT={global_limit} STATUS_AFTER=BLOCKED",
              file=__import__('sys').stderr, flush=True)
        return "Coding Task is blocked: task-global recovery budget exhausted."
    if (not user_revision and replan_count_in_epoch >= MAX_SUBSTANTIAL_REPLANS_PER_TASK
            and deterministic_fallback is None):
        _transition_resumable(task_id,"REPLAN_LIMIT","RECOVERABLE_INTERNAL","REPLAN_CONTINUATION")
        return "Coding Task could not continue after the replan limit."
    recovery_epoch = int(managed.get("recovery_epoch") or 0)
    no_progress, no_progress_signature, no_progress_count = _repeated_zero_progress_failure(task_id, recovery_epoch)
    if not user_revision and no_progress and deterministic_fallback is None:
        # A second structurally equivalent rejected operation with zero
        # accepted mutations cannot be repaired by another unconstrained model
        # call.  Stop before invoking the planner again; PathGuard and all
        # accepted writes remain untouched.
        current_phase_id = (managed.get("current_phase_id") or
                            next((phase.get("id") for phase in (managed.get("plan") or {}).get("phases", [])
                                  if phase.get("id") not in completed_ids), None))
        current_state = (db.coding_task(task_id) or {}).get("resume_state")
        current_state = dict(current_state) if isinstance(current_state, dict) else {}
        current_state.update({
            "epoch_no_progress_count": no_progress_count,
            "epoch_last_failure_signature": no_progress_signature,
            "lifetime_no_progress_count": max(int(current_state.get("lifetime_no_progress_count") or 0), no_progress_count),
            "next_task_action": "TERMINATE",
        })
        db.update_coding_task(task_id, status="BLOCKED", activity="NONE", queue_order=None,
                              current_phase_id=current_phase_id,
                              recovery_action="NONE", recovery_reason="NO_PROGRESS",
                              resume_state=current_state)
        print(f"TASK_ID={task_id} NO_PROGRESS=YES ZERO_WRITE=YES REPEATED_EQUIVALENT_FAILURE=YES "
              f"NO_PROGRESS_COUNT={no_progress_count} NO_PROGRESS_SIGNATURE={no_progress_signature} "
              f"RECOVERY_EPOCH={recovery_epoch} NO_PROGRESS_EVALUATED=YES "
              "NEXT_TASK_ACTION=TERMINATE TASK_STATUS=BLOCKED", file=__import__('sys').stderr, flush=True)
        return "Coding Task is blocked: repeated implementation attempts made no filesystem progress."
    # Reserve the bounded recovery attempt before invoking the replanner.  A
    # malformed schema, path validation failure, or blueprint rejection is
    # still a recovery attempt and must consume the same epoch budget as a
    # successfully applied replan.  Otherwise an invalid model response can
    # loop indefinitely without ever reaching REPLAN_LIMIT.
    if deterministic_fallback is None:
        reserved_replan_count = int(managed.get("replan_count") or 0) + (0 if user_revision else 1)
        reserved_epoch_count = replan_count_in_epoch + (0 if user_revision else 1)
        db.update_coding_task(task_id, replan_count=reserved_replan_count,
                              replan_count_in_epoch=reserved_epoch_count)
    current=managed.get("plan") or {}
    current, current_mode_changes = ensure_explicit_phase_execution_modes(current)
    if current_mode_changes:
        print(f"TASK_ID={task_id} EXISTING_PLAN_PHASE_EXECUTION_MODE_NORMALIZED=YES CHANGES={json.dumps(current_mode_changes, ensure_ascii=False)}",
              file=__import__('sys').stderr, flush=True)
    continuation_policy = (managed.get("requirements") or {}).get("execution_policy") or {}
    reports=[r["structured_report"] for r in db.coding_phase_reports(task_id)]
    unfinished=[phase for phase in current.get("phases",[]) if phase.get("id") not in completed_ids]
    failure_history=[_bounded_review_context(report) for report in reports[-4:] if report.get("manager_decision")]
    structural_reason = bool(diagnosis and (
        diagnosis.get("unmet_done") or diagnosis.get("unmet_verify") or
        diagnosis.get("replan_instruction_source") == "model" or
        diagnosis.get("replan_reason_source") == "model"))
    structural_reason = structural_reason or any(term in reason.lower() for term in (
        "structur", "verification criteria", "verify criteria", "unobservable", "unsatisfiable"))
    failing_phase_id = unfinished[0].get("id") if unfinished else None
    compact_plan = _bounded_replan_plan_context(current, completed_ids, failing_phase_id)
    original_plan_chars = len(json.dumps(current, ensure_ascii=False))
    compact_plan_chars = len(json.dumps(compact_plan, ensure_ascii=False))
    replan_payload = {
        "original_goal": managed["original_goal"],
        "current_plan": compact_plan,
        "current_plan_revision": int(managed.get("plan_revision") or 0),
        "failing_phase_id": failing_phase_id,
        "completed_phase_ids": sorted(completed_ids),
        "failure_history": failure_history,
        "reason": reason[:1200],
        "approved_scopes": managed.get("approved_scopes", []),
        "replan_count": managed.get("replan_count", 0),
    }
    prompt=("Return a replacement read-only coding plan JSON. Preserve original goal, approved scope, completed phase IDs "
            "and accepted implementation results. The approved file scope is immutable: do not add paths to scope.allowed, do not "
            "turn read-only evidence targets into mutation targets, and treat files outside the approved scope as read-only. "
            "Preserve the existing module loading strategy, public API and consumer contracts; do not introduce unrelated module-format changes or new architecture to repair an observed failure. "
            "Separate an observed typed operation failure from a criterion that was not requested or not executed. "
            "Use the exact failing operation and current source evidence to choose a repair; do not redesign work merely because an optional check did not run. "
            "Redesign only unfinished work. Use the bounded failure history and unmet criteria to "
            "make the next phase materially actionable; do not repeat an ineffective phase structure. "
            + json.dumps(replan_payload, ensure_ascii=False))
    print(f"TASK_ID={task_id} REPLAN_PLAN_CONTEXT_COMPACTED=YES "
          f"ORIGINAL_PLAN_CHARS={original_plan_chars} COMPACT_PLAN_CHARS={compact_plan_chars} "
          f"COMPACT_PHASE_COUNT={len(compact_plan['phases'])} "
          f"COMPACT_MANIFEST_COUNT={len(compact_plan['file_manifest'])}",
          file=__import__('sys').stderr, flush=True)
    if verification_requested:
        prompt += "\nThe user explicitly requested verification. Preserve only those checks and use their observed results when repairing the implementation."
    else:
        prompt += "\nNo verification was requested. Keep verify:[] and do not create test/build/browser acceptance phases during this replan."
    if continuation_policy.get("task_size") == "LARGE":
        verification_continuation = ("Keep explicitly requested checks in the smallest coherent phase. "
                                     if verification_requested else
                                     "Do not add verification-only phases or routine checks. ")
        prompt += ("\nPreserve the completed orchestrator blueprint. Keep unfinished work in coherent implementation deliverables. "
                   + verification_continuation + "Continuation policy: " + json.dumps(continuation_policy))
    print(f"TASK_ID={task_id} REPLAN_FAILURE_CONTEXT_PRESENT={'true' if failure_history else 'false'} "
          f"REPLAN_BOUNDED_FAILURE_COUNT={len(failure_history)} REPLAN_CONTEXT_FINGERPRINT={_context_fingerprint({'revision': managed.get('plan_revision',0), 'completed': sorted(completed_ids), 'history': failure_history, 'reason': reason[:500]})}",
          file=__import__('sys').stderr,flush=True)
    if deterministic_fallback is not None:
        plan = deterministic_fallback
        print(f"TASK_ID={task_id} DETERMINISTIC_VERIFIER_REPLAN=PASS "
              "SOURCE=EXPLICIT_USER_REVISION SCOPE_PRESERVED=YES MODEL_CALLS_ADDED=0",
              file=__import__('sys').stderr, flush=True)
    else:
        revision_requirements = dict(managed.get('requirements') or {})
        if user_revision:
            revision_requirements['_explicit_instruction_revision'] = True
            if verification_requested:
                revision_requirements['_explicit_verification_request_revision'] = True
            prompt += ('\nThis is a newly received user correction/addition, not an automatic failure retry. '
                       'Prioritize the current instruction with minimal edits and relevant verification. '
                       'Keep completed work and do not expand a small correction into rebuilding the product. '
                       'If an existing file was created in a passed phase, you may add a small amendment phase '
                       'to update that file; retain the historical completed phase and verify the affected behavior. '
                       'The file/phase structure may remain unchanged when only the instruction changes behavior.\n')
        else:
            replan_phase_limit = max(1, min(len(unfinished), 8))
            revision_requirements['_replan_phase_limit'] = replan_phase_limit
            revision_requirements['_preserve_completed_phase_ids'] = sorted(completed_ids)
            prompt += (f'\nAUTOMATIC_RECOVERY_PHASE_LIMIT={replan_phase_limit}. Return only the replacement phases '
                       'for existing unfinished phase IDs. Do not repeat completed phases, split existing work into '
                       'additional phases, or add new phases; the host restores completed verified phases.\n')
        # Persist the recovery stage before entering provider code. If the
        # model or its transport fails immediately, the scheduler can resume
        # the saved replan action without guessing from a stale phase status.
        db.update_coding_task(task_id, status="RUNNING", activity="QWEN_REPLANNING",
                              recovery_action="REPLAN_CONTINUATION", recovery_reason="REPLAN_LIMIT")
        plan,_=_generate_plan(task_id,managed["original_goal"],prompt,"QWEN_REPLANNING",
                              requirements=revision_requirements, recovery=True)
    if not plan and int((db.coding_task(task_id) or {}).get("task_total_recovery_model_calls") or 0) >= TASK_GLOBAL_RECOVERY_MODEL_CALL_LIMIT:
        plan = _deterministic_verifier_recovery_plan(managed, reason)
        if plan:
            print(f"TASK_ID={task_id} DETERMINISTIC_VERIFIER_REPLAN=PASS "
                  "SOURCE=EXPLICIT_USER_REVISION SCOPE_PRESERVED=YES MODEL_CALLS_ADDED=0",
                  file=__import__('sys').stderr, flush=True)
    if not plan:
        _transition_resumable(task_id,"REPLAN_VALIDATION","RECOVERABLE_INTERNAL","REPLAN_CONTINUATION")
        return "Coding Task replan could not be validated."
    plan, checkpoint_changes = enforce_explicit_phase_failure_checkpoint(
        plan, managed.get("original_goal", ""))
    if checkpoint_changes:
        print(f"REPLAN_CHECKPOINT_POLICY_NORMALIZED=YES CHANGES={json.dumps(checkpoint_changes, ensure_ascii=False)}",
              file=__import__('sys').stderr, flush=True)
    if not user_revision:
        # A replan response may repeat the persisted plan so the host can
        # compare completed-phase contracts. Count genuinely new phase IDs,
        # rather than all returned phases: otherwise a full plan with a
        # completed prefix is rejected before the preservation check runs.
        plan, phase_id_changes = normalize_replanned_phase_ids(plan, current, completed_ids)
        if phase_id_changes:
            print(f"REPLAN_PHASE_IDENTITY_PRESERVED=YES CHANGES={json.dumps(phase_id_changes, ensure_ascii=False)}",
                  file=__import__('sys').stderr, flush=True)
        existing_phase_ids = {str(phase.get('id')) for phase in current.get('phases') or []}
        proposed_phase_ids = {str(phase.get('id')) for phase in plan.get('phases') or []}
        added_phase_ids = proposed_phase_ids - existing_phase_ids
        proposed_unfinished_ids = {
            str(phase.get('id')) for phase in plan.get('phases') or []
            if str(phase.get('id')) not in completed_ids
        }
        exceeds_phase_limit = (bool(added_phase_ids)
                               or len(proposed_unfinished_ids) > max(1, len(unfinished)))
    else:
        added_phase_ids = set()
        exceeds_phase_limit = False
    if exceeds_phase_limit:
        # Structured schemas are a generation aid, not an authorization
        # boundary. Reject a recovery plan that expands the phase graph even
        # when the model provider ignored phases.maxItems.
        _transition_resumable(task_id,"REPLAN_PHASE_LIMIT","RECOVERABLE_INTERNAL","REPLAN_CONTINUATION")
        print(f"TASK_ID={task_id} AUTOMATIC_REPLAN_PHASE_LIMIT=FAIL "
              f"UNFINISHED_PHASE_COUNT={len(unfinished)} PROPOSED_PHASE_COUNT={len(plan.get('phases') or [])} "
              f"ADDED_PHASE_IDS={json.dumps(sorted(added_phase_ids))} "
              "PLAN_PERSISTED=NO", file=__import__('sys').stderr, flush=True)
        return "Coding Task replan exceeded the remaining phase limit."
    conversation = db.conversation(managed.get("conversation_id", "")) or {}
    project = db.project(conversation.get("project_id", "")) or {}
    replan_root = task_workspaces.service.root_for(task_id, str(Path(project.get("workspace_path")).expanduser().resolve()) if project.get("workspace_path") else None)
    plan = _bind_scope_contract(plan, _workspace_scope_contract(replan_root))
    requirements_for_replan = managed.get("requirements") or {}
    plan, dependency_changes = associate_dependency_requirements(plan, requirements_for_replan)
    if dependency_changes:
        print(f"TASK_ID={task_id} DEPENDENCY_REQUIREMENT_PHASE_ASSOCIATION=PASS "
              f"CHANGES={json.dumps(dependency_changes, ensure_ascii=False)}",
              file=__import__('sys').stderr, flush=True)
    plan=_retain_completed_replan_phases(plan,current,completed_ids)
    if verification_requested:
        plan=inherit_owned_verification(plan,current)
    else:
        plan, verification_changes = suppress_unrequested_verification(
            plan, preserve_phase_ids=completed_ids if not user_revision else None)
        if verification_changes:
            print(f"TASK_ID={task_id} REPLAN_UNREQUESTED_VERIFICATION_REMOVED=YES CHANGES={json.dumps(verification_changes, ensure_ascii=False)}",
                  file=__import__('sys').stderr, flush=True)
    if continuation_policy.get("task_size") == "LARGE":
        from .continuation import phase_lifecycle_stages
        if any(len(phase_lifecycle_stages(p)) >= 4 for p in plan["phases"] if p["id"] not in completed_ids):
            _transition_resumable(task_id,"REPLAN_PHASE_COMPLEXITY","RECOVERABLE_INTERNAL","REPLAN_CONTINUATION")
            return "Coding Task replan still combines too many lifecycle stages."
        plan["blueprint"] = current.get("blueprint", {})
        for previous in current.get("phases", []):
            if previous.get("kind") != "ORCHESTRATOR_BLUEPRINT":
                continue
            proposed_blueprint = next((p for p in plan["phases"] if p["id"] == previous["id"]), None)
            if not proposed_blueprint or _phase_signature(proposed_blueprint) != _phase_signature(previous):
                _transition_resumable(task_id,"REPLAN_BLUEPRINT_CHANGED","RECOVERABLE_INTERNAL","REPLAN_CONTINUATION")
                return "Coding Task replan must preserve its completed planning artifact."
            proposed_blueprint["kind"] = "ORCHESTRATOR_BLUEPRINT"
    # A replan may only redesign unfinished work.  Persisted manager-approved
    # reports are the authority for completed phases, so do not let a model
    # silently omit or reopen one of them.
    old_signatures={phase.get("id"):_phase_signature(phase) for phase in current.get("phases",[])}
    new_signatures={phase.get("id"):_phase_signature(phase) for phase in plan.get("phases",[]) if phase.get("id") in old_signatures}
    # A completed phase may remain PASS only when its acceptance contract is
    # unchanged.  Revisions that alter a completed phase revalidate that phase
    # alone rather than resetting the whole task.
    invalidated_completed={phase_id for phase_id in completed_ids
                           if new_signatures.get(phase_id) != old_signatures.get(phase_id)}
    proposed={phase.get("id"):phase for phase in plan.get("phases",[])}
    # Unchanged completed phases must remain PASS.  A phase whose acceptance
    # contract changed is the sole exception: it is explicitly invalidated
    # below and will be revalidated without resetting unrelated completed work.
    if any(phase_id not in proposed or
           (proposed[phase_id].get("status") != "pass" and phase_id not in invalidated_completed)
           for phase_id in completed_ids):
        _transition_resumable(task_id,"REPLAN_VALIDATION","RECOVERABLE_INTERNAL","REPLAN_CONTINUATION")
        return "Coding Task replan did not preserve completed phases."
    for phase_id in invalidated_completed:
        if phase_id in proposed:
            proposed[phase_id]["status"]="pending"
    completed_ids=set(completed_ids)-invalidated_completed
    changed=[phase_id for phase_id,signature in old_signatures.items()
             if new_signatures.get(phase_id) != signature]
    structure_changed=set(old_signatures) != set(new_signatures) or bool(changed)
    failing_phase_id=unfinished[0].get("id") if unfinished else ""
    print(f"TASK_ID={task_id} REPLAN_OLD_REVISION={int(managed.get('plan_revision') or 0)} "
          f"REPLAN_NEW_REVISION={int(managed.get('plan_revision') or 0)+1} "
          f"OLD_PLAN_REVISION={int(managed.get('plan_revision') or 0)} NEW_PLAN_REVISION={int(managed.get('plan_revision') or 0)+1} "
          f"OLD_PHASE_SIGNATURE={old_signatures.get(failing_phase_id,'')} NEW_PHASE_SIGNATURE={new_signatures.get(failing_phase_id,'')} "
          f"REPLAN_OLD_PHASE_SIGNATURES={json.dumps(old_signatures,sort_keys=True)} "
          f"REPLAN_NEW_PHASE_SIGNATURES={json.dumps(new_signatures,sort_keys=True)} "
          f"FAILING_PHASE_CHANGED={'true' if structure_changed else 'false'} REPLAN_EFFECTIVE={'true' if structure_changed else 'false'}",
          file=__import__('sys').stderr,flush=True)
    if not structure_changed and (not user_revision or not unfinished):
        unmet = []
        if diagnosis:
            unmet.extend(diagnosis.get("unmet_done") or [])
            unmet.extend(diagnosis.get("unmet_verify") or [])
        pending = {"type":"REPLAN_INEFFECTIVE", "reason":"Phase replan did not change the failing phase structure.", "unmet_criteria": unmet[:8], "state":"PENDING"}
        # An unchanged replacement cannot make the failing phase complete.
        # Keep its cursor and wait for a materially different user/model
        # decision instead of treating the replan call itself as progress.
        db.update_coding_task(task_id,status="WAITING_FOR_USER",activity="NONE",queue_order=None,
                              current_phase_id=failing_phase_id or None,
                              pending_authorization=pending,pending_user_confirmation=1,
                              recovery_action="NONE",recovery_reason="REPLAN_INEFFECTIVE")
        print(f"TASK_ID={task_id} PHASE_ID_BEFORE={failing_phase_id or 'UNKNOWN'} PHASE_COMPLETE=false "
              "REPLAN_EFFECTIVE=false PHASE_CURSOR_ADVANCED=false "
              "PHASE_ADVANCE_REASON=INEFFECTIVE_REPLAN "
              f"PHASE_ID_AFTER={failing_phase_id or 'UNKNOWN'} "
              "FAILURE_STAGE=REPLAN_INEFFECTIVE NEXT_TASK_ACTION=WAITING_FOR_USER",
              file=__import__('sys').stderr,flush=True)
        return _record_coding_stop(task_id, "REPLAN_INEFFECTIVE", False)
    expansion=_scope_expansion(current,plan)
    count = (int(managed.get("replan_count") or 0) if deterministic_fallback is not None
             else reserved_replan_count)
    epoch_count = (replan_count_in_epoch if deterministic_fallback is not None
                   else reserved_epoch_count)
    if expansion and not full_access(settings):
        authorization={"requested_scope":expansion,"reason":reason,"source":"replan","state":"PENDING"}
        db.update_coding_task(task_id,status="WAITING_FOR_USER",activity="SCOPE_AUTHORIZATION",pending_plan=plan,pending_authorization=authorization,pending_user_confirmation=1,replan_count=count,replan_count_in_epoch=epoch_count)
        return "Coding Task requires authorization for the proposed scope expansion."
    # Automatic replans may return only the changed phase's file list even
    # though file_manifest is a task-wide authorization contract.  Retain all
    # previously approved entries and merge explicit additions from the new
    # response; the normal scope and path gates below still validate additions.
    # Explicit user revisions may replace the manifest through the same gates.
    prior_artifact = current.get("implementation_plan_artifact") if isinstance(current, dict) else None
    if isinstance(prior_artifact, dict) and not user_revision:
        approved_manifest = prior_artifact.get("file_manifest")
        if not isinstance(approved_manifest, list) or not approved_manifest:
            approved_manifest = current.get("file_manifest") if isinstance(current.get("file_manifest"), list) else None
        if isinstance(approved_manifest, list) and approved_manifest:
            model_manifest = plan.get("file_manifest") if isinstance(plan.get("file_manifest"), list) else []
            merged_manifest = copy.deepcopy(approved_manifest)
            approved_by_path = {_manifest_path_identity(item): item for item in merged_manifest
                                if _manifest_path_identity(item)}
            prior_approved_paths = set(approved_by_path)
            model_by_path = {_manifest_path_identity(item): item for item in model_manifest
                             if _manifest_path_identity(item)}
            for path, item in model_by_path.items():
                if path not in approved_by_path:
                    candidate = copy.deepcopy(item)
                    merged_manifest.append(candidate)
                    approved_by_path[path] = candidate
            phase_by_id = {str(phase.get("id") or ""): phase for phase in plan.get("phases") or []
                           if isinstance(phase, dict) and phase.get("id")}
            mutation_phase_ids = [phase_id for phase_id, phase in phase_by_id.items()
                                  if phase.get("kind") != "ORCHESTRATOR_BLUEPRINT"
                                  and phase.get("execution_mode") != "VERIFICATION_ONLY"]
            fallback_owner = mutation_phase_ids[0] if mutation_phase_ids else ""
            for path, item in approved_by_path.items():
                model_item = model_by_path.get(path)
                model_owner = str((model_item or {}).get("owner_phase") or "")
                prior_owner = str(item.get("owner_phase") or "") if isinstance(item, dict) else ""
                if isinstance(item, dict) and model_owner in mutation_phase_ids:
                    item["owner_phase"] = model_owner
                elif isinstance(item, dict) and prior_owner and prior_owner not in phase_by_id and fallback_owner:
                    item["owner_phase"] = fallback_owner
            model_paths = set(model_by_path)
            model_only_paths = sorted(model_paths - prior_approved_paths)
            plan = {**plan, "file_manifest": merged_manifest}
            plan["implementation_plan_artifact"] = {
                **prior_artifact, "plan_revision": int(managed.get("plan_revision") or 0) + 1}
            print(f"TASK_ID={task_id} REPLAN_APPROVED_MANIFEST_RETAINED=YES "
                  f"APPROVED_PATH_COUNT={len(prior_approved_paths)} MODEL_PATH_COUNT={len(model_paths)} "
                  f"MODEL_ONLY_PATHS_ADDED={json.dumps(model_only_paths, ensure_ascii=False)} "
                  f"APPROVED_PATHS_OMITTED_BY_MODEL={json.dumps(sorted(prior_approved_paths - model_paths), ensure_ascii=False)}",
                  file=__import__('sys').stderr, flush=True)
    if isinstance(prior_artifact, dict) and "file_manifest" not in plan:
        plan["file_manifest"] = list(prior_artifact.get("file_manifest") or [])
        plan["implementation_plan_artifact"] = {**prior_artifact, "plan_revision": int(managed.get("plan_revision") or 0) + 1}
    elif isinstance(prior_artifact, dict) and isinstance(plan.get("file_manifest"), list):
        try:
            repair_workspace = workspace_state(prior_artifact.get("target_root"))
            repair_requirements = managed.get("requirements") or {}
            repair_workspace["new_project_intent"] = bool(
                repair_requirements.get("new_project_intent") and
                repair_workspace.get("project_state") != "ESTABLISHED" and
                repair_requirements.get("task_profile") in {"FRONTEND_ONLY_MARKETING_SITE", "GENERAL_CODING"})
            repair_workspace["workspace_state"] = repair_workspace.get("project_state", "UNKNOWN")
            repair_workspace["host_workspace_authorized"] = bool(valid_workspace(prior_artifact.get("target_root")))
            repair_workspace["host_authorized_root"] = str(Path(prior_artifact.get("target_root")).expanduser().resolve()) if repair_workspace["host_workspace_authorized"] else None
            provenance = _current_task_file_provenance(
                task_id, prior_artifact, reports, prior_artifact.get("target_root"))
            repair_workspace["replan_reconciliation"] = True
            repair_workspace["current_task_provenance"] = provenance
            repair_workspace["current_task_created_paths"] = sorted(
                path for path, kind in provenance.items()
                if kind in {"CREATED_BY_CURRENT_TASK_SCAFFOLD", "CREATED_BY_CURRENT_TASK_IMPLEMENTATION"})
            print(f"TASK_ID={task_id} WORKTREE_PROVENANCE_TRACKING=YES "
                  f"CURRENT_TASK_CREATED_PATHS={json.dumps(repair_workspace['current_task_created_paths'], ensure_ascii=False)}",
                  file=__import__('sys').stderr, flush=True)
            plan, replacement_artifact = _prepare_task_implementation_plan(
                task_id, plan, prior_artifact.get("target_root"),
                {**repair_requirements, "requirements_hash": _context_fingerprint(repair_requirements)},
                repair_workspace)
            replacement_artifact["plan_revision"] = int(managed.get("plan_revision") or 0) + 1
            plan["implementation_plan_artifact"] = replacement_artifact
            print(f"TASK_ID={task_id} IMPLEMENTATION_PLAN_REVISED=YES IMPLEMENTATION_PLAN_LOCATION=task_state:coding_tasks.plan_json FILE_MANIFEST_COUNT={replacement_artifact['file_manifest_count']}", file=__import__('sys').stderr, flush=True)
        except (OSError, TypeError, ValueError, PermissionError) as exc:
            diagnostics = getattr(exc, "diagnostics", []) or []
            if isinstance(exc, PlanStackConformanceError):
                stack_details = getattr(exc, "diagnostics", {}) or {}
                print(f"TASK_ID={task_id} PLAN_STACK_CONFORMANCE=FAIL "
                      f"EXPECTED_STACK={json.dumps(stack_details.get('expected_stack') or [], ensure_ascii=False)} "
                      f"OBSERVED_STACK_SIGNALS={json.dumps(stack_details.get('observed_stack_signals') or [], ensure_ascii=False)} "
                      f"STACK_CONFLICTS={json.dumps(stack_details.get('stack_conflicts') or [], ensure_ascii=False)} "
                      "PLAN_MANIFEST_COVERAGE=NOT_RUN PLAN_PATH_VALIDATION=NOT_RUN IMPLEMENTATION_STARTED=NO",
                      file=__import__('sys').stderr, flush=True)
                _transition_resumable(task_id, "PLAN_STACK_CONFORMANCE", "RECOVERABLE_INTERNAL", "REPLAN_CONTINUATION", exc,
                                      "PLAN_STACK_CONFORMANCE")
                return stack_conformance_message(stack_details)
            if diagnostics:
                pending_plan = dict(plan)
                pending_plan["path_validation_diagnostics"] = diagnostics[:16]
                db.update_coding_task(task_id, pending_plan=pending_plan)
            first_diagnostic = diagnostics[0] if diagnostics else {}
            coverage_failure = isinstance(exc, PlanManifestCoverageError)
            repair_progress: dict[str, Any] = {}
            if coverage_failure:
                before_coverage = (prior_artifact.get("manifest_coverage")
                                    if isinstance(prior_artifact, dict) else None)
                if not isinstance(before_coverage, dict):
                    before_coverage = manifest_coverage(
                        {**current, "file_manifest": list((prior_artifact or {}).get("file_manifest") or [])},
                        {**repair_requirements, "requirements_hash": _context_fingerprint(repair_requirements)},
                        repair_workspace)
                candidate_coverage = manifest_coverage(
                    plan, {**repair_requirements, "requirements_hash": _context_fingerprint(repair_requirements)},
                    repair_workspace)
                repair_progress = manifest_repair_progress(before_coverage, candidate_coverage)
                print(f"TASK_ID={task_id} MANIFEST_REPAIR_CLASSIFICATION={repair_progress['classification']} "
                      f"MISSING_ARTIFACTS_BEFORE={json.dumps(repair_progress['missing_artifacts_before'], ensure_ascii=False)} "
                      f"MISSING_ARTIFACTS_AFTER={json.dumps(repair_progress['missing_artifacts_after'], ensure_ascii=False)}",
                      file=__import__('sys').stderr, flush=True)
            if coverage_failure:
                print(" ".join([
                    f"TASK_ID={task_id}", "PLAN_MANIFEST_COVERAGE=FAIL", "PLAN_PATH_VALIDATION=NOT_RUN",
                    f"MISSING_PLANNED_ARTIFACTS={json.dumps(exc.missing, ensure_ascii=False)}",
                    "SCAFFOLD_STARTED=NO", "IMPLEMENTATION_STARTED=NO",
                ]), file=__import__('sys').stderr, flush=True)
            else:
                print(" ".join([
                    f"TASK_ID={task_id}", "PLAN_PATH_VALIDATION=FAIL",
                    f"OFFENDING_PLAN_PATH={first_diagnostic.get('offending_plan_path', 'UNKNOWN')}",
                    f"OFFENDING_PLAN_FIELD={first_diagnostic.get('offending_plan_field', 'UNKNOWN')}",
                    f"OFFENDING_PHASE={first_diagnostic.get('offending_phase', 'UNKNOWN')}",
                    f"PATH_VALIDATION_REASON={first_diagnostic.get('path_validation_reason', str(exc))}",
                    "IMPLEMENTATION_STARTED=NO",
                ]), file=__import__('sys').stderr, flush=True)
            no_progress = coverage_failure and repair_progress.get("classification") == "REPAIR_NO_CHANGE"
            recovery_reason = ("PLAN_MANIFEST_REPAIR_NO_PROGRESS" if no_progress else
                               "PLAN_MANIFEST_COVERAGE" if coverage_failure else "PLAN_PATH_VALIDATION")
            if no_progress:
                print(f"TASK_ID={task_id} MANIFEST_REPAIR_NO_PROGRESS=YES "
                      f"MISSING_ARTIFACTS_BEFORE={json.dumps(repair_progress['missing_artifacts_before'], ensure_ascii=False)} "
                      f"MISSING_ARTIFACTS_AFTER={json.dumps(repair_progress['missing_artifacts_after'], ensure_ascii=False)} "
                      "IMPLEMENTATION_STARTED=NO SCAFFOLD_STARTED=NO",
                      file=__import__('sys').stderr, flush=True)
            if coverage_failure:
                unmet = [f"承認済みmanifestでカバーできない成果物: {path}" for path in exc.missing[:8]]
                pending = {"type": "REPLAN_INEFFECTIVE", "state": "PENDING",
                           "reason": "Automatic replanning could not validate the complete approved file manifest.",
                           "unmet_criteria": unmet}
                db.update_coding_task(
                    task_id, status="WAITING_FOR_USER", activity="NONE", queue_order=None,
                    current_phase_id=failing_phase_id or current.get("current_phase_id"),
                    pending_authorization=pending, pending_user_confirmation=1,
                    recovery_action="NONE", recovery_reason="REPLAN_INEFFECTIVE")
                _record_coding_stop(task_id, "REPLAN_INEFFECTIVE", False)
                print(f"TASK_ID={task_id} REPLAN_MANIFEST_COVERAGE=WAITING_FOR_USER "
                      f"AUTO_REPLAN_REPEAT=NO MISSING_PLANNED_ARTIFACTS={json.dumps(exc.missing, ensure_ascii=False)}",
                      file=__import__('sys').stderr, flush=True)
            else:
                _transition_resumable(task_id, "IMPLEMENTATION_PREPARE", "RECOVERABLE_INTERNAL", "REPLAN_CONTINUATION", exc,
                                      recovery_reason)
            if no_progress:
                return manifest_repair_no_progress_message()
            if coverage_failure:
                return manifest_coverage_message(replan=False) + (
                    " 不足している成果物: " + ", ".join(exc.missing[:8]) if exc.missing else "")
            code = first_diagnostic.get("path_validation_code") or path_validation_code(first_diagnostic.get("path_validation_reason") or str(exc))
            return path_validation_message(code, replan=False)
    next_phase=next((phase for phase in plan.get("phases",[])
                     if phase.get("id") not in completed_ids
                     and all(dep in completed_ids for dep in phase.get("dependencies",[]))), None)
    phase_cursor_advanced = bool(failing_phase_id and next_phase and next_phase.get("id") != failing_phase_id)
    print(f"TASK_ID={task_id} PHASE_ID_BEFORE={failing_phase_id or 'UNKNOWN'} "
          f"PHASE_COMPLETE={'true' if failing_phase_id in completed_ids else 'false'} "
          f"REPLAN_EFFECTIVE={'true' if structure_changed else 'false'} "
          f"PHASE_CURSOR_ADVANCED={'true' if phase_cursor_advanced else 'false'} "
          f"PHASE_ADVANCE_REASON={'VALID_REPLACEMENT' if phase_cursor_advanced else 'REPLAN_CONTINUATION'} "
          f"PHASE_ID_AFTER={next_phase.get('id') if next_phase else 'NONE'}",
          file=__import__('sys').stderr,flush=True)
    superseded_revision = isinstance(managed.get("pending_authorization"), dict) and managed["pending_authorization"].get("type") == "REPLAN_INEFFECTIVE"
    db.update_coding_task(task_id,plan=plan,plan_revision=int(managed.get("plan_revision") or 0)+1,replan_count=count,replan_count_in_epoch=epoch_count,
                          current_phase_id=next_phase.get("id") if next_phase else None,
                          retry_count=0,recovery_action="NONE",recovery_reason="NONE",
                          pending_authorization=None if superseded_revision else managed.get("pending_authorization"),
                          pending_user_confirmation=0 if superseded_revision else managed.get("pending_user_confirmation", 0))
    _initialize_subtask_progress(task_id,plan,preserve=True,completed_phase_ids=completed_ids)
    db.enqueue_coding_task(task_id,clear_pause=False)
    if _pause_at_checkpoint(task_id):
        return 'Task paused after replanning.'
    return "Coding Task was replanned and requeued."

def _finalization_log(task_id: str, *, final_phase_id: str | None, all_phases_pass: bool,
                     completion_check_started: bool, completion_check_raw_decision: str,
                     completion_check_valid: bool, final_report_started: bool,
                     final_report_valid: bool, final_report_persisted: bool,
                     status_before: str, status_after: str, failure_stage: str = "NONE",
                     exception_type: str = "NONE") -> None:
    """Emit bounded finalization diagnostics without logging report bodies."""
    fields=(f"TASK_ID={task_id}", f"FINAL_PHASE_ID={final_phase_id or 'NONE'}",
            f"ALL_PHASES_PASS={'true' if all_phases_pass else 'false'}",
            f"COMPLETION_CHECK_STARTED={'true' if completion_check_started else 'false'}",
            f"COMPLETION_CHECK_RAW_DECISION={completion_check_raw_decision[:80] or 'NONE'}",
            f"COMPLETION_CHECK_VALID={'true' if completion_check_valid else 'false'}",
            f"FINAL_REPORT_STARTED={'true' if final_report_started else 'false'}",
            f"FINAL_REPORT_VALID={'true' if final_report_valid else 'false'}",
            f"FINAL_REPORT_PERSISTED={'true' if final_report_persisted else 'false'}",
            f"TASK_STATUS_BEFORE_COMPLETION={status_before}", f"TASK_STATUS_AFTER_COMPLETION={status_after}",
            f"FINALIZATION_FAILURE_STAGE={failure_stage}", f"FINALIZATION_EXCEPTION_TYPE={exception_type}")
    print(" ".join(fields), file=__import__('sys').stderr, flush=True)


def _report_plan_revision(report: dict) -> int:
    """Read a report revision defensively; legacy reports belong to revision 0."""
    try:
        return int(report.get("plan_revision", 0) or 0)
    except (TypeError, ValueError):
        return 0


def _report_recovery_epoch(report: dict) -> int:
    """Read the execution epoch defensively; legacy reports belong to epoch 0."""
    try:
        return int(report.get("recovery_epoch", 0) or 0)
    except (TypeError, ValueError):
        return 0


def _report_has_execution_attempt(report: dict) -> bool:
    """Return whether a report carries completed Implementer execution evidence."""
    if "execution_attempt_started" in report:
        return bool(report.get("execution_attempt_started"))
    # Reports written before provenance fields existed are still valid history.
    # Their persisted phase attempt/decision is the legacy execution marker;
    # the phase report itself is created only after the executor returns.
    return "attempt" in report and (
        isinstance(report.get("typed_execution_summary"), dict)
        or "status" in report
        or isinstance(report.get("manager_decision"), dict)
    )


def _phase_reports_for_epoch(task_id: str, phase_id: str, revision: int,
                            recovery_epoch: int) -> list[dict]:
    """Return only active-epoch execution reports for scheduler control flow."""
    return [row for row in db.coding_phase_reports(task_id)
            if row.get("phase_id") == phase_id
            and row.get("validation_status") == "PASS"
            and _report_plan_revision(row.get("structured_report") or {}) == revision
            and _report_recovery_epoch(row.get("structured_report") or {}) == recovery_epoch
            and _report_has_execution_attempt(row.get("structured_report") or {})]


def _latest_current_phase_report(task_id: str, phase_id: str, revision: int) -> dict | None:
    """Return the latest report for a phase in this plan revision only."""
    rows=[row for row in db.coding_phase_reports(task_id)
          if row.get("phase_id") == phase_id and _report_plan_revision(row["structured_report"]) == revision]
    if not rows:
        return None
    latest=rows[-1]
    if latest.get("validation_status") != "PASS":
        return None
    if latest["structured_report"].get("manager_decision",{}).get("decision") != "PASS":
        return None
    return latest


def _prior_saved_phase_reports(task_id: str, current: dict) -> list[dict]:
    """Use the same chronological phase evidence at review and completion."""
    result = []
    revision = _report_plan_revision(current.get('structured_report') or {})
    for row in db.coding_phase_reports(task_id):
        if row.get('id') == current.get('id'):
            break
        if (row.get('phase_id') == current.get('phase_id') and row.get('validation_status') == 'PASS'
                and _report_plan_revision(row.get('structured_report') or {}) == revision):
            result.append(row['structured_report'])
    return result


def _saved_phase_pass_is_current(task_id: str, phase: dict, row: dict, workspace_root: str | None) -> bool:
    """Recheck owned artifact/verification facts without rerunning blueprints."""
    if phase.get('kind') == 'ORCHESTRATOR_BLUEPRINT':
        return True
    report = row['structured_report']
    prior = _prior_saved_phase_reports(task_id,row)
    artifact_gate = (phase.get('verify') == ['Typed workspace writes and read-back succeed for the changed files.']
                     and phase.get('done') and all(re.fullmatch(r'.+ exists',str(item)) for item in phase['done']))
    if phase.get('host_verification') or artifact_gate:
        return evaluate_phase(phase,report,prior,workspace_root=workspace_root)['phase_complete']
    if workspace_root:
        root = Path(workspace_root)
        for item in [*prior,report]:
            if (item.get('typed_execution_summary') or {}).get('worktree_state') == 'ROLLED_BACK':
                continue
            for operation in (item.get('typed_execution_summary') or {}).get('operations') or []:
                output = operation.get('output') or {}
                if (operation.get('tool') in {'workspace_write','workspace_patch'}
                        and operation.get('status') == 'success' and output.get('post_apply_hash') and output.get('path')):
                    supplied = Path(output['path'])
                    if not (supplied if supplied.is_absolute() else root / supplied).is_file():
                        return False
    return True


def _phase_passed_in_epoch(task_id: str, phase: dict, revision: int, recovery_epoch: int,
                           workspace_root: str | None = None) -> bool:
    """Ignore stale/non-PASS retry reports when deciding whether to skip a phase."""
    phase_id = str(phase.get("id") or "")
    reports = _phase_reports_for_epoch(task_id, phase_id, revision, recovery_epoch)
    if reports:
        latest_decision = (reports[-1].get("structured_report") or {}).get("manager_decision") or {}
        if latest_decision.get("decision") in {"RETRY", "BLOCKED", "REPLAN_REQUIRED"}:
            return False
        if latest_decision.get("decision") == "PASS":
            return _saved_phase_pass_is_current(task_id,phase,reports[-1],workspace_root)
    if phase.get('status') != 'pass' or phase.get('host_verification'):
        return False
    if phase.get('execution_mode') is None:
        return True  # preserve legacy plans without a typed execution contract
    inherited = (_latest_current_phase_report(task_id,phase_id,revision)
                 or _latest_completed_phase_report(task_id,phase_id))
    return bool(inherited and _saved_phase_pass_is_current(task_id,phase,inherited,workspace_root))


def _latest_completed_phase_report(task_id: str, phase_id: str) -> dict | None:
    """Return the latest validated PASS report across plan revisions."""
    rows=[row for row in db.coding_phase_reports(task_id)
          if row.get("phase_id") == phase_id and row.get("validation_status") == "PASS"
          and row.get("structured_report", {}).get("manager_decision", {}).get("decision") == "PASS"]
    return rows[-1] if rows else None


def _phase_package_install_satisfied(task_id: str, phase_id: str, plan_revision: int) -> bool:
    """Return true only for persisted successful PACKAGE_INSTALL evidence."""
    for row in db.coding_phase_reports(task_id):
        if row.get("phase_id") != phase_id or row.get("validation_status") != "PASS":
            continue
        report = row.get("structured_report") if isinstance(row.get("structured_report"), dict) else {}
        if _report_plan_revision(report) != int(plan_revision):
            continue
        typed = report.get("typed_execution_summary") if isinstance(report.get("typed_execution_summary"), dict) else {}
        for operation in typed.get("operations") or []:
            if not isinstance(operation, dict) or operation.get("tool") != "package_install":
                continue
            output = operation.get("output") if isinstance(operation.get("output"), dict) else {}
            if (str(operation.get("status") or "").lower() in {"success", "completed", "ok"}
                    and output.get("exit_code") == 0
                    and output.get("process_started") is True):
                return True
    return False


def _phase_package_install_evidence(task_id: str, phase_id: str, plan_revision: int) -> list[dict]:
    """Return bounded successful install evidence for a file-operation retry."""
    evidence: list[dict] = []
    for row in db.coding_phase_reports(task_id):
        if row.get("phase_id") != phase_id or row.get("validation_status") != "PASS":
            continue
        report = row.get("structured_report") if isinstance(row.get("structured_report"), dict) else {}
        if _report_plan_revision(report) != int(plan_revision):
            continue
        typed = report.get("typed_execution_summary") if isinstance(report.get("typed_execution_summary"), dict) else {}
        for item in typed.get("package_install_evidence") or []:
            if isinstance(item, dict) and str(item.get("status") or "").upper() == "PASS":
                evidence.append(dict(item))
    return evidence[-4:]


_RESUME_STATE_VERSION = 1
_PACKAGE_ARTIFACT_FILES = ("package.json", "package-lock.json", "npm-shrinkwrap.json",
                           "pnpm-lock.yaml", "yarn.lock")


def _package_artifact_snapshot(workspace_root: str | None) -> dict[str, dict]:
    """Read the small package-manager surface needed for resume validation."""
    snapshot: dict[str, dict] = {}
    if not workspace_root:
        return snapshot
    root = Path(workspace_root).expanduser().resolve()
    for name in _PACKAGE_ARTIFACT_FILES:
        path = root / name
        if not path.is_file():
            snapshot[name] = {"exists": False}
            continue
        try:
            raw = path.read_bytes()
            snapshot[name] = {"exists": True, "sha256": hashlib.sha256(raw).hexdigest(), "bytes": len(raw)}
        except OSError as exc:
            snapshot[name] = {"exists": True, "read_error": type(exc).__name__}
    node_modules = root / "node_modules"
    snapshot["node_modules"] = {"exists": node_modules.is_dir()}
    return snapshot


def _package_dependency_fingerprint(packages: list[str] | None) -> str:
    values = sorted(dict.fromkeys(str(item).strip() for item in (packages or []) if str(item).strip()))
    return hashlib.sha256(json.dumps(values, ensure_ascii=False, separators=(",", ":")).encode("utf-8")).hexdigest()


def _package_install_state_from_reports(task_id: str, phase_id: str, plan_revision: int) -> dict | None:
    """Reduce successful typed package operations to restart-safe evidence."""
    packages: list[str] = []
    package_manager: str | None = None
    package_json_after: dict | None = None
    lockfiles: dict[str, dict] = {}
    node_modules_exists: bool | None = None
    workspace_root: str | None = None
    attempts: list[int] = []
    for row in db.coding_phase_reports(task_id):
        if row.get("phase_id") != phase_id:
            continue
        report = row.get("structured_report") if isinstance(row.get("structured_report"), dict) else {}
        if _report_plan_revision(report) != int(plan_revision):
            continue
        typed = report.get("typed_execution_summary") if isinstance(report.get("typed_execution_summary"), dict) else {}
        for operation in typed.get("operations") or []:
            if not isinstance(operation, dict) or operation.get("tool") != "package_install":
                continue
            output = operation.get("output") if isinstance(operation.get("output"), dict) else {}
            if (str(operation.get("status") or "").lower() not in {"success", "completed", "ok"}
                    or output.get("exit_code") != 0 or output.get("process_started") is not True):
                continue
            attempts.append(int(row.get("attempt") or 0))
            package_manager = str(output.get("package_manager") or package_manager or "") or None
            workspace_root = str(output.get("workspace_root") or workspace_root or "") or None
            for item in output.get("packages_authorized") or output.get("packages_requested") or []:
                if str(item).strip() and str(item).strip() not in packages:
                    packages.append(str(item).strip())
            if isinstance(output.get("package_json_after"), dict):
                package_json_after = dict(output["package_json_after"])
            if isinstance(output.get("lockfile_after"), dict):
                for name, value in output["lockfile_after"].items():
                    if isinstance(value, dict):
                        lockfiles[str(name)] = dict(value)
        for operation in typed.get("operations") or []:
            if not isinstance(operation, dict) or operation.get("tool") != "workspace_refresh" or operation.get("status") != "success":
                continue
            output = operation.get("output") if isinstance(operation.get("output"), dict) else {}
            if isinstance(output.get("artifacts"), dict):
                for name, value in output["artifacts"].items():
                    if isinstance(value, dict) and name in _PACKAGE_ARTIFACT_FILES:
                        lockfiles[name] = dict(value) if name != "package.json" else lockfiles.get(name, dict(value))
            if isinstance(output.get("node_modules_exists"), bool):
                node_modules_exists = output["node_modules_exists"]
            workspace_root = str(output.get("workspace_root") or workspace_root or "") or workspace_root
    if not attempts or not packages:
        return None
    evidence = {
        "status": "PASS",
        "package_install_status": "PASS",
        "dependencies_satisfied": True,
        "owner": "PACKAGE_INSTALL",
        "package_json_owner": "PACKAGE_INSTALL",
        "package_manager": package_manager,
        "authorized_package_set": sorted(packages),
        "dependency_fingerprint": _package_dependency_fingerprint(packages),
        "package_json": package_json_after or {},
        "package_json_hash": (package_json_after or {}).get("sha256"),
        "lockfiles": lockfiles,
        "lockfile_hashes": {name: value.get("sha256") for name, value in lockfiles.items()
                            if isinstance(value, dict) and value.get("sha256")},
        "node_modules_exists": node_modules_exists,
        "exit_code": 0,
        "package_manager_exit_code": 0,
        "phase_id": phase_id,
        "plan_revision": int(plan_revision),
        "source": "TYPED_PACKAGE_INSTALL_REPORT",
        "attempts": sorted(set(attempts)),
    }
    if workspace_root:
        evidence["workspace_root"] = str(Path(workspace_root).expanduser().resolve())
    return evidence


def _resume_state_package_entry(task: dict, phase_id: str) -> dict | None:
    state = task.get("resume_state") if isinstance(task.get("resume_state"), dict) else {}
    entries = state.get("package_install_evidence") if isinstance(state.get("package_install_evidence"), dict) else {}
    entry = entries.get(phase_id)
    return dict(entry) if isinstance(entry, dict) else None


def _persist_resume_package_state(task_id: str, phase_id: str, plan_revision: int,
                                  evidence: dict, *, phase_cursor: str | None = None) -> dict:
    task = db.coding_task(task_id) or {}
    current = task.get("resume_state") if isinstance(task.get("resume_state"), dict) else {}
    entries = dict(current.get("package_install_evidence") or {}) if isinstance(current.get("package_install_evidence"), dict) else {}
    entries[phase_id] = {**evidence, "phase_id": phase_id, "plan_revision": int(plan_revision),
                         "resume_evidence_invalidated": bool(evidence.get("resume_evidence_invalidated", False)),
                         "resume_evidence_invalidation_reason": str(evidence.get("resume_evidence_invalidation_reason") or "NONE")}
    state = {**current, "version": _RESUME_STATE_VERSION, "package_install_evidence": entries,
             "phase_cursor": phase_cursor or task.get("current_phase_id"),
             "updated_at": time.time()}
    db.update_coding_task(task_id, resume_state=state)
    return state


def _reconcile_package_install_resume(task_id: str, phase: dict, plan_revision: int,
                                      workspace_root: str | None,
                                      dependency_records: list[dict] | None) -> tuple[bool, list[dict], dict | None]:
    """Validate persisted install facts against the current authorized workspace."""
    task = db.coding_task(task_id) or {}
    phase_id = str(phase.get("id") or "")
    state = _resume_state_package_entry(task, phase_id)
    if state is None:
        state = _package_install_state_from_reports(task_id, phase_id, plan_revision)
        if state is not None:
            _persist_resume_package_state(task_id, phase_id, plan_revision, state,
                                          phase_cursor=task.get("current_phase_id") or phase_id)
            print(f"TASK_ID={task_id} RESUME_EVIDENCE_RESTORED=YES RESUME_EVIDENCE_SOURCE=PHASE_REPORT "
                  f"PHASE_ID={phase_id}", file=__import__('sys').stderr, flush=True)
    if not isinstance(state, dict) or not state.get("authorized_package_set"):
        print(f"TASK_ID={task_id} RESUME_EVIDENCE_RESTORED=NO RESUME_EVIDENCE_INVALIDATED=NO "
              f"RESUME_EVIDENCE_INVALIDATION_REASON=NO_PERSISTED_PACKAGE_EVIDENCE PHASE_ID={phase_id}",
              file=__import__('sys').stderr, flush=True)
        return False, [], state
    expected = dependency_requirement_specs(dependency_records or [])
    stored = [str(item) for item in (state.get("authorized_package_set") or [])]
    if expected and set(expected) != set(stored):
        reason = "DEPENDENCY_FINGERPRINT_MISMATCH"
    else:
        reason = ""
    root = Path(workspace_root).expanduser().resolve() if workspace_root else None
    if not reason and state.get("workspace_root") and root and Path(str(state["workspace_root"])).expanduser().resolve() != root:
        reason = "WORKSPACE_ROOT_MISMATCH"
    snapshot = _package_artifact_snapshot(str(root) if root else None)
    print(f"TASK_ID={task_id} PHASE_ID={phase_id} WORKSPACE_AUTO_INSPECTION=YES "
          f"POST_RESUME_WORKTREE_REFRESH={'YES' if root else 'NO'} "
          "USER_READINESS_CONFIRMATION=NOT_REQUIRED",
          file=__import__('sys').stderr, flush=True)
    if not reason:
        package_json = snapshot.get("package.json") or {}
        persisted_package_json = state.get("package_json") if isinstance(state.get("package_json"), dict) else {}
        persisted_package_hash = persisted_package_json.get("sha256") or state.get("package_json_hash")
        if not package_json.get("exists"):
            reason = "PACKAGE_JSON_MISSING"
        elif not persisted_package_hash:
            reason = "PACKAGE_JSON_HASH_MISSING"
        elif package_json.get("sha256") != persisted_package_hash:
            reason = "PACKAGE_JSON_HASH_CHANGED"
        else:
            try:
                data = json.loads((root / "package.json").read_text(encoding="utf-8")) if root else {}
                declared = set(dependency_requirement_names(list((data.get("dependencies") or {}).keys()) + list((data.get("devDependencies") or {}).keys())))
                required_names = set(dependency_requirement_names(expected or stored))
                if not required_names.issubset(declared):
                    reason = "DEPENDENCY_DECLARATIONS_MISSING"
            except (OSError, ValueError, TypeError):
                reason = "PACKAGE_JSON_UNREADABLE"
    if not reason:
        for name, expected_value in (state.get("lockfiles") or {}).items():
            if not isinstance(expected_value, dict) or not expected_value.get("exists"):
                continue
            current_value = snapshot.get(name) or {}
            if not current_value.get("exists"):
                reason = f"LOCKFILE_MISSING:{name}"; break
            if not expected_value.get("sha256"):
                reason = f"LOCKFILE_HASH_MISSING:{name}"; break
            if current_value.get("sha256") != expected_value.get("sha256"):
                reason = f"LOCKFILE_HASH_CHANGED:{name}"; break
    if not reason and state.get("node_modules_exists") is True and not (snapshot.get("node_modules") or {}).get("exists"):
        reason = "NODE_MODULES_MISSING"
    if reason:
        invalidated = {**state, "status": "INVALIDATED", "package_install_status": "NEEDS_INSPECTION",
                       "dependencies_satisfied": False, "owner": "PACKAGE_INSTALL", "package_json_owner": "PACKAGE_INSTALL",
                       "resume_evidence_invalidated": True, "resume_evidence_invalidation_reason": reason,
                       "invalidated_at": time.time()}
        _persist_resume_package_state(task_id, phase_id, plan_revision, invalidated,
                                      phase_cursor=task.get("current_phase_id") or phase_id)
        print(f"TASK_ID={task_id} RESUME_EVIDENCE_RESTORED=NO RESUME_EVIDENCE_INVALIDATED=YES "
              f"RESUME_EVIDENCE_INVALIDATION_REASON={reason} PHASE_ID={phase_id}",
              file=__import__('sys').stderr, flush=True)
        return False, [], invalidated
    restored = {**state, "status": "PASS", "package_install_status": "PASS",
                "dependencies_satisfied": True, "owner": "PACKAGE_INSTALL", "package_json_owner": "PACKAGE_INSTALL",
                "resume_evidence_invalidated": False, "resume_evidence_invalidation_reason": "NONE",
                "validated_at": time.time(), "workspace_snapshot": snapshot}
    _persist_resume_package_state(task_id, phase_id, plan_revision, restored,
                                  phase_cursor=task.get("current_phase_id") or phase_id)
    evidence = [{"status": "PASS", "operation_type": "PACKAGE_INSTALL",
                 "package_manager": restored.get("package_manager"),
                 "packages_authorized": restored.get("authorized_package_set") or [],
                 "workspace_root": str(root) if root else restored.get("workspace_root"),
                 "exit_code": 0, "dependency_requirements_satisfied": True,
                 "package_json_after": restored.get("package_json"),
                 "lockfile_after": restored.get("lockfiles") or {}}]
    print(f"TASK_ID={task_id} RESUME_EVIDENCE_RESTORED=YES RESUME_EVIDENCE_INVALIDATED=NO "
          f"RESUME_EVIDENCE_INVALIDATION_REASON=NONE PHASE_ID={phase_id} PACKAGE_INSTALL_STATUS=PASS "
          "DEPENDENCIES_SATISFIED=YES PACKAGE_JSON_OWNER=PACKAGE_INSTALL",
          file=__import__('sys').stderr, flush=True)
    return True, evidence, restored


def _artifact_paths_from_reports(reports: list[dict], workspace_root: str | None = None) -> list[str]:
    """Collect deterministic paths produced by successful typed file writes."""
    paths: set[str] = set()
    write_tools = {"workspace_write", "workspace_write_normalized", "workspace_patch", "write_text"}
    for report in reports:
        for value in report.get("changed_files") or []:
            if isinstance(value, str) and value.strip():
                paths.add(value.strip())
        typed = report.get("typed_execution_summary")
        operations = typed.get("operations") if isinstance(typed, dict) else []
        for operation in operations or []:
            if not isinstance(operation, dict) or operation.get("tool") not in write_tools:
                continue
            if str(operation.get("status") or "").lower() not in {"success", "completed", "ok", "normalized"}:
                continue
            output = operation.get("output") if isinstance(operation.get("output"), dict) else {}
            input_value = operation.get("input") if isinstance(operation.get("input"), dict) else {}
            value = output.get("path") or input_value.get("path")
            if isinstance(value, str) and value.strip():
                paths.add(value.strip())
    normalized: set[str] = set()
    for value in paths:
        candidate = Path(value).expanduser()
        if not candidate.is_absolute() and workspace_root:
            candidate = Path(workspace_root).expanduser() / candidate
        if candidate.is_absolute():
            normalized.add(str(candidate.resolve()))
        else:
            normalized.add(value)
    return sorted(normalized)


def _current_task_file_provenance(task_id: str, artifact: dict | None,
                                  reports: list[dict], workspace_root: str | None = None) -> dict[str, str]:
    """Reconstruct bounded file provenance for the current task only."""
    root = Path(workspace_root).expanduser().resolve() if workspace_root else None
    provenance: dict[str, str] = {}

    def relative(value: str) -> str:
        candidate = Path(value).expanduser()
        if candidate.is_absolute() and root:
            try:
                return candidate.resolve().relative_to(root).as_posix()
            except ValueError:
                return candidate.as_posix()
        return candidate.as_posix().lstrip("./")

    artifact = artifact if isinstance(artifact, dict) else {}
    for path, kind in (artifact.get("current_task_provenance") or {}).items():
        if isinstance(path, str) and isinstance(kind, str):
            provenance[relative(path)] = kind
    for path in artifact.get("scaffold_created_paths") or []:
        if isinstance(path, str):
            provenance[relative(path)] = "CREATED_BY_CURRENT_TASK_SCAFFOLD"
    for entry in artifact.get("file_manifest") or []:
        if not isinstance(entry, dict) or not isinstance(entry.get("path"), str):
            continue
        path = relative(entry["path"])
        if entry.get("exists_before") is True and path not in provenance:
            provenance[path] = "PREEXISTING_BEFORE_TASK"

    for report in reports:
        typed = report.get("typed_execution_summary") if isinstance(report.get("typed_execution_summary"), dict) else {}
        if typed.get("worktree_state") == "ROLLED_BACK":
            continue
        for operation in typed.get("operations") or []:
            if not isinstance(operation, dict) or operation.get("tool") not in {
                    "workspace_write", "workspace_write_normalized", "workspace_patch"}:
                continue
            if str(operation.get("status") or "").lower() not in {"success", "completed", "ok", "normalized"}:
                continue
            output = operation.get("output") if isinstance(operation.get("output"), dict) else {}
            input_value = operation.get("input") if isinstance(operation.get("input"), dict) else {}
            value = output.get("path") or input_value.get("path")
            if not isinstance(value, str) or not value.strip():
                continue
            path = relative(value)
            if output.get("created_by_current_task") is True:
                provenance[path] = "CREATED_BY_CURRENT_TASK_IMPLEMENTATION"
            elif path not in provenance:
                provenance[path] = "MODIFIED_BY_CURRENT_TASK"
    return provenance


def _append_artifact_paths(final_text: str, reports: list[dict], workspace_root: str | None = None) -> str:
    paths = _artifact_paths_from_reports(reports, workspace_root)
    lines = ["", "成果物ファイル:"]
    if paths:
        lines.extend(f"- {path}" for path in paths)
    else:
        lines.append("- なし")
    return final_text.rstrip() + "\n" + "\n".join(lines)


def _append_static_app_launch(final_text: str, task: dict, plan: dict, workspace_root: str | None) -> str:
    """Offer a local launch command only for the classified standalone static app."""
    requirements=task.get('requirements') or {}
    if (not workspace_root or not (requirements.get('planning_policy') or {}).get('coherent_static_application')
            or requirements.get('dependency_requirements')):
        return final_text
    root=Path(workspace_root).resolve()
    for entry in plan.get('file_manifest') or []:
        name=entry.get('path') if isinstance(entry,dict) else None
        if not isinstance(name,str) or not name.endswith('.html'):
            continue
        target=(root/name).resolve()
        if not target.is_relative_to(root) or not target.is_file():
            continue
        # ES modules require HTTP in ordinary browsers. Serve the actual
        # workspace on loopback; this is guidance, never an executed command.
        import shlex
        from urllib.parse import quote
        command='python3 -m http.server 8000 --bind 127.0.0.1 --directory '+shlex.quote(str(root))
        url='http://127.0.0.1:8000/'+quote(target.relative_to(root).as_posix())
        return (final_text.rstrip()+'\n\n## 起動方法\n\nターミナルで次を実行し、表示したURLをブラウザーで開いてください。\n\n'
                +'```sh\n'+command+'\n```\n\n'+url
                +'\n\n終了はターミナルで Ctrl+C。ポート8000が使用中の場合は、コマンドとURLの両方を空いている同じ番号に変更してください。')
    return final_text


_MCP_LIFECYCLE_ONLY_TOOLS = {"", "initialize", "tools/list"}


def _required_mcp_names(managed: dict) -> list[str]:
    requirements = managed.get("requirements") if isinstance(managed.get("requirements"), dict) else {}
    names = requirements.get("required_mcps", requirements.get("required_mcp", managed.get("required_mcp") or []))
    return [str(name) for name in names if str(name)]


def _mcp_usage_rows(managed: dict, server_id: str) -> list[dict]:
    return [item for item in (managed.get("mcp_evidence") or [])
            if isinstance(item, dict) and item.get("mcp_name") == server_id
            and item.get("status") == "PASS"
            and str(item.get("tool_name") or "") not in _MCP_LIFECYCLE_ONLY_TOOLS]


def _mcp_readiness_state(managed: dict, server_id: str) -> dict[str, str]:
    """Return one truthful readiness state for one required MCP provider."""
    rows = [item for item in (managed.get("mcp_evidence") or [])
            if isinstance(item, dict) and item.get("mcp_name") == server_id]
    usage = _mcp_usage_rows(managed, server_id)
    if usage:
        return {"state": "PASS", "reason": "NONE"}
    latest = rows[-1] if rows else {}
    status = str(latest.get("status") or "PENDING")
    if status in {"FAILED", "BLOCKED", "BLOCKED_NETWORK", "VERSION_CONFLICT"}:
        return {"state": "FAILED", "reason": str(latest.get("error") or "MCP failure reason was not recorded")}
    return {"state": "PENDING", "reason": "NOT_CHECKED"}


def _mcp_display_name(server_id: str) -> str:
    return {"animejs": "Anime.js", "shadcn": "shadcn", "playwright": "Playwright"}.get(server_id, server_id)


def _required_mcp_checkpoint_message(task_id: str, *, continuation: str) -> str:
    task = db.coding_task(task_id) or {}
    required = _required_mcp_names(task)
    states = {name: _mcp_readiness_state(task, name) for name in required}
    passed = [_mcp_display_name(name) for name, state in states.items() if state["state"] == "PASS"]
    pending = [_mcp_display_name(name) for name, state in states.items() if state["state"] == "PENDING"]
    if pending:
        prefix = (f"{ '、'.join(passed) or '実装' } MCP の事前検証が完了しました。"
                  f"{ '、'.join(pending) } MCP の検証は次工程で実行します。")
    else:
        prefix = "リポジトリ確認・必須 MCP 検証・実装計画の保存が完了しました。"
    return prefix + continuation


def _required_mcp_failure_message(task_id: str, server_id: str, error: str) -> str:
    task = db.coding_task(task_id) or {}
    required = _required_mcp_names(task)
    states = {name: _mcp_readiness_state(task, name) for name in required}
    passed = [_mcp_display_name(name) for name, state in states.items()
              if name != server_id and state["state"] == "PASS"]
    passed_prefix = f"{ '、'.join(passed) } MCP の検証は成功しました。" if passed else ""
    return (f"{passed_prefix}必須の {_mcp_display_name(server_id)} MCP 検証を実行できないため、"
            f"タスクをブロックしました。原因: {error or 'UNKNOWN'}")


def _verification_content_gaps(task_id: str, reports: list[dict]) -> list[str]:
    """Compare current bytes with the latest host-recorded verification for each target."""
    managed = db.coding_task(task_id) or {}
    requirements = managed.get('requirements') if isinstance(managed.get('requirements'), dict) else {}
    if not verification_requested_by_user(str(managed.get('original_goal') or ''), requirements):
        return []
    expected: dict[str, str] = {}
    for report in reports:
        for operation in (report.get('typed_execution_summary') or {}).get('operations') or []:
            if not isinstance(operation, dict) or operation.get('tool') != 'verification_command' or operation.get('status') != 'success':
                continue
            hashes = (operation.get('output') or {}).get('target_sha256')
            if isinstance(hashes, dict):
                expected.update(hashes)
    if not expected:
        return []  # Historical reports predate content fingerprints.
    conversation = db.conversation(managed.get('conversation_id', '')) or {}
    project = db.project(conversation.get('project_id', '')) or {}
    workspace = task_workspaces.service.root_for(task_id, project.get('workspace_path'))
    if not workspace:
        return ['verification workspace unavailable']
    root = Path(workspace).resolve()
    gaps = []
    for relative, digest in expected.items():
        try:
            target = (root / relative).resolve(strict=True)
            target.relative_to(root)
            if hashlib.sha256(target.read_bytes()).hexdigest() == digest:
                continue
        except (OSError, ValueError, TypeError):
            pass
        gaps.append(f'verified content changed: {relative}')
    return gaps


def _final_acceptance_gaps(managed: dict, reports: list[dict]) -> list[str]:
    """Compute final gates strictly from persisted typed state, never prose."""
    gaps = [f"required MCP used: {name}" for name in _required_mcp_names(managed)
            if not _mcp_usage_rows(managed, name)]
    requirements = managed.get("requirements") if isinstance(managed.get("requirements"), dict) else {}
    verification_requested = verification_requested_by_user(str(managed.get("original_goal") or ""), requirements)
    requested = ({str(name) for name in (requirements.get("required_verification") or [])}
                 if verification_requested else set())
    verification_ops = [op for report in reports
                        for op in (report.get('typed_execution_summary') or {}).get('operations') or []
                        if isinstance(op, dict) and op.get('tool') == 'verification_command' and op.get('status') == 'success']
    if 'tests' in requested and not any(
            any(t.get('returncode') == 0 and int(t.get('tests') or 0) > 0 for t in (op.get('output') or {}).get('test_runs') or [])
            or (any(arg in {'--test', 'unittest', 'pytest'} for arg in (op.get('input') or {}).get('command') or [])
                and (op.get('output') or {}).get('returncode') == 0 and (op.get('output') or {}).get('zero_tests') is False)
            for op in verification_ops):
        gaps.append('required tests were not executed')
    if "build" in requested and not any(report.get("build_pass") == "PASS" for report in reports):
        gaps.append("required build verification")
    if "typecheck" in requested:
        typecheck = any(((op.get('output') or {}).get('project_build') or {}).get('typecheck_executed') is True
                        and ((op.get('output') or {}).get('project_build') or {}).get('typecheck_passed') is True
                        for op in verification_ops) or any("typecheck" in " ".join(map(str, report.get("test_pass") or [])).lower()
                        and not report.get("test_fail") and not report.get("errors") for report in reports)
        if not typecheck:
            gaps.append("required typecheck verification")
    if "browser" in requested and not (_mcp_usage_rows(managed, "playwright") or
            any(int((op.get('output') or {}).get('browser_checks') or 0) > 0 for op in verification_ops)):
        gaps.append("required browser verification")
    return gaps


def _invalidate_changed_verification(task_id: str, reports: list[dict]) -> None:
    """Make stale verification unfinished so Resume cannot loop on the same PASS."""
    task = db.coding_task(task_id) or {}
    plan = task.get('plan') or {}
    verified = {report.get('phase_id') for report in reports
                if any(isinstance(op, dict) and op.get('tool') == 'verification_command'
                       and (op.get('output') or {}).get('target_sha256')
                       for op in (report.get('typed_execution_summary') or {}).get('operations') or [])}
    for phase in plan.get('phases') or []:
        if phase.get('id') in verified:
            phase['status'] = 'pending'
    db.update_coding_task(task_id, plan=plan, status='RESUMABLE', activity='NONE',
                         resume_state={**(task.get('resume_state') or {}), 'verification_invalidated_phases': sorted(verified - {None})},
                         recovery_action='REPLAN_CONTINUATION', recovery_reason='VERIFICATION_CONTENT_CHANGED')


def _append_mcp_telemetry(final_text: str, managed: dict) -> str:
    required=set(_required_mcp_names(managed))
    requirements = managed.get("requirements") if isinstance(managed.get("requirements"), dict) else {}
    evidence=managed.get("mcp_evidence") or []
    lines=["", "MCP telemetry:"]
    generic_available=[]; generic_used=[]; generic_purpose=[]; generic_skips=[]
    for name in ("shadcn", "playwright", "serena", "animejs"):
        rows=[item for item in evidence if isinstance(item,dict) and item.get("mcp_name") == name]
        usage=_mcp_usage_rows(managed, name)
        calls=[str(item.get("tool_name") or "") for item in usage]
        purpose=next((str(item.get("purpose") or "") for item in usage), "NONE")
        skip_reason=("NOT_REQUIRED" if name not in required else
                     "NONE" if usage else
                     next((str(item.get("error") or "") for item in reversed(rows) if item.get("error")), "UNVERIFIED"))
        # Task usage is not a live connection test. Never label an unattempted
        # provider unavailable, or a failed handshake available.
        availability = task_connection_availability(rows)
        lines.append(f"{name.upper()}_MCP_AVAILABLE={availability}")
        lines.append(f"{name.upper()}_MCP_USED={'YES' if usage else 'NO'}")
        lines.append(f"{name.upper()}_MCP_TOOL_CALLS={','.join(calls) if calls else 'NONE'}")
        lines.append(f"{name.upper()}_MCP_PURPOSE={purpose}")
        if name == "animejs":
            lines.append(f"ANIMEJS_MCP_REQUIRED={'YES' if name in required else 'NO'}")
            lines.append("ANIMEJS_VERSION_CONTEXT=V4" if usage else "ANIMEJS_VERSION_CONTEXT=NONE")
            mode = next((str(item.get("resource_mode")) for item in reversed(rows) if item.get("resource_mode")), "NONE")
            lines.append(f"MCP_RESOURCE_MODE={mode}")
            lines.append(f"ANIMEJS_MCP_INITIALIZE={'PASS' if any(item.get('tool_name') == 'initialize' and item.get('status') == 'PASS' for item in rows) else 'NOT_RUN'}")
            lines.append(f"ANIMEJS_MCP_TOOLS_LIST={'PASS' if any(item.get('tool_name') == 'tools/list' and item.get('status') == 'PASS' for item in rows) else 'NOT_RUN'}")
            lines.append(f"ANIMEJS_MCP_TOOL_CALL={'PASS' if usage else 'NOT_RUN'}")
            project = requirements.get("animejs_project") if isinstance(requirements.get("animejs_project"), dict) else {}
            for key in ("ANIMEJS_PROJECT_DEPENDENCY_PRESENT", "ANIMEJS_PROJECT_VERSION", "ANIMEJS_PROJECT_MAJOR_VERSION", "ANIMEJS_VERSION_COMPATIBILITY"):
                lines.append(f"{key}={project.get(key, 'UNKNOWN')}")
            lines.append(f"ANIMEJS_MIGRATION_PERFORMED={'YES' if project.get('ANIMEJS_VERSION_COMPATIBILITY') == 'MIGRATION_REQUESTED' else 'NO'}")
        lines.append(f"{name.upper()}_MCP_SKIP_REASON={skip_reason}")
        generic_available.append(f"{name}:{availability}")
        generic_used.append(f"{name}:{'YES' if usage else 'NO'}")
        generic_purpose.append(f"{name}:{purpose}")
        generic_skips.append(f"{name}:{skip_reason}")
    # Stable generic fields let consumers render a single deterministic MCP
    # summary while the per-server fields retain diagnostic detail.
    lines.extend([f"MCP_AVAILABLE={';'.join(generic_available)}",
                  f"MCP_USED={';'.join(generic_used)}",
                  f"MCP_PURPOSE={';'.join(generic_purpose)}",
                  f"MCP_SKIP_REASON={';'.join(generic_skips)}"])
    return final_text.rstrip()+"\n"+"\n".join(lines)


def _final_report_only(task_id: str, managed: dict, plan: dict, reports: list[dict], *,
                       completion_check_started: bool = False,
                       completion_check_raw_decision: str = "NONE",
                       completion_check_valid: bool = False) -> str:
    """Generate and persist only the final report for FINAL_REPORT recovery."""
    before=db.coding_task(task_id) or {}
    final_phase_id=(plan.get("phases") or [{}])[-1].get("id")
    if before.get('status') == 'COMPLETED':
        return 'Coding Task completed.'
    if _pause_at_checkpoint(task_id):
        return 'Task paused before final report.'
    content_gaps = _verification_content_gaps(task_id, reports)
    if content_gaps:
        _invalidate_changed_verification(task_id, reports)
        return 'Coding Task requires verification again: ' + ', '.join(content_gaps)
    gaps = _final_acceptance_gaps(before or managed, reports)
    if gaps:
        reason = "REQUIRED_MCP_UNVERIFIED" if any(item.startswith("required MCP") or item.startswith("required browser") for item in gaps) else "REQUIRED_VERIFICATION_UNVERIFIED"
        after = db.update_coding_task(task_id, status="RESUMABLE", activity="NONE",
                                      recovery_action="RECOVERY_REVIEW", recovery_reason=reason) or {}
        _finalization_log(task_id, final_phase_id=final_phase_id, all_phases_pass=False,
                          completion_check_started=completion_check_started,
                          completion_check_raw_decision=completion_check_raw_decision,
                          completion_check_valid=completion_check_valid, final_report_started=False,
                          final_report_valid=False, final_report_persisted=False,
                          status_before=before.get("status", "UNKNOWN"),
                          status_after=after.get("status", "RESUMABLE"),
                          failure_stage="REQUIRED_ACCEPTANCE", exception_type="NONE")
        _finish_coding_telemetry(task_id, "FAIL")
        return "Coding Task final verification is incomplete: " + ", ".join(gaps)
    # Final report generation is a deterministic projection of persisted task
    # evidence.  Keep it as a separate lifecycle activity so the frontend can
    # show the existing FINAL_REPORTING state, while never routing this path
    # through a model or changing the already-established task result.
    db.update_coding_task(task_id, status="FINAL_REPORTING", activity="DETERMINISTIC_FINAL_REPORT")
    format_started = time.perf_counter()
    try:
        report_task = dict(db.coding_task(task_id) or managed)
        # The report is persisted only after this projection succeeds. The
        # successful completion path therefore reports the terminal status.
        report_task["status"] = "COMPLETED"
        final = deterministic_final_report(
            report_task,
            plan,
            reports,
            handoff=report_task.get("batch_handoff"),
        )
        conversation = db.conversation(managed.get("conversation_id", "")) or {}
        project = db.project(conversation.get("project_id", "")) or {}
        persisted_reports = [row["structured_report"] for row in db.coding_phase_reports(task_id)
                             if row.get("validation_status") == "PASS"]
        final = _append_artifact_paths(final, persisted_reports or reports, task_workspaces.service.root_for(task_id, project.get("workspace_path")))
        final = _append_static_app_launch(final, report_task, plan,
                                         task_workspaces.service.root_for(task_id, project.get("workspace_path")))
        final = _append_mcp_telemetry(final, db.coding_task(task_id) or managed)
        format_ms = (time.perf_counter() - format_started) * 1000
        telemetry = _coding_telemetry.get(task_id)
        if telemetry is not None:
            telemetry.record_final_report_format(format_ms, generation_mode="DETERMINISTIC")
    except Exception as exc:
        _transition_resumable(task_id,"FINAL_REPORT","RECOVERABLE_INTERNAL","FINAL_REPORT",exc,"FORMATTER")
        _finalization_log(task_id,final_phase_id=final_phase_id,all_phases_pass=True,completion_check_started=completion_check_started,
                          completion_check_raw_decision=completion_check_raw_decision,completion_check_valid=completion_check_valid,final_report_started=True,
                          final_report_valid=False,final_report_persisted=False,status_before=before.get("status","UNKNOWN"),
                          status_after="RESUMABLE",failure_stage="FINAL_REPORT",exception_type=type(exc).__name__)
        return "Coding Task final report could not be generated."
    if final is None:
        after=db.coding_task(task_id) or {}
        _finalization_log(task_id,final_phase_id=final_phase_id,all_phases_pass=True,completion_check_started=completion_check_started,
                          completion_check_raw_decision=completion_check_raw_decision,completion_check_valid=completion_check_valid,final_report_started=True,
                          final_report_valid=False,final_report_persisted=False,status_before=before.get("status","UNKNOWN"),
                          status_after=after.get("status","RESUMABLE"),failure_stage="PAUSED",exception_type="NONE")
        return "Task paused before final report."
    final_text=final.strip() if isinstance(final,str) else ""
    if not final_text:
        _transition_resumable(task_id,"FINAL_REPORT","RECOVERABLE_INTERNAL","FINAL_REPORT",recovery_reason="INVALID_OUTPUT")
        _finalization_log(task_id,final_phase_id=final_phase_id,all_phases_pass=True,completion_check_started=completion_check_started,
                          completion_check_raw_decision=completion_check_raw_decision,completion_check_valid=completion_check_valid,final_report_started=True,
                          final_report_valid=False,final_report_persisted=False,status_before=before.get("status","UNKNOWN"),
                          status_after="RESUMABLE",failure_stage="FINAL_REPORT",exception_type="INVALID_OUTPUT")
        return "Coding Task final report could not be validated."
    if coding_git_intent(str(managed.get('original_goal') or ''), git_integration.github.automatic()):
        if git_integration.github.automatic():
            final_text += ('\n\nGit操作の結果はGitパネルに表示します。' if response_language() == 'ja' else '\n\nGit operation results appear in the Git panel.')
        else:
            final_text += ('\n\nGit操作は差分・送信先の確認待ちです。コミット／プッシュの結果はGitパネルで表示します。' if response_language() == 'ja' else '\n\nGit operations await diff/destination review. Commit and push results appear in the Git panel.')
    content_gaps = _verification_content_gaps(task_id, reports)
    if content_gaps:
        _invalidate_changed_verification(task_id, reports)
        return 'Coding Task requires verification again: ' + ', '.join(content_gaps)
    try:
        db.save_coding_completion(task_id, int(managed.get('plan_revision') or 0), final_text)
        persisted=db.coding_task(task_id) or {}
        if persisted.get("status") != "COMPLETED" or persisted.get("final_report_status") != "PASS":
            raise RuntimeError("final report persistence verification failed")
    except Exception as exc:
        if str(exc) == 'COMPLETION_INTERRUPTED':
            _pause_at_checkpoint(task_id)
            return 'Task paused before final report persistence.'
        if str(exc) == 'COMPLETION_PENDING_INSTRUCTIONS':
            current = db.coding_task(task_id) or managed
            result = _apply_task_steering(task_id, current)
            if result is not None:
                return result
            _transition_resumable(task_id, 'FINAL_REPORT', 'RECOVERABLE_INTERNAL', 'RECOVERY_REVIEW', recovery_reason='PENDING_INSTRUCTIONS')
            return 'Coding Task has instructions requiring review before completion.'
        _transition_resumable(task_id,"FINAL_REPORT_PERSISTENCE","RECOVERABLE_INTERNAL","FINAL_REPORT",exc,"PERSISTENCE")
        _finalization_log(task_id,final_phase_id=final_phase_id,all_phases_pass=True,completion_check_started=completion_check_started,
                          completion_check_raw_decision=completion_check_raw_decision,completion_check_valid=completion_check_valid,final_report_started=True,
                          final_report_valid=True,final_report_persisted=False,status_before=before.get("status","UNKNOWN"),
                          status_after="RESUMABLE",failure_stage="FINAL_REPORT_PERSISTENCE",exception_type=type(exc).__name__)
        return "Coding Task final report could not be persisted."
    _finalization_log(task_id,final_phase_id=final_phase_id,all_phases_pass=True,completion_check_started=completion_check_started,
                      completion_check_raw_decision=completion_check_raw_decision,completion_check_valid=completion_check_valid,final_report_started=True,
                      final_report_valid=True,final_report_persisted=True,status_before=before.get("status","UNKNOWN"),
                      status_after="COMPLETED")
    try:
        _finish_coding_telemetry(task_id, "PASS")
    except Exception as exc:
        print(f'TASK_ID={task_id} CODING_TELEMETRY_FINISH=FAILED ERROR_TYPE={type(exc).__name__} '
              'COMPLETION_PRESERVED=YES',file=__import__('sys').stderr,flush=True)
    try:
        git_integration.completed_task(db.coding_task(task_id) or managed)
    except Exception as exc:
        print(f"TASK_ID={task_id} GIT_HANDOFF_STATUS=UNAVAILABLE ERROR_TYPE={type(exc).__name__}", file=__import__('sys').stderr, flush=True)
    return "Coding Task completed."


def _complete_task(task_id: str, managed: dict) -> str:
    before=db.coding_task(task_id) or {}
    if before.get("status") == "COMPLETED":
        return "Coding Task completed."
    managed = before or managed
    plan=managed.get("plan") or {}
    current_revision=int(managed.get("plan_revision") or 0)
    phases=plan.get("phases") or []
    final_phase_id=phases[-1].get("id") if phases else None
    # Reports from prior replans are historical evidence only.  A finalization
    # decision must be based on the currently approved plan revision.
    reports=[]
    prior_evidence=[]
    for phase in phases:
        latest=_latest_current_phase_report(task_id,phase.get("id"),current_revision)
        if latest is None and phase.get("status") == "pass":
            latest=_latest_completed_phase_report(task_id,phase.get("id"))
        if latest is None:
            after=db.update_coding_task(task_id,status="RESUMABLE",activity="NONE",recovery_action="RECOVERY_REVIEW",recovery_reason="COMPLETION_EVIDENCE") or {}
            _finalization_log(task_id,final_phase_id=final_phase_id,all_phases_pass=False,completion_check_started=False,
                              completion_check_raw_decision="NONE",completion_check_valid=False,final_report_started=False,
                              final_report_valid=False,final_report_persisted=False,status_before=before.get("status","UNKNOWN"),
                              status_after=after.get("status","RESUMABLE"),failure_stage="EVIDENCE",exception_type="NONE")
            return "Coding Task completion evidence is incomplete."
        reports.append(latest["structured_report"])
        prior_evidence.append(_prior_saved_phase_reports(task_id,latest))
    all_phases_pass=len(reports)==len(phases) and len(reports)>0
    conversation = db.conversation(str(managed.get("conversation_id") or "")) or {}
    project = db.project(str(conversation.get("project_id") or "")) or {}
    workspace_root = task_workspaces.service.root_for(task_id, project.get("workspace_path"))
    if not all_phases_pass or managed.get("pending_authorization") or any(
            (r.get('manager_decision') or {}).get('decision') not in {None, 'PASS'} or
            (p.get('execution_mode') is not None and not evaluate_phase(p, r, prior, workspace_root=workspace_root)['phase_complete']) or
            report_has_authoritative_failure(
                r, p, workspace_root, prior)
            for r, p, prior in zip(reports, phases, prior_evidence)):
        after=db.update_coding_task(task_id,status="RESUMABLE",activity="NONE",recovery_action="RECOVERY_REVIEW",recovery_reason="COMPLETION_EVIDENCE") or {}
        _finalization_log(task_id,final_phase_id=final_phase_id,all_phases_pass=all_phases_pass,completion_check_started=False,
                          completion_check_raw_decision="NONE",completion_check_valid=False,final_report_started=False,
                          final_report_valid=False,final_report_persisted=False,status_before=before.get("status","UNKNOWN"),
                          status_after=after.get("status","RESUMABLE"),failure_stage="EVIDENCE",exception_type="NONE")
        return "Coding Task completion evidence is incomplete."
    # Completion is a deterministic consequence of every phase carrying
    # authoritative evidence.  Coding must not call the lightweight Gemma
    # router as a second quality or completion judge.
    print(f"TASK_ID={task_id} CODING_GEMMA_COMPLETION_CHECK=REMOVED COMPLETION_CHECK=DETERMINISTIC_PASS", file=__import__('sys').stderr, flush=True)
    return _final_report_only(task_id, managed, plan, reports, completion_check_started=False,
                              completion_check_raw_decision="DETERMINISTIC_PASS", completion_check_valid=True)

def _heavy_batch_checkpoint(task_id: str, plan: dict, completed: set[str], *, blueprint_report: dict | None = None,
                            await_continuation: bool = True, checkpoint_reason: str | None = None) -> str | None:
    """Persist a bounded handoff after one heavy batch; never use authorization."""
    remaining=[phase for phase in plan.get("phases",[]) if phase.get("id") not in completed]
    if not remaining:
        return None
    task = db.coding_task(task_id) or {}
    if task.get("pending_authorization"):
        return None
    reports=[]
    for phase in plan.get("phases", []):
        if phase["id"] not in completed:
            continue
        row = _latest_current_phase_report(task_id, phase["id"], int(task.get("plan_revision") or 0)) or _latest_completed_phase_report(task_id, phase["id"])
        report = blueprint_report if blueprint_report and blueprint_report["phase_id"] == phase["id"] else (row or {}).get("structured_report")
        if not report or report_has_authoritative_failure(report, phase):
            raise RuntimeError("checkpoint requires successful phase evidence")
        reports.append(report)
    changed=sorted({path for report in reports for path in (report.get("changed_files") or []) if isinstance(path,str)})
    cursor=next((index for index,phase in enumerate(plan.get("phases",[])) if phase.get("id") not in completed),len(plan.get("phases",[])))
    handoff={"changed_files":changed,"created_interfaces":[],"data_contracts":[],"decisions":[],"verification":[],"unresolved":[],"next_constraints":[str(remaining[0].get("goal") or "")[:500]]}
    handoff.update(completed_phases=sorted(completed), next_phase_id=remaining[0]["id"],
                   verification=[{"phase_id": r.get("phase_id"), "status": r.get("status"), "test_pass": r.get("test_pass", []), "build_pass": r.get("build_pass")} for r in reports],
                   unresolved=[item for r in reports for item in r.get("risks", [])],
                   completed_phase_id=reports[-1]["phase_id"],
                   plan_revision=int(task.get("plan_revision") or 0),
                   mcp_evidence=list(task.get("mcp_evidence") or []),
                   blueprint=plan.get("blueprint"))
    saved = db.save_coding_checkpoint(task_id, plan, handoff, cursor, int(task.get("plan_revision") or 0),
                                      blueprint_report, await_continuation, checkpoint_reason)
    _persist_coding_telemetry_snapshot(task_id)
    if not saved or saved.get("batch_handoff") != handoff:
        raise RuntimeError("Checkpoint persistence failed")
    reason = checkpoint_reason or ("RESOURCE_CHECKPOINT" if await_continuation else "CONTINUOUS")
    print(f"TASK_ID={task_id} CHECKPOINT_CREATED={'YES' if await_continuation else 'NO'} CHECKPOINT_REASON={reason} NEXT_PHASE_ID={remaining[0]['id']} BATCH_CURSOR={cursor}",file=__import__('sys').stderr,flush=True)
    return _record_coding_stop(task_id, reason, True) if await_continuation else None


def _finish_planning_boundary(task_id: str, plan: dict, await_continuation: bool, *, checkpoint_reason: str | None = None) -> str | None:
    """Record actual orchestration work and its persisted blueprint, once."""
    task = db.coding_task(task_id) or {}
    phase = next(p for p in plan["phases"] if p.get("kind") == "ORCHESTRATOR_BLUEPRINT")
    if "preflight" not in (plan.get("blueprint") or {}):
        raise RuntimeError("planning boundary has no persisted preflight context")
    report = {"phase_id": phase["id"], "attempt": 0, "plan_revision": int(task.get("plan_revision") or 0), "status": "PASS",
              "implemented": ["Validated implementation blueprint and preflight context persisted"], "changed_files": [],
              "test_executed": [], "test_pass": [], "test_fail": [], "build_executed": "NOT_APPLICABLE",
              "build_pass": "NOT_APPLICABLE", "errors": [], "blockers": [], "risks": [],
              "manager_decision": {"decision": "PASS", "reason": "Validated planning artifact; implementation has not started"}}
    stable_plan = _phase_status(plan, phase["id"], "pass")
    return _heavy_batch_checkpoint(task_id, stable_plan, {phase["id"]}, blueprint_report=report,
                                   await_continuation=await_continuation, checkpoint_reason=checkpoint_reason)

def _prepare_task_implementation_plan(task_id: str, plan: dict, *args, **kwargs):
    plan = task_workspaces.service.execution_plan(task_id, plan)
    task_workspaces.service.capture_manifest(task_id, plan)
    result = prepare_implementation_plan(task_id, plan, *args, **kwargs)
    task_workspaces.service.checkpoint(task_id, [
        {"path": path, "hash": value} for path, value in (result[1] or {}).get("scaffold_created_hashes", {}).items()])
    return result


def _prepare_approved_plan_artifact(task_id: str, managed: dict, plan: dict,
                                    workspace_root: str) -> tuple[dict, dict]:
    """Validate and bind the exact-file artifact after a plan is approved.

    Plan-only tasks deliberately defer filesystem writes until approval.  The
    resumed task must therefore run the same coverage/path/scaffold boundary
    as initial planning instead of treating an empty manifest as a fatal
    malformed artifact.
    """
    canonical_root = Path(workspace_root).expanduser().resolve(strict=True)
    requirements = managed.get("requirements") if isinstance(managed.get("requirements"), dict) else {}
    artifact_requirements = {**requirements, "requirements_hash": _context_fingerprint(requirements)}
    current_workspace = workspace_state(canonical_root)
    project_state = current_workspace.get("project_state") or current_workspace.get("workspace_state")
    profile = str(requirements.get("task_profile") or managed.get("task_profile") or "")
    current_workspace.update({
        "new_project_intent": bool(requirements.get("new_project_intent")
                                    and project_state != "ESTABLISHED"
                                    and profile in {"FRONTEND_ONLY_MARKETING_SITE", "GENERAL_CODING"}),
        "workspace_state": project_state,
        "host_workspace_authorized": True,
        "host_authorized_root": str(canonical_root),
    })
    preflight = ((plan.get("blueprint") or {}).get("preflight")
                 if isinstance(plan.get("blueprint"), dict) else None)
    if not isinstance(preflight, dict):
        preflight = requirements.get("preflight") if isinstance(requirements.get("preflight"), dict) else {}
    recorded_scope = preflight.get("mutation_scope_contract") if isinstance(preflight, dict) else {}
    recorded_scope = recorded_scope if isinstance(recorded_scope, dict) else {}
    live_scope = _workspace_scope_contract(str(canonical_root))
    current_workspace["authorized_mutation"] = list(
        live_scope.get("write_allowed") or recorded_scope.get("write_allowed") or [])
    current_workspace["read_only"] = list(
        live_scope.get("read_only") or recorded_scope.get("read_only") or [])

    candidate_plan = plan
    manifest_source = "APPROVED_PLAN"
    if "file_manifest" not in plan:
        prior_task_writes = []
        for report in db.coding_phase_reports(task_id):
            operations = ((report.get("structured_report") or {}).get("typed_execution_summary") or {}).get("operations") or []
            for operation in operations:
                output = operation.get("output") if isinstance(operation, dict) else None
                if (isinstance(operation, dict) and operation.get("tool") == "workspace_write"
                        and operation.get("status") == "success" and isinstance(output, dict)
                        and output.get("net_changed") is True and isinstance(output.get("path"), str)):
                    prior_task_writes.append(output["path"])
        legacy_manifest = reconstruct_legacy_file_manifest(
            plan, canonical_root, prior_task_writes)
        if legacy_manifest:
            candidate_plan = {**plan, "file_manifest": legacy_manifest}
            manifest_source = "LEGACY_APPROVED_SCOPE"
    coverage = manifest_coverage(candidate_plan, artifact_requirements, current_workspace)
    if not coverage.get("valid"):
        completed, _ = deterministic_manifest_completion(
            candidate_plan, coverage, canonical_root, current_workspace)
        if completed is not None:
            candidate_plan = completed
            manifest_source = "DETERMINISTIC_COMPLETION"
            coverage = manifest_coverage(candidate_plan, artifact_requirements, current_workspace)

    manifest = candidate_plan.get("file_manifest") if isinstance(candidate_plan, dict) else None
    if not isinstance(manifest, list) or not manifest or not coverage.get("valid"):
        missing = list(coverage.get("missing_paths") or [])
        repair_requirements = {
            **requirements,
            "planning_policy": {**(requirements.get("planning_policy") or {}), "mode": "LEAN"},
        }
        repair_prompt = (
            "Return a corrected JSON plan for the same already-approved coding task. "
            "Preserve the current phase IDs, goals, dependencies, execution modes, original goal, and scope. "
            "Only repair the top-level file_manifest: enumerate every concrete writable repository-relative file "
            "needed by the approved implementation, including the missing paths below. Use create for missing files "
            "and modify only for files currently present. Exclude read-only evidence and dependency names. Do not "
            "add directories, wildcard paths, or workspace-external paths.\n" + json.dumps({
                "original_goal": managed.get("original_goal"),
                "current_phases": [{key: phase.get(key) for key in ("id", "kind", "goal", "done", "execution_mode")}
                                   for phase in plan.get("phases") or [] if isinstance(phase, dict)],
                "current_manifest": manifest if isinstance(manifest, list) else [],
                "missing_paths": missing,
                "required_stack": requirements.get("required_stack") or [],
                "workspace_state": {key: current_workspace.get(key) for key in
                                    ("root", "project_state", "workspace_state", "new_project_intent", "entries", "files")},
            }, ensure_ascii=False))
        candidate, _ = _generate_plan(task_id, str(managed.get("original_goal") or ""),
                                      repair_prompt, "QWEN_PLAN_MANIFEST_REPAIR",
                                      repair_requirements, recovery=True, repair=True)
        repaired_manifest = candidate.get("file_manifest") if isinstance(candidate, dict) else None
        if isinstance(repaired_manifest, list) and repaired_manifest:
            phase_by_id = {str(phase.get("id")): phase for phase in plan.get("phases") or []
                           if isinstance(phase, dict) and phase.get("id")}
            implementation_phase_id = next((str(phase.get("id")) for phase in plan.get("phases") or []
                                             if isinstance(phase, dict)
                                             and phase.get("kind") != "ORCHESTRATOR_BLUEPRINT"
                                             and phase.get("execution_mode") != "VERIFICATION_ONLY"), "")
            repaired_manifest = [dict(item) if isinstance(item, dict) else item
                                 for item in repaired_manifest]
            for entry in repaired_manifest:
                if not isinstance(entry, dict):
                    continue
                owner = str(entry.get("owner_phase") or "")
                owner_phase = phase_by_id.get(owner)
                if (not owner_phase or owner_phase.get("kind") == "ORCHESTRATOR_BLUEPRINT"
                        or owner_phase.get("execution_mode") == "VERIFICATION_ONLY"):
                    entry["owner_phase"] = implementation_phase_id
            candidate_plan = {**candidate_plan, "file_manifest": repaired_manifest}
            coverage = manifest_coverage(candidate_plan, artifact_requirements, current_workspace)
            if coverage.get("valid"):
                manifest_source = "PLANNER_REPAIR"
        manifest = candidate_plan.get("file_manifest") if isinstance(candidate_plan, dict) else None
        if not isinstance(manifest, list) or not manifest or not coverage.get("valid"):
            missing = list(coverage.get("missing_paths") or missing)
            diagnostics = [{"offending_plan_path": path, "offending_plan_field": "file_manifest",
                            "offending_phase": "IMPLEMENTATION",
                            "manifest_coverage_reason": "manifest does not cover implementation contract",
                            "manifest_coverage_code": "INCOMPLETE_MANIFEST_COVERAGE"}
                           for path in missing]
            raise PlanManifestCoverageError(
                "approved plan does not contain a complete writable file manifest",
                missing or ["concrete implementation file paths"], diagnostics)

    prepared, artifact = _prepare_task_implementation_plan(
        task_id, candidate_plan, canonical_root, artifact_requirements, current_workspace)
    artifact = {**artifact, "manifest_source": manifest_source}
    prepared["implementation_plan_artifact"] = artifact
    db.update_coding_task(task_id, plan=prepared)
    print(f"TASK_ID={task_id} APPROVED_PLAN_MANIFEST_PREPARED=YES "
          f"MANIFEST_SOURCE={manifest_source} FILE_MANIFEST_COUNT={artifact['file_manifest_count']} "
          f"PLAN_MANIFEST_COVERAGE=PASS PLAN_PATH_VALIDATION=PASS",
          file=__import__('sys').stderr, flush=True)
    return prepared, artifact


def _apply_task_steering(task_id: str, managed: dict) -> str | None:
    if managed.get("pending_authorization") or managed.get("pause_requested"):
        return None
    rows = task_workspaces.service.take_steering(task_id)
    if not rows:
        return None
    revision = int(managed.get("plan_revision") or 0)
    plan = managed.get("plan") or {}
    completed = {p["id"] for p in plan.get("phases", []) if p.get("status") == "pass"}
    try:
        result = _replan_task(task_id, managed, completed,
            "Explicit user instructions at a phase boundary:\n" + "\n".join(r["message"] for r in rows))
        current = db.coding_task(task_id) or managed
        if current.get('pending_plan') and current.get('pending_authorization'):
            db.update_coding_task(task_id, pending_authorization={**current['pending_authorization'],
                'steering_ids': [row['id'] for row in rows], 'steering_revision': revision})
        task_workspaces.service.finish_steering(rows, int(current.get("plan_revision") or 0), int(current.get("plan_revision") or 0) > revision)
        return result
    except Exception:
        task_workspaces.service.finish_steering(rows, revision, False)
        raise


def _coding_permission_wait(task: dict) -> str | None:
    """A switch to confirm takes effect at the next phase, using the existing wait route."""
    if settings.permission_level != 'confirm' or not task.get('plan'):
        return None
    scopes = task.get('approved_scopes') or []
    if any(isinstance(scope, dict) and scope.get('source') == 'explicit_plan_approval' for scope in scopes):
        return None
    plan = task['plan']
    authorization = {'type':'PERMISSION_MODE', 'source':'plan', 'state':'PENDING', 'reason':'Permission mode requires plan approval.',
                     'requested_scope':list((plan.get('scope') or {}).get('allowed') or [])}
    db.update_coding_task(task['id'],status='WAITING_FOR_USER',activity='SCOPE_AUTHORIZATION',
                          pending_plan=plan,pending_authorization=authorization,pending_user_confirmation=1)
    response = '権限設定が「承認を確認」のため、次の工程の前に計画の承認が必要です。「承認します」と返信してください。'
    db.add_message(task['conversation_id'],'assistant',response,time.time(),str(uuid.uuid4()),task['id'])
    return response


def _run_managed_task(task_id: str, workspace_root: str | None) -> str:
    """Run one approved task serially through the existing typed Runtime executor."""
    managed=db.coding_task(task_id)
    if not managed or managed["status"] not in {"QUEUED","RUNNING"} or managed["archived"] or managed["pause_requested"]: return ""
    permission_wait = _coding_permission_wait(managed)
    if permission_wait is not None:
        return permission_wait
    steering_result = _apply_task_steering(task_id, managed)
    if steering_result is not None:
        return steering_result
    plan=managed.get("plan") or {}
    requirements = managed.get('requirements') or {}
    original_goal = str(managed.get('original_goal') or '')
    verification_requested = verification_requested_by_user(original_goal, requirements)
    if requirements.get('verification_requested') is not verification_requested:
        requirements = {**requirements, 'verification_requested': verification_requested}
        db.update_coding_task(task_id, requirements=requirements)
        managed = db.coding_task(task_id) or {**managed, 'requirements': requirements}
    # Older replacement plans lost the host-only flags. The recorded owned
    # runner invocation is authoritative provenance, not a model assertion.
    owned_phase_ids=[]
    runner=Path(__file__).with_name('coding_verification_runner.cjs').resolve()
    for row in db.coding_phase_reports(task_id):
        for operation in (row.get('structured_report',{}).get('typed_execution_summary') or {}).get('operations') or []:
            command=(operation.get('input') or {}).get('command')
            if (operation.get('tool')=='verification_command' and isinstance(command,list) and len(command)>1
                    and Path(str(command[1])).resolve()==runner and row['phase_id'] not in owned_phase_ids):
                owned_phase_ids.append(row['phase_id'])
    restored = (inherit_owned_verification(plan,plan,owned_phase_ids)
                if verification_requested else suppress_unrequested_verification(plan)[0])
    scheduled = normalize_static_verification(restored, workspace_root, verification_requested)
    if verification_requested:
        scheduled = bind_original_acceptance(scheduled, original_goal)
    schedule_changed=scheduled != plan
    if schedule_changed:
        plan = scheduled
        db.update_coding_task(task_id, plan=plan)
        managed = db.coding_task(task_id) or managed
        print(f'TASK_ID={task_id} VERIFICATION_SCHEDULE=DEFERRED_UNTIL_IMPLEMENTATION_COMPLETE', file=__import__('sys').stderr, flush=True)
    from .coding_tasks import required_verification_contract
    required_checks = (required_verification_contract(original_goal, managed.get('required_mcp') or [])
                       if verification_requested else [])
    if required_checks != (requirements.get('required_verification') or []):
        db.update_coding_task(task_id, requirements={**requirements, 'required_verification': required_checks})
        managed = db.coding_task(task_id) or managed
    execution_plan = task_workspaces.service.execution_plan(task_id, plan)
    if execution_plan != plan:
        plan = execution_plan
        db.update_coding_task(task_id, plan=plan)
        managed = db.coding_task(task_id) or managed
    _initialize_subtask_progress(task_id,plan,preserve=True)
    plan, checkpoint_changes = enforce_explicit_phase_failure_checkpoint(plan, managed.get("original_goal", ""))
    plan, manifest_changes = enforce_explicit_single_file_manifest(plan, managed.get("original_goal", ""))
    if checkpoint_changes:
        db.update_coding_task(task_id, plan=plan)
        managed = db.coding_task(task_id) or {**managed, "plan": plan}
        print(f"TASK_ID={task_id} PERSISTED_PLAN_CHECKPOINT_ENFORCEMENT=YES "
              f"CHANGES={json.dumps(checkpoint_changes, ensure_ascii=False)}",
              file=__import__('sys').stderr, flush=True)
    if manifest_changes:
        plan = task_workspaces.service.execution_plan(task_id, plan)
        db.update_coding_task(task_id, plan=plan)
        managed = db.coding_task(task_id) or {**managed, "plan": plan}
        print(f"TASK_ID={task_id} PERSISTED_PLAN_MANIFEST_ENFORCEMENT=YES "
              f"CHANGES={json.dumps(manifest_changes, ensure_ascii=False)}",
              file=__import__('sys').stderr, flush=True)
    plan, dependency_changes = associate_dependency_requirements(plan, managed.get("requirements") or {})
    if dependency_changes:
        db.update_coding_task(task_id, plan=plan)
        managed = {**managed, "plan": plan}
        print(f"TASK_ID={task_id} DEPENDENCY_REQUIREMENT_PHASE_ASSOCIATION=RECOVERY_BOUNDARY "
              f"CHANGES={json.dumps(dependency_changes, ensure_ascii=False)}",
              file=__import__('sys').stderr, flush=True)
    # The persisted plan is the final executable graph.  Any remaining cycle
    # or namespace error must stop before scaffold, package installation, or
    # implementation; intermediate planner diagnostics may be repaired or
    # normalized before this boundary.
    criterion_errors=plan_criterion_errors(plan)
    if criterion_errors:
        print(f'TASK_ID={task_id} PLAN_CRITERIA_VALIDATION=FAIL IMPLEMENTATION_STARTED=NO ERRORS={json.dumps(criterion_errors,ensure_ascii=False)}',file=__import__('sys').stderr,flush=True)
        completed_ids={phase['id'] for phase in plan.get('phases',[])
            if _phase_passed_in_epoch(task_id,phase,int(managed.get('plan_revision') or 0),int(managed.get('recovery_epoch') or 0),workspace_root)}
        return _replan_task(task_id,managed,completed_ids,'Invalid plan criteria: '+'; '.join(criterion_errors))
    final_graph = graph_validation_diagnostics(plan)
    if final_graph.get("errors"):
        first = final_graph.get("first_error") or {}
        reason = str(first.get("reason") or "invalid dependency graph")
        print(f"TASK_ID={task_id} GRAPH_VALIDATION=FAIL FINAL_GRAPH_VALIDATION=FAIL GRAPH_FAIL_CLOSED=YES "
              f"OFFENDING_PHASE_ID={first.get('offending_phase_id') or 'NONE'} "
              f"OFFENDING_TASK_ID={first.get('offending_task_id') or 'NONE'} "
              f"OFFENDING_DEPENDENCY_REF={first.get('offending_dependency_ref') or 'NONE'} "
              f"GRAPH_ERROR_FINGERPRINT={first.get('fingerprint') or 'NONE'} "
              f"DEPENDENCY_VALIDATION_REASON={reason}", file=__import__('sys').stderr, flush=True)
        db.update_coding_task(task_id, status="BLOCKED", activity="NONE", recovery_action="NONE",
                              recovery_reason="FINAL_GRAPH_VALIDATION")
        return "Coding Task is blocked: final dependency graph validation failed."
    phases=plan.get("phases",[])
    # Do not enter approved-plan recovery (which may call a planning model)
    # until we know that the next ready row is work the implementation
    # executor can own.  The later dispatch loop enforces the same invariant,
    # but reaching it only after manifest repair leaves orchestration-only
    # plans stuck waiting for a model that must never be called.
    preparation_revision = int(managed.get("plan_revision") or 0)
    preparation_epoch = int(managed.get("recovery_epoch") or 0)
    preparation_completed = {
        phase["id"] for phase in phases
        if _phase_passed_in_epoch(task_id, phase, preparation_revision,
                                  preparation_epoch, workspace_root)
    }
    next_ready_phase = next((phase for phase in phases
        if phase.get("id") not in preparation_completed
        and all(dependency in preparation_completed
                for dependency in phase.get("dependencies", []))), None)
    if (next_ready_phase
            and next_ready_phase.get("kind") != "ORCHESTRATOR_BLUEPRINT"
            and not phase_has_observable_deliverable(next_ready_phase)):
        print(f"TASK_ID={task_id} CONTROL_PLANE_INVARIANT_FAILURE=NON_ARTIFACT_PHASE_DISPATCH "
              f"PHASE_ID={next_ready_phase['id']} BEFORE_APPROVED_PLAN_PREPARATION=YES",
              file=__import__('sys').stderr, flush=True)
        db.update_coding_task(task_id, status="BLOCKED", activity="NONE",
                              recovery_action="NONE", recovery_reason="NON_ARTIFACT_PHASE")
        return "Coding Task is blocked: orchestration-only work cannot enter implementation."
    implementation_artifact = plan.get("implementation_plan_artifact") if isinstance(plan, dict) else None
    manifest = plan.get("file_manifest") if isinstance(plan, dict) else None
    implementation_phases = [phase for phase in phases if isinstance(phase, dict)
                              and phase.get("kind") != "ORCHESTRATOR_BLUEPRINT"
                              and phase.get("execution_mode") != "VERIFICATION_ONLY"]
    execution_policy = (managed.get("requirements") or {}).get("execution_policy") or {}
    large_task = (managed.get("execution_mode") == "HEAVY_BATCHED"
                  or execution_policy.get("task_size") == "LARGE")
    # Plan-only approval deliberately skips scaffolding. Once the user
    # approves, large tasks (and any task with no mutable manifest) must cross
    # the full coverage/path/scaffold boundary before their first phase.
    prepare_approved_plan = (not isinstance(implementation_artifact, dict)
                             and bool(workspace_root) and bool(implementation_phases)
                             and not preparation_completed
                             and (large_task or not isinstance(manifest, list) or not manifest))
    if prepare_approved_plan:
        try:
            plan, implementation_artifact = _prepare_approved_plan_artifact(
                task_id, managed, plan, workspace_root)
            managed = db.coding_task(task_id) or managed
            plan = managed.get("plan") or plan
        except (OSError, TypeError, ValueError, PermissionError) as exc:
            current_task = db.coding_task(task_id) or managed
            if current_task.get("status") == "BLOCKED":
                return "Coding Task is blocked: the bounded plan-repair budget is exhausted."
            diagnostics = getattr(exc, "diagnostics", []) or []
            if diagnostics:
                pending_plan = dict(plan)
                pending_plan["path_validation_diagnostics"] = diagnostics[:16]
                db.update_coding_task(task_id, pending_plan=pending_plan)
            if isinstance(exc, PlanStackConformanceError):
                failure_reason = "PLAN_STACK_CONFORMANCE"
                message = stack_conformance_message(getattr(exc, "diagnostics", {}) or {})
            elif isinstance(exc, PlanManifestCoverageError):
                failure_reason = "PLAN_MANIFEST_COVERAGE"
                message = manifest_coverage_message(replan=True)
            else:
                failure_reason = "PLAN_PATH_VALIDATION"
                first_diagnostic = diagnostics[0] if diagnostics else {}
                message = path_validation_message(
                    first_diagnostic.get("path_validation_code")
                    or first_diagnostic.get("path_validation_reason") or str(exc),
                    replan=True)
            print(f"TASK_ID={task_id} APPROVED_PLAN_PREPARATION=RECOVERABLE_FAILURE "
                  f"RECOVERY_REASON={failure_reason} ERROR_TYPE={type(exc).__name__} "
                  f"DIAGNOSTIC_COUNT={len(diagnostics)} IMPLEMENTATION_STARTED=NO",
                  file=__import__('sys').stderr, flush=True)
            _transition_resumable(task_id, "IMPLEMENTATION_PREPARE", "RECOVERABLE_INTERNAL",
                                  "RECOVERY_REVIEW", exc, failure_reason)
            _add_task_message_once(managed["conversation_id"], task_id, message)
            return "Coding Task paused before implementation: " + message
    # Small tasks with a concrete manifest retain the lightweight historical
    # continuation path. Large or empty-manifest plans use the complete
    # preparation boundary above.
    if (not isinstance(implementation_artifact, dict) and isinstance(plan, dict)
            and isinstance(plan.get("file_manifest"), list) and bool(plan["file_manifest"])
            and workspace_root):
        canonical_root = Path(workspace_root).expanduser().resolve()
        exact_manifest = []
        manifest_valid = bool(plan["file_manifest"])
        seen_manifest_paths: set[str] = set()
        for entry in plan["file_manifest"]:
            if not isinstance(entry, dict) or not isinstance(entry.get("path"), str):
                manifest_valid = False
                break
            requested_path = Path(entry["path"]).expanduser()
            target_path = (requested_path if requested_path.is_absolute()
                           else canonical_root / requested_path).resolve()
            if canonical_root not in target_path.parents or target_path == canonical_root:
                manifest_valid = False
                break
            relative_path = target_path.relative_to(canonical_root).as_posix()
            if relative_path in seen_manifest_paths:
                manifest_valid = False
                break
            seen_manifest_paths.add(relative_path)
            exact_manifest.append({**entry, "path": relative_path})
        if manifest_valid:
            implementation_artifact = {"target_root": str(canonical_root),
                                       "file_manifest": exact_manifest,
                                       "file_manifest_count": len(exact_manifest),
                                       "manifest_source": "PLAN_FILE_MANIFEST"}
            plan["implementation_plan_artifact"] = implementation_artifact
            db.update_coding_task(task_id, plan=plan)
        else:
            db.update_coding_task(task_id, status="BLOCKED", activity="NONE",
                                  recovery_action="NONE", recovery_reason="INVALID_FILE_MANIFEST")
            print(f"TASK_ID={task_id} PLAN_MANIFEST_VALID=NO IMPLEMENTATION_STARTED=NO",
                  file=__import__('sys').stderr, flush=True)
            return "Coding Task is blocked: the plan file manifest is invalid."
    if isinstance(implementation_artifact, dict) and implementation_artifact.get("target_root"):
        persisted_root = str(Path(str(implementation_artifact["target_root"])).expanduser().resolve())
        supplied_root = str(Path(workspace_root).expanduser().resolve()) if workspace_root else None
        print(f"TASK_ID={task_id} CANONICAL_TARGET_ROOT={persisted_root} PATHGUARD_TARGET_ROOT_MATCH={'YES' if supplied_root in {None, persisted_root} else 'NO'}", file=__import__('sys').stderr, flush=True)
        if supplied_root is not None and supplied_root != persisted_root:
            db.update_coding_task(task_id, status='BLOCKED', activity='NONE', recovery_action='NONE',
                                  recovery_reason='WORKSPACE_IDENTITY_MISMATCH')
            return 'Coding Task is blocked: saved execution plan belongs to a different workspace. Replan for the selected workspace before implementation.'
        # The persisted artifact is the continuation boundary.  Reuse it on
        # Continue/restart so planner, scaffold and implementation agree.
        workspace_root = persisted_root
    task_workspaces.service.capture_manifest(task_id, plan)
    heavy=managed.get("execution_mode") == "HEAVY_BATCHED"
    policy = (managed.get("requirements") or {}).get("execution_policy") or {}
    major_checkpoints = policy.get("continuation_policy") == "MAJOR_CHECKPOINTS" if policy else heavy
    current_revision=int(managed.get("plan_revision") or 0)
    recovery_epoch=int(managed.get("recovery_epoch") or 0)
    completed={phase["id"] for phase in phases
               if _phase_passed_in_epoch(task_id, phase, current_revision, recovery_epoch, workspace_root)}
    # Reconcile persisted evidence against the current deterministic evaluator
    # before honoring stale recovery decisions.  This also covers a restart in
    # the middle of a model recovery call, where recovery_reason may no longer
    # be REPLAN_LIMIT even though the saved phase evidence is already complete.
    current_phase = next((phase for phase in phases if phase.get("id") == managed.get("current_phase_id")), None)
    if current_phase:
        phase_rows = [row for row in db.coding_phase_reports(task_id)
                      if row.get("phase_id") == current_phase.get("id")
                      and _report_plan_revision(row.get("structured_report") or {}) == current_revision
                      and row.get("validation_status") == "PASS"]
        latest_report = phase_rows[-1] if phase_rows else None
        if latest_report:
            restored=_restore_legacy_executor_error(latest_report['structured_report'])
            if restored!=latest_report['structured_report']:
                db.update_coding_phase_report(latest_report['id'],restored,'PASS')
                latest_report={**latest_report,'structured_report':restored}
        if latest_report and _verification_coverage_pending(current_phase,latest_report['structured_report']):
            restored=dict(latest_report['structured_report'])
            restored.update(status='PASS',verification_pending=True,errors=[],test_fail=[],
                manager_decision={'decision':'RETRY','reason':'Executed checks passed; acceptance coverage is incomplete',
                                  'retry_channel':'VERIFICATION_CONTRACT'})
            db.update_coding_phase_report(latest_report['id'],restored,'PASS')
            latest_report={**latest_report,'structured_report':restored}
            print(f'TASK_ID={task_id} PARTIAL_VERIFICATION_RESTORED=YES SOURCE_REPAIR_REQUIRED=NO',file=__import__('sys').stderr,flush=True)
        previous_decision = ((latest_report or {}).get("structured_report") or {}).get("manager_decision") or {}
        if latest_report and previous_decision.get("decision") != "PASS":
            phase_reports = [row["structured_report"] for row in db.coding_phase_reports(task_id)
                             if row.get("phase_id") == current_phase.get("id")
                             and row.get("id") != latest_report.get("id")]
            resumed_evaluation = evaluate_phase(current_phase, latest_report["structured_report"],
                                                phase_reports, workspace_root)
            print(f"TASK_ID={task_id} RESUME_REEVALUATION=YES "
                  f"PHASE_ID={current_phase.get('id')} "
                  f"PHASE_EVALUATION_COMPLETE={'true' if resumed_evaluation.get('phase_complete') else 'false'} "
                  f"MISSING_MCP={json.dumps(resumed_evaluation.get('missing_mcp', []), ensure_ascii=False)}",
                  file=__import__('sys').stderr, flush=True)
            if resumed_evaluation.get("phase_complete"):
                promoted_report = dict(latest_report["structured_report"])
                promoted_report["phase_evaluation"] = resumed_evaluation
                promoted_report["manager_decision"] = {
                    "decision": "PASS",
                    "reason": "Persisted phase evidence satisfies the current deterministic evaluator",
                }
                db.update_coding_phase_report(latest_report["id"], promoted_report, "PASS")
                _set_subtask_state(task_id, current_phase['id'], 'DONE',
                    attempt=int(latest_report.get('attempt') or 0), report=promoted_report, decision='PASS')
                plan = _phase_status(plan, current_phase["id"], "pass")
                phases = plan.get("phases", phases)
                db.update_coding_task(task_id, plan=plan, recovery_action="NONE", recovery_reason="NONE",
                                      replan_count_in_epoch=0)
                managed = db.coding_task(task_id) or managed
                completed.add(current_phase["id"])
                print(f"TASK_ID={task_id} RESUME_REEVALUATION=PASS "
                      "NEXT_TASK_ACTION=CONTINUE_EXISTING_PLAN MODEL_REPAIR_CALL=SKIPPED",
                      file=__import__('sys').stderr, flush=True)
    # A human Resume from REPLAN_LIMIT starts a fresh bounded recovery epoch.
    # The saved terminal decision remains the authority for the first action:
    # perform the required replan before attempting another implementation.
    if managed.get("recovery_action") == "REPLAN_CONTINUATION" and managed.get("recovery_reason") == "REPLAN_LIMIT":
        print(f"TASK_ID={task_id} RECOVERY_EPOCH={managed.get('recovery_epoch',0)} "
              f"REPLAN_COUNT_IN_EPOCH={managed.get('replan_count_in_epoch',0)} "
              "NEXT_TASK_ACTION=QWEN_REPLANNING",file=__import__('sys').stderr,flush=True)
        resume_state = managed.get("resume_state") if isinstance(managed.get("resume_state"), dict) else {}
        reason = (resume_state.get("continuation_user_revision")
                  or "explicit human resume after REPLAN_LIMIT")
        return _replan_task(task_id,managed,completed,reason)
    if managed.get("recovery_action") == "REPLAN_CONTINUATION" and managed.get("recovery_reason") == "USER_REVISION":
        resume_state = managed.get("resume_state") if isinstance(managed.get("resume_state"), dict) else {}
        revision = (resume_state.get("continuation_user_revision")
                    or (managed.get("pending_authorization") or {}).get("user_revision")
                    or "user supplied phase revision")
        print(f"TASK_ID={task_id} NEXT_TASK_ACTION=QWEN_REPLANNING USER_REVISION_PRESENT=true",file=__import__('sys').stderr,flush=True)
        return _replan_task(task_id,managed,completed,revision)
    if (managed.get("recovery_action") == "REPLAN_CONTINUATION"
            and managed.get("recovery_reason") == "PHASE_FAILURE_CHECKPOINT"):
        resume_state = managed.get("resume_state") if isinstance(managed.get("resume_state"), dict) else {}
        checkpoint = resume_state.get("phase_failure_checkpoint") if isinstance(resume_state.get("phase_failure_checkpoint"), dict) else {}
        print(f"TASK_ID={task_id} PHASE_FAILURE_CHECKPOINT_RESUME=YES "
              f"PHASE_ID={checkpoint.get('phase_id', 'UNKNOWN')} "
              "NEXT_TASK_ACTION=QWEN_REPLANNING SAME_TASK_ID=YES",
              file=__import__('sys').stderr, flush=True)
        return _replan_task(task_id,managed,completed,"explicit resume after phase failure checkpoint",checkpoint)
    if managed.get('recovery_reason') == 'VERIFICATION_CONTENT_CHANGED':
        invalidated = set((managed.get('resume_state') or {}).get('verification_invalidated_phases') or [])
        return _replan_task(task_id, managed, completed - invalidated,
                            'Verified source bytes changed after testing. Preserve current implementation and plan read-only verification again; stale test results cannot establish completion.')
    if managed.get("recovery_action") == "FINAL_REPORT":
        # Persistence/formatting recovery must retain the same completion gate
        # as normal execution; a saved FINAL_REPORT action is not proof of PASS.
        return _complete_task(task_id, managed)
    for phase in phases:
        permission_wait = _coding_permission_wait(db.coding_task(task_id) or managed)
        if permission_wait is not None:
            return permission_wait
        steering_result = _apply_task_steering(task_id, db.coding_task(task_id) or managed)
        if steering_result is not None:
            return steering_result
        if phase["id"] in completed: continue
        if any(dep not in completed for dep in phase.get("dependencies",[])): continue
        if phase.get("kind") == "ORCHESTRATOR_BLUEPRINT":
            checkpoint = _finish_planning_boundary(task_id, plan, major_checkpoints)
            return checkpoint or _run_managed_task(task_id, workspace_root)
        if not phase_has_observable_deliverable(phase):
            print(f"TASK_ID={task_id} CONTROL_PLANE_INVARIANT_FAILURE=NON_ARTIFACT_PHASE_DISPATCH PHASE_ID={phase['id']}",file=__import__('sys').stderr,flush=True)
            db.update_coding_task(task_id,status="BLOCKED",activity="NONE",recovery_action="NONE",recovery_reason="NON_ARTIFACT_PHASE")
            return "Coding Task is blocked: orchestration-only work cannot enter implementation."
        if (db.coding_task(task_id) or {}).get("pause_requested"):
            _pause_at_checkpoint(task_id); return "Task paused."
        plan_revision=current_revision
        reports=_phase_reports_for_epoch(task_id, phase["id"], plan_revision, recovery_epoch)
        latest=reports[-1] if reports else None
        latest_evaluation = (latest["structured_report"].get("phase_evaluation")
                             if latest and isinstance(latest["structured_report"].get("phase_evaluation"), dict)
                             else {})
        latest_decision = (latest["structured_report"].get("manager_decision")
                           if latest and isinstance(latest["structured_report"].get("manager_decision"), dict)
                           else {})
        if (schedule_changed and latest and latest_decision.get('decision') in {'RETRY','REPLAN_REQUIRED'}
                and phase.get('execution_mode')=='IMPLEMENTATION'
                and phase.get('verify')==['Typed workspace writes and read-back succeed for the changed files.']
                and evaluate_phase(phase,latest['structured_report'],
                    [row['structured_report'] for row in reports[:-1]],workspace_root)['phase_complete']):
            # A corrected host schedule may move an unexecuted integration
            # condition to final acceptance. Reuse actual saved writes for
            # the remaining artifact facts instead of repeating source edits.
            decision=_review_phase(task_id,managed,phase,latest,
                [r['structured_report'] for r in db.coding_phase_reports(task_id) if r['phase_id'] in completed],workspace_root)
            if decision is None:return 'Task paused after updated phase evaluation.'
            latest=next(row for row in db.coding_phase_reports(task_id) if row['id']==latest['id'])
            latest_evaluation=latest['structured_report'].get('phase_evaluation') or {}
            latest_decision=latest['structured_report'].get('manager_decision') or {}
            print(f'TASK_ID={task_id} DEFERRED_PHASE_REEVALUATION={decision} SAVED_WRITES_REUSED=YES',file=__import__('sys').stderr,flush=True)
        verification_retry = bool(latest and latest_decision.get("decision") == "RETRY"
                                  and latest_decision.get("retry_channel") not in {None, "", "IMPLEMENTATION", "PACKAGE_INSTALL"}
                                  and latest_evaluation.get("phase_advance_eligible"))
        if latest and (not latest["structured_report"].get("manager_decision") or (
                latest_decision.get('decision') == 'REPLAN_REQUIRED'
                and int(latest.get('attempt') or 0) < _phase_retry_limit(phase, latest['structured_report'],
                    [row['structured_report'] for row in reports if row['id'] != latest['id']]))):
            decision=_review_phase(task_id,managed,phase,latest,[r["structured_report"] for r in db.coding_phase_reports(task_id) if r["phase_id"] in completed],workspace_root)
            if decision is None: return "Task paused after phase report."
            latest=next((row for row in db.coding_phase_reports(task_id) if row["id"] == latest["id"]), latest)
            latest_evaluation = latest["structured_report"].get("phase_evaluation") or {}
            latest_decision = latest["structured_report"].get("manager_decision") or {}
            verification_retry = bool(latest_decision.get("decision") == "RETRY"
                and latest_decision.get("retry_channel") not in {None, "", "IMPLEMENTATION", "PACKAGE_INSTALL"}
                and latest_evaluation.get("phase_advance_eligible"))
        stale_pass_report = bool(latest and phase.get('execution_mode') is not None
            and latest_decision.get('decision') == 'PASS'
            and not _saved_phase_pass_is_current(task_id,phase,latest,workspace_root))
        if stale_pass_report and phase.get('host_verification'):
            verification_retry = True
        if (latest and (verification_requested_by_user(str(managed.get('original_goal') or ''), managed.get('requirements') or {})
                        or phase.get('host_verification') or phase.get('verification_command') or phase.get('verify'))
                and any((operation.get('output') or {}).get('executor_error')
                        for operation in (latest['structured_report'].get('typed_execution_summary') or {}).get('operations') or [])):
            verification_retry = True
        if latest and latest["structured_report"].get("manager_decision",{}).get("decision") == "PASS" and not stale_pass_report:
            _set_subtask_state(task_id,phase["id"],"DONE",attempt=int(latest["attempt"]),report=latest["structured_report"],decision="PASS")
            completed.add(phase["id"]); plan=_phase_status(plan,phase["id"],"pass"); db.update_coding_task(task_id,plan=plan,activity="NONE",retry_count=0,recovery_action="NONE",recovery_reason="NONE"); continue
        # Reports may be filtered after an interrupted/invalid attempt. Never
        # reuse an attempt ID just because the active report list has a gap.
        attempt=max((int(row.get("attempt") or 0) for row in reports), default=-1) + 1
        latest_report=latest['structured_report'] if latest else {}
        latest_test_diagnosis=latest_report.get('project_test_diagnosis') or {}
        prior_project_test_claim=bool(latest and (
            latest_report.get('project_test_defect')
            or latest_test_diagnosis.get('evidence_origin')=='CURRENT_PROJECT_TEST_EXECUTION'))
        # A saved ownership label is only a hint to re-run the project's
        # command. It cannot authorize another write after the source or test
        # files may have changed; only a fresh preflight below can restore
        # project_test_recovery for this attempt.
        project_test_recovery=False
        current_project_test_diagnosis=None
        current_project_source_evidence=None
        current_project_tests_passed=False
        # Re-run every failed legacy project-test command against current bytes
        # before granting another write. A failure is not evidence that the
        # application is wrong: distinguish a repaired/flaky test, a test
        # harness defect, an invalid test oracle, and an application defect
        # before choosing a repair or allowing a replan.
        legacy_command=normalized_verification_argv(phase.get('verification_command'))
        should_reobserve_project_tests=bool(prior_project_test_claim or
            latest and _reported_project_test_failure(latest['structured_report'],legacy_command))
        if (verification_requested_by_user(str(managed.get('original_goal') or ''), managed.get('requirements') or {})
                and not phase.get('host_verification') and latest and should_reobserve_project_tests):
            if not is_project_test_command(legacy_command):
                _transition_resumable(task_id,'VERIFICATION_EXECUTOR','RECOVERABLE_INTERNAL',
                    'VERIFICATION_EXECUTOR_UNAVAILABLE',recovery_reason='VERIFICATION_EXECUTOR_UNAVAILABLE')
                return 'Coding Task paused: the saved project-test failure has no registered project-test command to re-run.'
            current_test=_run_read_only_verification(phase,workspace_root)
            if not current_test or current_test[1].get('executor_error'):
                _transition_resumable(task_id,'VERIFICATION_EXECUTOR','RECOVERABLE_INTERNAL',
                    'RECOVERY_REVIEW',recovery_reason='VERIFICATION_EXECUTOR_UNAVAILABLE')
                return 'Coding Task paused: current project-test executor is unavailable.'
            if current_test[1].get('passed'):
                # Historical failure ownership is stale when the unchanged
                # command now passes. Confirm it again read-only before phase
                # completion, without dispatching another implementation.
                verification_retry=True
                current_project_tests_passed=True
                project_test_recovery=True
            else:
                diagnosis=current_test[1].get('test_diagnosis') or {}
                if diagnosis.get('verdict')=='CHECK_DEFECT':
                    current_project_test_diagnosis={**diagnosis,
                        'project_test_setup_repair':diagnosis.get('project_test_setup_repair') is True}
                    project_test_recovery=True
                else:
                    # Assertion failures need an independent comparison with
                    # the original request. Never let a retry prompt turn an
                    # unreviewed test expectation into a production-code bug.
                    current_sources={}
                    root=Path(workspace_root).resolve()
                    for entry in plan.get('file_manifest') or []:
                        target=(root/str(entry.get('path') or '')).resolve()
                        if target.is_relative_to(root) and target.is_file():
                            current_sources[target.relative_to(root).as_posix()]=target.read_text(errors='replace')
                    current_criteria=acceptance_criteria(phase)
                    finding=_review_project_test_failures(task_id,str(managed.get('original_goal') or ''),
                        current_criteria,current_sources,current_test[1],
                        file_manifest=plan.get('file_manifest') or [])
                    source_paths=[path for path in finding.get('repair_paths') or []
                        if path in current_sources and not is_project_test_path(path)]
                    if finding.get('verdict')=='SOURCE_DEFECT' and source_paths:
                        current_project_source_evidence={'review':finding,'repair_paths':source_paths,
                            'failures':current_test[1].get('failures') or [],
                            'test_runs':current_test[1].get('test_runs') or []}
                        project_test_recovery=True
                    elif finding.get('verdict')=='CHECK_DEFECT':
                        paths=reviewed_project_test_paths(finding,current_sources)
                        if paths:
                            current_project_test_diagnosis={**finding,'repair_paths':paths,
                                'project_test_setup_repair':False}
                            project_test_recovery=True
                    if not current_project_source_evidence and not current_project_test_diagnosis:
                        reason=str(finding.get('reason') or 'No attributable requirement or source evidence was established.')
                        _record_verification_preparation_failure(task_id,phase['id'],RuntimeError(
                            'VERIFICATION_CONTRACT_INVALID: current project-test failure ownership is inconclusive; no files may be changed. '+reason))
                        _transition_resumable(task_id,'VERIFICATION_CONTRACT','RECOVERABLE_INTERNAL',
                            'RECOVERY_REVIEW',recovery_reason='VERIFICATION_CONTRACT_INVALID')
                        return 'Coding Task paused: the project-test failure could not be tied to an attributable requirement/source review; no files were changed.'
        retry_state = (db.coding_task(task_id) or {}).get("resume_state") or {}
        retry_grant = retry_state.get("ineffective_replan_retry_requested") or {}
        direct_phase_retry = bool(
            retry_grant.get("phase_id") == phase["id"]
            and retry_grant.get("plan_revision") == plan_revision
            and not retry_grant.get("consumed_at")
        )
        if latest:
            decision=latest["structured_report"].get("manager_decision",{}).get("decision")
            reason=latest["structured_report"].get("manager_decision",{}).get("reason","manager decision")
            if decision == "BLOCKED":
                _set_subtask_state(task_id,phase["id"],"FAILED",attempt=int(latest["attempt"]),report=latest["structured_report"],decision=decision)
                db.update_coding_task(task_id,status="BLOCKED",activity="NONE",
                                      recovery_reason=latest_decision.get("failure_class") or "BLOCKED")
                print(f"MANAGER_DECISION=BLOCKED NEXT_TASK_ACTION=STOP_BLOCKED TASK_STATUS=BLOCKED TASK_ACTIVITY=NONE",file=__import__('sys').stderr,flush=True)
                return "Coding Task is blocked: "+reason
            if decision == "NEED_USER":
                _set_subtask_state(task_id,phase["id"],"PARTIAL",attempt=int(latest["attempt"]),report=latest["structured_report"],decision=decision)
                db.update_coding_task(task_id,status="WAITING_FOR_USER",activity="NONE")
                return "Coding Task is waiting for user authorization: "+reason
            if decision == "REPLAN_REQUIRED" and not direct_phase_retry and not project_test_recovery:
                diagnosis=latest["structured_report"].get("manager_decision",{}).get("diagnosis")
                return _replan_task(task_id,managed,completed,reason,diagnosis)
        # A resumed task keeps its persisted attempt count and existing bounds.
        if latest and not project_test_recovery and not stale_pass_report and attempt > _phase_retry_limit(phase, latest['structured_report'],
                [row['structured_report'] for row in reports if row['id'] != latest['id']]) and not direct_phase_retry:
            return _replan_task(task_id,managed,completed,"retry limit reached",latest["structured_report"].get("manager_decision",{}).get("diagnosis"))
        retry_context=_bounded_review_context(latest["structured_report"]) if latest else None
        if retry_context:
            retry_context['stalled_acceptance']=_verification_repair_stalled([row['structured_report'] for row in reports])
            if retry_context['stalled_acceptance']:
                retry_context['previous_failed_repairs']=_failed_repair_history([row['structured_report'] for row in reports])
        if direct_phase_retry and retry_context:
            retry_context["diagnosis"]["retry_instruction"] = retry_grant["instruction"]
        if retry_context:
            previous=latest["structured_report"]
            previous_typed = previous.get("typed_execution_summary") if isinstance(previous.get("typed_execution_summary"), dict) else {}
            previous_failure = str(previous_typed.get("failure_class") or "")
            prior_attempt_progress = (previous.get("phase_progress") is True or
                                      int(previous.get("accepted_mutations") or previous_typed.get("accepted_mutations") or 0) > 0 or
                                      int(previous.get("files_written") or previous_typed.get("files_written") or 0) > 0)
            instruction = "" if prior_attempt_progress else zero_mutation_retry_instruction(
                phase, previous, [row["structured_report"] for row in reports[:-1]], workspace_root)
            # A phase may have made real progress and still need another
            # attempt.  In that case the old zero-write helper intentionally
            # returned nothing, which left the next Implementer without a
            # structured instruction to refresh its preimages.  Carry a
            # bounded diagnostic for all current-worktree-sensitive retries.
            if prior_attempt_progress or (not instruction and (previous_failure == "PREIMAGE_MISMATCH" or
                                     previous_typed.get("worktree_state") == "ROLLED_BACK")):
                instruction = (
                    "The previous attempt changed or inspected the authorized worktree but did not complete this phase. "
                    "Re-enumerate the current authorized files and rebuild every source hash and patch preimage from the live worktree before emitting operations. "
                    "Do not reuse old_text or context from an earlier attempt; preserve successful prior mutations and address the remaining Done/Verify criteria."
                )
                if previous_failure == "PREIMAGE_MISMATCH":
                    instruction += " " + patch_preimage_retry_instruction()
            if previous.get("implementation_result_kind") == "NARRATIVE_ONLY":
                instruction=("Do not describe future steps. Execute the current phase now using the available "
                             "repository/file tool protocol. Return one or more valid file operations and then "
                             "authoritative changed-file and verification evidence.")
            if previous_failure == "PACKAGE_JSON_OWNERSHIP_VIOLATION":
                instruction = (
                    "The previous typed operation was rejected as PACKAGE_JSON_OWNERSHIP_VIOLATION. "
                    "PACKAGE_INSTALL owns package.json dependency and devDependency declarations, and the package installation already passed. "
                    "Do not emit any patch or write operation for package.json dependencies or devDependencies; continue the remaining source/config work in the effective authorized scope. "
                    "Treat package installation evidence as preserved and do not repeat PACKAGE_INSTALL."
                )
            if instruction:
                retry_context["diagnosis"]["retry_instruction"]=instruction
                retry_context["diagnosis"]["specific_fix"]=instruction
            mutation_classification = str(previous_typed.get("mutation_classification") or previous.get("mutation_classification") or "")
            retry_cause = ("NARRATIVE_ONLY" if previous.get("implementation_result_kind") == "NARRATIVE_ONLY" else
                           "PACKAGE_JSON_OWNERSHIP_VIOLATION" if previous_failure == "PACKAGE_JSON_OWNERSHIP_VIOLATION" else
                           "IDEMPOTENT_NO_NET_CHANGE" if mutation_classification == "IDEMPOTENT_NOOP" and instruction else
                           "ZERO_WORKSPACE_MUTATION" if instruction else "PHASE_EVIDENCE_INCOMPLETE")
            print(f"RETRY_CAUSE={retry_cause} RETRY_INSTRUCTION_KIND={'EXECUTION_BINDING' if retry_cause == 'NARRATIVE_ONLY' else 'IDEMPOTENT_NO_NET_CHANGE' if retry_cause == 'IDEMPOTENT_NO_NET_CHANGE' else 'ZERO_MUTATION' if instruction else 'PRIOR_DIAGNOSIS'} PREVIOUS_WORKSPACE_MUTATION_COUNT={workspace_mutation_count(previous)}",file=__import__('sys').stderr,flush=True)
        context_payload={"phase_id":phase["id"],"plan_revision":plan_revision,"attempt":attempt,
                         "prior_review":retry_context} if retry_context else {"phase_id":phase["id"],"plan_revision":plan_revision,"attempt":attempt}
        previous_report = (latest or {}).get('structured_report') or {}
        repairing_verification=bool(phase.get('verification_repair_allowed') and previous_report.get('test_fail'))
        coding_model = _coding_phase_model(phase, task_goal=str(managed.get("original_goal") or ""),
                                          repairing_verification=repairing_verification)
        coding_diagnostic_model = coding_model
        implementation_handoff=False
        previous_typed_for_handoff = (previous_report.get('typed_execution_summary')
                                      if isinstance(previous_report.get('typed_execution_summary'), dict) else {})
        previous_mutation_class = str(previous_report.get('mutation_classification') or
                                      previous_typed_for_handoff.get('mutation_classification') or '')
        previous_made_progress = (
            int(previous_report.get('accepted_mutations') or previous_typed_for_handoff.get('accepted_mutations') or 0) > 0
            or int(previous_report.get('final_worktree_mutations') or previous_typed_for_handoff.get('final_worktree_mutations') or 0) > 0
            or previous_report.get('phase_progress') is True)
        stalled_short_model = (previous_report.get('implementation_model') == settings.short_coding_model
            and bool(previous_report.get('test_fail'))
            and (previous_mutation_class == 'IDEMPOTENT_NOOP' or not previous_made_progress
                 or bool((retry_context or {}).get('stalled_acceptance'))))
        previous_operations = (((latest or {}).get('structured_report') or {}).get('typed_execution_summary') or {}).get('operations') or []
        structural_output_failure=any(op.get('tool') == 'operation_application_failure'
               and ((op.get('output') or {}).get('operation_diagnostic') or {}).get('reason_subtype') == 'STRUCTURAL_VALIDATION_FAILED'
               for op in previous_operations if isinstance(op, dict))
        if stalled_short_model:
            coding_model = settings.long_implementation_model
            implementation_handoff=True
            cause=('STALLED_ACCEPTANCE_REPAIR' if (retry_context or {}).get('stalled_acceptance') else
                   'IDEMPOTENT_FAILED_REPAIR')
            print(f'TASK_ID={task_id} IMPLEMENTER_ROLE_HANDOFF={cause} MODEL_NAME={coding_model}',file=__import__('sys').stderr,flush=True)
        elif structural_output_failure:
            previous_model=str(previous_report.get('implementation_model') or coding_model)
            alternate=_alternate_coding_model(previous_model,managed.get('conversation_id'))
            if alternate:
                coding_model=alternate
                implementation_handoff=True
                cause='SOURCE_SYNTAX_REPAIR_DISTINCT_MODEL'
            else:
                _set_subtask_state(task_id,phase['id'],'FAILED',attempt=attempt,decision='RECOVERABLE_INTERNAL')
                _transition_resumable(task_id,'STRUCTURAL_REPAIR','RECOVERABLE_INTERNAL',
                    'RECOVERY_REVIEW',recovery_reason='STRUCTURAL_REPAIR_MODEL_UNAVAILABLE')
                return ('Coding Task paused: the last implementation output failed structural validation, '
                        'and no distinct configured coding model is available for a bounded repair.')
            print(f'TASK_ID={task_id} IMPLEMENTER_ROLE_HANDOFF={cause} '
                      f'PREVIOUS_MODEL={previous_model} MODEL_NAME={coding_model}',file=__import__('sys').stderr,flush=True)
        print(f"TASK_ID={task_id} PHASE_ID={phase['id']} PHASE_ATTEMPT={attempt} "
              f"RETRY_CONTEXT_PRESENT={'true' if retry_context else 'false'} "
              f"RETRY_INSTRUCTION_PRESENT={'true' if retry_context and retry_context['diagnosis'].get('retry_instruction') else 'false'} "
              f"IMPLEMENTATION_CONTEXT_FINGERPRINT={_context_fingerprint(context_payload)}",
              file=__import__('sys').stderr,flush=True)
        db.update_coding_task(task_id,status="RUNNING",activity="READ_ONLY_VERIFICATION" if verification_retry else "QWEN_IMPLEMENTATION",current_phase_id=phase["id"],retry_count=max(0,attempt-1),recovery_action="NONE",recovery_reason="NONE")
        _set_subtask_state(task_id,phase["id"],"RUNNING",attempt=attempt)
        print(f"TASK_ID={task_id} TASK_STATUS=RUNNING TASK_ACTIVITY={'READ_ONLY_VERIFICATION' if verification_retry else 'IMPLEMENTATION'} MODEL_SLOT_OWNER={task_id} MODEL_NAME={coding_model} PHASE_ID={phase['id']} PHASE_ATTEMPT={attempt}",file=__import__('sys').stderr,flush=True)
        phase_mcp=_phase_required_mcp(plan,phase["id"])
        mcp_context=[]
        for server_id in phase_mcp:
            persisted=db.coding_task(task_id) or {}
            evidence=next((item for item in reversed(persisted.get("mcp_evidence") or [])
                           if item.get("mcp_name") == server_id and item.get("status") == "PASS"
                           and str(item.get("tool_name") or "") not in _MCP_LIFECYCLE_ONLY_TOOLS),None)
            if evidence is None:
                preflight=(persisted.get("requirements") or {}).get("preflight") or {}
                if server_id == "shadcn" and preflight.get("shadcn") == "PASS":
                    print(f"TASK_ID={task_id} CONTROL_PLANE_INVARIANT_FAILURE=MCP_EVIDENCE_LOST REQUIRED_MCP=shadcn",file=__import__('sys').stderr,flush=True)
                    db.update_coding_task(task_id,status="BLOCKED",activity="NONE",recovery_action="NONE",recovery_reason="MCP_EVIDENCE_LOST")
                    _set_subtask_state(task_id,phase["id"],"FAILED",attempt=attempt,decision="BLOCKED")
                    return "Coding Task is blocked: persisted shadcn preflight evidence was lost."
                evidence,error=_run_required_mcp(task_id,server_id,workspace_root,
                                                 f"{'required' if server_id in _required_mcp_names(managed) else 'automatic animation reference'} by phase {phase['id']}")
                if error:
                    if server_id not in _required_mcp_names(managed):
                        # An automatic helper is advisory; its failed attempt is
                        # still typed evidence, but must not turn into a false
                        # required-MCP gate.
                        continue
                    db.update_coding_task(task_id,status="BLOCKED",activity="NONE",recovery_action="NONE",
                                          recovery_reason="REQUIRED_MCP_FAILED")
                    _set_subtask_state(task_id,phase["id"],"FAILED",attempt=attempt,decision="BLOCKED")
                    print(f"TASK_ID={task_id} REQUIRED_MCP={server_id} MCP_USAGE=FAILED "
                          f"MCP_FAILURE_REASON={error or 'UNKNOWN'} TASK_STATUS=BLOCKED",
                          file=__import__('sys').stderr,flush=True)
                    message = _required_mcp_failure_message(task_id, server_id, error or "UNKNOWN")
                    _add_task_message_once(managed["conversation_id"], task_id, message)
                    return message
            mcp_context.append(evidence)
        phase_dependency_records = phase.get("dependency_requirements") if isinstance(phase.get("dependency_requirements"), list) else []
        artifact_coverage = (implementation_artifact or {}).get("manifest_coverage") or {}
        artifact_dependency_records = artifact_coverage.get("dependency_requirement_records") or ((artifact_coverage.get("requirement_types") or {}).get("DEPENDENCY_REQUIREMENT_PROVENANCE") or [])
        # Phase ownership is the authorization boundary.  A global artifact
        # contract may contain dependencies for another phase, so never pass
        # the entire manifest list to the active Implementer.
        dependency_records = phase_dependency_records or [item for item in artifact_dependency_records
                                                           if isinstance(item, dict) and str(item.get("phase_id") or "") == str(phase.get("id"))]
        dependency_requirements = dependency_requirement_specs(dependency_records)
        package_install_operations = dependency_install_operations(dependency_records)
        package_install_required = phase.get("requires_dependency_installation") is True
        package_install_authorized = package_install_required and bool(dependency_requirements)
        package_install_satisfied, package_install_evidence, resume_package_state = _reconcile_package_install_resume(
            task_id, phase, plan_revision, workspace_root, dependency_records)
        # Keep the legacy report scan as a compatibility fallback for old task
        # rows whose workspace has not yet crossed the new resume boundary.
        if not package_install_satisfied and resume_package_state is None:
            package_install_satisfied = _phase_package_install_satisfied(task_id, phase["id"], plan_revision)
            package_install_evidence = _phase_package_install_evidence(task_id, phase["id"], plan_revision)
        package_json_config_mutation_allowed = bool(phase.get("package_json_config_mutation") is True)
        package_json_owner = "PACKAGE_INSTALL" if package_install_authorized else "NONE"
        package_json_mutation_classes = ["DEPENDENCY_DECLARATION", "DEV_DEPENDENCY_DECLARATION",
                                         "SCRIPT_CONFIGURATION", "PROJECT_METADATA", "OTHER_CONFIG"]
        package_json_dependency_mutation_allowed = not package_install_authorized
        skip_reason = ("ALREADY_PASS" if package_install_satisfied else
                       "NONE" if package_install_authorized else
                       "NO_CANONICAL_DEPENDENCY_REQUIREMENTS" if not dependency_records else
                       "PHASE_DEPENDENCY_INSTALLATION_NOT_REQUIRED")
        print(f"TASK_ID={task_id} PHASE_ID={phase['id']} CANONICAL_DEPENDENCY_COUNT={len(artifact_dependency_records)} "
              f"PHASE_DEPENDENCY_COUNT={len(dependency_records)} AUTHORIZED_PACKAGE_COUNT={len(dependency_requirements)} "
              f"AUTHORIZED_PACKAGES={json.dumps(dependency_requirements, ensure_ascii=False)}", file=__import__('sys').stderr, flush=True)
        print(f"TASK_ID={task_id} PHASE_ID={phase['id']} PACKAGE_INSTALL_CAPABILITY_DETECTED={'YES' if package_install_authorized else 'NO'} "
              f"PACKAGE_INSTALL_ACTION_PLANNED={'YES' if package_install_authorized and not package_install_satisfied else 'NO'} "
              f"PACKAGE_INSTALL_ALREADY_SATISFIED={'YES' if package_install_satisfied else 'NO'} "
              f"PACKAGE_INSTALL_SKIP_REASON={skip_reason}",
              file=__import__('sys').stderr, flush=True)
        print(f"TASK_ID={task_id} PHASE_ID={phase['id']} PACKAGE_JSON_DEPENDENCY_OWNER={package_json_owner} "
              f"DEPENDENCIES_ALREADY_SATISFIED={'YES' if package_install_satisfied else 'NO'} "
              f"PACKAGE_JSON_DEPENDENCY_MUTATION_ALLOWED={'YES' if package_json_dependency_mutation_allowed else 'NO'} "
              f"PACKAGE_JSON_EFFECTIVE_MUTATION_SCOPE={'CONFIG_ALLOWED' if package_json_config_mutation_allowed else 'DEPENDENCIES_EXCLUDED'}",
              file=__import__('sys').stderr, flush=True)
        phase_contract_metadata = {**phase, "required_mcp": phase_mcp,
                                   "package_manager_executor": ("AUTHORIZED_PACKAGE_MANAGER"
                                                                  if package_install_authorized
                                                                  else None),
                                   "authorized_package_requirements": dependency_requirements,
                                   "authorized_package_requirement_records": dependency_records,
                                   "package_install_operations": package_install_operations,
                                   "package_install_required": package_install_authorized,
                                   "package_install_satisfied": package_install_satisfied,
                                   "package_install_evidence": package_install_evidence,
                                   "package_json_dependency_owner": package_json_owner,
                                   "package_json_mutation_classes": package_json_mutation_classes,
                                   "package_json_dependency_mutation_allowed": package_json_dependency_mutation_allowed,
                                   "dependencies_already_satisfied": package_install_satisfied,
                                   "package_json_effective_mutation_scope": "EXCLUDE_PACKAGE_JSON_DEPENDENCY_DECLARATIONS" if package_install_authorized else "NORMAL_FILE_SCOPE"}
        phase_with_contract={**phase_contract_metadata,"execution_expectations":_phase_execution_expectations(phase_contract_metadata)}
        if current_project_test_diagnosis:
            current_test_diagnosis=current_project_test_diagnosis or {}
            phase_with_contract.update(host_project_test_defect=True,
                host_current_command_evidence={**current_test[1],'test_diagnosis':current_test_diagnosis},
                host_project_test_repair_paths=current_test_diagnosis['repair_paths'],
                host_project_test_setup_repair=current_test_diagnosis.get('project_test_setup_repair') is True,
                host_verification_current_source_reviewed=True,host_current_command_failure=True,
                verification_repair_allowed=True)
        if current_project_source_evidence:
            phase_with_contract.update(host_source_defect=True,host_source_defect_evidence=current_project_source_evidence,
                host_current_command_evidence=current_test[1],
                host_source_defect_repair_paths=current_project_source_evidence.get('repair_paths') or [],
                host_verification_current_source_reviewed=True,verification_repair_allowed=True)
            retry_context={**(retry_context or {}),'source_bound_repair':True,
                'reviewed_source_paths':current_project_source_evidence.get('repair_paths') or []}
        # Prepare and exercise the owned acceptance contract before choosing
        # read-only versus writable dispatch. A measured source contradiction
        # must enter the implementation path, even when the saved phase was
        # originally planned as verification-only.
        if phase.get('host_verification'):
            try:
                phase_with_contract = _host_verification_phase(task_id, phase_with_contract, plan, workspace_root)
            except VerificationExecutorError as exc:
                _record_verification_preparation_failure(task_id,phase['id'],exc)
                _transition_resumable(task_id,'VERIFICATION_EXECUTOR','RECOVERABLE_INTERNAL',
                                      'VERIFICATION_EXECUTOR_UNAVAILABLE')
                return 'Coding Task paused: verification executor is unavailable. ' + str(exc)
            except RuntimeError as exc:
                if not str(exc).startswith('VERIFICATION_CONTRACT_INVALID:'):
                    raise
                _set_subtask_state(task_id, phase['id'], 'FAILED', attempt=attempt)
                _record_verification_preparation_failure(task_id,phase['id'],exc)
                _transition_resumable(task_id, 'VERIFICATION_CONTRACT', 'RECOVERABLE_INTERNAL',
                                      'RECOVERY_REVIEW', recovery_reason='VERIFICATION_CONTRACT_INVALID')
                return 'Coding Task paused: executable checks could not be prepared. ' + str(exc)
            if _pause_at_checkpoint(task_id):
                return 'Task paused before verification.'
        # Bind the repair prompt after both legacy and host preflight have
        # selected the current failure. A saved generic file-container failure
        # cannot describe the exception just reproduced on current bytes.
        if phase_with_contract.get('host_project_test_defect'):
            observed=phase_with_contract.get('host_current_command_evidence') or {}
            finding=observed.get('test_diagnosis') or {}
            retry_context={**(retry_context or {}),'source_bound_repair':True,
                'project_test_setup_repair':bool(phase_with_contract.get('host_project_test_setup_repair')),
                'project_test_diagnosis':finding}
            if observed:
                case=finding.get('failure_case')
                retry_context['verification_failures']=([case] if case else project_test_review_cases(observed)[:1])
        elif phase_with_contract.get('host_source_defect'):
            evidence=phase_with_contract.get('host_current_command_evidence') or {}
            if evidence.get('test_runs'):
                finding=(phase_with_contract.get('host_source_defect_evidence') or {}).get('review') or {}
                case=finding.get('failure_case')
                retry_context={**(retry_context or {}),
                    'verification_failures':[case] if case else project_test_review_cases(evidence)[:1]}
        host_source_defect=bool(phase_with_contract.get('host_source_defect'))
        # Keep the first source contradiction as execution evidence even if
        # post-repair verification rebuilds phase_with_contract from fresh
        # source and clears transient host diagnostics.
        host_source_defect_evidence=phase_with_contract.get('host_source_defect_evidence')
        current_source_reviewed=bool(phase_with_contract.get('host_verification_current_source_reviewed'))
        verification_repair = _verification_repair_authorized(
            phase_with_contract, (latest or {}).get('structured_report') or {})
        if current_project_tests_passed and not host_source_defect and not phase_with_contract.get('host_project_test_defect'):
            verification_repair=False
            verification_retry=True
        if phase.get('host_verification') and current_source_reviewed and not verification_repair:
            verification_retry=True
        contract_failures = [failure for operation in (((latest or {}).get('structured_report') or {}).get('typed_execution_summary') or {}).get('operations') or []
                             for failure in (operation.get('output') or {}).get('failures') or []
                             if isinstance(failure, dict) and failure.get('contract_error') and not failure.get('executor_error')]
        if latest and not current_source_reviewed and not host_source_defect and any((operation.get('output') or {}).get('executor_error')
                for operation in (latest['structured_report'].get('typed_execution_summary') or {}).get('operations') or []):
            verification_repair = False
        if phase.get('host_verification') and contract_failures and not current_source_reviewed and not host_source_defect:
            # A check authoring error can first surface after a source repair.
            # Its ownership does not change because the phase attempt is >1.
            # Authoring probes and its bounded repair loop own this failure.
            # Historical bad checks must not permanently block an explicit
            # resume after the verifier itself has been repaired/upgraded.
            verification_repair = False
            phase_with_contract['host_contract_failure'] = json.dumps(contract_failures, ensure_ascii=False)
        if host_source_defect and verification_repair:
            verification_repair=True
            verification_retry=False
            # Initial measured defects use the short repair role. A stalled
            # repair/syntax handoff already selected above must survive the
            # fresh verifier review; otherwise every retry returns to the same
            # role whose ineffective edit caused the handoff.
            if not implementation_handoff:
                coding_model=settings.short_coding_model
                coding_diagnostic_model=coding_model
            print(f'TASK_ID={task_id} PHASE_ID={phase["id"]} OBSERVED_SOURCE_DEFECT=YES '
                  f'IMPLEMENTATION_REPAIR=REQUIRED CHECK_REAUTHORING=NO IMPLEMENTER_MODEL={coding_model}',
                  file=__import__('sys').stderr,flush=True)
        if verification_repair:
            verification_retry = False
            phase_contract_metadata = {**phase_contract_metadata, 'execution_mode': 'IMPLEMENTATION_AND_VERIFICATION'}
            phase_with_contract = {**phase_with_contract, **phase_contract_metadata,
                                   **{key:value for key,value in phase_with_contract.items()
                                      if key.startswith('host_') or key in ('verification_command','verification_targets')},
                                   'execution_expectations': _phase_execution_expectations(phase_contract_metadata)}
        if verification_retry:
            # Reuse the same phase contract and evidence, but route the next
            # attempt through the read-only verifier.  No Implementer call or
            # writable operation is allowed for this continuation.
            phase_contract_metadata = {**phase_contract_metadata,
                                       "execution_mode": "VERIFICATION_ONLY",
                                       "requires_repo_mutation": False,
                                       "requires_dependency_installation": False,
                                       "package_manager_executor": None,
                                       "authorized_package_requirements": [],
                                       "dependency_requirements": [],
                                       "file_manifest": [],
                                       "verification_executor": "READ_ONLY_VERIFICATION"}
            phase_with_contract = {**phase_with_contract, **phase_contract_metadata,
                                   **{key:value for key,value in phase_with_contract.items()
                                      if key.startswith('host_') or key in ('verification_command','verification_targets')},
                                   "execution_expectations": _phase_execution_expectations(phase_contract_metadata)}
            print(f"TASK_ID={task_id} PHASE_ID={phase['id']} VERIFICATION_CONTINUATION=YES "
                  f"NEXT_REQUIRED_EXECUTOR={latest_decision.get('retry_channel') or 'VERIFICATION'} "
                  "IMPLEMENTER_RETRY_REQUIRED=NO IMPLEMENTER_SKIPPED=YES",
                  file=__import__('sys').stderr, flush=True)
        expectations = phase_with_contract["execution_expectations"]
        print(f"TASK_ID={task_id} PHASE_ID={phase['id']} PHASE_EXECUTION_MODE={expectations.get('execution_mode') or 'LEGACY'} "
              f"PHASE_EXECUTION_MODE_SOURCE={expectations.get('execution_mode_source')} "
              f"PHASE_EXECUTION_MODE_VALID={'YES' if expectations.get('execution_mode_valid') else 'NO'} "
              f"IMPLEMENTER_REQUIRED={'YES' if expectations.get('requires_repo_mutation') else 'NO'}",
              file=__import__('sys').stderr, flush=True)
        executor_capability = phase_executor_capability(phase_with_contract)
        if not executor_capability["executable"]:
            missing = executor_capability["missing"]
            reason = "PHASE_EXECUTOR_CAPABILITY_MISMATCH"
            print(f"TASK_ID={task_id} PHASE_ID={phase['id']} PHASE_EXECUTOR_CAPABILITY=FAIL "
                  f"REQUIRED_NOT_RUN_IDS={json.dumps([item['kind'] for item in missing], ensure_ascii=False)} "
                  f"REQUIRED_NOT_RUN_KINDS={json.dumps([item['kind'] for item in missing], ensure_ascii=False)} "
                  f"REQUIRED_NOT_RUN_EXECUTOR_CAPABILITY={json.dumps([item['executor'] for item in missing], ensure_ascii=False)} "
                  "IMPLEMENTATION_DISPATCH=BLOCKED",
                  file=__import__('sys').stderr, flush=True)
            typed = {"state": "blocked", "error": reason, "failure_class": reason,
                     "worktree_state": "UNCHANGED", "operations": [], "phase_progress": False,
                     "required_not_run": missing}
            report = {"phase_id": phase["id"], "attempt": attempt, "plan_revision": plan_revision,
                      "recovery_epoch": recovery_epoch,
                      "attempt_id": f"{task_id}:{recovery_epoch}:{phase['id']}:{attempt}",
                      "execution_generation": f"recovery-epoch-{recovery_epoch}",
                      "execution_attempt_started": True, "execution_attempt_completed": True,
                      "status": "BLOCKED", "implemented": [], "changed_files": [],
                      "test_executed": [], "test_pass": [], "test_fail": [],
                      "build_executed": "NOT_RUN", "build_pass": "NOT_RUN",
                      "errors": [reason], "blockers": [reason], "risks": [],
                      "typed_execution_summary": typed, "execution_expectations": expectations,
                      "implementation_result_kind": "BLOCKED_EXECUTOR_CAPABILITY",
                      "attempted_mutations": 0, "accepted_mutations": 0, "rejected_mutations": 0,
                      "files_written": 0, "rolled_back_mutations": 0, "final_worktree_mutations": 0,
                      "phase_progress": False, "no_progress": True,
                      "manager_decision": {"decision": "BLOCKED", "reason": reason}}
            row = db.add_coding_phase_report(task_id, phase["id"], attempt, report, "PASS", time.time())
            _set_subtask_state(task_id, phase["id"], "FAILED", attempt=attempt, report=report, decision="BLOCKED")
            db.update_coding_task(task_id, status="BLOCKED", activity="NONE", recovery_action="NONE", recovery_reason=reason)
            return "Coding Task is blocked: the phase requires an executor capability that OLCR does not provide."
        animejs_context = ((db.coding_task(task_id) or {}).get("requirements") or {}).get("animejs_project")
        animejs_safety = ("Anime.js version evidence: " + json.dumps(animejs_context, ensure_ascii=False) + "\n"
                          if isinstance(animejs_context, dict) else "")
        # Carry bounded original requirements so generic phase goals do not
        # erase requested behavior. The persisted file scope remains the
        # authorization boundary for the JSON file-operation executor.
        execution_artifact = implementation_artifact
        read_context = _read_only_context(workspace_root, managed.get('approved_scopes', []))
        if implementation_artifact and phase_with_contract.get('host_project_test_defect'):
            repair_paths=set(phase_with_contract.get('host_project_test_repair_paths') or [])
            manifest=implementation_artifact.get('file_manifest') or []
            owned=[entry for entry in manifest if entry.get('path') in repair_paths and is_project_test_path(entry.get('path',''))]
            if not owned:
                _transition_resumable(task_id,'PROJECT_TEST_REPAIR','RECOVERABLE_INTERNAL','RECOVERY_REVIEW',recovery_reason='PROJECT_TEST_REPAIR_SCOPE_UNAVAILABLE')
                return 'Coding Task paused: project-test repair has no approved test-file scope.'
            execution_artifact={**implementation_artifact,'file_manifest':owned}
            read_context['manifest_dependency_paths']=[entry['path'] for entry in manifest if entry not in owned and entry.get('path')]
        if implementation_artifact and phase_with_contract.get('host_source_defect'):
            repair_paths=set(phase_with_contract.get('host_source_defect_repair_paths') or [])
            manifest=implementation_artifact.get('file_manifest') or []
            owned=[entry for entry in manifest if entry.get('path') in repair_paths
                and not is_project_test_path(entry.get('path',''))]
