        typed_report = report.get("typed_execution_summary") if isinstance(report.get("typed_execution_summary"), dict) else {}
        print(f"TASK_ID={task_id} PHASE_ID={phase['id']} MUTATION_ATTEMPTED_OPERATIONS={typed_report.get('attempted_mutations', 0)} "
              f"MUTATION_SUCCESSFUL_OPERATIONS={typed_report.get('successful_operation_count', 0)} "
              f"MUTATION_ACCEPTED_COUNT={typed_report.get('accepted_mutations', 0)} "
              f"MUTATION_NET_CHANGED_PATH_COUNT={typed_report.get('net_changed_mutation_count', 0)} "
              f"MUTATION_UNCHANGED_OPERATION_COUNT={typed_report.get('unchanged_operation_count', 0)} "
              f"MUTATION_ROLLED_BACK_COUNT={typed_report.get('rolled_back_mutations', 0)} "
              f"MUTATION_CLASSIFICATION={typed_report.get('mutation_classification', 'UNKNOWN')}",
              file=__import__('sys').stderr, flush=True)
        # A planner may legally combine an implementation criterion with a
