                        mcp_evidence=mcp_context,test_executed=[' '.join(post_verification[1]['command'])],
                        test_pass=[' '.join(post_verification[1]['command'])+' (executed checks passed; acceptance incomplete)'],
                        verification_preparation_error=str(exc)[:4000],
