        label = labels.get(operation, "計算結果")
        expression = format_latex(data.get("expression"))
        value = format_latex(data.get("result"))
        subject = f"${expression}$ の" if expression else ""
        response = f"{subject}{label}は、\n$$\n{value}\n$$\nです。"
