@app.get("/api/maps/reverse")
def map_reverse(lat: float = Query(ge=-90, le=90), lon: float = Query(ge=-180, le=180)):
    if not capability_enabled(settings, "external_access_enabled"):
        raise HTTPException(403, "EXTERNAL_ACCESS_REQUIRED")
    if not __import__('math').isfinite(lat) or not __import__('math').isfinite(lon):
        raise HTTPException(422, "MAP_COORDINATES_INVALID")
    try:
        return reverse_place(round(lat, 5), round(lon, 5))
    except (ValueError, __import__('httpx').HTTPError):
        raise HTTPException(502, "MAP_PLACE_LOOKUP_FAILED")


def _chat_assistant_action(value: ChatInput, intent: dict):
    from .response_language import response_language
    conversation_id, _, _ = _resolve_chat_context(value)
    service = get_assistant_service()
    if value.client_time_zone:
        from .assistant_actions import timezone, ActionError
        try:
            timezone(value.client_time_zone)
        except ActionError:
            raise HTTPException(422,'CALENDAR_TIMEZONE_INVALID')
        intent={**intent,'time_zone':value.client_time_zone}
    source_id = value.message_id or str(uuid.uuid4())
    with service.turn_lock(conversation_id):
        result = service.handle(intent, conversation_id, source_id, response_language())
        for role, content, blocks in [('user', value.message, None),
                                      ('assistant', result['response'], result['blocks'])]:
            message_id = uuid.uuid5(uuid.NAMESPACE_URL, conversation_id + ':' + source_id + ':' + role).hex
            with db.connect() as con:
                exists = con.execute('SELECT 1 FROM messages WHERE id=?', (message_id,)).fetchone()
            if not exists:
                db.add_message(conversation_id, role, content, time.time(), message_id, blocks=blocks)
    return {'conversation_id': conversation_id, 'response': result['response'], 'blocks': result['blocks'], 'sources': []}


def _knowledge_youtube_supplement(question: str, answer: str, conversation_id: str, *, knowledge: bool = False):
    """Attach a YouTube internal-player card only for an explicit request or a matched work title."""
    from .knowledge_media import remove_youtube_links, youtube_links, youtube_query_for_knowledge
    from .assistant_integrations import search_youtube, video_id

    query = youtube_query_for_knowledge(question, answer)
    links = youtube_links(answer) if knowledge or query else []
    if not query and not links:
        return answer, []
    if not capability_enabled(settings, "external_access_enabled"):
        return answer, []

    candidates = []
    try:
        if links:
            for label, url in links:
                ident = video_id(url)
                if ident:
                    candidates.append({"id": ident, "title": label or "YouTube", "url": url})
        if query and not candidates:
            service = get_assistant_service()
            service.network()
            candidates = search_youtube(query, service.youtube_key)
    except Exception:
        # A supplementary media lookup must never replace or fail the answer.
        return answer, []
    if not candidates:
        return answer, []

    response = remove_youtube_links(answer) if links else answer
    ident = str(uuid.uuid4())
    return response, [{"type": "assistant_action", "kind": "media", "id": ident,
                       "conversation_id": conversation_id, "created_at": time.time(),
                       "query": query or "", "candidates": candidates[:5], "autoplay": False}]


def _assistant_intent(value):
    if any((value.attachment, value.image, value.concept_diagram, value.location_map, value.computer_use_event)):
        return None
    from .action_followups import previous_action,followup_intent
    if value.conversation_id:
        contextual=followup_intent(value.message,previous_action((db.conversation(value.conversation_id) or {}).get('messages',[])))
        if contextual:return contextual
    intent = action_intent(value.message)
    if intent or not value.conversation_id:
        return intent
    latest = (db.conversation(value.conversation_id) or {}).get('messages', [])[-1:]
    blocks = latest[0].get('blocks', []) if latest and latest[0].get('role') == 'assistant' else []
    previous = next((b for b in reversed(blocks or []) if b.get('type') == 'assistant_action'), None)
    if not previous:
        return None
    text = value.message.strip().rstrip('。.!！')
    if previous.get('kind') == 'calendar_action' and re.fullmatch(r'はい|それで(?:登録|変更|削除)して|確認したので(?:登録|変更|削除)して|yes|confirm(?: it)?|go ahead', text, re.I):
        action = previous.get('action') or {}
        if action.get('status') == 'pending':
            return {'service': 'calendar', 'text': text, 'confirm': action['id'], 'revision': action['revision']}
    if previous.get('kind') == 'calendar_action' and re.fullmatch(r'やめて|取り消して|キャンセル|cancel|never mind', text, re.I):
        action = previous.get('action') or {}
        if action.get('status') == 'pending':
            return {'service': 'calendar', 'text': text, 'cancel': action['id'], 'revision': action['revision']}
    if re.fullmatch(r'一時停止(?:して)?|停止(?:して)?|止めて|再開(?:して)?|残り(?:は)?|pause|stop|cancel|resume|how much time is left\??', text, re.I):
        if previous.get('kind') == 'timers':
            return action_intent(('アラーム ' if any(t.get('kind')=='alarm' for t in previous.get('timers',[])) else 'タイマー ') + text)
        if previous.get('kind') in {'media', 'media_control'}:
            return action_intent('YouTube ' + text)
    return None


def _explicit_knowledge_video_request(text: str) -> bool:
    from .knowledge_media import explicit_knowledge_video_request
    return explicit_knowledge_video_request(text)


_coding_skill_invocation = ContextVar('olcr_coding_skill_invocation', default=None)


def _lexical_chat_request_intent(value: ChatInput):
    """Resolve deterministic ownership without invoking contextual model routing.

    Specialist handlers (medication, symptoms, product help and typed
    workflows) must get the first chance to own their requests.  The
    contextual assistant-action classifier is only needed after those owners
    decline the turn.
    """
    project_id=value.project_id or ((db.conversation(value.conversation_id) or {}).get('project_id') if value.conversation_id else None)
    project=db.project(project_id) if project_id else None
    return resolve_request_intent(value.message,
        project_scoped=bool((project or {}).get('workspace_path') or (value.attachment or {}).get('kind')=='folder'),
        attachment_present=bool(value.image or value.attachment),execution_intent=value.execution_intent)


def _chat_request_intent(value: ChatInput):
    result = _lexical_chat_request_intent(value)
    # Explicit software work owns the request before follow-up/domain-action
    # heuristics run. Calling the assistant router here let unrelated actions
    # throw or capture a coding request before the orchestrator could create
    # its task.
    if (re.match(r'^\s*/skill(?:\s|$)',value.message) or
            result.owner in {'CODING','CLARIFY_CODING','COMMAND'} or _coding_skill_invocation.get()):
        return result
    contextual=_assistant_intent(value)
    if contextual and contextual.get('followup'):
        from .request_intent import RequestIntent
        return RequestIntent('ASSISTANT_ACTION',{**result.facts,'reason':'CONTEXTUAL_ACTION_FOLLOWUP'})
    return result


def _is_explicit_coding_request(value: ChatInput, intent=None) -> bool:
    """Keep workflow slash controls on their owner instead of ordinary inference."""
    request_intent = intent or _chat_request_intent(value)
    if request_intent.owner in {"CODING", "CLARIFY_CODING"}:
        return True
    if request_intent.owner != "COMMAND":
        return False
    # /workflow is a typed confirmation/cancellation namespace; other slash
    # commands retain the command/coding ingress boundary.
    return not bool(re.match(r"^\s*/workflow(?:\s|$)", value.message, re.I))


def _is_explicit_scrape_control(value: ChatInput) -> bool:
    """Route a scrape control only when this chat contains a scrape task.

    Short Japanese controls such as ``再開して`` are shared with timers and
    other assistant actions, so the text classifier alone cannot establish
    ownership.
    """
    if value.attachment or value.image or not chat_scrape_control(value.message) or not value.conversation_id:
        return False
    conversation = db.conversation(value.conversation_id) or {}
    return any(isinstance(block, dict) and block.get('type') == 'scrape_task'
               for message in conversation.get('messages') or []
               for block in message.get('blocks') or [])


def _skill_coding_requested(text: str) -> bool:
    match=re.match(r'^\s*/skill\s+\S+\s+([\s\S]+)$',text)
    return bool(settings.task_manager_enabled and match and
                resolve_request_intent(match.group(1)).blocks_external_answer)


def _coding_skill_context(managed: dict) -> str:
    pinned=(managed.get('requirements') or {}).get('explicit_skill') or {}
    return str(pinned.get('context') or '')


def _chat_explicit_skill(value: ChatInput):
    # Attach a chosen folder before resolving Skill execution scope, just as
    # normal chat does. Never silently discard other attachment types.
    conversation_id, project_id, _ = _resolve_chat_context(value)
    if isinstance(value.attachment, dict) and value.attachment.get('kind') == 'folder':
        from .working_folders import WorkingFolders
        try:
            WorkingFolders(db).attach(conversation_id, value.attachment)
        except (OSError, ValueError) as exc:
            raise HTTPException(422, str(exc)) from exc
    elif value.attachment or value.image or value.concept_diagram or value.location_map:
        raise HTTPException(422, "SKILL_REQUIRES_TEXT_OR_WORKING_FOLDER")
    if _skill_coding_requested(value.message):
        name,prompt=value.message.strip().split(maxsplit=2)[1:]
        try:
            loaded=skills.load(name)
        except SkillPolicyError as exc:
            raise HTTPException(422,'SKILL_NOT_INSTALLED_OR_ENABLED' if str(exc)=='SKILL_NOT_FOUND' else str(exc)) from exc
        from .explicit_skills import invocation
        workspace_root=(task_workspaces.service.conversation_root(conversation_id)
                        or (db.project(project_id) or {}).get('workspace_path'))
        try:
            request,context=invocation(loaded,prompt,db.conversation(conversation_id),workspace_root,runtime.context_budget())
        except (OSError,ValueError) as exc:
            raise HTTPException(422,'SKILL_WORKSPACE_UNAVAILABLE') from exc
        token=_coding_skill_invocation.set({'name':name,'context':context,
            'content_hash':loaded['skill'].get('content_hash'),'command':value.message})
        try:
            return chat(value.model_copy(update={'message':request,'conversation_id':conversation_id,'project_id':project_id}))
        finally:
            _coding_skill_invocation.reset(token)
    result = execute_command(CommandInput(text=value.message, project_id=project_id or None,
                                          conversation_id=conversation_id))
    execution = result['data']['execution']
    return {'conversation_id': result['conversation_id'], 'response': result['message'],
            'task': {'id': execution['task_id'], 'state': execution['state'], 'route': execution['route']},
            'blocks': result['blocks'], 'sources': result['sources']}


def _operation_help_response(value: ChatInput):
    from .operation_help import requested, answer, identity_response
    if value.image or value.attachment or value.concept_diagram or value.location_map:
        return None
    # Help topics overlap with ordinary language ("use a Skill", "search for
    # a function", "search YouTube videos"). Explicit operations and local
    # source requests must reach their owning path before docs are matched.
    explicit_action = bool(re.search(
        r"(?:検索|探し|見つけ|再生|流し|かけ|停止|一時停止|登録|追加|削除|設定|開始|変更|キャンセル|予約)"
        r"(?:して|してください|願います|する|します|しろ)|"
        r"\b(?:search|find|play|pause|stop|register|add|delete|set|start|change|cancel|schedule)\b",
        value.message, re.I,
    ))
    if (_requests_automatic_skill_selection(value.message)
            or _requests_source_code_inspection(value.message)
            or (action_intent(value.message) is not None and explicit_action)
            or _explicit_knowledge_video_request(value.message)):
        return None
    identity = identity_response(value.message, response_language())
    if identity is None and not requested(value.message):
        return None
    result = ({"response": identity, "sources": []} if identity is not None
              else answer(value.message, response_language()))
    conversation_id,_,_=_resolve_chat_context(value)
    task=Task(value.message);task.route=Route.RETRIEVAL
    task.transition(TaskState.ROUTING);task.transition(TaskState.SEARCHING)
    task.selected_context=[{"source":item['source'],"line":item['line'],"graphify":item['graphify']} for item in result['sources']]
    task.transition(TaskState.COMPLETED);db.save_task(task,conversation_id)
    db.add_message(conversation_id,'user',value.message,time.time(),value.message_id or str(uuid.uuid4()))
    db.add_message(conversation_id,'assistant',result['response'],time.time(),str(uuid.uuid4()),task.id)
    return {**result,'conversation_id':conversation_id,'task':serialize_task(task)}


