def _mail_workflow_stream(engine, value):
    def emit(event):
        return 'data: '+json.dumps(event,ensure_ascii=False)+'\n\n'
    conversation_id=value.conversation_id
    if not conversation_id:
        conversation_id,_,_=_resolve_chat_context(value)
        value=value.model_copy(update={'conversation_id':conversation_id})
    def stream():
        yield emit({'type':'meta','conversation_id':conversation_id,'task_id':None})
        confirmation=engine.is_mail_confirmation(value)
        status=('Apple Mailへ送信を依頼しています。応答を待っています。' if confirmation
                else 'メールの本文案を作成しています。')
        yield emit({'type':'reasoning_delta','reasoning':{'kind':'status','text':status,'complete':True,'truncated':False}})
        result=engine.respond(value,_resolve_chat_context)
        if result is None:
            yield emit({'type':'error','message':'MAIL_WORKFLOW_NOT_HANDLED'})
            return
        block=next((b for b in result.get('blocks',[]) if b.get('type')=='assistant_workflow'),None)
        if block:
            if block.get('status')=='error' and confirmation:status='送信結果を確認してください。送信済みを確認し、自動再送はしません。'
            elif block.get('status')=='error':status='メールの準備を完了できませんでした。内容と接続状態を確認してください。'
            elif block.get('status')=='review':status='メールの下書きができました。宛先と本文を確認してください。'
            elif block.get('title')=='送信依頼済み':status='Apple Mailが送信依頼を受け付けました。'
            else:status='メールの処理が完了しました。'
            yield emit({'type':'reasoning_delta','reasoning':{'kind':'status','text':status,'complete':True,'truncated':False}})
        yield emit({'type':'chunk','text':result['response']})
        for result_block in result.get('blocks',[]):
            yield emit({'type':'block','block':result_block})
        yield emit({'type':'done','conversation_id':result['conversation_id'],'response_owner':'ASSISTANT_WORKFLOW'})
    return stream()


_travel_booking_services={}
_travel_booking_services_lock=threading.RLock()


def _travel_booking_service():
    from .permissions import capability_enabled
    from .travel_bookings import ManagedBrowserTravelProvider, TravelBookingService
    key=str(db.path)
    with _travel_booking_services_lock:
        service=_travel_booking_services.get(key)
        if service is None:
            def permission_check():
                if not capability_enabled(settings,'external_access_enabled'):
                    raise ValueError('TRAVEL_BOOKING_PERMISSION_DENIED')
            provider=ManagedBrowserTravelProvider(browser_sessions,permission_check=permission_check)
            service=TravelBookingService(db,{'managed-browser':provider},permission_check=permission_check)
            _travel_booking_services[key]=service
        return service


def _chat_trip(value: ChatInput, progress=None):
    from .trip_planning import TripPlanner, collect_evidence
    if value.conversation_id:
        from .custom_agents import AgentStore
        if AgentStore(db).bound(value.conversation_id):
            return None
    def generate(instructions, payload, schema):
        if _personal_tasks.db.path == db.path:
            instructions += '\n'+_personal_tasks.profile_context()
        from .brain_models import brain_scope
        from .coding_tasks import model_slot
        with brain_scope(brain_models.configuration(value.conversation_id)), model_slot():
            result = runtime._generate_brain([
                {'role':'system','content':instructions},
                {'role':'user','content':json.dumps(payload,ensure_ascii=False)}],
                value.message, structured_schema=schema.model_json_schema(),
                model_name='role:normal_chat', max_tokens=12000, thinking_override=False)
        return json.loads(result['text'])
    planner = TripPlanner(db, generate, lambda brief: collect_evidence(brief, settings),_travel_booking_service())
    return planner.respond(value, _resolve_chat_context,progress=progress)


def _travel_booking_chat_stream(value: ChatInput):
    from queue import Empty, Queue
    import threading as _threading
    queue=Queue()
    def worker():
        try:
            result=_chat_trip(value,progress=lambda status:queue.put(('status',status)))
            queue.put(('result',result))
        except Exception:queue.put(('error','旅行予約の処理に失敗しました。予約先の状態を確認してください。'))
    thread=_threading.Thread(target=worker,name='olcr-travel-booking-chat',daemon=True)
    thread.start()
    yield 'data: '+json.dumps({'type':'meta','conversation_id':value.conversation_id,'task_id':None})+'\n\n'
    while thread.is_alive() or not queue.empty():
        try:kind,payload=queue.get(timeout=0.25)
        except Empty:continue
        if kind=='status':
            yield 'data: '+json.dumps({'type':'reasoning_delta','reasoning':{'kind':'status','text':payload,'complete':False,'truncated':False}},ensure_ascii=False)+'\n\n'
        elif kind=='error':
            yield 'data: '+json.dumps({'type':'error','message':payload},ensure_ascii=False)+'\n\n'
            return
        else:
            if payload is None:
                yield 'data: '+json.dumps({'type':'error','message':'TRAVEL_BOOKING_NOT_HANDLED'})+'\n\n'
                return
            yield 'data: '+json.dumps({'type':'chunk','text':payload['response']},ensure_ascii=False)+'\n\n'
            for block in payload.get('blocks',[]):
                yield 'data: '+json.dumps({'type':'block','block':block},ensure_ascii=False)+'\n\n'
            yield 'data: '+json.dumps({'type':'done','conversation_id':payload['conversation_id'],'response_owner':'TRIP_PLANNING'})+'\n\n'
            return


def _is_travel_booking_stream_turn(value: ChatInput) -> bool:
    from .trip_planning import TripPlanner, booking_confirmation, booking_intent
    state=None
    if value.conversation_id:
        try:state=TripPlanner(db,lambda *_:None,lambda *_:([],[],[])).state(value.conversation_id)
        except Exception:state=None
    if booking_intent(value.message,state):return True
    if value.conversation_id and booking_confirmation(value.message):
        try:return _travel_booking_service().latest_review(value.conversation_id) is not None
        except Exception:return False
    return False


@app.post("/api/chat")
def chat(value: ChatInput):
    # Audio ingress owns audio attachments before any Brain/request-intent
    # routing. Besides avoiding needless classifier work, malformed audio
    # payloads must be rejected before a model route can observe the turn.
    audio_result = _chat_audio_file(value)
    if audio_result is not None:
        return audio_result
    explicit_scrape_control = _is_explicit_scrape_control(value)
    # Resolve explicit software work before any specialist chat handler.  A
    # coding request can contain words such as "E2E", "trip", or "create";
    # letting an unrelated workflow inspect it first can consume the turn
    # before Coding Task Manager gets a chance to own it.
    early_request_intent = _lexical_chat_request_intent(value)
    explicit_coding_request = _is_explicit_coding_request(value, early_request_intent)
    workflow_result = None if (explicit_coding_request or explicit_scrape_control) else _chat_assistant_workflow(value)
    if workflow_result is not None:
        return workflow_result
    trip_result = None if (explicit_coding_request or explicit_scrape_control) else _chat_trip(value)
    if trip_result is not None:
        return trip_result
    medication_result = None if (explicit_coding_request or explicit_scrape_control) else _chat_medication(value)
    if medication_result is not None:
        return medication_result
    symptom_result = (None if (explicit_coding_request or explicit_scrape_control) else
                      symptom_chat_response(db, value, _resolve_chat_context, _symptom_chat))
    if symptom_result is not None:
        return symptom_result
    help_result=None if (explicit_coding_request or explicit_scrape_control) else _operation_help_response(value)
    if help_result is not None: return help_result
    request_intent=_chat_request_intent(value)
    if not request_intent.blocks_external_answer and not explicit_scrape_control:
        from .connector_chat import intent as connector_intent, handle as connector_handle
        from .service_connectors import ConnectorError
        try:
            connector_request=connector_intent(value.message)
            if connector_request:
                return connector_handle(db,value,connector_request,get_service_connectors(),_resolve_chat_context)
        except ConnectorError as exc:
            raise HTTPException(422,str(exc)) from None
    if re.match(r"^\s*/skill(?:\s|$)", value.message):
        return _chat_explicit_skill(value)
    knowledge_video_request = (not explicit_scrape_control and not request_intent.blocks_external_answer
                               and _explicit_knowledge_video_request(value.message))
    everyday = (None if explicit_scrape_control or request_intent.blocks_external_answer or knowledge_video_request or
                _coding_skill_invocation.get() else _assistant_intent(value))
    if everyday:
        return _chat_assistant_action(value, everyday)
    _API_ROUTING_TRACE.set(None)
    from .agent_builder import requested as builder_requested, handle_builder
    if not explicit_scrape_control and not request_intent.blocks_external_answer and builder_requested(db,value):
        conversation_id, _, _ = _resolve_chat_context(value)
        try:
            from .brain_models import brain_scope
            with brain_scope(brain_models.configuration(conversation_id)):
                return handle_builder(_custom_agent_host(),value,conversation_id)
        except ValueError as exc:
            raise HTTPException(422,str(exc)) from exc
    from .file_conversion import conversion_target
    target = None if (explicit_scrape_control or request_intent.blocks_external_answer) else conversion_target(value.message)
    if target:
        return _chat_file_conversion(value, target)
    if not explicit_scrape_control and not request_intent.blocks_external_answer and value.conversation_id and AgentStore(db).bound(value.conversation_id):
        return agent_chat(_custom_agent_host(),value)
    print("GUI_CHAT_BACKEND_RECEIVED=true", file=__import__("sys").stderr, flush=True)
    control = None if explicit_scrape_control or request_intent.blocks_external_answer or value.attachment or value.image or value.concept_diagram or value.location_map else workspace_command(value.message)
    if control:
        result = execute_command(CommandInput(text=value.message, project_id=value.project_id,
                                              conversation_id=value.conversation_id))
        return {"conversation_id": result["conversation_id"], "response": result["message"],
                "blocks": result["blocks"], "sources": []}
    conversation_id, project_id, existing = _resolve_chat_context(value)
    if value.message_id:
        prior=db.coding_task_for_source_message(value.message_id)
        if prior:
            response=""
            print(f"CODING_TASK_IDEMPOTENT_HIT=true CODING_TASK_ID={prior['id']} NORMAL_RUNTIME_FALLBACK=false",file=__import__('sys').stderr,flush=True)
            return {"conversation_id":conversation_id,"coding_task_id":prior["id"],"response":response,"sources":[]}
    print("GUI_CHAT_VALIDATION=PASS GUI_CHAT_PROJECT_RESOLUTION=PASS GUI_CHAT_CONVERSATION_RESOLUTION=PASS", file=__import__("sys").stderr, flush=True)
    from .chat_attachments import ChatAttachments
    attachment_service = ChatAttachments(db)
    try:
        attachment, working_folder = attachment_service.prepare(conversation_id, value.attachment)
    except (OSError, ValueError, TypeError) as exc:
        raise HTTPException(422, str(exc)) from exc
    value = value.model_copy(update={'attachment': attachment})
    working_root = working_folder['root'] if working_folder else (db.project(project_id) or {}).get('workspace_path')
    source_message_id=value.message_id or str(uuid.uuid4())
    if value.message_id:
        prior_scrape = next((block for message in existing.get("messages", [])
            for block in (message.get("blocks") or [])
            if isinstance(block, dict) and block.get("type") == "scrape_task"
            and block.get("source_message_id") == value.message_id), None)
        if prior_scrape is not None:
            print(f"CHAT_SCRAPE_IDEMPOTENT_HIT=true SOURCE_MESSAGE_ID={value.message_id} "
                  f"RUN_ID={prior_scrape.get('run_id') or ''}", file=__import__('sys').stderr, flush=True)
            return {"conversation_id": conversation_id,
                    "response": "このチャット指示のスクレイプタスクは既に開始済みです。既存のタスクを表示します。",
                    "blocks": [prior_scrape], "sources": []}
        prior_local_e2e = next((block for message in existing.get("messages", [])
            for block in (message.get("blocks") or [])
            if isinstance(block, dict) and block.get("type") == "local_e2e_task"
            and block.get("source_message_id") == value.message_id), None)
        if prior_local_e2e is not None:
            return {"conversation_id": conversation_id,
                    "response": "このチャット指示のローカルE2Eは既に開始済みです。既存のタスクを表示します。",
                    "blocks": [prior_local_e2e], "sources": []}
        prior_computer_use = next((block for message in existing.get("messages", [])
            for block in (message.get("blocks") or [])
            if isinstance(block, dict) and block.get("type") == "computer_use_task"
            and block.get("source_message_id") == value.message_id), None)
        if prior_computer_use is not None:
            return {"conversation_id": conversation_id,
                    "response": "このComputer Use指示は既に記録済みです。",
                    "blocks": [prior_computer_use], "sources": []}
    attachment_meta=value.image if isinstance(value.image,dict) else value.attachment if isinstance(value.attachment,dict) else None
    image_request = isinstance(value.image, dict)
    user_blocks=([{"type":"attachment","name":str(attachment_meta.get("name") or "attachment")[:200],
                   "mime_type":str(attachment_meta.get("mime_type") or attachment_meta.get("mimeType") or "application/octet-stream")[:120],
                   **({'kind': 'folder', 'folder_id': working_folder['id'], 'root': working_folder['root']}
                      if working_folder and attachment_meta.get('kind') == 'folder' else {})}]
                 if attachment_meta else None)
    if user_blocks:
        user_blocks[0].update(image_preview(db,conversation_id,attachment_meta))
    if value.location_map is not None:
        user_blocks = (user_blocks or []) + [value.location_map.model_dump()]
    if value.concept_diagram is not None:
        user_blocks = (user_blocks or []) + [value.concept_diagram.model_dump()]
    control_event = _coding_resume_control_event(value.message)
    execution_intent = str(value.execution_intent or "").strip().upper()
    resume_metadata = bool(value.resume_control or value.resume_task_id or
                           execution_intent in {"RESUME", "RESUME_CODING_TASK", "CONTINUE_CODING_TASK"})
    independent_chat_turn = _independent_external_chat_turn(value)
    def coding_tasks_for_turn():
        return [] if independent_chat_turn else [task for task in db.coding_tasks(conversation_id) if not task.get('archived')]
    has_managed_task = any(task.get("status") in {"RESUMABLE", "BLOCKED", "QUEUED", "RUNNING", "PLANNING", "FINAL_REPORTING"}
                           for task in coding_tasks_for_turn())
    # Continue/resume is an orchestrator control event, not semantic coding
    # content. Keep it out of the transcript and project-goal context when a
    # managed task is present.
    if value.location_map is not None or not ((control_event or resume_metadata) and has_managed_task):
        db.add_message(conversation_id,"user",(_coding_skill_invocation.get() or {}).get("command",value.message),time.time(),source_message_id,blocks=user_blocks)
    selected_map = value.location_map
    if selected_map is None and re.search(r"ピン|地図|マップ|地点|\bpin[s]?\b|\bmap\b", value.message, re.I):
        selected_map = latest_map(existing)
    if selected_map is not None:
        request = value.message + map_context(selected_map)
        routing = None
        if not capability_enabled(settings, "external_access_enabled"):
            outcome = {"blocked": "EXTERNAL_ACCESS_REQUIRED"}
        elif not _external_data_prohibited(value.message) and not _tool_execution_prohibited(value.message):
            try:
                router_decision(request)
                routing = _API_ROUTING_TRACE.get()
            except RouterUnavailable:
                pass
            outcome = _run_autonomous_analysis(request, routing, location_map=selected_map)
            if ('blocked' not in outcome and not outcome.get('sources')
                    and not (outcome.get('tool') or {}).get('results') and not outcome.get('task')):
                outcome = {**outcome, 'blocked': 'NO_VERIFIED_MAP_EVIDENCE'}
        else:
            outcome = {"blocked": "EXTERNAL_DATA_PROHIBITED"}
        if "blocked" in outcome:
            reason = str(outcome['blocked'])
            response = ("外部アクセスがオフです。設定で有効にすると、指定地点の情報を取得できます。"
                        if reason == 'EXTERNAL_ACCESS_REQUIRED' else
                        "情報源から確認できる根拠を取得できませんでした。地点名と利用できる情報源・モデルの設定を確認してください。")
            response += " 地域の統計範囲・年次・出典を確認できていないため、数値の比較は行っていません。"
            blocks = outcome.get('blocks', [])
            sources = []
        else:
            task = outcome['task']
            db.save_task(task, conversation_id)
            response, blocks, sources = outcome['response'], outcome.get('blocks', []), outcome.get('sources', [])
        completed_task = outcome.get('task') if 'blocked' not in outcome else None
        db.add_message(conversation_id, "assistant", response, time.time(), str(uuid.uuid4()),
                       completed_task.id if completed_task else None, blocks=blocks or None)
        return {"conversation_id": conversation_id, "response": response, "blocks": blocks, "sources": sources,
                **({'task': completed_task.__dict__ | {'route': completed_task.route.value if completed_task.route else None,
                                                     'state': completed_task.state.value},
                    'tool': outcome.get('tool')} if completed_task else {})}
    if value.computer_use_event is not None:
        if chat_computer_use_intent(value.message) != value.computer_use_event.action:
            raise HTTPException(422, "COMPUTER_USE_EVENT_INTENT_MISMATCH")
        prior_event = next((block for message in existing.get("messages", [])
            for block in (message.get("blocks") or [])
            if isinstance(block, dict) and block.get("type") == "computer_use_task"
            and block.get("source_message_id") == source_message_id), None)
        if prior_event is not None:
            return {"conversation_id": conversation_id,
                    "response": "このComputer Use指示は既に記録済みです。",
                    "blocks": [prior_event], "sources": []}
        event = value.computer_use_event
        if event.action == "start" and not capability_enabled(settings, "computer_use_enabled"):
            response = "Computer Use is OFF. Turn it on in Settings, then name the app you want to control in chat."
            db.add_message(conversation_id, "assistant", response, time.time(), str(uuid.uuid4()))
            return {"conversation_id": conversation_id, "response": response, "sources": []}
        if event.action == "start" and event.status == "RUNNING" and (not event.capture_session_id
                                         or not event.application_pid or not event.application_bundle_id):
            raise HTTPException(422, "COMPUTER_USE_START_EVENT_INCOMPLETE")
        if event.action == "stop" and event.status != "STOPPED":
            raise HTTPException(422, "COMPUTER_USE_STOP_EVENT_STILL_RUNNING")
        if event.action == "status" and event.status == "RUNNING" and not event.capture_session_id:
            raise HTTPException(422, "COMPUTER_USE_STATUS_SESSION_MISSING")
        if event.action == "start":
            if event.status == "RUNNING":
                response = (f"Computer Use の画面キャプチャを開始しました（{event.application_bundle_id}）。"
                            + ("このチャットで依頼された操作を続けます。" if event.followup_action
                               else "続けてこのチャットで実行したい操作を指示してください。"))
            elif event.status == "BLOCKED" and event.reason == "TARGET_APPLICATION_NOT_SELECTED":
                response = "Computer Use is enabled, but no target app is selected. Name the app you want to control in your chat message."
            elif event.status == "BLOCKED" and (event.reason or "").startswith("TARGET_APPLICATION_AMBIGUOUS:"):
                candidates = (event.reason or "").partition(":")[2].strip()
                response = f"複数のアプリが見つかりました（{candidates}）。対象のアプリ名を指定して、チャットからもう一度開始してください。"
            elif event.status == "BLOCKED" and event.reason == "TARGET_APPLICATION_NOT_RUNNING":
                response = "指定したアプリが起動していません。アプリを起動してから、チャットでもう一度指示してください。"
            elif event.status == "BLOCKED" and event.reason == "TARGET_APPLICATION_MISMATCH":
                response = "Computer Use is already watching a different app. Stop the current session before starting a new target."
            elif event.status == "BLOCKED" and event.reason == "NO_TARGET_RUNNING":
                response = "操作対象のアプリが起動していません。アプリ名を確認して、チャットからもう一度開始してください。"
            elif event.status == "BLOCKED" and event.reason == "COMPUTER_USE_DISABLED":
                response = "Computer Use is OFF. Enable it in Settings before starting a session."
            else:
                response = f"Computer Use could not start: {(event.reason or 'native screen capture did not start')[:200]}"
        elif event.action == "stop":
            response = "Computer Use stopped. The native screen capture session has been released."
        else:
            response = ("Computer Use is running." if event.status == "RUNNING" else "Computer Use is stopped.")
        block = {"type": "computer_use_task", "source_message_id": source_message_id,
                 "action": event.action, "status": event.status,
                 "capture_session_id": event.capture_session_id,
                 "application_pid": event.application_pid,
                 "application_bundle_id": event.application_bundle_id,
                 "followup_action": event.followup_action,
                 "reason": event.reason}
        db.add_message(conversation_id, "assistant", response, time.time(), str(uuid.uuid4()), blocks=[block])
        return {"conversation_id": conversation_id, "response": response,
                "blocks": [block], "sources": []}
    conversation_project_state=_conversation_project_context(conversation_id, project_id, "" if ((control_event or resume_metadata) and has_managed_task) else value.message)
    attachment_evidence=attachment_repair_evidence(
        attachment_meta, value.message,
        project_scoped=bool(conversation_project_state.get("workspace_path")),
    )
    print(f"ACTIVE_PROJECT_ID={project_id} ACTIVE_WORKSPACE={conversation_project_state.get('workspace_path') or ''} "
          f"PROJECT_CONTEXT_LOADED=YES PROJECT_CONTEXT_REVISION={conversation_project_state.get('revision',0)} "
          f"ACTIVE_SUBJECT={conversation_project_state.get('current_subject','')} "
          f"ACTIVE_SUBJECT_SOURCE={(conversation_project_state.get('provenance') or {}).get('current_subject','')} "
          f"PROJECT_CONTEXT_FACT_COUNT={len([key for key, item in conversation_project_state.items() if item and key not in {'revision','provenance'}])} "
          f"ATTACHMENT_COUNT={1 if attachment_meta else 0}", file=__import__('sys').stderr, flush=True)
    print("GUI_CHAT_USER_SAVE=PASS GUI_CHAT_RUNTIME_START", file=__import__("sys").stderr, flush=True)
    managed_reply = _managed_coding_chat(value, conversation_id, source_message_id)
    if managed_reply is not None: return managed_reply
    planning_session, planning_response = ((None, None) if independent_chat_turn else
                                           _resolve_interactive_planning_reply(conversation_id, value.message))
    if planning_response is not None:
        _record_planning_decisions(conversation_id, project_id, planning_session)
        db.add_message(conversation_id, "assistant", planning_response, time.time(), str(uuid.uuid4()))
        print("CODING_TASK_CREATED=NO CODING_ROUTE=INTERACTIVE_PLANNING", file=__import__("sys").stderr, flush=True)
        return {"conversation_id": conversation_id, "response": planning_response, "sources": []}
    approved_message=bool(re.search(r"^(?:はい、?\s*)?(?:承認します|許可します|承認|この計画を承認します|この計画を実行してください|この計画で進めて|この計画でお願いします|実行してください|進めてください|進めて|この内容でok|お願いします、?実装して)\s*[。！!]*$",value.message.strip(),re.I))
    waiting=next((task for task in coding_tasks_for_turn() if task["status"] == "WAITING_FOR_PLAN_APPROVAL" and not task.get("archived")),None)
    if waiting and approved_message:
        print(f"MANAGED_INPUT_ROUTED=true CODING_TASK_ID={waiting['id']} CODING_ROUTE=PLAN_APPROVAL",file=__import__('sys').stderr,flush=True)
        if (waiting.get("requirements") or {}).get("planning_only") is True:
            allowed=list(((waiting.get("plan") or {}).get("scope") or {}).get("allowed") or [])
            approved_scope={"source":"explicit_plan_approval","requested_scope":allowed}
            requirements={**(waiting.get("requirements") or {}),"planning_only":False}
            db.update_coding_task(waiting["id"],approved_scopes=[approved_scope],requirements=requirements)
            print(f"TASK_ID={waiting['id']} PLAN_APPROVAL=EXPLICIT APPROVED_SCOPE_COUNT={len(allowed)}",file=__import__('sys').stderr,flush=True)
        db.enqueue_coding_task(waiting["id"]); _coding_scheduler_wake.set()
        response="Coding Task を実行キューへ追加しました。"
        db.add_message(conversation_id,"assistant",response,time.time(),str(uuid.uuid4()),waiting["id"])
        return {"conversation_id":conversation_id,"coding_task_id":waiting["id"],"response":response,"sources":[]}
    if waiting:
        print(f"MANAGED_INPUT_ROUTED=true CODING_TASK_ID={waiting['id']} CODING_ROUTE=PLAN_APPROVAL_WAITING",file=__import__('sys').stderr,flush=True)
        response="計画の承認待ちです。計画を実行する場合は「この計画で進めて」と返信してください。"
        db.add_message(conversation_id,"assistant",response,time.time(),str(uuid.uuid4()),waiting["id"])
        return {"conversation_id":conversation_id,"coding_task_id":waiting["id"],"response":response,"sources":[]}
    ineffective_waiting=next((task for task in coding_tasks_for_turn()
                              if task["status"] == "WAITING_FOR_USER" and task.get("recovery_reason") == "REPLAN_INEFFECTIVE"),None)
    if ineffective_waiting:
        if re.fullmatch(r"(?:再開(?:して)?|続行(?:して)?|再試行(?:して)?|失敗情報を使ってこの工程を再実行|元の要件で再計画して再試行|resume|continue|retry)[。！!]*", value.message.strip(), re.I):
            return _resume_coding_task_control(ineffective_waiting, source="EXPLICIT_CHAT_REPLAN_RETRY")
        intent=classify_waiting_input(value.message)
        print(f"TASK_ID={ineffective_waiting['id']} WAITING_INPUT_INTENT={intent} USER_REVISION_PRESENT={'true' if intent == 'REVISION' else 'false'}",file=__import__('sys').stderr,flush=True)
        if intent == "REVISION":
            revision=value.message.strip()
            revision_context={**(ineffective_waiting.get("pending_authorization") or {}), "user_revision": revision, "state": "PENDING"}
            db.update_coding_task(ineffective_waiting["id"], status="QUEUED", activity="QWEN_REPLANNING",
                                  pending_authorization=revision_context, recovery_action="REPLAN_CONTINUATION",
                                  recovery_reason="USER_REVISION", pending_user_confirmation=0)
            db.enqueue_coding_task(ineffective_waiting["id"]); _coding_scheduler_wake.set()
            response="修正指示を受け取り、未完了部分の再計画を開始します。"
            db.add_message(conversation_id,"assistant",response,time.time(),str(uuid.uuid4()),ineffective_waiting["id"])
            return {"conversation_id":conversation_id,"coding_task_id":ineffective_waiting["id"],"response":response,"sources":[]}
        pending=ineffective_waiting.get("pending_authorization") or {}
        unmet=pending.get("unmet_criteria") or []
        details="\n".join(f"- {item}" for item in unmet[:6])
        phase_id=str(ineffective_waiting.get("current_phase_id") or "")
        phase_label=f"Phase {phase_id[1:]}" if re.fullmatch(r"p\d+", phase_id, re.IGNORECASE) else (phase_id or "未完了のPhase")
        response=(f"{phase_label} の自動復旧で改善できず、再試行方法の選択が必要です。成果物の確認・合格判定を求めているわけではありません。\n"
                  + ("現在の未達条件:\n" + details + "\n" if details else "")
                  + "元の要件で再試行する場合は「再試行」と入力するか、進捗カードの「失敗情報を使ってこの工程を再実行」を押してください。変更したい条件があれば、その内容をチャットへ入力してください。")
        print(f"TASK_ID={ineffective_waiting['id']} CLARIFICATION_NO_MUTATION=true QWEN_REPLANNING_STARTED=false QUEUE_ENTRY_CREATED=false PLAN_REVISION_CHANGED=false CURRENT_PHASE_CHANGED=false STATUS_AFTER=WAITING_FOR_USER",file=__import__('sys').stderr,flush=True)
        db.add_message(conversation_id,"assistant",response,time.time(),str(uuid.uuid4()),ineffective_waiting["id"])
        return {"conversation_id":conversation_id,"coding_task_id":ineffective_waiting["id"],"response":response,"sources":[]}
    scope_waiting=next((task for task in coding_tasks_for_turn() if task["status"] == "WAITING_FOR_USER" and task.get("pending_authorization")),None)
    if scope_waiting and approved_message:
        db.accept_pending_plan(scope_waiting["id"])
        if (scope_waiting.get('pending_authorization') or {}).get('type') == 'PERMISSION_MODE':
            approved = {'source':'explicit_plan_approval',
                        'requested_scope':list(((scope_waiting.get('pending_plan') or {}).get('scope') or {}).get('allowed') or [])}
            db.update_coding_task(scope_waiting['id'],approved_scopes=[*(scope_waiting.get('approved_scopes') or []),approved])
        db.enqueue_coding_task(scope_waiting["id"]); _coding_scheduler_wake.set()
        response="追加スコープを承認し、実行キューへ追加しました。"
        db.add_message(conversation_id,"assistant",response,time.time(),str(uuid.uuid4()),scope_waiting["id"])
        return {"conversation_id":conversation_id,"coding_task_id":scope_waiting["id"],"response":response,"sources":[]}
    if scope_waiting:
        intent=classify_waiting_input(value.message)
        print(f"TASK_ID={scope_waiting['id']} WAITING_INPUT_INTENT={intent} USER_REVISION_PRESENT=false QWEN_REPLANNING_STARTED=false QUEUE_ENTRY_CREATED=false STATUS_AFTER=WAITING_FOR_USER",file=__import__('sys').stderr,flush=True)
        response="追加スコープの承認待ちです。内容を確認し、「承認します」と返信してください。"
        db.add_message(conversation_id,"assistant",response,time.time(),str(uuid.uuid4()),scope_waiting["id"])
        return {"conversation_id":conversation_id,"coding_task_id":scope_waiting["id"],"response":response,"sources":[]}
    waiting_task=next((task for task in coding_tasks_for_turn() if task["status"] == "WAITING_FOR_USER"),None)
    if waiting_task:
        intent=classify_waiting_input(value.message)
        print(f"TASK_ID={waiting_task['id']} WAITING_INPUT_INTENT={intent} USER_REVISION_PRESENT=false QWEN_REPLANNING_STARTED=false QUEUE_ENTRY_CREATED=false STATUS_AFTER=WAITING_FOR_USER",file=__import__('sys').stderr,flush=True)
        response="確認が必要です。現在のTaskはユーザー入力を待っています。変更内容を具体的に入力してください。"
        db.add_message(conversation_id,"assistant",response,time.time(),str(uuid.uuid4()),waiting_task["id"])
        return {"conversation_id":conversation_id,"coding_task_id":waiting_task["id"],"response":response,"sources":[]}
    # Task-control/status requests stay under the managed task authority even
