            marker = state.get("last_verified_false_pass_reopen") if isinstance(state, dict) else None
            current_epoch = int(task.get("recovery_epoch") or 0)
            same_epoch_retry = (task.get("status") == "RESUMABLE" and isinstance(marker, dict)
                and int(marker.get("next_recovery_epoch", -1)) == current_epoch
                and bool(_phase_reports_for_epoch(str(task.get("id") or ""), str(marker.get("phase_id") or ""),
                                                  int(task.get("plan_revision") or 0), current_epoch)))
