    if blocked and resume_request:
        print(f"MANAGED_INPUT_ROUTED=true CODING_TASK_ID={blocked['id']} CODING_ROUTE=BLOCKED_TASK_RESUME_CONTROL NORMAL_RUNTIME_FALLBACK=false",file=__import__('sys').stderr,flush=True)
        result = _resume_coding_task_control(blocked, source="EXPLICIT_CHAT_COMMAND_BLOCKED")
