@app.post('/api/audio/synthesize/stream')
async def stream_audio_synthesis(value: dict[str, Any]):
    text, language = value.get('text'), value.get('language')
    if not isinstance(text, str) or not 0 < len(text.strip()) <= 180 or not isinstance(language, str) or language not in {'ja', 'en'}:
        raise HTTPException(422, 'AUDIO_SYNTHESIS_REQUEST_INVALID')

    async def events():
        loop = asyncio.get_running_loop()
        queue = asyncio.Queue()
        cancelled = threading.Event()
        def publish(event):
            if not cancelled.is_set() and not loop.is_closed():
                loop.call_soon_threadsafe(queue.put_nowait, event)
        def produce():
            from .audio_synthesis import stream_synthesize
            try:
                for event in stream_synthesize(text, language, cancelled):
                    if cancelled.is_set():
                        break
                    publish(event)
            except Exception:
                traceback.print_exc()
                publish({'type': 'error', 'error': 'AUDIO_SYNTHESIS_FAILED'})
            finally:
                publish(None)
        context = copy_context()
        threading.Thread(target=lambda: context.run(produce), name='olcr-tts', daemon=True).start()
        try:
            while True:
                event = await queue.get()
                if event is None:
                    break
                yield json.dumps(event, ensure_ascii=False) + '\n'
        finally:
            cancelled.set()
    return StreamingResponse(events(), media_type='application/x-ndjson', headers={'Cache-Control': 'no-store', 'X-Accel-Buffering': 'no'})


@app.post("/api/audio/transcribe")
def transcribe_audio(value: dict[str, Any]):
    """Transcribe a short, user-recorded voice clip with the local LFM audio model."""
    audio = value.get("audio_base64")
    language = value.get("language")
    if not isinstance(audio, str) or language not in {'ja', 'en'}:
        raise HTTPException(422, "AUDIO_REQUEST_INVALID")
    try:
        selected = purpose_models.choice('transcription_' + language)
        if selected['protocol'] != 'preset':
            return purpose_models.transcribe(audio, language, selected)
        from .audio_transcription import transcribe_audio as run_transcription
        return run_transcription(audio, language, purpose_models.audio_model(language))
    except ValueError as exc:
        raise HTTPException(422, str(exc)) from exc
    except Exception as exc:
        print(f"LOCAL_AUDIO_TRANSCRIPTION_FAILED={type(exc).__name__}",
              file=__import__("sys").stderr, flush=True)
        raise HTTPException(503, str(exc) if str(exc).startswith("AUDIO_") else "AUDIO_MODEL_UNAVAILABLE") from exc

@app.post("/api/audio/transcribe/stream")
async def stream_audio_transcription(value: dict[str, Any]):
    audio, language = value.get("audio_base64"), value.get("language")
    handsfree_session = value.get('handsfree_session')
    if handsfree_session is not None:
        try: handsfree.require(handsfree_session)
        except ValueError as exc: raise HTTPException(409, str(exc)) from exc
    if not isinstance(audio, str) or not isinstance(language, str) or language not in {"ja", "en"}:
        raise HTTPException(422, "AUDIO_REQUEST_INVALID")
    if len(audio) > 12 * 1024 * 1024 * 4 // 3 + 16:
        raise HTTPException(422, "AUDIO_CLIP_TOO_LARGE")

    async def events():
        # Keep torch's thread-local inference context on one worker for the
        # whole generation; StreamingResponse's sync iterator can change threads.
        loop = asyncio.get_running_loop()
        queue = asyncio.Queue()
        cancelled = threading.Event()
        def publish(event):
            if not cancelled.is_set():
                loop.call_soon_threadsafe(queue.put_nowait, event)
        def produce():
            from .audio_transcription import stream_transcribe_audio
            selected = {'protocol': 'preset'} if handsfree_session is not None else purpose_models.choice('transcription_' + language)
            def selected_transcription():
                result = purpose_models.transcribe(audio, language, selected)
                yield {'type': 'text', **result}
                yield {'type': 'done', **result}
            model_id = (purpose_models.audio_model(language)
                        if handsfree_session is None and selected['protocol'] == 'preset' else None)
            iterator = (stream_transcribe_audio(audio, language, cancelled=cancelled, model_id=model_id)
                        if handsfree_session is not None or selected['protocol'] == 'preset' else selected_transcription())
            try:
                for event in iterator:
                    if cancelled.is_set():
                        break
                    publish(event)
            except Exception as exc:
                traceback.print_exc()
                code = str(exc) if str(exc).startswith("AUDIO_") else "AUDIO_MODEL_UNAVAILABLE"
                publish({"type": "error", "error": code})
            finally:
                iterator.close()
                publish(None)
        context = copy_context()
        threading.Thread(target=lambda: context.run(produce), name="olcr-asr", daemon=True).start()
        try:
            while True:
                event = await queue.get()
                if event is None:
                    break
                yield json.dumps(event, ensure_ascii=False) + "\n"
        finally:
            cancelled.set()

    return StreamingResponse(events(), media_type="application/x-ndjson", headers={"Cache-Control": "no-store", "X-Accel-Buffering": "no"})


