@app.post("/api/web/browser/sessions")
def open_web_browser_session(value: BrowserSessionOpenInput | None = None):
    request = value or BrowserSessionOpenInput()
    result = browser_sessions.open(request.profile_id,
                                   interactive_login=request.interactive_login)
    if result.get("status") == "LIMIT_REACHED": raise HTTPException(429, result["error"])
    if result.get("status") == "PROFILE_IN_USE": raise HTTPException(409, result["error"])
    if result.get("status") == "FAILED" and result.get("error") == "BROWSER_PROFILE_NOT_FOUND":
        raise HTTPException(404, result["error"])
    if result.get("status") == "FAILED" and result.get("error") in {
        "BROWSER_PROFILE_ID_INVALID", "PERSISTENT_PROFILE_REQUIRED_FOR_INTERACTIVE_LOGIN",
        "BROWSER_PROFILES_UNAVAILABLE", "BROWSER_PROFILE_PATH_INVALID",
    }:
        raise HTTPException(422, result["error"])
    if result.get("status") != "READY": raise HTTPException(503, result.get("error", "BROWSER_UNAVAILABLE"))
    return result

