@app.post("/api/web/browser/sessions/{session_id}/reload")
def reload_web_browser_session(session_id: str):
    result = browser_sessions.reload(session_id)
    if result.get("status") == "NOT_FOUND": raise HTTPException(404, result["error"])
    if result.get("error") == "BROWSER_SESSION_NOT_NAVIGATED": raise HTTPException(409, result["error"])
    if result.get("status") != "AVAILABLE": raise HTTPException(502, result.get("error", "BROWSER_RELOAD_FAILED"))
    return result

