def _public_scrape_run(run: dict[str, Any]) -> dict[str, Any]:
    recipe = run.pop("recipe", {})
    run.pop("next_url", None)
    run["output_format"] = recipe.get("output_format", "csv")
    return run

def _csv_safe_value(value: Any) -> str:
    if isinstance(value, (dict, list)): value = json.dumps(value, ensure_ascii=False)
    if isinstance(value, (int, float)) and not isinstance(value, bool): return str(value)
    text = str(value) if value is not None else ""
    if text[:1] in {"=", "+", "-", "@", "\t", "\r"}: text = "'" + text
    return text

def _export_row_batches(rows, batch_size: int = 64):
    batch = []
    for row in rows:
        batch.append(row)
        if len(batch) >= batch_size:
            yield batch
            batch = []
    if batch:
        yield batch

