@app.get("/api/web/scrape/runs/{run_id}/export")
def export_web_scrape_run(run_id: str, format: Literal["csv", "json", "jsonl", "xlsx"] | None = None):
    run = db.web_scrape_run(run_id)
    if run is None: raise HTTPException(404, "SCRAPE_RUN_NOT_FOUND")
    recipe = run.get("recipe") or {}
    fields = (list((recipe.get("network_json") or {}).get("fields") or {})
              if recipe.get("source") == "network_json" else list(recipe.get("fields") or {}))
    fields += list((recipe.get("detail") or {}).get("fields") or {})
    if recipe.get("tool") or run.get("status") in {"COMPLETED", "STOPPED", "PAUSED", "FAILED", "INTERRUPTED"}:
        fields = list(dict.fromkeys(key for row in db.stream_web_scrape_rows(run_id) for key in row))[:200]
    output_format = format or (run.get("recipe") or {}).get("output_format", "csv")
    if output_format == "xlsx":
        from .scrape_table import xlsx_bytes
        if run["record_count"] > 10000: raise HTTPException(409, "EXCEL_EXPORT_LIMIT_10000_USE_CSV")
        try: workbook = xlsx_bytes(db.stream_web_scrape_rows(run_id), fields)
        except ValueError as exc: raise HTTPException(409, str(exc)) from exc
        return StreamingResponse(iter([workbook]),
            media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            headers={"Content-Disposition": f'attachment; filename="olcr-{run_id}.xlsx"'})
    def stream():
        rows = db.stream_web_scrape_rows(run_id)
        if output_format == "csv":
            buffer = io.StringIO(newline="")
            writer = csv.writer(buffer)
            writer.writerow(fields); yield buffer.getvalue(); buffer.seek(0); buffer.truncate(0)
            for batch in _export_row_batches(rows):
                writer.writerows(
                    [_csv_safe_value(row.get(field)) for field in fields]
                    for row in batch
                )
                yield buffer.getvalue(); buffer.seek(0); buffer.truncate(0)
        elif output_format == "json":
            yield "["
            first = True
            for batch in _export_row_batches(rows):
                serialized = ",".join(
                    json.dumps(row, ensure_ascii=False, separators=(",", ":"))
                    for row in batch
                )
                yield ("" if first else ",") + serialized
                first = False
            yield "]"
        else:
            for batch in _export_row_batches(rows):
                yield "".join(
                    json.dumps(row, ensure_ascii=False, separators=(",", ":")) + "\n"
                    for row in batch
                )
    media = "text/csv; charset=utf-8" if output_format == "csv" else "application/json" if output_format == "json" else "application/x-ndjson"
    return StreamingResponse(stream(), media_type=media,
        headers={"Content-Disposition": f'attachment; filename="olcr-{run_id}.{output_format if output_format != "jsonl" else "jsonl"}"'})

