def _profile_installed_ids():
    return {row['id'] for row in purpose_models.downloads.catalog()['presets'] if row.get('downloaded')}


def _managed_brain_slots(configuration=None):
    from .brain_models import INITIAL as BRAIN_INITIAL
    configuration = configuration or brain_models.configuration()
    previous = db.load_settings().get('model_profile_brain_slots', {})
    managed = set()
    for slot, value in configuration.get('selections', {}).items():
        baseline = previous.get(slot, BRAIN_INITIAL['selections'][slot]) if isinstance(previous, dict) else BRAIN_INITIAL['selections'][slot]
        if value == baseline or value == BRAIN_INITIAL['selections'][slot]:
            managed.add(slot)
    return managed


def _profile_brain_download_id(model_id):
    from .brain_models import BONSAI, ORNITH_MLX
    if model_id == BONSAI:
        return 'ternary_bonsai_2_27b'
    if model_id == ORNITH_MLX:
        return 'ornith_1_5_9b_8bit'
    return next((key for key, value in model_profile_catalog.models.items()
                 if value.get('brain_id') == model_id), None)


def _profile_required_download_ids(selection):
    presets = purpose_models.downloads.presets()
    from .model_registry import ROLE_TO_MODEL
    required = set()
    try:
        if purpose_models.choice('semantic_embedding')['protocol'] == 'preset':
            embedding_model = ROLE_TO_MODEL.get('semantic_embedding')
            if embedding_model in presets:
                required.add(embedding_model)
    except ValueError:
        pass
    for role, model_id in selection['roles'].items():
        if role in ROLE_TO_MODEL and model_id in presets:
            try:
                if purpose_models.choice(role)['protocol'] != 'preset':
                    continue
            except ValueError:
                pass
            required.add(model_id)
            continue
        try:
            if purpose_models.choice(role)['protocol'] == 'preset' and model_id in presets:
                required.add(model_id)
        except ValueError:
            continue
    for role in ('transcription_ja', 'transcription_en'):
        try:
            if purpose_models.choice(role)['protocol'] != 'preset':
                continue
        except ValueError:
            continue
        model_id = selection['audio'].get(role)
        if model_id in presets:
            required.add(model_id)
    # The current local read-aloud engine uses the language-specific LFM Audio
    # checkpoints even when Whisper is selected for speech recognition.
    if selection['audio'].get('read_aloud') == 'lfm2_5_audio_1_5b':
        required.update(model_id for model_id in ('transcription_ja', 'transcription_en') if model_id in presets)
    configuration = brain_models.configuration()
    for slot in _managed_brain_slots(configuration):
        model_id = selection['brain'][slot]
        download_id = _profile_brain_download_id(model_id)
        if download_id in presets:
            required.add(download_id)
    return sorted(model_id for model_id in required if not purpose_models.downloads.installed(presets[model_id]))


def _apply_model_profile(selection):
    from .brain_models import INITIAL as BRAIN_INITIAL
    configuration = brain_models.configuration()
    prior_managed = db.load_settings().get('model_profile_brain_slots', {})
    if not isinstance(prior_managed, dict):
        prior_managed = {}
    managed = {}
    for slot, model_id in selection['brain'].items():
        current = configuration['selections'].get(slot)
        baseline = prior_managed.get(slot, BRAIN_INITIAL['selections'][slot])
        if current == baseline or current == BRAIN_INITIAL['selections'][slot]:
            configuration['selections'][slot] = model_id
            managed[slot] = model_id
    brain_models._inventory_at = 0
    brain_models.save(configuration)
    set_effective_role_map(selection['roles'])
    now = time.time()
    db.save_setting('effective_model_role_map', selection['roles'], now)
    db.save_setting('profile_audio_models', selection['audio'], now)
    db.save_setting('model_profile_brain_slots', managed, now)
    db.save_setting('model_profile_selection', {**selection, 'applied': True, 'updated_at': now}, now)


@app.get('/api/model-profiles')
def get_model_profiles(memory_gb: int | None = Query(default=None, ge=1, le=1024)):
    detected = detect_hardware()
    selected_memory = memory_gb if memory_gb is not None else detected.memory_gb
    hardware = HardwareProfile(selected_memory, detected.chip, detected.architecture,
                               'manual' if memory_gb is not None else detected.source)
    state = db.load_settings().get('model_profile_selection')
    catalog = model_profile_catalog.for_device(selected_memory, detected.chip, _profile_installed_ids(),
                                               current=state if isinstance(state, dict) else None,
                                               hardware=hardware)
    installed_brain = []
    try:
        reserve = int(catalog['memory_policy']['reserved_system_gb'].get(catalog['recommended_profile'], 32))
        overhead = int(catalog['memory_policy'].get('runtime_overhead_gb', 4))
        for model in brain_models.catalog()['models']:
            if not model.get('local') or not model.get('available'):
                continue
            descriptor = next((row for row in model_profile_catalog.models.values()
                               if row.get('brain_id') == model.get('id')), None)
            size = int(model.get('size_bytes') or (descriptor or {}).get('size_bytes') or 0)
            weight_gb = float((descriptor or {}).get('weight_gb') or size / (1024 ** 3))
            fits = selected_memory is not None and weight_gb > 0 and weight_gb + reserve + overhead <= selected_memory
            row = {**model, 'size_bytes': size or None, 'fits_memory': fits,
                   'available': bool(model.get('available') and fits), 'downloaded': True}
            installed_brain.append(row)
            if not fits:
                continue
            for role in ('brain', 'coder', 'short_coding', 'general_inference', 'long_implementation', 'normal_chat'):
                options = catalog['options'].setdefault(role, [])
                if not any(option.get('id') == model['id'] for option in options):
                    options.append({'id': model['id'], 'download_id': None,
                        'label': model.get('label') or model['id'], 'runtime': model.get('provider') or 'Local',
                        'size_bytes': size or None, 'downloaded': True, 'fits_memory': True,
                        'recommended': False, 'available': True, 'installed_custom': True})
    except Exception:
        pass
    catalog['installed_brain_models'] = installed_brain
    return catalog


class ModelProfileSelectionInput(BaseModel):
    profile_id: str = Field(min_length=1, max_length=12)
    role_models: dict[str, str] = Field(default_factory=dict)
    audio_models: dict[str, str] = Field(default_factory=dict)
    memory_gb: int | None = Field(default=None, ge=1, le=1024)
    confirm_apply: bool = False


@app.put('/api/model-profiles/selection')
def put_model_profile_selection(value: ModelProfileSelectionInput):
    if value.confirm_apply is not True:
        raise HTTPException(400, 'MODEL_PROFILE_CONFIRMATION_REQUIRED')
    memory = value.memory_gb or int(value.profile_id)
    try:
        brain_inventory = [model for model in brain_models.catalog()['models']
                           if model.get('local') and model.get('available')]
        brain_sizes = {model['id']: int(model.get('size_bytes') or 0) for model in brain_inventory}
        selection = normalize_selection(value.profile_id, value.role_models, value.audio_models,
                                        memory, brain_sizes)
        now = time.time()
        pending = _profile_required_download_ids(selection)
        if not pending:
            _apply_model_profile(selection)
            db.save_setting('model_profile_memory_gb', memory, now)
            return {'selection': selection, 'applied': True, 'download_ids': []}
        db.save_setting('model_profile_selection', {**selection, 'applied': False, 'updated_at': now}, now)
        db.save_setting('model_profile_memory_gb', memory, now)
        return {'selection': selection, 'applied': False, 'download_ids': pending}
    except (ValueError, KeyError, TypeError) as exc:
        raise HTTPException(422, str(exc)) from None


