def probe_preset_runtime(role):
    import base64
    if role == 'semantic_embedding':
        from .purpose_models import vectors as validate_vectors
        validate_vectors(OllamaEmbeddingProvider(settings.ollama_endpoint).embed(['OLCR test', '互換性の確認'], 'embeddinggemma:latest'), 2)
    elif role == 'typed_local_decisions':
        local = laya_provider.local
        if not local.loaded:
            local, _ = _startup_laya_provider(settings)
        if not local.loaded: raise ValueError('MODEL_PRESET_RUNTIME_UNAVAILABLE')
        local.choice(question='Select yes.', candidates=[{'tool_id': 'yes', 'criteria': 'Correct answer'}, {'tool_id': 'no', 'criteria': 'Incorrect answer'}])
        purpose_models.prepared_local_decisions = local
    elif role.startswith('transcription_'):
        import io, wave
        buffer = io.BytesIO()
        with wave.open(buffer, 'wb') as wav:
            wav.setnchannels(1); wav.setsampwidth(2); wav.setframerate(16000); wav.writeframes(b'\0' * 3200)
        from .audio_transcription import transcribe_audio
        transcribe_audio(base64.b64encode(buffer.getvalue()).decode(), role[-2:], purpose_models.audio_model(role[-2:]))
    elif role == 'translation':
        result = purpose_models.translate('こんにちは。ありがとうございます。', 'ja', 'en', {'protocol': 'preset'})
        if not result.get('text', '').strip(): raise ValueError('MODEL_PRESET_RUNTIME_UNAVAILABLE')
    else:
        from .purpose_models import vision_probe_image
        image = vision_probe_image()
        provider = RoleAwareModelProvider(settings, ModelRegistry(settings.model_manifest_path))
        try:
            result = provider.vision(image, 'image/png', 'Describe this blank image.', 'role:' + role)
            if not isinstance(result.get('text'), str) or not result['text'].strip(): raise ValueError('MODEL_PRESET_RUNTIME_UNAVAILABLE')
        finally: provider.close()


