@app.post('/api/purpose-models/{role}/probe')
def probe_purpose_model(role: str, value: PurposeModelProbeInput):
    try:
        clean = purpose_models.validate(role, value.configuration)
        if clean['protocol'] not in {'preset', 'ollama'} and not purpose_models.local(clean) and not value.confirm_remote:
            raise ValueError('MODEL_REMOTE_PROBE_CONSENT_REQUIRED')
        purpose_models.settings = settings
        purpose_models.preset_probe = probe_preset_runtime
        return purpose_models.prepare(role, clean, value.api_key or None)
    except (ValueError, TypeError, KeyError, IndexError, RuntimeError) as exc:
        raise HTTPException(422, str(exc) if isinstance(exc, (ValueError, ModelFailure)) else 'MODEL_COMPATIBILITY_TEST_FAILED') from None


class PurposeModelActivationInput(BaseModel):
    token: str = Field(min_length=32, max_length=32)


@app.post('/api/purpose-models/{role}/cancel')
def cancel_purpose_model(role: str, value: PurposeModelActivationInput):
    purpose_models.cancel(role, value.token)
    return {'cancelled': True}


@app.post('/api/purpose-models/{role}/activate')
def activate_purpose_model(role: str, value: PurposeModelActivationInput):
    global _api_embedding_provider, vectors, conversation_memory, laya_provider, _laya_startup_status
    try:
        with _settings_update_lock:
            selected = purpose_models.activate(role, value.token)
            if role == 'semantic_embedding':
                settings.embedding_model = purpose_models.namespace()
                _api_embedding_provider = purpose_embedding_provider(timeout=5.0)
                vectors = LocalVectorStore(db, purpose_embedding_provider(), settings.embedding_model, settings.allowed_roots) if settings.vector_enabled else DisabledVectorStore()
                retrieval.vectors = vectors
                retrieval.graphify = GraphifyRAG(purpose_embedding_provider(timeout=2.0), lambda: laya_provider, settings.embedding_model, settings.graphify_enabled, min_relevance=settings.rag_min_relevance)
                conversation_memory = ConversationMemory(db, purpose_embedding_provider(), settings.embedding_model, min_relevance=settings.conversation_memory_min_relevance, budget=settings.context_budget // 4, cross_project=settings.conversation_memory_cross_project_enabled)
                # Rebuild authorized document vectors in the selected namespace.
                # Capture the store: a subsequent switch cannot mix models mid-job.
                store = vectors
                def reindex():
                    with db.connect() as con: documents = [dict(row) for row in con.execute('SELECT id,source,text FROM documents')]
                    for row in documents:
                        try:
                            if isinstance(store, LocalVectorStore): store.index_document(row['id'], row['source'], row['text'])
                        except Exception:
                            print('PURPOSE_EMBEDDING_REINDEX_DOCUMENT_SKIPPED=YES', file=__import__('sys').stderr, flush=True)
                threading.Thread(target=reindex, daemon=True, name='olcr-embedding-reindex').start()
            elif role == 'typed_local_decisions' and selected['protocol'] == 'preset':
                local = getattr(purpose_models, 'prepared_local_decisions', laya_provider.local)
                laya_provider = PurposeDecisionProvider(purpose_models, local)
            return {'configuration': selected, 'applied': True}
    except ValueError as exc:
        raise HTTPException(422, str(exc)) from None


