async def _mobile_chat_events(body, generation):
    """Keep the stream and any detached coding task under PC ownership."""
    from .generation_control import generation_scope
    from .response_language import response_language_scope
    from .mobile_runs import follow_coding_task
    with generation_scope(generation), response_language_scope(body.get('language', 'ja')), brain_scope(brain_models.configuration(body['conversation_id'])):
        response = await asyncio.to_thread(stream_chat, ChatInput(
            message=body['message'], conversation_id=body['conversation_id'], message_id=body['request_id']))
        pending = ''
        coding_id = None
        async for chunk in response.body_iterator:
            pending += chunk.decode() if isinstance(chunk, bytes) else chunk
            pending = pending.replace('\r\n', '\n')
            while '\n\n' in pending:
                frame, pending = pending.split('\n\n', 1)
                data = '\n'.join(line[5:].lstrip() for line in frame.splitlines() if line.startswith('data:'))
                if not data:
                    continue
                event = json.loads(data)
                task = event.get('task') or {}
                if event.get('type') == 'done' and task.get('type') == 'coding_task_progress':
                    coding_id = task.get('task_id')
                else:
                    yield event
        if coding_id:
            owned = db.coding_task(coding_id)
            if not owned or owned.get('conversation_id') != body['conversation_id']:
                yield {'type': 'error', 'code': 'CODING_TASK_CONVERSATION_MISMATCH'}
                return
            baseline = {m['id'] for m in (db.conversation(body['conversation_id']) or {}).get('messages', [])}
            def pause(identifier):
                update_coding_task(identifier, CodingTaskUpdate(pause_requested=True))
            async for event in follow_coding_task(coding_id, db.coding_task, pause, generation):
                if event.get('type') == 'done':
                    for message in (db.conversation(body['conversation_id']) or {}).get('messages', []):
                        if message['role'] == 'assistant' and message['id'] not in baseline:
                            yield {'type': 'chunk', 'text': message['content']}
                    if event.get('waiting_for_user'):
                        yield {'type': 'chunk', 'text': '\nOLCRからの確認・回答待ちです。詳細な計画承認はPCで確認してください。'}
                yield event


def _mobile_approve_request(identifier, approved):
    if not request_approvals.approve(identifier, approved):
        raise HTTPException(409, 'PERMISSION_APPROVAL_EXPIRED')
    return {'approved': approved}


from .mobile_api import install_mobile_api
mobile_runs = install_mobile_api(app, db=db, settings=lambda: settings,
    access=mobile_bridge_access, source=_mobile_chat_events, approve_request=_mobile_approve_request)
